local config = {
  ui_story_5031_50310101_1_dialog_content = "Hadirin sekalian, dan tamu dari semua lapisan masyarakat! Selamat Datang di <color=#FFB400>The Illusionist & Old Bill's Circus</color>! Nama saya adalah <color=#FFB400>Rainbow</color>, dan saya akan menjadi pembawa acara Anda untuk acara malam ini!",
  ui_story_5031_50310101_2_dialog_content = "Semua yang telah bergabung dengan kami di atas Emerald malam yang indah ini adalah tamu paling terhormat dari sirkus kami.",
  ui_story_5031_50310101_3_dialog_content = "Tolong singkirkan kekhawatiran Anda dan nikmati pertunjukan kami yang luar biasa.",
  ui_story_5031_50310101_4_dialog_content = "Pertunjukan spektakuler yang ditawarkan oleh Illusionist & Old Bill's Circus dimaksudkan untuk menentang semua alasan dan melampaui imajinasi terliar Anda!",
  ui_story_5031_50310101_5_dialog_content = "Momen ajaib ini milikmu, milikku, milik seluruh dunia!",
  ui_story_5031_50310101_6_dialog_content = "Tanpa basa-basi lagi, mari kita sambut aksi pertama kita: akrobat terbang tinggi dari tiga saudara perempuan yang telah menguasai seni trapeze! Tolong beri sambutan hangat untuk Merylt—",
  ui_story_5031_50310101_7_dialog_content = "Subli—",
  ui_story_5031_50310101_8_dialog_content = "Dan Frimet—",
  ui_story_5031_50310101_9_dialog_content = "Saat mereka naik panggung!",
  ui_story_5031_50310101_10_dialog_content = "U-uh, Rainbow...? Bukankah peralatan trapeze masih diperbaiki sekarang?",
  ui_story_5031_50310101_11_dialog_content = "Ya, bahkan kita tidak mampu terbang sendiri.",
  ui_story_5031_50310101_12_dialog_content = "Heehee... Sebenarnya, aku sudah berlatih dengan orang kuat sirkus untuk sementara waktu sekarang.",
  ui_story_5031_50310101_13_dialog_content = "Aku bahkan mungkin bisa melemparkan kalian berdua ke udara sendirian!",
  ui_story_5031_50310101_14_dialog_content = "B-Bagaimana kalau tidak, itu terlalu berbahaya... Selain itu, mungkin ada kerusakan tambahan...",
  ui_story_5031_50310101_15_dialog_content = "Hei Bos, Anda bisa memasukkan beberapa sen, Anda tahu.",
  ui_story_5031_50310101_16_dialog_content = "Kita tidak bisa melakukan gladi bersih jika peralatan kita belum siap!",
  ui_story_5031_50310101_17_dialog_content = "Mengingat betapa berbakatnya kami, saya ragu kami bahkan perlu berlatih!",
  ui_story_5031_50310101_18_dialog_content = "Subli... Itu bukan cara yang baik untuk berbicara dengan Ringmaster Jeno.",
  ui_story_5031_50310101_19_dialog_content = "Hmm? Kami sedang mengerjakannya saat kami berbicara.",
  ui_story_5031_50310101_20_dialog_content = "Persediaan Elvis akhirnya datang. Mereka sedang memberikan sentuhan akhir pada peralatanmu sekarang.",
  ui_story_5031_50310101_21_dialog_content = "Jika kalian bertiga tidak ingin berlatih, pergilah dan cari tempat untuk beristirahat.",
  ui_story_5031_50310101_22_dialog_content = "Rainbow, cari ekstra yang mengaku bisa berbicara dengan binatang dan membawanya.",
  ui_story_5031_50310101_23_dialog_content = "Dia bisa menggantikan penjinak binatang yang masih sakit karena makan es serut.",
  ui_story_5031_50310101_24_dialog_content = "Diterima!",
  ui_story_5031_50310101_25_dialog_content = "Apakah Anda siap, Bu Fia?",
  ui_story_5031_50310101_26_dialog_content = "J-Sebentar!",
  ui_story_5031_50310101_27_dialog_content = "Ayo, Bika! Di sini, tolong!",
  ui_story_5031_50310101_28_dialog_content = "Hai.",
  ui_story_5031_50310101_29_dialog_content = "Seperti yang saya katakan, Bica. Lompat dan lakukan jungkir balik, oke?",
  ui_story_5031_50310101_30_dialog_content = "Hai!",
  ui_story_5031_50310101_31_dialog_content = "Tolong, Bika! Sekali ini saja, maukah kau mendengarkanku? Pemimpin sirkus yang tampak menakutkan itu masih menonton!",
  ui_story_5031_50310101_32_dialog_content = "Hai!!",
  ui_story_5031_50310101_33_dialog_content = "Aduh! Tenang, aku akan minta maaf, berhentilah menggigitku!",
  ui_story_5031_50310101_34_dialog_content = "Berhenti, berhenti, berhenti!!",
  ui_story_5031_50310101_35_dialog_content = "Apa yang terjadi di atas sana? Selesaikan masalah Anda di luar panggung, jangan mengganggu latihan!",
  ui_story_5031_50310101_36_dialog_content = "Pemimpin sirkus Jeno!",
  ui_story_5031_50310101_37_dialog_content = "Apa? Apakah Anda dan teman kecil Anda akhirnya selesai mengobrol?",
  ui_story_5031_50310101_38_dialog_content = "Itu tidak akan mendengarkan sepatah kata pun yang saya katakan, Ringmaster Jeno! Sudah benar-benar manja busuk!",
  ui_story_5031_50310101_39_dialog_content = "Manja busuk, katamu?",
  ui_story_5031_50310101_40_dialog_content = "Betul sekali! Dan itu menggigitku dengan sangat keras sekarang juga!",
  ui_story_5031_50310101_41_dialog_content = "Oh, itu sangat normal.",
  ui_story_5031_50310101_42_dialog_content = "Normal?!",
  ui_story_5031_50310101_43_dialog_content = "Sebagai bagian dari sirkus, mereka berhak atas hak istimewa yang sama seperti orang lain. Yakni, mereka bebas menolak pekerjaan apa pun kapan pun mereka merasa tidak ingin bekerja.",
  ui_story_5031_50310101_44_dialog_content = "Apa?!",
  ui_story_5031_50310101_45_dialog_content = "Sirkus ini tidak seperti yang pernah saya baca! Bahkan tidak dekat!",
  ui_story_5031_50310101_46_dialog_content = "Semua sirkus dalam buku memperlakukan hewan mereka dengan kejam dan menggunakan rasa takut untuk membuat mereka tampil. Maksudmu memberitahuku sirkusmu tidak melakukan itu?",
  ui_story_5031_50310101_47_dialog_content = "Dan apa yang pernah memberi Anda ide itu?",
  ui_story_5031_50310101_48_dialog_content = "Saya belum pernah mendengar metode seperti itu... Mengapa saya, atau orang lain, menyakiti mereka? Bagaimanapun, mereka bukan hanya sesama artis kita, tetapi juga teman-teman kita yang terkasih dan penting.",
  ui_story_5031_50310101_49_dialog_content = "Lihat saja Bica ini, dan bulunya yang lembut dan halus. Mengapa ada orang yang menyakiti sesuatu yang begitu berharga?",
  ui_story_5031_50310101_50_dialog_content = "Hai!",
  ui_story_5031_50310101_51_dialog_content = "Bagaimanapun, sirkus saya tidak akan pernah menganiaya pemain hewan kami seperti itu. Tidak sekarang, tidak pernah.",
  ui_story_5031_50310101_52_dialog_content = "Setiap penjinak yang datang sebelum Anda dapat menemukan cara untuk memimpin mereka melalui penampilan mereka. Anda juga harus menemukan jalan Anda sendiri.",
  ui_story_5031_50310101_53_dialog_content = "A-Kamu pikir kamu sedang berbicara dengan siapa?!",
  ui_story_5031_50310101_54_dialog_content = "*Menangis* Saya ingin Anda tahu, nama saya Fia, ahli ekstrozoologi terhebat di dunia! Hubungan saya dengan binatang ajaib lebih kuat dari orang lain!",
  ui_story_5031_50310101_55_dialog_content = "Bagaimana... Bagaimana mungkin aku bisa kalah...",
  ui_story_5031_50310101_56_dialog_content = "Jangan khawatir, PlayerName. Pertunjukan balet bukanlah tantangan bagi saya.",
  ui_story_5031_50310101_57_dialog_content = "Saya tidak pernah berpikir saya akan melihat Anda menari balet, Carleen.",
  ui_story_5031_50310101_58_dialog_content = "Di Colossus, saya pernah mendengar Lumopolis Aurorian lain berbicara tentang keterampilan balet Anda yang mengesankan. Seseorang pernah berkata bahwa Anda bahkan membuat kagum seorang instruktur profesional dengan penampilan Anda!",
  ui_story_5031_50310101_59_dialog_content = "Benarkah itu? Jika demikian, mau tidak mau saya merasa senang melihatnya juga!",
  ui_story_5031_50310101_60_dialog_content = "PlayerName!!",
  ui_story_5031_50310101_61_dialog_content = "fia? Bukankah kamu seharusnya melatih penampilan penjinakan binatang buasmu? Apa yang kamu lakukan di sini?",
  ui_story_5031_50310101_62_dialog_content = "Wah, wah... Monster kecil busuk itu membuatku gila! Mereka tidak mendengarkan karena mereka diizinkan untuk tidak bekerja kapan pun mereka mau!",
  ui_story_5031_50310101_63_dialog_content = "Saat aku memikirkan itu... dan bagaimana tuanku sendiri mengaturku... aku... aku... Waaaaaaaah!!!",
  ui_story_5031_50310101_64_dialog_content = "H-Hei, sekarang! Jangan menangis, Fia...",
  ui_story_5031_50310101_65_dialog_content = "Anda seharusnya menjadi ahli ekstrozoologi terhebat di dunia, ingat?",
  ui_story_5031_50310101_66_dialog_content = "Saya tahu itu! Jadi mengapa \"ahli ekstrozoologi terhebat di dunia\" masih harus sibuk sepanjang hari melakukan perintah tuannya?!",
  ui_story_5031_50310101_67_dialog_content = "Cobalah untuk tidak memikirkannya, oke? Ingat caramu biasanya mengejekku? Anda membutuhkan energi semacam itu sekarang!",
  ui_story_5031_50310101_68_dialog_content = "APA?!",
  ui_story_5031_50310101_69_dialog_content = "Yah, maksudku... Ingat semua kesulitan yang kita atasi bersama? Itu semua untuk mewujudkan impian terbesar Anda!",
  ui_story_5031_50310101_70_dialog_content = "Wah... Impian terbesarku... dan kesulitan yang kita atasi...",
  ui_story_5031_50310101_71_dialog_content = "<color=#e8d9bb>Tepat setelah tiba di Harbour City</color>",
  ui_story_5031_50310101_72_dialog_content = "Terima kasih sudah mengundang Vice dan saya ke Harbour City, Carleen.",
  ui_story_5031_50310101_73_dialog_content = "Tempat ini sangat bagus, bukan? Sangat tenang dan damai... Tempat yang sempurna untuk beristirahat dan bersantai!",
  ui_story_5031_50310101_74_dialog_content = "Saya sangat senang semua orang bisa ikut juga!",
  ui_story_5031_50310101_75_dialog_content = "Dengan senang hati. Semua orang telah bekerja sangat keras akhir-akhir ini, jadi saya pikir kita semua bisa menggunakan waktu istirahat untuk memulihkan tubuh dan pikiran kita.",
  ui_story_5031_50310101_76_dialog_content = "Saya hanya seorang gadis kecil terakhir kali saya datang ke Harbour City, tetapi itu meninggalkan kesan yang mendalam bagi saya.",
  ui_story_5031_50310101_77_dialog_content = "Saya tidak pernah berpikir tempat ini akan makmur begitu banyak, meskipun. Pemimpin kota saat ini pastilah pemimpin yang bijaksana.",
  ui_story_5031_50310101_78_dialog_content = "<size=33>Menemukan Anda...</size>",
  ui_story_5031_50310101_79_dialog_content = "Anda pikir dia seperti Tuhan Schwartz?",
  ui_story_5031_50310101_80_dialog_content = "Melihat ekspresi bahagia di wajah semua orang di sini... Itu benar-benar membuatku bertanya-tanya orang macam apa yang bertanggung jawab di sekitar sini.",
  ui_story_5031_50310101_81_dialog_content = "Aku... tidak percaya keduanya sangat mirip.",
  ui_story_5031_50310101_82_dialog_content = "Karena sopan santun, kita harus mengunjungi laird kota sekarang karena kita di sini.",
  ui_story_5031_50310101_83_dialog_content = "Saya melihat poster di jalan barusan, itu mengatakan sesuatu tentang sirkus dan karnaval di salah satu kapal pesiar besar?",
  ui_story_5031_50310101_84_dialog_content = "Kita juga bisa bertanya lebih banyak kepada laird kota tentang itu.",
  ui_story_5031_50310101_85_dialog_content = "Jika kita di sini untuk bersantai, maka ini adalah cara yang bagus untuk memulai! Pengalaman \"liburan musim panas\" yang nyata!",
  ui_story_5031_50310101_86_dialog_content = "Ya! Saya tidak keberatan bertanya tentang apa lagi yang harus dilakukan di sini di Harbour City! Atau suguhan lezat apa yang mereka tawarkan!",
  ui_story_5031_50310101_87_dialog_content = "Vice hampir tidak bisa menahan kegembiraannya ... Kurasa sudah terlalu lama kita tidak istirahat.",
  ui_story_5031_50310101_88_dialog_content = "<size=33>Target terkunci—PlayerName!</size>",
  ui_story_5031_50310101_89_dialog_content = "Nah, apa yang kita tunggu? Mari kita goo—<size=50>ADUH!</size>",
  ui_story_5031_50310101_90_dialog_content = "Ow ow! Punggungku!",
  ui_story_5031_50310101_91_dialog_content = "(Tunggu, ini sepertinya sangat familiar...)",
  ui_story_5031_50310101_92_dialog_content = "Tetap kembali, atau aku akan memanggil bantuan! Saya sungguh-sungguh!",
  ui_story_5031_50310101_93_dialog_content = "Pergi-",
  ui_story_5031_50310101_94_option_content = "Paksa... Aduh!!",
  ui_story_5031_50310101_95_dialog_content = "Punggungku!!",
  ui_story_5031_50310101_96_dialog_content = "halo halo!",
  ui_story_5031_50310101_97_dialog_content = "Kerja bagus, Kylo. Oke, mundur melalui hutan seperti yang direncanakan!",
  ui_story_5031_50310101_98_dialog_content = "Tapi aku hanya... Dengar, aku hanya ingin seorang teman.",
  ui_story_5031_50310101_99_dialog_content = "lihat...",
  ui_story_5031_50310101_100_dialog_content = "Semua orang bilang aku hanya bisa berteman dengan binatang yang menakjubkan. Aku hanya ingin membuktikan bahwa itu tidak benar, dan bahwa aku juga bisa berteman dengan Aurorian dan Caelestites...",
  ui_story_5031_50310101_101_dialog_content = "Heehee... Hei, PlayerName, ini menjadikanmu teman pertamaku!",
  ui_story_5031_50310101_102_dialog_content = "Saya sangat senang Anda adalah teman saya, PlayerName!",
  ui_story_5031_50310101_103_dialog_content = "Lihat, Guru! Saya membuat teman!",
  ui_story_5031_50310101_104_dialog_content = "J-Jadi itu benar-benar kamu, Fia!!",
  ui_story_5031_50310101_105_dialog_content = "Kenapa kamu menyerangku dari tempat sampah itu?!",
  ui_story_5031_50310101_106_dialog_content = "Heee! Gotcha, PlayerName!",
  ui_story_5031_50310101_107_dialog_content = "Fi?",
  ui_story_5031_50310101_108_dialog_content = "Ya, ini Fia. Jangan pedulikan dia, dia memang begitu.",
  ui_story_5031_50310101_109_dialog_content = "Jadi ini extrozoologist kecil yang kamu temui sebelumnya?",
  ui_story_5031_50310101_110_dialog_content = "Saya pernah mendengar tentang mereka dan bidang studi mereka, tetapi saya tidak pernah berharap untuk bertemu dengan yang begitu muda.",
  ui_story_5031_50310101_111_dialog_content = "Sudah lama, Fia.",
  ui_story_5031_50310101_112_dialog_content = "Hai, Vice! Lama tidak bertemu!",
  ui_story_5031_50310101_113_dialog_content = "Izinkan saya untuk memperkenalkan diri, Nona Carleen. Nama saya Fia, dan saya ekstrozoologi nomor satu di seluruh dunia!",
  ui_story_5031_50310101_114_dialog_content = "Atau setidaknya saya akan suatu hari nanti. Magang saya baru saja berakhir, jadi saya masih memiliki banyak ruang untuk ditingkatkan. Jika saya membuat masalah bagi Anda di masa depan, harap bersabar dengan saya!",
  ui_story_5031_50310101_115_dialog_content = "Senang bertemu dengan Anda. saya Carleen dari Lumopolis. Anda tahu, Anda sangat mengingatkan saya pada Raphael.",
  ui_story_5031_50310101_116_dialog_content = "Saya harus memperkenalkan Anda ketika ada kesempatan. Saya membayangkan kalian berdua akan bergaul dengan cukup baik.",
  ui_story_5031_50310101_117_dialog_content = "Tunggu sebentar...",
  ui_story_5031_50310101_118_dialog_content = "Kenapa kamu tiba-tiba bertingkah begitu imut dan polos?",
  ui_story_5031_50310101_119_dialog_content = "A-Apa yang kamu bicarakan, PlayerName? Aku selalu manis ini, bukan? Tidak baik mengatakan hal seperti itu, tahu!",
  ui_story_5031_50310101_120_dialog_content = "Ya, tentu... Mari kita lihat berapa lama kamu bisa bertahan kali ini, Fia.",
  ui_story_5031_50310101_121_dialog_content = "Lagi pula, apa yang Anda lakukan di sini di tempat pertama? Dan dimana Kyllo?",
  ui_story_5031_50310101_122_dialog_content = "Ssst! Tidak begitu keras! Jika Anda harus tahu, Kyllo dan saya berada di <color=#FFB400>misi rahasia</color>. Perintah Guru!",
  ui_story_5031_50310101_123_dialog_content = "Kyllo sedang menyelidiki perairan terdekat saat kita berbicara!",
  ui_story_5031_50310101_124_dialog_content = "\"Misi rahasia\"? Dia tidak mengirimmu mengejar angsa liar lagi, kan?",
  ui_story_5031_50310101_125_dialog_content = "Juga... Kyllo sangat besar terakhir kali aku melihat kalian! Tidakkah menurutmu itu akan menarik terlalu banyak perhatian?",
  ui_story_5031_50310101_126_dialog_content = "Hah! Itu adalah bentuk raksasanya! Sejak itu Kyllo menguasai seni beralih antar bentuk, kau tahu?",
  ui_story_5031_50310101_127_dialog_content = "Guru berkata bahwa dengan pelatihan yang cukup... bahkan mungkin mencapai bentuk manusia!",
  ui_story_5031_50310101_128_dialog_content = "Itu... terdengar sedikit menakutkan, jujur saja.",
  ui_story_5031_50310101_129_dialog_content = "Jangan takut! Tidak ada yang perlu ditakutkan, selama kamu tidak membuat Kyllo marah!",
  ui_story_5031_50310101_130_dialog_content = "Tapi cukup tentang Kyllo! Misi yang ada sangat penting, dan itu ada hubungannya dengan <color=#FFB400>eksotik</color> binatang yang menakjubkan!",
  ui_story_5031_50310101_131_dialog_content = "Erm... Aku tidak bermaksud menguping, dengan cara apapun...",
  ui_story_5031_50310101_132_dialog_content = "Tapi tidakkah kamu pikir kamu harus mengecilkan suaramu, Fia?",
  ui_story_5031_50310101_133_dialog_content = "Juga, apakah aman untuk berasumsi bahwa alasan Anda mencari PlayerName adalah untuk merekrutnya untuk \"misi rahasia\" Anda?",
  ui_story_5031_50310101_134_dialog_content = "Ups! Kira saya menjadi sedikit keras, ya?",
  ui_story_5031_50310101_135_dialog_content = "Yah, karena kalian berdua adalah teman dekat PlayerName, kurasa aku bisa mempercayaimu dengan detailnya.",
  ui_story_5031_50310101_136_dialog_content = "Sekarang, izinkan saya menjelaskan situasinya sejelas mungkin.",
  ui_story_5031_50310101_137_dialog_content = "Semuanya dimulai beberapa hari yang lalu ...",
  ui_story_5031_50310101_138_dialog_content = "Apa! Kota Pelabuhan? Betulkah?!",
  ui_story_5031_50310101_139_dialog_content = "Wah! Kudengar pemandangannya luar biasa di sana, dan ada banyak makanan enak juga!",
  ui_story_5031_50310101_140_dialog_content = "Saya tidak pernah tahu Anda begitu peduli, Guru! Mengirim saya berlibur setelah semua kerja keras yang saya lakukan ...",
  ui_story_5031_50310101_141_dialog_content = "Pantai-pantai di sana cukup terkenal, sekarang saya ingat. Aku harus pergi memilih baju renang!",
  ui_story_5031_50310101_142_dialog_content = "Anda menjadi sangat maju dari diri Anda sendiri, Anda tahu ...",
  ui_story_5031_50310101_143_dialog_content = "Jika itu perjalanan yang menyenangkan, tas saya pasti sudah dikemas.",
  ui_story_5031_50310101_144_dialog_content = "Aku mengirimmu untuk tugas, Fia, bukan liburan.",
  ui_story_5031_50310101_145_dialog_content = "Ini sejumlah uang untuk biaya perjalanan. Pergi.",
  ui_story_5031_50310101_146_dialog_content = "Hai! Apa yang harus saya lakukan dengan perubahan bodoh seperti ini?!",
  ui_story_5031_50310101_147_dialog_content = "T-Tunggu, Tuan! Kemana kamu pergi?!",
  ui_story_5031_50310101_148_dialog_content = "Grr... Seharusnya aku tahu! Tuanku yang tidak berguna itu tidak akan pernah sebaik itu!",
  ui_story_5031_50310101_149_dialog_content = "Uh... Kira-kira kamu bisa langsung ke inti ceritanya, Fia? Kurasa kita sudah cukup mendengar tentang tuanmu...",
  ui_story_5031_50310101_150_dialog_content = "Aku mengerti!",
  ui_story_5031_50310101_151_dialog_content = "Ahem... Tujuan dari misi kami adalah binatang ajaib yang dikenal sebagai <color=#FFB400>paus awan</color>.",
  ui_story_5031_50310101_152_dialog_content = "Tuanku telah melacak Lumina khusus untuk beberapa waktu sekarang. Ada tanda-tanda itu datang ke perairan Harbour City.",
  ui_story_5031_50310101_153_dialog_content = "Tapi setelah kami tiba, Lumina tiba-tiba menghilang...",
  ui_story_5031_50310101_154_dialog_content = "Teori saya adalah karena menghilang begitu tiba-tiba dan begitu lengkap, Cloudwhale pasti tidak meninggalkan Harbour City... Sebaliknya, sesuatu pasti telah terjadi padanya!",
  ui_story_5031_50310101_155_dialog_content = "Begitu... Kedengarannya tidak menyenangkan, memang.",
  ui_story_5031_50310101_156_dialog_content = "Jangan bercanda, dan terlebih lagi... Tuanku mengatakan bahwa kekuatan Cloudwhale ini bahkan lebih besar dari Drakolion.",
  ui_story_5031_50310101_157_dialog_content = "Legenda mengatakan bahwa kekuatannya menyebabkan Eclipsites meringkuk ketakutan, dan Lumina-nya dapat menghilangkan Darkflow yang paling tebal sekalipun.",
  ui_story_5031_50310101_158_dialog_content = "Cloudwhale juga dikatakan memiliki rentang hidup yang sangat panjang, jadi sangat kecil kemungkinannya ia mati karena sebab alami.",
  ui_story_5031_50310101_159_dialog_content = "Mempertimbangkan semua ini, tuanku khawatir itu jatuh ke tangan yang salah.",
  ui_story_5031_50310101_160_dialog_content = "Cloudwhale pada dasarnya jinak, tetapi jika kekuatannya disalahgunakan oleh orang yang salah, hasilnya bisa menjadi bencana...",
  ui_story_5031_50310101_161_dialog_content = "Jika semuanya seperti yang Anda katakan... maka kita tidak bisa berdiam diri.",
  ui_story_5031_50310101_162_dialog_content = "Apakah Anda memiliki petunjuk tentang keberadaannya?",
  ui_story_5031_50310101_163_dialog_content = "Hmm... Tidak ada sama sekali! Setelah tuanku menyerahkan tugas ini padaku, dia pergi tanpa mengucapkan sepatah kata pun...",
  ui_story_5031_50310101_164_dialog_content = "Jadi selama ini kau berkeliaran tanpa tujuan di sekitar Harbour City sampai kau menemukan jejakku? Lalu kau baru saja menyergapku di sini?",
  ui_story_5031_50310101_165_dialog_content = "Anda memukul tepat di kepala, PlayerName! Bukan hanya itu, tetapi uang yang Guru berikan kepada saya untuk biaya perjalanan semuanya dihabiskan...",
  ui_story_5031_50310101_166_dialog_content = "Saya tidak tahu apa yang harus dilakukan jika Anda tidak muncul, PlayerName!",
  ui_story_5031_50310101_167_dialog_content = "Sudah kuduga.",
  ui_story_5031_50310101_168_dialog_content = "Mengapa kita tidak mulai dengan mengumpulkan informasi? Kami baru saja dalam perjalanan untuk mengunjungi laird kota.",
  ui_story_5031_50310101_169_dialog_content = "Dia mungkin tahu satu atau dua hal tentang situasinya.",
  ui_story_5031_50310101_170_dialog_content = "Oke! saya akan mendengarkan Carleen. Ayo pergi!",
  ui_story_5031_50310101_171_dialog_content = "Hai! Mengapa sibuk di depan, Fia? Apakah Anda bahkan tahu ke mana Anda pergi?",
  ui_story_5031_50310101_172_dialog_content = "Dia benar-benar bersemangat, bukan?",
  ui_story_5031_50310201_1_dialog_content = "Tuan tanah <color=#FFB400>Elvis</color>, para prajurit yang setia kepada Anda sudah siap sekarang.",
  ui_story_5031_50310201_2_dialog_content = "Semuanya berjalan seperti yang Anda rencanakan, Pak. Kami akan menggunakan transportasi perbekalan dan kembang api ke Emerald sebagai penutup.",
  ui_story_5031_50310201_3_dialog_content = "Ya saya mengerti.",
  ui_story_5031_50310201_4_dialog_content = "Bagus sekali, Kapten Patou. Mungkin hanya kamu yang bisa kupercaya kali ini...",
  ui_story_5031_50310201_5_dialog_content = "Seperti yang Anda katakan, Pak. Tolong serahkan sisanya padaku. Merupakan kehormatan besar melayani laird saya.",
  ui_story_5031_50310201_6_dialog_content = "Sayangnya... Jika ada lebih banyak waktu untuk menunggu, saya tidak akan menempatkan Anda pada risiko seperti itu.",
  ui_story_5031_50310201_7_dialog_content = "Laird Elvis! Kapten Patou! F-Maafkan gangguannya!",
  ui_story_5031_50310201_8_dialog_content = "Bagaimana kasar... Saya pikir saya membuatnya sangat jelas bahwa tidak ada yang diizinkan masuk?",
  ui_story_5031_50310201_9_dialog_content = "Y-Ya, Kapten. Maafkan saya, tetapi seorang bangsawan telah datang berkunjung...",
  ui_story_5031_50310201_10_dialog_content = "Apa yang mulia? Tenangkan dirimu, prajurit! Anda berada dalam pelayanan Rumah Modali, sekarang bertindak seperti itu!",
  ui_story_5031_50310201_11_dialog_content = "Dipahami! I-Ini Nona Carleen, Putri Lumopolis, Pak!",
  ui_story_5031_50310201_12_dialog_content = "Apa? Putri Carleen dari Lumopolis, katamu?",
  ui_story_5031_50310201_13_dialog_content = "Berdasarkan Carleen, Harbour City berada di bawah yurisdiksi dan perlindungan resmi Lumopolis tepat sebelum Krisis Darkover.",
  ui_story_5031_50310201_14_dialog_content = "Apakah itu berarti mereka mengandalkan kekuatan mereka sendiri untuk mempertahankan rumah mereka sebelum itu?",
  ui_story_5031_50310201_15_dialog_content = "Dokumen sejarah menyatakan bahwa Harbour City pernah penuh dengan Eclipsites. Penduduk malang itu berjuang siang dan malam agar tidak jatuh ke momok Eclipsite.",
  ui_story_5031_50310201_16_dialog_content = "Sepanjang pertempuran yang berkepanjangan, para penguasa dari House <color=#FFB400>Modali</color>, yang memiliki Lumina yang sangat besar, bersekutu dengan pembangkit tenaga listrik lainnya.",
  ui_story_5031_50310201_17_dialog_content = "Setelah pertempuran berdarah yang tak terhitung jumlahnya, mereka akhirnya bisa sepenuhnya mengusir penjajah itu.",
  ui_story_5031_50310201_18_dialog_content = "Jadi...",
  ui_story_5031_50310201_19_dialog_content = "Diberkati oleh <color=#FFB400>Dewa Cahaya</color>, kota ini jarang diganggu oleh Eclipsites sejak itu.",
  ui_story_5031_50310201_20_dialog_content = "Orang-orang sekarang menjalani hidup mereka dalam damai, dan ekonomi telah berkembang secara signifikan.",
  ui_story_5031_50310201_21_dialog_content = "Saya merasa terhormat bahwa Anda sangat mengenal sejarah Harbour City, Yang Mulia.",
  ui_story_5031_50310201_22_dialog_content = "Saya juga berterima kasih kepada Anda dan Lumopolis atas perlindungan Anda yang murah hati. Lagipula, kita tidak akan pernah selamat dari Krisis Darkover tergantung pada <color=#FFB400>Berkat Dewa Cahaya</color> sendiri.",
  ui_story_5031_50310201_23_dialog_content = "Saya Elvis Modali, keturunan dari House Modali dan laird dari Harbour City.",
  ui_story_5031_50310201_24_dialog_content = "(Aneh... Kenapa Lumina di sekitar pria ini begitu redup?)",
  ui_story_5031_50310201_25_dialog_content = "Salam, Laird Elvis. Saya berdoa agar kunjungan kami tidak menyebabkan Anda terlalu banyak ketidaknyamanan.",
  ui_story_5031_50310201_26_dialog_content = "Tentu saja tidak, Yang Mulia. Saya hanya berharap Anda mengirim kabar lebih cepat, sehingga saya bisa menerima Anda dan teman-teman Anda dengan baik.",
  ui_story_5031_50310201_27_dialog_content = "Itu tidak perlu, karena kami berharap dapat melihat Anda tanpa keriuhan atau formalitas yang biasa. Tolong jangan khusus dengan kami.",
  ui_story_5031_50310201_28_dialog_content = "Bagaimanapun, kami datang ke Harbour City bukan sebagai delegasi dalam bentuk apa pun, tetapi sebagai pelancong biasa yang sedang berlibur.",
  ui_story_5031_50310201_29_dialog_content = "Yakinlah, Yang Mulia, saya sepenuhnya memahami penderitaan Anda. Bolehkah saya berasumsi bahwa kedua teman Anda ini tidak lain adalah Nona Vice dan Caelestit yang legendaris?",
  ui_story_5031_50310201_30_dialog_content = "Salam, saya PlayerName.",
  ui_story_5031_50310201_31_dialog_content = "Dan saya Vice, Laird Elvis. Meskipun saya tidak pernah berharap Anda mengenali PlayerName, apalagi saya sendiri.",
  ui_story_5031_50310201_32_dialog_content = "U-Um...!",
  ui_story_5031_50310201_33_dialog_content = "Oh? Dan siapa ini?",
  ui_story_5031_50310201_34_dialog_content = "H-Halo! Namaku Fia! Saya seorang ahli ekstrozoologi profesional, dan juga teman PlayerName, Vice, dan Carleen!",
  ui_story_5031_50310201_35_dialog_content = "Seorang ahli ekstrozoologi? Hehe, begitu... Senang bertemu denganmu, Nona Fia.",
  ui_story_5031_50310201_36_dialog_content = "Saya sudah menyiapkan jamuan makan. Sebagai laird of Harbour City, saya akan merasa terhormat jika Anda bergabung dengan saya untuk makan.",
  ui_story_5031_50310201_37_dialog_content = "Begitu... Dan apakah kamu cukup tertarik dengan acara yang diadakan di atas kapal <color=#FFB400>Zamrud</color>, Merindukan Vice?",
  ui_story_5031_50310201_38_dialog_content = "Sebenarnya, akulah yang mengundang <color=#FFB400>the Illusionist & Old Bill's Circus</color> dan Zamrud ke Kota Pelabuhan.",
  ui_story_5031_50310201_39_dialog_content = "Harapan saya adalah mereka dapat memberikan pengalaman yang tak terlupakan kepada orang-orang di kota saya musim panas ini.",
  ui_story_5031_50310201_40_dialog_content = "Apakah seluruh kapal milik sirkus? Pasti ada kesan romantis...",
  ui_story_5031_50310201_41_dialog_content = "Memang. Jika Anda dan teman Anda tertarik, Anda selalu dapat mempertimbangkan untuk ikut serta dalam perayaan tersebut.",
  ui_story_5031_50310201_42_dialog_content = "Pemimpin sirkus adalah teman masa kecil saya. Meskipun kami belum bertemu cukup lama, dia mampu dan dapat dipercaya.",
  ui_story_5031_50310201_43_dialog_content = "Saya tidak ragu bahwa dia akan memberikan hiburan terbaik untuk seluruh kota.",
  ui_story_5031_50310201_44_dialog_content = "Ah... Kapal pesiar!",
  ui_story_5031_50310201_45_dialog_content = "Um, permisi! Bisakah salah satu temanmu menunjukkan bagian dalam kapal, Laird Elvis?",
  ui_story_5031_50310201_46_dialog_content = "Hmm?",
  ui_story_5031_50310201_47_dialog_content = "<size=33>Fi! Permintaan aneh macam apa itu?</size>",
  ui_story_5031_50310201_48_dialog_content = "Saya baru ingat Kyllo memberi tahu saya bahwa sebuah kapal besar yang aneh telah berlabuh di Harbour City belum lama ini.",
  ui_story_5031_50310201_49_dialog_content = "Jika Cloudwhale tiba-tiba menghilang, itu bisa saja disimpan di dalam kapal semacam itu!",
  ui_story_5031_50310201_50_dialog_content = "Maaf, tapi sepertinya saya tidak bisa mengabulkan permintaan ini.",
  ui_story_5031_50310201_51_dialog_content = "Eh... Kenapa?",
  ui_story_5031_50310201_52_dialog_content = "Saya sendiri tidak yakin dengan detailnya, tetapi ini menyangkut salah satu aturan sirkus.",
  ui_story_5031_50310201_53_dialog_content = "Kemarin, saya naik kapal untuk berbicara dengan <color=#FFB400>Jeno</color>, pemimpin sirkus, tentang menyediakan perbekalan untuk rombongannya.",
  ui_story_5031_50310201_54_dialog_content = "Saya pikir Jeno akan memberi saya tur kabin, tetapi dia hanya bersedia menunjukkan saya sejauh koridor ketika mendiskusikan bisnis kami.",
  ui_story_5031_50310201_55_dialog_content = "Karena penasaran, saya menyebutkan bahwa saya ingin melihat bagian dalam kapal yang agung dan menakjubkan ini...",
  ui_story_5031_50310201_56_dialog_content = "Tapi dia menolakku, menyatakan bahwa sudah menjadi kebijakan mereka bahwa hanya anggota sirkus yang boleh masuk lebih jauh ke dalam kabin.",
  ui_story_5031_50310201_57_dialog_content = "Sebagai teman dan mitra bisnis, ini sejauh yang saya bisa lakukan. Saya khawatir entri untuk Anda akan semakin jauh dari pertanyaan.",
  ui_story_5031_50310201_58_dialog_content = "Apakah ada alasan tertentu Anda ingin memasuki kapal? Saya mungkin bisa bernegosiasi dengan pemimpin sirkus atas nama Anda.",
  ui_story_5031_50310201_59_dialog_content = "Sebenarnya, Fia...",
  ui_story_5031_50310201_60_dialog_content = "Ahahaha! Itu karena penasaran juga! Saya berasal dari tempat yang sangat kecil, dan saya belum pernah melihat bagian dalam kapal sebelumnya.",
  ui_story_5031_50310201_61_dialog_content = "<size=33>Jangan lupa, kita sedang dalam misi rahasia! Kami tidak dapat menumpahkan informasi apa pun tentang tujuan eksotis kami!</size>",
  ui_story_5031_50310201_62_dialog_content = "Saya mengerti bagaimana perasaan Anda, Nona Fia. Lagipula, kapal sebesar Zamrud bukanlah hal yang biasa, bahkan di Harbour City.",
  ui_story_5031_50310201_63_dialog_content = "Saya yakin Anda juga tidak sendirian. Banyak pengunjung karnaval pasti sangat ingin tahu lebih banyak tentang kapal dan apa yang ada di dalamnya.",
  ui_story_5031_50310201_64_dialog_content = "Baiklah... Izinkan saya untuk mencoba berbicara dengan Jeno sekali lagi.",
  ui_story_5031_50310201_65_dialog_content = "Betulkah? Terima kasih banyak Pak!",
  ui_story_5031_50310201_66_dialog_content = "Dengan senang hati, meskipun tolong cobalah untuk tidak terlalu berharap terlalu tinggi. Jeno dengan cepat menolak bahkan sponsornya.",
  ui_story_5031_50310201_67_dialog_content = "Namun, akan ada banyak perayaan lain untuk diikuti di dek, seperti kontes memasak, karnaval, dan pertunjukan sirkus.",
  ui_story_5031_50310201_68_dialog_content = "Saya percaya mereka akan pergi jauh dalam memuaskan rasa ingin tahu Anda juga, Nona Fia.",
  ui_story_5031_50310201_69_dialog_content = "*Batuk-batuk*",
  ui_story_5031_50310201_70_dialog_content = "Pak!",
  ui_story_5031_50310201_71_dialog_content = "Aku baik-baik saja, Patou.",
  ui_story_5031_50310201_72_dialog_content = "Tampaknya dalam kegembiraan Yang Mulia dan kunjungan semua orang, saya benar-benar lupa minum obat saya.",
  ui_story_5031_50310201_73_dialog_content = "Laird Elvis...",
  ui_story_5031_50310201_74_dialog_content = "Terima kasih atas keramahan Anda yang ramah.",
  ui_story_5031_50310201_75_dialog_content = "Kehormatan adalah milikku, Yang Mulia. Saya berharap bahwa kesehatan saya yang hilang sesaat tidak merusak kesenangan Anda.",
  ui_story_5031_50310201_76_dialog_content = "Sama sekali tidak. Tolong jaga dirimu baik-baik, Laird.",
  ui_story_5031_50310201_77_dialog_content = "Kami akan segera pergi ke Zamrud untuk melihat karnaval. Tolong jangan bangun demi kami. Kami akan segera berangkat.",
  ui_story_5031_50310201_78_dialog_content = "... Saya mengerti. Namun, saya harus menyiapkan hadiah untuk Yang Mulia sebelum saya berangkat ke Zamrud nanti.",
  ui_story_5031_50310201_79_dialog_content = "Merupakan kebiasaan bagi subjek untuk menawarkan hadiah kepada penguasa mereka. Mohon diterima dengan baik, Yang Mulia.",
  ui_story_5031_50310201_80_dialog_content = "Jika Anda bersikeras.",
  ui_story_5031_50310201_81_dialog_content = "Ayo, semuanya. Sudah waktunya untuk pergi.",
  ui_story_5031_50310201_82_dialog_content = "...",
  ui_story_5031_50310201_83_dialog_content = "Pak.",
  ui_story_5031_50310201_84_dialog_content = "Perintahkan orang-orang kita untuk mempersiapkan diri, Patou.",
  ui_story_5031_50310201_85_dialog_content = "Bisakah... Mungkinkah Lumopolis mengetahui tindakan kita begitu cepat?",
  ui_story_5031_50310201_86_dialog_content = "Saya yakin masih terlalu dini untuk mengatakan dengan pasti... Tapi untuk saat ini, kita harus terus mengawasi mereka.",
  ui_story_5031_50310201_87_dialog_content = "Apa pun yang terjadi, rencananya harus dilanjutkan hari ini.",
  ui_story_5031_50310201_88_dialog_content = "Maafkan ketidaktahuan saya, Pak, tetapi bisakah Anda tidak meminta bantuan Ringmaster Jeno?",
  ui_story_5031_50310201_89_dialog_content = "Seperti yang Anda katakan, dia adalah teman masa kecil Anda.",
  ui_story_5031_50310201_90_dialog_content = "Segalanya tidak sesederhana itu, Patou. Sejarah bersama kami tidak berarti saya bisa mempercayainya.",
  ui_story_5031_50310201_91_dialog_content = "Lagi pula, dia menolak permintaan saya untuk melihat bagian dalam kapalnya tanpa ragu-ragu.",
  ui_story_5031_50310201_92_dialog_content = "Menurut temuan saya, dia saat ini berutang kesetiaannya kepada <color=#FFB400>Pesanan Benar</color>.",
  ui_story_5031_50310201_93_dialog_content = "Jika tujuan kami terungkap karena kecerobohan kami... seluruh rencana mungkin akan berantakan dalam sekejap.",
  ui_story_5031_50310201_94_dialog_content = "Pada titik ini, saya tidak yakin apakah saya bisa mempercayai pria itu, yang pernah saya sebut \"teman\" ...",
  ui_story_5031_50310201_95_dialog_content = "Saya mengerti, Pak. Serahkan padaku.",
  ui_story_5031_50310201_96_dialog_content = "Sangat baik. Saya akan terus mencari Jeno untuk melihat apakah dia masih orang yang sama yang pernah saya kenal...",
  ui_story_5031_50310201_97_dialog_content = "Laird Elvis sepertinya orang yang sangat baik, ya? Dia menyambut kami dengan sangat hangat dan juga baik kepada Vice dan saya.",
  ui_story_5031_50310201_98_dialog_content = "Ya, dia tampak jauh lebih baik daripada beberapa bangsawan yang pernah kita temui sebelumnya. Dia tidak membawa dirinya dengan jenis keangkuhan yang sama seperti mereka.",
  ui_story_5031_50310201_99_dialog_content = "Memang. Rumah Modali sangat berbeda dari banyak keluarga bangsawan lainnya. Mereka sangat protektif terhadap orang-orang mereka sendiri, dan juga dicintai oleh banyak orang.",
  ui_story_5031_50310201_100_dialog_content = "Ketika datang ke pemerintahan, keluarga mereka adalah salah satu yang terbaik, tapi sayangnya...",
  ui_story_5031_50310201_101_dialog_content = "Ah... Apa ini ada hubungannya dengan seberapa lemah Lumina-nya?",
  ui_story_5031_50310201_102_dialog_content = "Sepertinya Anda juga memperhatikannya. Ketika Elvis mulai batuk tak terkendali sebelumnya... yah, anggap saja itu bukan karena flu biasa.",
  ui_story_5031_50310201_103_dialog_content = "Bahkan bekas luka di wajahnya... Penyakitnya dikenal orang lain sebagai <color=#FFB400>Sindrom Modali</color>.",
  ui_story_5031_50310201_104_dialog_content = "Jadi bekas luka di wajahnya karena penyakitnya? aku tidak akan pernah menduga...",
  ui_story_5031_50310201_105_dialog_content = "Lalu... Apakah ini serius?",
  ui_story_5031_50310201_106_dialog_content = "Saya tidak mengerti banyak tentang penyakit di luar namanya, jujur. Saya hanya mengetahuinya secara sepintas, ketika saya terlibat dalam studi sejarah saya.",
  ui_story_5031_50310201_107_dialog_content = "Ketika saya menyerah pada rasa ingin tahu saya, saya segera menemukan bahwa informasi mengenai Sindrom Modali dan keluarga itu sendiri sangat langka.",
  ui_story_5031_50310201_108_dialog_content = "Yang saya pelajari adalah bahwa penyakit ini dengan cepat melemahkan Lumina korban dan mencegahnya pulih ke tingkat normal untuk jangka waktu yang lama.",
  ui_story_5031_50310201_109_dialog_content = "Ini tidak melemahkan bagi mereka yang memiliki tingkat Lumina di atas rata-rata, tetapi bagi yang lain... tertular penyakit dengan cepat dan sangat merusak kemampuan mereka untuk menjalani kehidupan normal.",
  ui_story_5031_50310201_110_dialog_content = "Dalam kasus ekstrim, penyakit ini bahkan bisa berakibat fatal.",
  ui_story_5031_50310201_111_dialog_content = "Apakah itu benar-benar buruk?!",
  ui_story_5031_50310201_112_dialog_content = "Ya... Tapi penyakit ini sangat unik dan hanya pernah muncul di Harbour City. Dengan demikian, para sarjana percaya bahwa itu entah bagaimana terikat ke wilayah ini.",
  ui_story_5031_50310201_113_dialog_content = "Orang-orang Harbour City, di sisi lain, sepenuhnya yakin bahwa penyakit itu adalah simbol dari . mereka <color=#FFB400>garis keturunan heroik</color>.",
  ui_story_5031_50310201_114_dialog_content = "Mereka mengatakan bahwa nenek moyang mereka, orang-orang yang menangkis Eclipsites di masa lalu, dengan berani dan rela menanggung kutukan ini demi rakyat mereka.",
  ui_story_5031_50310201_115_dialog_content = "Dengan demikian, keturunan mereka juga memiliki kesempatan untuk mengontraknya.",
  ui_story_5031_50310201_116_dialog_content = "Untungnya, tampaknya kasus yang dikonfirmasi dari penyakit ini telah berkurang secara bertahap selama beberapa tahun terakhir.",
  ui_story_5031_50310201_117_dialog_content = "Oh... begitu, begitu.",
  ui_story_5031_50310201_118_dialog_content = "Anda tidak perlu berpura-pura mengerti semua itu, Anda tahu?",
  ui_story_5031_50310201_119_dialog_content = "T-Tentu saja aku mengerti! Hanya karena aku muda bukan berarti aku bodoh!",
  ui_story_5031_50310201_120_dialog_content = "Bagaimanapun, saya pikir laird memahami nasibnya sendiri lebih baik daripada orang lain.",
  ui_story_5031_50310201_121_dialog_content = "Sama seperti saya—saya dilahirkan untuk menjadi ahli ekstrozoologi terhebat di dunia!",
  ui_story_5031_50310201_122_dialog_content = "Melanjutkan kejayaan generasi yang tak terhitung jumlahnya di masa lalu... Ini pasti menjadi beban yang rumit dan berat untuk ditanggung.",
  ui_story_5031_50310201_123_dialog_content = "Sebagai orang luar, saya tidak berpikir kita memiliki hak untuk menilai situasi sama sekali.",
  ui_story_5031_50310201_124_dialog_content = "Fia membuat poin yang sangat bagus.",
  ui_story_5031_50310201_125_dialog_content = "Ya, dia melakukannya, meskipun dia bisa membuat poin yang sama dengan tidak mengatakan apa-apa juga.",
  ui_story_5031_50310201_126_dialog_content = "Hehe! Bagaimanapun, kita harus benar-benar fokus untuk naik ke Emerald dan melihat-lihat. Ayo pergi!",
  ui_story_5031_50310201_127_dialog_content = "Cepat dan simpan yang eksotis. Selesaikan pencarian ini dan saya akan punya waktu untuk bermain!",
  ui_story_5031_50310201_128_dialog_content = "Tunggu sebentar, Fia! Apa yang membuatmu begitu yakin bisa mengakses bagian dalam Emerald?",
  ui_story_5031_50310201_129_dialog_content = "Saya hanya harus mengandalkan pesona saya yang luar biasa, bukan?",
  ui_story_5031_50310201_130_dialog_content = "Apa \"pesona luar biasa\"... Anda akan lebih beruntung berpura-pura menjadi binatang kecil dan mengikuti audisi untuk sirkus.",
  ui_story_5031_50310201_131_dialog_content = "Ugh!",
  ui_story_5031_50310201_132_dialog_content = "Itu adalah lelucon pendek lainnya, bukan?!",
  ui_story_5031_50310201_133_dialog_content = "Sini!",
  ui_story_5031_50310201_134_dialog_content = "H-Hei, itu sakit! Berhenti menarik begitu keras, Fia!",
  ui_story_5031_50310201_135_dialog_content = "Anda akan langsung ke laut, brengsek besar! Kyllo bisa melemparmu seperti bola, aku peduli!",
  ui_story_5031_50310201_136_dialog_content = "Apa? Apakah Anda menyebut Kyllo segel atau sesuatu? Saya tidak berpikir Kyllo akan menghargai itu!",
  ui_story_5031_50310201_137_dialog_content = "Aku tidak peduli!",
  ui_story_5031_50310201_138_dialog_content = "Wah... Melihat mereka berdebat seperti itu entah bagaimana membuatku lebih nyaman.",
  ui_story_5031_50310201_139_dialog_content = "Ya... Sudah lama kita tidak bersantai seperti ini.",
  ui_story_5031_50310201_140_dialog_content = "Tunggu!",
  ui_story_5031_50310201_141_dialog_content = "A-Baiklah, hentikan! Apa itu, Carleen?",
  ui_story_5031_50310201_142_dialog_content = "Di sana... Apa yang dilakukan Eclipsites di pantai ini?!",
  ui_story_5031_50310201_143_dialog_content = "Bersiaplah untuk pertempuran, dan tetap waspada, semuanya! Ada yang aneh dengan Eclipsites ini...",
  ui_story_5031_50310202_1_dialog_content = "Graah...",
  ui_story_5031_50310202_2_dialog_content = "Mengapa Eclipsites ini begitu lemah...?",
  ui_story_5031_50310202_3_dialog_content = "Anda banyak, apakah Anda baik-baik saja?",
  ui_story_5031_50310202_4_dialog_content = "Tunggu... K-Kamu Putri Carleen! M-Maafkan saya jika Anda terluka... Karena kelalaian saya, Eclipsites itu berhasil melewatinya!",
  ui_story_5031_50310202_5_dialog_content = "Tidak perlu panik. Kami bukan warga negara yang tidak bersenjata dan sangat mampu membela diri.",
  ui_story_5031_50310202_6_dialog_content = "Meskipun demikian, Anda dan anak buah Anda harus tetap waspada setiap saat. Bahaya bisa mengintai di setiap sudut.",
  ui_story_5031_50310202_7_dialog_content = "Dipahami! Terima kasih atas bimbingan Anda, Yang Mulia! Kami akan meningkatkan patroli kami, serta menyelidiki asal usul Eclipsites ini!",
  ui_story_5031_50310202_8_dialog_content = "Sangat bagus, sekarang mulai bekerja, prajurit.",
  ui_story_5031_50310202_9_dialog_content = "Baik, Yang Mulia!",
  ui_story_5031_50310202_10_dialog_content = "Itu sangat keren, Carleen! Anda tampak dan terdengar seperti seorang ratu!",
  ui_story_5031_50310202_11_dialog_content = "Tentu saja dia melakukannya, Fia! Carleen adalah putri Penguasa Lumopolis, dan tentu saja dia akan menjadi penguasa yang bijaksana suatu hari nanti.",
  ui_story_5031_50310202_12_dialog_content = "T-Terima kasih... Tapi aku masih harus banyak belajar.",
  ui_story_5031_50310202_13_dialog_content = "Tapi cukup tentang itu. Zamrud ada di depan, jadi mari kita terus bergerak.",
  ui_story_5031_50310202_14_dialog_content = "Siapa pun yang ingin berpartisipasi dalam kontes memasak, datang ke sini!",
  ui_story_5031_50310202_15_dialog_content = "Sepertinya kita di sini, ya? Tempat ini pasti ramai!",
  ui_story_5031_50310202_16_dialog_content = "Mari kita mulai dengan mengumpulkan informasi terlebih dahulu, PlayerName.",
  ui_story_5031_50310202_17_dialog_content = "Ya, itu masuk akal.",
  ui_story_5031_50310202_18_dialog_content = "Halo, bolehkah saya bertanya tentang karnaval...?",
  ui_story_5031_50310202_19_dialog_content = "Yo! Selamat datang di Illusionist & Old Bill's Circus!",
  ui_story_5031_50310202_20_dialog_content = "Sepertinya ini pertama kalinya kamu melihat sirkus kami, kan? Tidak perlu malu, guys! Benar dengan cara ini!",
  ui_story_5031_50310202_21_dialog_content = "Jangan membuat masalah di atas kapal, oke? Aku tidak akan terlalu baik jika kamu mulai membuat keributan...",
  ui_story_5031_50310202_22_dialog_content = "Ayo, Merylt! Ringmaster Jeno memposting kami di sini untuk menyambut tamu, jadi jangan bermalas-malasan!",
  ui_story_5031_50310202_23_dialog_content = "Nih nih. Sepertinya seseorang datang sekarang, dan dia hanya tipemu! Mengapa Anda tidak menyapa, Merylt?",
  ui_story_5031_50310202_24_dialog_content = "Ah! Subli, jangan paksa aku...",
  ui_story_5031_50310202_25_dialog_content = "Katakanlah, dia benar-benar mirip dengannya, bukan? Merylt, lihat lebih dekat!",
  ui_story_5031_50310202_26_dialog_content = "Hah? Sepertinya siapa? Apa yang kalian berdua lakukan?",
  ui_story_5031_50310202_27_dialog_content = "Dia terlihat seperti pria di poster Umbraton Daily itu! Yang Merylt sembunyikan untuk dirinya sendiri!",
  ui_story_5031_50310202_28_dialog_content = "Er... Apa sebenarnya yang kamu bicarakan?",
  ui_story_5031_50310202_29_dialog_content = "Tunggu, mereka sangat mirip! Anda bukan Caelestit itu, kan?",
  ui_story_5031_50310202_30_dialog_content = "Y-Ya, sebenarnya aku... Tapi bagaimana kalian bertiga tahu tentangku?",
  ui_story_5031_50310202_31_dialog_content = "!!",
  ui_story_5031_50310202_32_dialog_content = "Mengapa Merylt kabur, Subli?",
  ui_story_5031_50310202_33_dialog_content = "Haruskah kita menahan orang ini sekarang?",
  ui_story_5031_50310202_34_dialog_content = "A-Apa?!",
  ui_story_5031_50310202_35_dialog_content = "Hahaha, apa yang menyenangkan! Tenang saja, Frimet. Mari kita serahkan mereka pada Rainbow. Untuk saat ini, cari saja Merylt, oke?",
  ui_story_5031_50310202_36_dialog_content = "Hai! Apakah Anda bermalas-malasan lagi?",
  ui_story_5031_50310202_37_dialog_content = "Maaf tentang itu, teman-teman! Ketiganya hanya membantu untuk saat ini.",
  ui_story_5031_50310202_38_dialog_content = "Anda harus berada di sini untuk karnaval, saya menerimanya?",
  ui_story_5031_50310202_39_dialog_content = "Izinkan saya untuk memperkenalkan diri. Saya Rainbow, pembawa acara sirkus, penghubung pelanggan, direktur keamanan, dan magang insinyur kelautan!",
  ui_story_5031_50310202_40_dialog_content = "I-Itu cukup seteguk ...",
  ui_story_5031_50310202_41_dialog_content = "Heee! Itu sebabnya semua orang berpikir aku sangat luar biasa, kau tahu?",
  ui_story_5031_50310202_42_dialog_content = "Senang bertemu denganmu, Rainbow! Bisakah Anda memberi tahu saya cara masuk ke dalam kapal—Ooh!",
  ui_story_5031_50310202_43_dialog_content = "Apa yang kamu lakukan? Anda benar-benar berpikir dia akan membiarkan Anda masuk hanya karena Anda bertanya?",
  ui_story_5031_50310202_44_dialog_content = "T-Tapi apa yang harus kita lakukan?",
  ui_story_5031_50310202_45_dialog_content = "Halo. Kami hanya ingin tahu lebih banyak tentang karnaval, dan cara terbaik untuk menikmatinya.",
  ui_story_5031_50310202_46_dialog_content = "Nah, karnaval masih bersiap-siap saat ini. Tidak apa-apa untuk nongkrong di geladak dan menunggu sinyal.",
  ui_story_5031_50310202_47_dialog_content = "Untuk saat ini, saya mengundang Anda semua untuk melihat kontes memasak yang diadakan di dekat sini!",
  ui_story_5031_50310202_48_dialog_content = "Sebuah kontes sengit akan segera berlangsung, dan ada banyak kedai makanan yang indah untuk dikunjungi!",
  ui_story_5031_50310202_49_dialog_content = "Berjalanlah seperti itu, dan Anda tidak akan melewatkannya!",
  ui_story_5031_50310202_50_dialog_content = "Terima kasih atas waktu Anda. Kami akan pergi melihat-lihat.",
  ui_story_5031_50310202_51_dialog_content = "Anggota sirkus itu cukup istimewa, bukan?",
  ui_story_5031_50310202_52_dialog_content = "Terutama ketiga saudara perempuan itu... Mereka sepertinya sangat tertarik dengan PlayerName.",
  ui_story_5031_50310202_53_dialog_content = "Betulkah...? Saya lebih suka untuk tidak terjebak dengan orang-orang aneh ...",
  ui_story_5031_50310202_54_dialog_content = "Mau tak mau aku berpikir hal-hal menjadi terlalu gila di sekitarku. Saya menantikan sedikit istirahat dan relaksasi.",
  ui_story_5031_50310202_55_dialog_content = "Hmm. Apa yang harus saya lakukan untuk masuk ke dalam kapal ini?",
  ui_story_5031_50310202_56_dialog_content = "Saya benar-benar berpikir saya telah meyakinkan wanita baik itu.",
  ui_story_5031_50310202_57_dialog_content = "Jadi menurut Anda tidak terlalu banyak kejujuran akan membuat Anda terlempar ke laut?",
  ui_story_5031_50310202_58_dialog_content = "Jangan lupa apa yang dikatakan Elvis—bagian dalam kapal disediakan untuk orang-orang sirkus.",
  ui_story_5031_50310202_59_dialog_content = "Tempat terbaik bagi kami untuk mulai mencari adalah di atas dek. Siapa tahu... kita mungkin menemukan sesuatu.",
  ui_story_5031_50310202_60_dialog_content = "Tunggu sebentar... kios itu sedikit lebih jauh... Aku bisa melihat beberapa wajah yang familiar di sana.",
  ui_story_5031_50310202_61_dialog_content = "Merupakan kegembiraan bagi saya untuk mempersembahkan salah satu cara terbaik di dunia untuk menghilangkan panasnya musim panas yang ganas ini.",
  ui_story_5031_50310202_62_dialog_content = "Termasuk rasa terbaru kami—<color=#FFB400>Edisi Terbatas Harbour City Breeze</color>.",
  ui_story_5031_50310202_63_dialog_content = "Kami akan memberikan hadiah lebih lanjut untuk setiap pembelian sepuluh cangkir es serut dengan kantong termal khusus yang diukir dengan penuh kasih dengan gambar Caelestite!",
  ui_story_5031_50310202_64_dialog_content = "Sangat baik. Sepuluh cangkir es serut dan kantong termal, nona cantik.",
  ui_story_5031_50310202_65_dialog_content = "Akulah yang menemukan gaya es serut ini! Dan aku tidak percaya Kleken menggunakan gambar Anda untuk tas!",
  ui_story_5031_50310202_66_dialog_content = "Vice... Pasti kamu ingat itu\"<color=#FFB400>Pengalihan Rahasia Dagang</color>\"anda menandatangani dengan Kleken tahun lalu?",
  ui_story_5031_50310202_67_dialog_content = "Saya sangat takut ini adalah hasilnya.",
  ui_story_5031_50310202_68_dialog_content = "Uh-oh... terlalu manis.",
  ui_story_5031_50310202_69_dialog_content = "Itu tidak memiliki kerumitan es serut Vice.",
  ui_story_5031_50310202_70_dialog_content = "Aku juga mau secangkir!",
  ui_story_5031_50310202_71_dialog_content = "Katakanlah, Anda tidak bisa menahan diri, bukan?",
  ui_story_5031_50310202_72_dialog_content = "Vice masih sangat lesu dengan kisah sedihnya tentang transfer kekayaan intelektual.",
  ui_story_5031_50310202_73_dialog_content = "Aku baik-baik saja dengan itu... Aku hanya senang, bagaimanapun itu terjadi, bahwa setiap orang sekarang mendapat kesempatan untuk menikmati es serut yang lezat dan aku hanya... Aku hanya ingin...",
  ui_story_5031_50310202_74_dialog_content = "saya akan mendapatkan Kleken untuk mentransfer kekayaan intelektual itu kembali kepada saya!",
  ui_story_5031_50310202_75_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian</color>",
  ui_story_5031_50310202_76_dialog_content = "Wow! Benar-benar dingin.",
  ui_story_5031_50310202_77_dialog_content = "Jangan memiliki semuanya sekaligus atau Anda akan mengalami pembekuan otak!",
  ui_story_5031_50310202_78_dialog_content = "Adalah Vice masih berbicara dengan Kleken? Apakah mereka baik-baik saja?",
  ui_story_5031_50310202_79_dialog_content = "PlayerName!",
  ui_story_5031_50310202_80_dialog_content = "Eh? Suara apa yang familiar itu?",
  ui_story_5031_50310202_81_dialog_content = "PlayerName, saya tidak percaya itu benar-benar Anda!",
  ui_story_5031_50310202_82_dialog_content = "Fleur, sedang apa kau di sini?",
  ui_story_5031_50310202_83_dialog_content = "Oh? Anda tidak di sini untuk mengambil bagian dalam Kejuaraan Pot Sihir? Ini adalah festival kompetisi gourmet. Harus segera dimulai.",
  ui_story_5031_50310202_84_dialog_content = "Dan saya juga ingin berterima kasih atas bantuan Anda dengan roti panggang itu saat itu.",
  ui_story_5031_50310202_85_dialog_content = "Saya punya sedikit pemikiran. Dan saya memutuskan untuk ikut serta dalam kompetisi tersebut. Tidak ada cara yang lebih baik untuk meningkatkan dan mendapatkan gaya unik saya di luar sana.",
  ui_story_5031_50310202_86_dialog_content = "Sama-sama. Saya harus mengatakan bahwa saya belum pernah mendengar apa pun tentang kompetisi gourmet ini sampai sekarang. Apa itu disebut lagi? \"<color=#FFB400>pot sihir</color>\"?",
  ui_story_5031_50310202_87_dialog_content = "Tunggu! Apakah itu referensi untuk pria Iron Chef dari Rediesel Desert itu?",
  ui_story_5031_50310202_88_dialog_content = "Penikmat Eclipsite, Paman Johnny? Sangat sama! Dan Panci Sihir yang dia gunakan!",
  ui_story_5031_50310202_89_dialog_content = "Tunggu sebentar. Siapa karakter \"Paman Johnny\" ini, Carleen?",
  ui_story_5031_50310202_90_dialog_content = "Hanya seorang kritikus makanan yang sangat populer yang tinggal jauh di Rediesel Desert. Saya tidak tahu lebih dari itu.",
  ui_story_5031_50310202_91_dialog_content = "Apa yang membuatmu begitu terlibat dalam hal ini?",
  ui_story_5031_50310202_92_dialog_content = "Dia bukan sembarang kritikus restoran tua! Dia menemukan hidangan paling terkenal di seluruh benua ini dalam panci itu!",
  ui_story_5031_50310202_93_dialog_content = "D-Apakah menurutmu Paman Johnny akan mengambil bagian dalam Kejuaraan itu sendiri?",
  ui_story_5031_50310202_94_dialog_content = "Oh, tidak, seorang koki dengan perawakannya pasti memiliki hal-hal yang lebih baik untuk dilakukan daripada... tunggu—apakah panci khasnya juga siap untuk diperebutkan?",
  ui_story_5031_50310202_95_dialog_content = "Tepat! Pemenang hadiah pertama mendapatkan tidak kurang dari Pot Sihir milik masterchef itu sendiri!",
  ui_story_5031_50310202_96_dialog_content = "Saya tidak tahu apakah pria itu sendiri akan ada di sana, tetapi saya yakin hadiah seperti itu akan menarik semua bintang dari seluruh dunia!",
  ui_story_5031_50310202_97_dialog_content = "Dan saya ingin bergabung! Bisakah saya? Apakah mereka akan membiarkan saya?",
  ui_story_5031_50310202_98_dialog_content = "Dapatkan panci ajaib itu di tangan Vice, dan itu akan menjadi luar biasa bagi kita semua di Colossus!",
  ui_story_5031_50310202_99_dialog_content = "Oh! Tapi jangan terlalu tergila-gila padaku, PlayerName. Siapa yang tahu apa yang akan terjadi?",
  ui_story_5031_50310202_100_dialog_content = "Saya minta maaf, Fleur. Saya hanya perlu berbicara dengan PlayerName dengan tenang.",
  ui_story_5031_50310202_101_dialog_content = "Jangan terlalu memaksa, Carleen, Fi.",
  ui_story_5031_50310202_102_dialog_content = "Hai! Fleur, tunggu aku! Saya kembali!",
  ui_story_5031_50310202_103_dialog_content = "Baik. Aku akan menunggu.",
  ui_story_5031_50310202_104_dialog_content = "Aku akan menunggumu di sini, PlayerName!",
  ui_story_5031_50310202_105_dialog_content = "PlayerName, jangan terburu-buru, oke?",
  ui_story_5031_50310202_106_dialog_content = "Saya minta maaf. Saya kira saya sedikit berlebihan di sana.",
  ui_story_5031_50310202_107_dialog_content = "Anda mengatakannya. Saya pikir seseorang benar-benar ingin mendapatkan pot ajaib itu, PlayerName.",
  ui_story_5031_50310202_108_dialog_content = "Apa yang kamu lakukan di sini? Akhirnya aku menemukanmu!",
  ui_story_5031_50310202_109_dialog_content = "Vice? Bagaimana diskusi Anda dengan Kleken Pergilah?",
  ui_story_5031_50310202_110_dialog_content = "Kegagalan yang menyedihkan! Satu-satunya hiburan saya adalah saya berhasil mendapatkan beberapa cangkir es serut gratis untuk kalian semua!",
  ui_story_5031_50310202_111_dialog_content = "Miliki mereka, teman-teman! Biarkan makanan penutup yang dingin ini menghilangkan rasa gagal! *Mengunyah*",
  ui_story_5031_50310202_112_dialog_content = "Saya tidak berpikir Vice bersenang-senang ... *Mengunyah*",
  ui_story_5031_50310202_113_dialog_content = "Argh. Pembekuan otak!",
  ui_story_5031_50310202_114_dialog_content = "Itulah yang terjadi jika Anda memakannya sekaligus, lho. Aduh... Aku juga mengerti.",
  ui_story_5031_50310202_115_dialog_content = "Eh? Lihat tangga di sana yang mengarah ke bawah? Jangan bilang itu pintu masuk ke dek bawah selama ini?",
  ui_story_5031_50310202_116_dialog_content = "Eh? Biarkan saya melihat-lihat.",
  ui_story_5031_50310202_117_dialog_content = "Saya pikir itu benar-benar ... Yah? Haruskah kita turun?",
  ui_story_5031_50310202_118_dialog_content = "Maksud Anda, Anda tidak melihat masalah dengan menerobos dan masuk?",
  ui_story_5031_50310202_119_dialog_content = "Jika kita berbicara tentang penjahat yang sama yang menculik Cloudwhale, mereka tidak akan menggelar tikar selamat datang.",
  ui_story_5031_50310202_120_dialog_content = "Pada akhirnya, kita harus mencoba.",
  ui_story_5031_50310202_121_dialog_content = "Ketuk-ketuk. Maaf atas gangguannya. Tolong biarkan aku masuk!",
  ui_story_5031_50310202_122_dialog_content = "Apakah Anda baru saja mengatakan \"ketukan-ketukan\"?",
  ui_story_5031_50310202_123_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5031_50310202_124_dialog_content = "Ahh!",
  ui_story_5031_50310202_125_dialog_content = "Siapa itu?!",
  ui_story_5031_50310202_126_dialog_content = "Oh maafkan saya! Rekan turis yang lewat!",
  ui_story_5031_50310202_127_dialog_content = "Kelompok lain dari jiwa yang hilang, saya ambil? Siap untuk membuang segalanya ke angin untuk kesempatan memasuki pintu ini?",
  ui_story_5031_50310202_128_dialog_content = "Atau, Anda bisa keluar dari sini.",
  ui_story_5031_50310202_129_dialog_content = "eh?",
  ui_story_5031_50310202_130_dialog_content = "Maksud saya adalah bahwa dek bawah terlarang bagi penumpang!",
  ui_story_5031_50310202_131_dialog_content = "Silakan kembali.",
  ui_story_5031_50310202_132_dialog_content = "Oh maaf! Kami akan pergi sekarang.",
  ui_story_5031_50310202_133_dialog_content = "Apa yang kamu tahu... Tidak mudah untuk masuk.",
  ui_story_5031_50310202_134_dialog_content = "Ini adalah teka-teki ... tidak diragukan lagi.",
  ui_story_5031_50310202_135_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5031_50310202_136_dialog_content = "\"Perhatian semua penumpang! Persiapan kompetisi karnaval baru saja selesai.\"",
  ui_story_5031_50310202_137_dialog_content = "\"Apakah semua peserta yang tertarik silakan pergi ke area yang ditentukan untuk pendaftaran dan pendaftaran.\"",
  ui_story_5031_50310202_138_dialog_content = "\"Peserta berdiri untuk menerima hadiah Nightium yang signifikan serta kesempatan untuk mengalami hari dalam kehidupan anggota sirkus.\"",
  ui_story_5031_50310202_139_dialog_content = "\"Pemenang hadiah pertama juga akan menerima hadiah utama secara pribadi di tangan pemimpin sirkus.\"",
  ui_story_5031_50310202_140_dialog_content = "Bagaimana menurutmu? Sehari dalam kehidupan anggota sirkus juga bisa berarti satu hari akses ke dek bawah.",
  ui_story_5031_50310202_141_dialog_content = "Bukan ide yang buruk, jika saya mengatakannya.",
  ui_story_5031_50310202_142_dialog_content = "Yuk, kita lihat lebih dekat.",
  ui_story_5031_50310202_143_dialog_content = "Astaga, aku tidak pernah menduga. Apa kerumunan!",
  ui_story_5031_50310202_144_dialog_content = "Ck... Mereka seperti gerombolan belalang yang mengerumuniku.",
  ui_story_5031_50310202_145_dialog_content = "Apa yang dilakukan hakim terhormat seperti saya, Hakim Matthieu, di antara orang-orang bodoh ini?",
  ui_story_5031_50310202_146_dialog_content = "...",
  ui_story_5031_50310202_147_dialog_content = "Pergi mengganggu orang lain!",
  ui_story_5031_50310202_148_dialog_content = "Ck. Keributan ini tidak baik untuk humor halusku. Aku bahkan semakin pendek denganmu, Loewe.",
  ui_story_5031_50310202_149_dialog_content = "Carleen, Saya pikir keduanya berasal dari Lumopolis.",
  ui_story_5031_50310202_150_dialog_content = "Mereka dari Hall of Justice, mungkin... tapi siapa peduli.",
  ui_story_5031_50310202_151_dialog_content = "Vice! PlayerName dan Carleen! Dan...?",
  ui_story_5031_50310202_152_dialog_content = "Petugas Gronru! Ini adalah...",
  ui_story_5031_50310202_153_dialog_content = "Saya Fia, seorang ahli ekstrozoologi. Senang berkenalan dengan Anda!",
  ui_story_5031_50310202_154_dialog_content = "Luar biasa. Saya harap Anda telah menjadi pengaruh yang baik pada anak-anak kecil, Caelestite?",
  ui_story_5031_50310202_155_dialog_content = "Untuk apa kau melihatku?!",
  ui_story_5031_50310202_156_dialog_content = "Jadi apa yang kita berutang kesenangan, Petugas Gronru?",
  ui_story_5031_50310202_157_dialog_content = "Aku baru saja mendapat firasat bahwa pertunjukan itu akan menghibur—bersama teman sekolahmu yang tersayang—",
  ui_story_5031_50310202_158_dialog_content = "C-Ce... U-Um, hai, aku Ciel... Mantan teman sekelas Vice.",
  ui_story_5031_50310202_159_dialog_content = "Ce?",
  ui_story_5031_50310202_160_dialog_content = "Lama tidak bertemu! Sebenarnya, itu sudah terlalu lama. Belum banyak melihat Anda sejak saya mulai bekerja dengan PlayerName.",
  ui_story_5031_50310202_161_dialog_content = "Ciel cukup malu. Itu tanda gugupnya—\"ce\".",
  ui_story_5031_50310202_162_dialog_content = "Tapi siapa yang peduli tentang itu, kan? Kami biasa memanggilnya jenius mutlak dalam hal apapun yang berkaitan dengan teknik, kan?",
  ui_story_5031_50310202_163_dialog_content = "Cukup adil. Orang pintar yang mantap sulit ditemukan.",
  ui_story_5031_50310202_164_dialog_content = "Petugas Gronru, Nona Ciel, apakah Anda di sini untuk bersenang-senang?",
  ui_story_5031_50310202_165_dialog_content = "Tidak tidak! Saya tidak akan mengenakan pakaian pengap ini jika saya ingin menikmati karnaval.",
  ui_story_5031_50310202_166_dialog_content = "Jangan bilang bahwa Caelestite saya yang terhormat belum mengetahuinya? Atau kamu, Vice?",
  ui_story_5031_50310202_167_dialog_content = "Sudahkah Anda menyebutkan ukuran kapal yang luar biasa ini? Pertimbangkan kerumitan struktur dan pembuatannya!",
  ui_story_5031_50310202_168_dialog_content = "Saya mengambil kesempatan pertama yang saya bisa untuk menyeret Ciel untuk menyelidiki karya seni teknik ini.",
  ui_story_5031_50310202_169_dialog_content = "Sayang sekali kami belum berhasil menemukan jalan ke geladak bawah! Sebuah survei sederhana dari eksterior tidak dapat memberikan wawasan yang cukup.",
  ui_story_5031_50310202_170_dialog_content = "Semua itu mau tidak mau harus membawa kita sekarang untuk mengikuti kompetisi sendiri!",
  ui_story_5031_50310202_171_dialog_content = "Jadi, Vice, apakah Anda akan membantu Petugas Gronru dan temannya?",
  ui_story_5031_50310202_172_dialog_content = "Itu cukup baik. Saya tidak ingin mengganggu intrik \"Tim Colossus.\" Dan saya percaya penyelenggara cukup fleksibel tentang ukuran tim.",
  ui_story_5031_50310202_173_dialog_content = "Dan aku sepenuhnya percaya bahwa kemampuan Ciel tidak kalah dengan temanku yang terhormat, Vice!",
  ui_story_5031_50310202_174_dialog_content = "Aku, uh, aku akan melakukan yang terbaik!",
  ui_story_5031_50310202_175_dialog_content = "Kalau begitu, saatnya untuk mempersiapkan diri kita untuk kejar-kejaran yang menyenangkan ini! Kami akan melihat Anda segera.",
  ui_story_5031_50310202_176_dialog_content = "Astaga. Kami sudah menyiapkan lawan yang tangguh, begitu...",
  ui_story_5031_50310202_177_dialog_content = "Mengapa mereka begitu lambat mengumumkan detailnya?",
  ui_story_5031_50310202_178_dialog_content = "Oh, saya pikir saya baru saja melihat dua orang naik ke atas panggung.",
  ui_story_5031_50310202_179_dialog_content = "Apakah itu Laird Elvis? Dan ada sosok lain, serba hitam?",
  ui_story_5031_50310202_180_dialog_content = "Ehem.",
  ui_story_5031_50310202_181_dialog_content = "Selamat datang, satu dan semua! Rekan-rekan warga Harbour City yang terkasih dan para pelancong jauh dan luas!",
  ui_story_5031_50310202_182_dialog_content = "Saya pemilik Harbour City, Elvis Modali.",
  ui_story_5031_50310202_183_dialog_content = "Laird Elvis!",
  ui_story_5031_50310202_184_dialog_content = "Elvis Modali! Elvis Modali!",
  ui_story_5031_50310202_185_dialog_content = "Terima kasih. Dan merupakan kehormatan dan hak istimewa saya untuk mengundang legenda laut sejati bersama kami di hari musim panas ini—",
  ui_story_5031_50310202_186_dialog_content = "Illusionist & Old Bill's Circus yang legendaris akan menampilkan pertunjukan spektakuler lainnya dalam karnaval ini!",
  ui_story_5031_50310202_187_dialog_content = "Saya pemimpin sirkus Illusionist & Old Bill's Circus, Jeno Gallacher. Terima kasih, semuanya, atas sambutan hangatnya.",
  ui_story_5031_50310202_188_dialog_content = "Mengingat keadilan, itu akan menjadi kebiasaan saya dalam proses hari ini untuk menyampaikan aturan sebelum setiap tantangan.",
  ui_story_5031_50310202_189_dialog_content = "Pesaing untuk melewati semua tantangan tidak hanya akan mendapatkan pengalaman sehari dalam kehidupan anggota sirkus ...",
  ui_story_5031_50310202_190_dialog_content = "Tetapi juga akan menerima hadiah istimewa dan berharga yang disiapkan secara pribadi oleh saya sendiri.",
  ui_story_5031_50310202_191_dialog_content = "Seperti yang sering dan benar diyakini, rombongan sirkus juga merupakan gudang dari banyak pernak-pernik yang luar biasa.",
  ui_story_5031_50310202_192_dialog_content = "Dan, sejujurnya, sirkus yang saya kelola tidak terkecuali!",
  ui_story_5031_50310202_193_dialog_content = "Perjalanan panjang kami untuk mencari keajaiban telah diberkati dengan cara yang sangat fisik dan luar biasa.",
  ui_story_5031_50310202_194_dialog_content = "Serta berbagai harta karun yang dianugerahkan oleh lautan itu sendiri—yaitu, hadiah utama utama dari karnaval ini!",
  ui_story_5031_50310202_195_dialog_content = "Jangan ragu untuk membayangkan harta karun eksotis ini. Harapkan dengan penuh semangat. Kamu tidak akan kecewa!",
  ui_story_5031_50310202_196_dialog_content = "Wow! Kedengarannya sangat berharga!",
  ui_story_5031_50310202_197_dialog_content = "Kita akan menjadi kaya!",
  ui_story_5031_50310202_197X1_dialog_content = "Harta karun eksotis yang diberikan oleh laut... Aku tahu!",
  ui_story_5031_50310202_197X2_dialog_content = "Itu pasti Awan—Ups!",
  ui_story_5031_50310202_197X3_dialog_content = "Mendiamkan! Diam. Apakah Anda ingin lebih banyak lawan mengetahui identitas aslinya dan melawan kami untuk itu?",
  ui_story_5031_50310202_197X4_dialog_content = "Ups, saya mengerti. Kemudian kita akan mengandalkan diri kita sendiri untuk memenangkan pertandingan dan menyelamatkan Cloudwhale!",
  ui_story_5031_50310202_198_dialog_content = "Juga, saya tidak berpikir Anda akan terkesan jika kami hanya memiliki satu juri untuk kompetisi kami.",
  ui_story_5031_50310202_199_dialog_content = "Jadi, dengan senang hati saya mengundang pemimpin besar Harbour City, Laird Elvis, untuk menjadi juri bersama saya!",
  ui_story_5031_50310202_200_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310202_201_dialog_content = "eh...? Jeno? Apakah ini sesuatu yang harus kita diskusikan terlebih dahulu?",
  ui_story_5031_50310202_202_dialog_content = "Apakah ada masalah, Pak? Saya pikir Anda akan berterima kasih atas kesempatan untuk menikmati apa yang seharusnya dapat dilakukan oleh pria mana pun di posisi Anda!",
  ui_story_5031_50310202_203_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310202_204_dialog_content = "Saya mengerti.",
  ui_story_5031_50310202_205_dialog_content = "Kami percaya bahwa Anda akan menikmati acara dengan isi hati Anda, semuanya!",
  ui_story_5031_50310301_0_dialog_content = "Um, jadi renda ini harus masuk ke sini...",
  ui_story_5031_50310301_0X1_dialog_content = "Hah? Kenapa ada renda lain?",
  ui_story_5031_50310301_0X2_dialog_content = "Yang ini... Uh, harus lewat sisi lain?",
  ui_story_5031_50310301_0X3_dialog_content = "Terima kasih telah membantu, Vice.",
  ui_story_5031_50310301_0X4_dialog_content = "Tidak masalah. Tunggu saja dan biarkan aku mencari tahu ini dalam satu menit.",
  ui_story_5031_50310301_0X5_dialog_content = "Gunakan waktumu. Saya sedang tidak buru-buru.",
  ui_story_5031_50310301_0X6_dialog_content = "Um, seharusnya begini, kan?",
  ui_story_5031_50310301_0X7_dialog_content = "Hm, mungkin tidak...",
  ui_story_5031_50310301_0X8_dialog_content = "... Vice.",
  ui_story_5031_50310301_0X9_dialog_content = "Hm? Apa itu? Apakah aku menyakitimu?",
  ui_story_5031_50310301_0X10_dialog_content = "Tidak. Hanya saja... Bolehkah aku menanyakan sesuatu yang pribadi?",
  ui_story_5031_50310301_0X11_dialog_content = "Pribadi?",
  ui_story_5031_50310301_0X12_dialog_content = "Yeah... Aku ingin tahu bagaimana perasaanmu... saat kau mendapat kekuatan baru.",
  ui_story_5031_50310301_0X13_dialog_content = "Oh, begitu... Itu sama sekali tidak pribadi!",
  ui_story_5031_50310301_0X14_dialog_content = "Angkat siku kanan Anda sedikit.",
  ui_story_5031_50310301_0X15_dialog_content = "Tentu.",
  ui_story_5031_50310301_0X16_dialog_content = "Um... Tapi itu sebenarnya pertanyaan yang sulit.",
  ui_story_5031_50310301_0X17_dialog_content = "Bukannya aku tidak ingin menjawab... Hanya saja sulit untuk dijelaskan.",
  ui_story_5031_50310301_0X18_dialog_content = "Aku mengerti.",
  ui_story_5031_50310301_0X19_dialog_content = "Bagi saya, rasanya seperti potensi saya dibuka.",
  ui_story_5031_50310301_0X20_dialog_content = "Saya memperoleh perspektif yang berbeda tentang Lumina, tetapi juga pada risiko tertentu.",
  ui_story_5031_50310301_0X21_dialog_content = "Risiko?",
  ui_story_5031_50310301_0X22_dialog_content = "Ya, saya tertidur selama proses itu. Saya pikir saya tidak akan pernah bangun.",
  ui_story_5031_50310301_0X23_dialog_content = "Aku terus berpikir kembali ke diriku yang dulu, takut aku akan kehilangan diriku sendiri jika aku santai bahkan untuk sesaat.",
  ui_story_5031_50310301_0X24_dialog_content = "Saya juga melihat banyak hal luar biasa, seperti saya ada di sana.",
  ui_story_5031_50310301_0X25_dialog_content = "Ilusi itu terasa begitu nyata, seperti ujian bagiku.",
  ui_story_5031_50310301_0X26_dialog_content = "Untungnya, saya berpegang teguh pada kilau dalam kesadaran dan dipertahankan sampai akhir.",
  ui_story_5031_50310301_0X27_dialog_content = "Saya mengerti. Jadi, apakah ini proses membuka potensi Anda...?",
  ui_story_5031_50310301_0X28_dialog_content = "Ya, itulah yang saya pikirkan.",
  ui_story_5031_50310301_0X29_dialog_content = "Sebenarnya, banyak Aurorian mendapatkan terobosan seperti itu dalam krisis.",
  ui_story_5031_50310301_0X30_dialog_content = "Kurasa itulah yang terjadi padaku.",
  ui_story_5031_50310301_0X31_dialog_content = "Tetapi bahkan sekarang, saya masih belum bisa menguasainya sepenuhnya.",
  ui_story_5031_50310301_0X32_dialog_content = "Itu mungkin karena masih baru bagi Anda. Anda akan, diberikan waktu.",
  ui_story_5031_50310301_0X33_dialog_content = "Itu benar!",
  ui_story_5031_50310301_0X34_dialog_content = "Jika Anda ingin mencobanya, mungkin Anda bisa memulainya dengan pelepasan kesadaran?",
  ui_story_5031_50310301_0X35_dialog_content = "Pelepasan kesadaran?",
  ui_story_5031_50310301_0X36_dialog_content = "Ya. Itulah yang akan saya lakukan setiap kali saya ingin memicu kekuatan saya, meskipun tidak selalu berhasil.",
  ui_story_5031_50310301_0X37_dialog_content = "Begitu rupanya. Aku mengerti.",
  ui_story_5031_50310301_0X38_dialog_content = "Saya akan mencobanya di lain waktu. Terima kasih, Vice.",
  ui_story_5031_50310301_0X39_dialog_content = "Bukan masalah!",
  ui_story_5031_50310301_0X40_dialog_content = "Ini dia, renda terakhir!",
  ui_story_5031_50310301_0X41_dialog_content = "Fiuh, mengenakan pakaian bangsawan benar-benar menyebalkan!",
  ui_story_5031_50310301_0X42_dialog_content = "Dan bahannya terlihat agak unik. Saya belum pernah melihat ini di Illumina.",
  ui_story_5031_50310301_0X43_dialog_content = "Ini adalah pertama kalinya saya juga. Ini mungkin spesialisasi Harbour City.",
  ui_story_5031_50310301_0X44_dialog_content = "Pakaian formal adalah keahlian mereka.",
  ui_story_5031_50310301_0X45_dialog_content = "Terima kasih sekali lagi atas bantuannya, Vice.",
  ui_story_5031_50310301_0X46_dialog_content = "Jangan berkeringat. Tapi kau terlihat sangat bagus dalam hal itu, Carleen!",
  ui_story_5031_50310301_0X47_dialog_content = "Ayo pamerkan ke PlayerName dan Fia. Mereka akan kagum!",
  ui_story_5031_50310301_1_dialog_content = "Mengapa tidak? Carleen kembali belum?",
  ui_story_5031_50310301_2_dialog_content = "Gadis membutuhkan waktu untuk berganti pakaian, belum lagi pakaiannya terlihat sangat rumit.",
  ui_story_5031_50310301_2X1_dialog_content = "Bahkan dengan bantuan dari Vice, itu masih harus memakan waktu cukup lama.",
  ui_story_5031_50310301_3_dialog_content = "Anda punya poin. Mengapa saya merasa bahwa bangsawan membutuhkan pelayan hanya untuk berpakaian?",
  ui_story_5031_50310301_4_dialog_content = "Bagaimana kalau Anda memberi? Carleen tangan juga, Fia?",
  ui_story_5031_50310301_5_dialog_content = "Hai? Apa aku, hambamu sekarang? Memerintahkanku seperti itu!",
  ui_story_5031_50310301_6_dialog_content = "Silahkan. Bukankah Carleen dan Vice melakukan yang terbaik untuk membantu Anda menemukan Cloudwhale?",
  ui_story_5031_50310301_7_dialog_content = "Baiklah baiklah! Aku belum pernah membantu seseorang mengenakan gaun sebelumnya. Saya dapat mencoba.",
  ui_story_5031_50310301_8_dialog_content = "PlayerName, santai saja di Fia.",
  ui_story_5031_50310301_9_dialog_content = "Maaf membuat semua orang menunggu...",
  ui_story_5031_50310301_10_dialog_content = "Sehat! Carleen, Anda terlihat... benar-benar menakjubkan!",
  ui_story_5031_50310301_11_dialog_content = "Ya! Kelihatannya nyaman, praktis, dan sangat cocok untuk Anda, Carleen!",
  ui_story_5031_50310301_12_dialog_content = "Terimakasih semuanya. Sungguh menakjubkan—jumlah penjahit profesional dan perancang busana luar biasa di sekitar Harbour City.",
  ui_story_5031_50310301_13_dialog_content = "Saya sebenarnya merasa sangat nyaman dalam hal ini.",
  ui_story_5031_50310301_14_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5031_50310301_15_dialog_content = "Saya minta maaf. Aku hanya terpesona sesaat. Tapi apa yang akan saya katakan adalah bahwa—",
  ui_story_5031_50310301_16_dialog_content = "Cantik! Anggun! Kuat!",
  ui_story_5031_50310301_17_dialog_content = "Anda adalah anak dari Schwartz keluarga dalam segala hal, Carleen, dan pakaian yang menakjubkan ini hanya untuk menunjukkannya.",
  ui_story_5031_50310301_18_dialog_content = "Saya tidak tahu harus berkata apa. Kurasa aku harus berterima kasih, Laird Elvis.",
  ui_story_5031_50310301_19_dialog_content = "Tolong, itu yang paling bisa saya lakukan. Saya pergi untuk sesuatu yang mengingatkan saya pada teladan, karakteristik mulia dari Schwartz keluarga.",
  ui_story_5031_50310301_20_dialog_content = "Anda dapat menganggap pakaian itu sebagai semacam pertanda baik untuk keberhasilan Anda masuk ke kompetisi!",
  ui_story_5031_50310301_21_dialog_content = "Saya dibutuhkan di tempat lain, tetapi saya berharap dapat bertemu Anda lagi nanti!",
  ui_story_5031_50310301_22_dialog_content = "Oh, maaf—kurasa aku tidak punya kesempatan untuk mengungkapkan pemikiranku tentang gaun baru Carleen.",
  ui_story_5031_50310301_23_dialog_content = "Urgh. Laird Elvis mencuri gunturku.",
  ui_story_5031_50310301_24_dialog_content = "Eh, saya tidak berpikir Anda harus mengatakan apa-apa ...",
  ui_story_5031_50310301_25_dialog_content = "Anda sudah mengatakan cukup dengan mata Anda.",
  ui_story_5031_50310301_26_dialog_content = "Hah?",
  ui_story_5031_50310301_27_dialog_content = "Salam, semuanya! Saatnya bagi saya untuk memberi Anda semua ikhtisar singkat dari acara tersebut.",
  ui_story_5031_50310301_28_dialog_content = "Izinkan saya untuk memperkenalkan diri. Saya Rainbow, pembawa acara sirkus, penghubung pelanggan, direktur keamanan, dan magang insinyur kelautan!",
  ui_story_5031_50310301_29_dialog_content = "Tapi hari ini saya akan mengenakan topi pembawa acara utama kompetisi!",
  ui_story_5031_50310301_30_dialog_content = "Pada tahap pertama ini saya dengan hormat meminta Anda semua untuk mengambil salah satu senjata air yang saya siapkan khusus dari sini.",
  ui_story_5031_50310301_31_dialog_content = "Pistol air ini telah dimodifikasi untuk menyalurkan Lumina menjadi menembakkan pelet khusus.",
  ui_story_5031_50310301_32_dialog_content = "Aturannya sangat sederhana: pukul target seperti yang diberikan oleh Ringmaster Jeno dengan pistol air Anda.",
  ui_story_5031_50310301_33_dialog_content = "Saya harus memberi tahu Anda bahwa kami tidak akan menghentikan pesaing atau tim untuk saling menggunakan senjata air!",
  ui_story_5031_50310301_34_dialog_content = "Hanya lima tim dengan skor tertinggi yang akan lolos ke babak berikutnya. Mereka yang tersingkir dibuang ke laut sebagai hukuman.",
  ui_story_5031_50310301_35_dialog_content = "Jadi kami tidak ingin ada kontestan yang tidak bisa berenang! Atau setidaknya pastikan Anda membawa perangkat flotasi!",
  ui_story_5031_50310301_36_dialog_content = "Tim bisa dari berbagai ukuran, tetapi perhatikan skor akhir Anda akan diperoleh dengan membagi skor tim Anda dengan jumlah anggota.",
  ui_story_5031_50310301_37_dialog_content = "Aturan ini sangat baik untuk kita, bukan?",
  ui_story_5031_50310301_38_dialog_content = "Kita pasti akan mendapatkan hadiahnya dengan Jona dan Azure di tim kami!",
  ui_story_5031_50310301_39_dialog_content = "Senjata air? Terlihat konyol, tapi aku tidak bisa mengabaikan hadiah utama itu...",
  ui_story_5031_50310301_40_dialog_content = "Apa lagi yang akan kita lakukan dengan waktu kita? Ini hanya sedikit kesenangan yang tidak berbahaya.",
  ui_story_5031_50310301_41_dialog_content = "Hai! Kami sudah membuatnya!",
  ui_story_5031_50310301_42_dialog_content = "Jangan menghitung ayam Anda terlalu dini! Bagaimanapun, kalian berdua baru saja bergabung dengan Rediesel Wrench.",
  ui_story_5031_50310301_43_dialog_content = "Ingat bagaimana orang-orang Rediesel Wrench menangani hal-hal di depan orang luar! Kami membuat diri kami bangga.",
  ui_story_5031_50310301_44_dialog_content = "Jangan khawatir tentang apa pun! Anda mengerti!",
  ui_story_5031_50310301_45_dialog_content = "Hanya beberapa hal yang perlu diingat! Mengerti!",
  ui_story_5031_50310301_46_dialog_content = "Apakah semua orang jelas tentang aturan?",
  ui_story_5031_50310301_47_dialog_content = "Keras dan jelas!",
  ui_story_5031_50310301_48_dialog_content = "Tunggu! Jika pistol air ini berjalan di Lumina, bagaimana itu akan berhasil untukku?",
  ui_story_5031_50310301_49_dialog_content = "Oh ya. Saya tidak mempertimbangkan itu untuk Caelestites.",
  ui_story_5031_50310301_50_dialog_content = "Merylt, apa menurutmu kau bisa pergi ke tim Caelestite dan membantu mereka?",
  ui_story_5031_50310301_51_dialog_content = "A-Apa yang harus saya lakukan dengan itu? Kami tidak diizinkan untuk mengambil bagian ...",
  ui_story_5031_50310301_52_dialog_content = "Konyol. Kenapa malah termasuk dia? Dia tidak banyak tauge.",
  ui_story_5031_50310301_53_dialog_content = "Bos, bagaimana dengan Caelestit?",
  ui_story_5031_50310301_54_dialog_content = "Kita bisa memperhitungkan handicap. Hitung Caelestite dan gadis kecil itu sebagai satu.",
  ui_story_5031_50310301_55_dialog_content = "Hai! Di alam semesta apa seorang Caelestit ditambah aku masing-masing setengah orang?",
  ui_story_5031_50310301_56_dialog_content = "Lakukan dengan cara Anda. Dua peserta kemudian.",
  ui_story_5031_50310301_57_dialog_content = "Uh, sebenarnya, aku agak muda dan tidak terlalu fit... Setelah dipikir-pikir, mungkin masuk akal untuk menggabungkan kita!",
  ui_story_5031_50310301_58_dialog_content = "Lalu, tanpa keberatan, aku akan segera mengirimkan targetmu—",
  ui_story_5031_50310301_59_dialog_content = "Ayo! Tepuk tangan untuk para pesaing gila kita!",
  ui_story_5031_50310301_60_dialog_content = "Sekarang, melolong! Seperti yang Anda maksudkan! Binatang Hades!",
  ui_story_5031_50310301_61_dialog_content = "Tunggu! Saya harap Boss tidak benar-benar berpikir untuk memanggil mereka ...",
  ui_story_5031_50310301_62_dialog_content = "Cepat! Tutup mata Rainbow! Dia akan menjadi gila jika dia melihat sebuah Eclipsite!",
  ui_story_5031_50310301_63_dialog_content = "Graah!",
  ui_story_5031_50310301_64_dialog_content = "Eclipsite?!",
  ui_story_5031_50310301_65_dialog_content = "gerhana!!",
  ui_story_5031_50310301_66_dialog_content = "Frimet! Lakukan sesuatu untuk membantuku dengan Rainbow. Dia akan kehilangan itu!",
  ui_story_5031_50310301_67_dialog_content = "Bos Bodoh! Mengapa memilih Eclipsites?!",
  ui_story_5031_50310301_68_dialog_content = "Eh... karena sangat cocok dengan angin ini.",
  ui_story_5031_50310301_69_dialog_content = "PlayerName, Fia—ikuti aku dan Vice.",
  ui_story_5031_50310301_70_dialog_content = "Jangan khawatir, teman-teman terkasih! Eclipsites ini tidak lebih dari ilusi yang saya buat dengan \"<color=#FFB400>Asal</color>.\"",
  ui_story_5031_50310301_71_dialog_content = "Dengan kekuatan kedua tanganku sendiri, aku telah menganalisis \"asal\" kekuatan Eclipsites selama pertarunganku!",
  ui_story_5031_50310301_72_dialog_content = "Dan, dengan menggunakan \"<color=#FFB400>Kartu Asal</color>,\" menciptakan ilusi gesit dan hidup yang Anda lihat di depan Anda.",
  ui_story_5031_50310301_73_dialog_content = "Grah...",
  ui_story_5031_50310301_74_dialog_content = "Grah...",
  ui_story_5031_50310301_75_dialog_content = "Seperti yang Anda lihat, Eclipsites sepenuhnya di bawah kendali saya dan membuat target yang sangat baik.",
  ui_story_5031_50310301_76_dialog_content = "Jadi, biarkan permainan dimulai!",
  ui_story_5031_50310401_1_dialog_content = "Hai! Sibuk! Saya ingin Anda membersihkan Eclipsites ini, karena tidak mungkin Rediesel Wrench akan puas dengan yang kedua!",
  ui_story_5031_50310401_2_dialog_content = "Mengerti, Bos! Tapi bagaimana dengan Aurorian?",
  ui_story_5031_50310401_3_dialog_content = "Bagaimana dengan mereka? Anda adalah Rediesel Wrench! Sekarang pukul keluar dari taman!",
  ui_story_5031_50310401_4_dialog_content = "Buat Rediesel Wrench terlihat bagus dan tembak siapa pun yang menghalangi Anda melewati sisi kapal!",
  ui_story_5031_50310401_5_dialog_content = "Aku paham.",
  ui_story_5031_50310401_6_dialog_content = "Intens, Jona.",
  ui_story_5031_50310401_7_dialog_content = "Apa masalahnya? Tidak ada pria, tidak peduli seberapa imutnya, di atas hukuman!",
  ui_story_5031_50310401_8_dialog_content = "Imut memang imut, tapi tetap manis itu hadiah utama...",
  ui_story_5031_50310401_9_dialog_content = "Urgh... Jona dan Azure ada di sini—mereka ahli senjata.",
  ui_story_5031_50310401_10_dialog_content = "Mereka mengatakan Anda hanya mendapatkan poin untuk menembak Eclipsites, tetapi orang-orang Rediesel Wrench ini hanya menembak pemain lain!",
  ui_story_5031_50310401_11_dialog_content = "Jika ilusi Jeno tidak membuat sampul yang sangat bagus, kami pasti sudah ditembak mati berabad-abad yang lalu.",
  ui_story_5031_50310401_12_dialog_content = "Kita mungkin masih bisa kecuali kita bisa melakukan sesuatu daripada hanya menunggu di sini. Ikuti saya! Kami akan berjuang melalui jalan kami!",
  ui_story_5031_50310401_13_dialog_content = "Tunggu, Carleen!",
  ui_story_5031_50310401_14_dialog_content = "Inilah yang Anda dapatkan karena tidak mengikuti semangat aturan, Anda penipu kotor — bunga es, tidak, pucuk es!",
  ui_story_5031_50310401_15_dialog_content = "Astaga!",
  ui_story_5031_50310401_16_dialog_content = "B-Bos!",
  ui_story_5031_50310401_17_dialog_content = "Itu dua dari mereka turun. Cepat, datang ke sini, semuanya.",
  ui_story_5031_50310401_18_dialog_content = "Kerja bagus... Langsung ke laut dengan tembakan es khas Carleen. Hai, Carleen, di balik penutup, cepat!",
  ui_story_5031_50310401_19_dialog_content = "Sekarang adalah kesempatan Anda, PlayerName!",
  ui_story_5031_50310401_20_dialog_content = "Itulah yang Anda dapatkan karena menjadi seorang ranger tunggal, Carleen! Ini berarti-",
  ui_story_5031_50310401_21_dialog_content = "Aku mendapatkanmu sekarang, putri cantikku dari Lumopolis!",
  ui_story_5031_50310401_22_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5031_50310401_23_dialog_content = "!!",
  ui_story_5031_50310401_24_dialog_content = "Carleen!",
  ui_story_5031_50310401_25_dialog_content = "Saya—maaf, PlayerName.",
  ui_story_5031_50310401_26_dialog_content = "Semua baik-baik saja yang berakhir dengan baik. Saya tidak berharap Jona menjadi begitu baik dengan pistol air Lumina.",
  ui_story_5031_50310401_27_dialog_content = "Hai! Anda preman Rediesel tercela! Berhenti memilih kami!",
  ui_story_5031_50310401_28_dialog_content = "Itu tidak akan berhasil. Kita harus mencari tahu kebuntuan ini.",
  ui_story_5031_50310401_29_dialog_content = "Sebuah kompetisi yang sangat menarik, semuanya.",
  ui_story_5031_50310401_30_dialog_content = "Ya. Memang. Dipenuhi dengan kekuatan yang tidak saya duga.",
  ui_story_5031_50310401_31_dialog_content = "Kekuatan yang saya peroleh dari True Order...",
  ui_story_5031_50310401_32_dialog_content = "Yang saya yakin Anda pernah mendengar lebih banyak legenda negatif sebagai bangsawan Lumopolis, Pak.",
  ui_story_5031_50310401_33_dialog_content = "Faktanya, apa yang \"asal\" mewakili lebih dari apa pun hanyalah cara lain untuk menciptakan ketegangan untuk efek performatif.",
  ui_story_5031_50310401_34_dialog_content = "Sebenarnya, apa yang saya miliki hanyalah kekuatan untuk mengubah energi... kebiasaan yang efektif dengan latihan, seperti yang Anda lihat.",
  ui_story_5031_50310401_35_dialog_content = "Saya bukan orang yang tersinggung dengan kekuatan aneh. Jangan khawatir.",
  ui_story_5031_50310401_36_dialog_content = "Tapi kenapa Eclipsites?",
  ui_story_5031_50310401_37_dialog_content = "Kita semua di sini untuk menghadiri karnaval, bukan? Apa itu karnaval selain serangkaian pertemuan yang mengasyikkan dan menakjubkan?",
  ui_story_5031_50310401_38_dialog_content = "Saya harus berpikir Eclipsites sesuai dengan tagihan dengan sangat baik.",
  ui_story_5031_50310401_39_dialog_content = "Saya tidak bisa menyalahkan logika bisnis Anda. Inspirasi.",
  ui_story_5031_50310401_40_dialog_content = "Secara alami, saya harus selalu menganggap kasus bisnis sebagai biang keladi dari seluruh rombongan sirkus.",
  ui_story_5031_50310401_41_dialog_content = "Saya minta maaf atas gangguan ini, Laird Elvis.",
  ui_story_5031_50310401_42_dialog_content = "Pato...? Nanti, Jeno.",
  ui_story_5031_50310401_43_dialog_content = "Ada berita apa?",
  ui_story_5031_50310401_44_dialog_content = "Sebuah laporan, diverifikasi. Kami telah menemukan kamar yang cocok dengan deskripsi Anda sebelumnya.",
  ui_story_5031_50310401_45_dialog_content = "Apa? Luar biasa...",
  ui_story_5031_50310401_46_dialog_content = "Sayangnya, ruangan itu dilindungi oleh kunci yang sangat aman yang belum pernah kita lihat. Masuk paksa pasti akan meningkatkan alarm.",
  ui_story_5031_50310401_47_dialog_content = "Saya mengerti. Kemudian kita harus menemukan kunci yang mampu membukanya.",
  ui_story_5031_50310401_48_dialog_content = "Saya akan berasumsi kunci seperti itu dapat ditemukan di kamar Jeno atau orangnya. Kita bisa mencoba kedua jalan secara bersamaan.",
  ui_story_5031_50310401_49_dialog_content = "Elvis!",
  ui_story_5031_50310401_50_dialog_content = "Saya harap saya tidak mengganggu Anda, tetapi tim lain baru saja mencetak poin besar, dan orang-orang berteriak agar Anda menghormati poin tersebut.",
  ui_story_5031_50310401_51_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310401_52_dialog_content = "Maaf, Jeno. Setelah beberapa kata lagi dengan Patou.",
  ui_story_5031_50310401_53_dialog_content = "Jadi apa yang harus kita lakukan, Pak?",
  ui_story_5031_50310401_54_dialog_content = "Anda dan anak buah Anda memiliki wewenang untuk melakukan apa pun yang diperlukan untuk menggeledah ruangan.",
  ui_story_5031_50310401_55_dialog_content = "Tapi saya khawatir ketidakhadiran yang signifikan dari acara hari itu akan menimbulkan kecurigaan Jeno.",
  ui_story_5031_50310401_56_dialog_content = "Sangat menarik betapa banyak peserta Aurorian yang kita miliki dengan motif yang tidak diketahui... dan saya menduga ide yang sama.",
  ui_story_5031_50310401_57_dialog_content = "Jadi tetapkan pengawasan ketat pada mereka. Siapa pun yang ingin bergerak harus melakukannya saat sepi—saat dek kurang sibuk.",
  ui_story_5031_50310401_58_dialog_content = "Saya menerimanya, Pak, kita harus terus mencari dengan tenang dan menunggu perintah lebih lanjut dari Yang Mulia.",
  ui_story_5031_50310401_59_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310401_60_dialog_content = "Aku akhirnya kembali, semuanya! Dan dengan ini saya umumkan tim Rediesel Wrench telah memenangkan poin lagi!",
  ui_story_5031_50310401_61_dialog_content = "Kembali memang. Kami mulai bertanya-tanya.",
  ui_story_5031_50310401_62_dialog_content = "Maaf, Jeno, untuk menunggu lama.",
  ui_story_5031_50310402_1_dialog_content = "Dan bagaimana dengan kunci itu? Bagaimana saya bisa tahu di mana Anda meletakkannya?",
  ui_story_5031_50310402_2_dialog_content = "Anda tampak agak aneh, Elvis?",
  ui_story_5031_50310402_3_dialog_content = "Maksudku, sepertinya sesuatu yang dikatakan pengawalmu membuatmu tidak senang.",
  ui_story_5031_50310402_4_dialog_content = "Saya percaya semuanya baik-baik saja? Tidak ada penyakit apapun?",
  ui_story_5031_50310402_5_dialog_content = "Tidak tidak. Saya sangat berterima kasih.",
  ui_story_5031_50310402_6_dialog_content = "Saya hanya menyibukkan diri dengan beberapa urusan negara. Maaf telah memberimu kesan itu.",
  ui_story_5031_50310402_7_dialog_content = "Saya harap menyeret Anda ke sini tidak membawa Anda pergi dari pekerjaan penting?",
  ui_story_5031_50310402_8_dialog_content = "Saya hanya berpikir bahwa mungkin Anda akan sangat menghargai kesempatan ini untuk menikmati festival yang indah bersama orang-orang Anda.",
  ui_story_5031_50310402_9_dialog_content = "Oh? Apakah itu pertama kalinya saya melihat Boss meminta maaf?",
  ui_story_5031_50310402_10_dialog_content = "Saya kira demikian. Saya kira dia bisa berbicara seperti orang normal jika dia mau.",
  ui_story_5031_50310402_11_dialog_content = "Jika Anda punya banyak waktu, pergi dan bantu Rainbow, oke?",
  ui_story_5031_50310402_12_dialog_content = "Pffffft.",
  ui_story_5031_50310402_13_dialog_content = "Sheesh. Ini seperti menggiring kucing, pagi sampai malam.",
  ui_story_5031_50310402_14_dialog_content = "Ah, jangan khawatirkan aku. Saya hanya...",
  ui_story_5031_50310402_15_dialog_content = "Saya telah terganggu oleh beberapa masalah berat yang membutuhkan keputusan.",
  ui_story_5031_50310402_16_dialog_content = "Kesempatan untuk bersantai ini berarti kesempatan untuk mendapatkan wawasan baru tentang beberapa hal dan orang. Ini sangat membantu.",
  ui_story_5031_50310402_17_dialog_content = "Luar biasa! Anda harus memberi tahu saya jika Anda merasa hari itu mengganggu karena alasan apa pun.",
  ui_story_5031_50310402_18_dialog_content = "Benar. Tidak masalah.",
  ui_story_5031_50310402_19_dialog_content = "\"Perhatian, peserta! Kami sekarang memasuki tahap yang lebih menarik dari permainan kami yang melibatkan proyeksi Eclipsite dua kali lebih banyak!\"",
  ui_story_5031_50310402_20_dialog_content = "Akhirnya! Waktu bonus!",
  ui_story_5031_50310402_21_dialog_content = "Lindungi aku, Ciel! Waktu bonus adalah tempat para juara membuat atau menghancurkannya!",
  ui_story_5031_50310402_22_dialog_content = "B-Mengerti, Petugas Gronru.",
  ui_story_5031_50310402_23_dialog_content = "Ah, kau berlari terlalu cepat untukku—",
  ui_story_5031_50310402_24_dialog_content = "Hai! Siapa itu?",
  ui_story_5031_50310402_25_dialog_content = "Apa yang kita miliki di sini? Gadis Illumina yang malang sendirian.",
  ui_story_5031_50310402_26_dialog_content = "H-Hei! Tinggal jauh dari saya!",
  ui_story_5031_50310402_27_dialog_content = "Kami membutuhkan hadiah itu. Hal-hal baik tidak datang murah.",
  ui_story_5031_50310402_28_dialog_content = "Maaf, nona, tapi aku akan menyita pistol airmu. Sekarang bantu kami dan lompat ke laut, ya?",
  ui_story_5031_50310402_29_dialog_content = "Tunggu—perlengkapan bagus! Kita bisa mendapatkan harga yang bagus untuk itu di Umbraton, bukan begitu?",
  ui_story_5031_50310402_30_dialog_content = "Ya! Dan kita selalu mendapatkan apa yang kita inginkan, nona. Jangan membuat ini sulit.",
  ui_story_5031_50310402_31_dialog_content = "Beri kami barang-barang berharga Anda!",
  ui_story_5031_50310402_32_dialog_content = "H-Lepaskan!",
  ui_story_5031_50310402_33_dialog_content = "Bekukan, kalian berdua!",
  ui_story_5031_50310402_34_dialog_content = "Jangan bilang itu pembawa acara!",
  ui_story_5031_50310402_35_dialog_content = "Sangat sama! Pencurian sangat bertentangan dengan aturan turnamen. Aku takut aku tidak akan bisa melepaskanmu!",
  ui_story_5031_50310402_36_dialog_content = "Kamu pikir kamu siapa? Kau pikir kami takut padamu karena kau pembawa acaranya?",
  ui_story_5031_50310402_37_dialog_content = "Saya tidak akan tahan dengan perilaku buruk seperti ini, Anda dengar saya?",
  ui_story_5031_50310402_38_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5031_50310402_39_dialog_content = "D-Bung!",
  ui_story_5031_50310402_40_dialog_content = "Kamu juga!",
  ui_story_5031_50310402_41_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5031_50310402_42_dialog_content = "Aduh!",
  ui_story_5031_50310402_43_dialog_content = "V-Sangat mengesankan... Berlebihan begitu saja.",
  ui_story_5031_50310402_44_dialog_content = "Anda tidak terluka, kan? Itu gila—berpikir mereka bisa menggunakan acara ini sebagai penggeledahan!",
  ui_story_5031_50310402_45_dialog_content = "Uh, aku harus membantu Petugas Gronru. Terima kasih!",
  ui_story_5031_50310402_46_dialog_content = "Pistol airku... Dimana itu?",
  ui_story_5031_50310402_47_dialog_content = "Oh. Maaf tentang itu. Di sini, memiliki ini.",
  ui_story_5031_50310402_48_dialog_content = "Saya telah menambahkan sesuatu pada aturan tentang \"orang yang kehilangan pistol air mereka dapat mengambil yang baru dari pembawa acara.\" Jadi jangan khawatir tentang hal itu.",
  ui_story_5031_50310402_49_dialog_content = "Oh oke! Terima kasih.",
  ui_story_5031_50310402_50_dialog_content = "Eh...",
  ui_story_5031_50310402_51_dialog_content = "Hah?",
  ui_story_5031_50310402_52_dialog_content = "Saya Ciel. Terima kasih, Bu Rainbow.",
  ui_story_5031_50310402_53_dialog_content = "Ciel? Aku akan mengingat namamu.",
  ui_story_5031_50310402_54_dialog_content = "Ya ampun. Seperti apa wanita berkelas itu? Carleen lakukan di acara seperti ini?",
  ui_story_5031_50310402_55_dialog_content = "Dia harus tahu lebih baik dengan asuhannya yang mulia. Dia membuat kita semua... terlihat buruk!",
  ui_story_5031_50310402_56_dialog_content = "...",
  ui_story_5031_50310402_57_dialog_content = "Hai! Apakah saya hanya berbicara pada diri saya sendiri di sini?",
  ui_story_5031_50310402_58_dialog_content = "Kita harus mengawasi dan melindungi Carleen.",
  ui_story_5031_50310402_59_dialog_content = "Tut, saya mungkin juga.",
  ui_story_5031_50310402_60_dialog_content = "Hei, datang ke sini! Ada banyak Eclipsites di sini yang bisa kamu kalahkan!",
  ui_story_5031_50310402_61_dialog_content = "Ah!",
  ui_story_5031_50310402_62_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310402_63_dialog_content = "Maaf, Pak... Saya tidak sengaja mendapatkan pistol air Anda.",
  ui_story_5031_50310402_64_dialog_content = "Biarkan saya membantu Anda mengambilnya.",
  ui_story_5031_50310402_65_dialog_content = "Tidak masalah. Jangan khawatir tentang itu. Temanmu sudah menunggu di sana. Selamat bersenang-senang.",
  ui_story_5031_50310402_66_dialog_content = "Terima kasih. Betapa mulianya dirimu!",
  ui_story_5031_50310402_67_dialog_content = "...",
  ui_story_5031_50310402_68_dialog_content = "... Menjijikkan.",
  ui_story_5031_50310402_69_dialog_content = "Air! Ambilkan aku air! Saya perlu mencuci tangan!",
  ui_story_5031_50310402_70_dialog_content = "... Dramatis.",
  ui_story_5031_50310402_71_dialog_content = "Graah!",
  ui_story_5031_50310402_72_dialog_content = "PlayerName, Jeno yakin menambahkan banyak Eclipsites.",
  ui_story_5031_50310402_73_dialog_content = "Dan orang-orang Rediesel itu tidak memberi kita istirahat.",
  ui_story_5031_50310402_74_dialog_content = "Mereka lebih suka mengambil risiko eliminasi dari kekurangan poin untuk fokus pada kita!",
  ui_story_5031_50310402_75_dialog_content = "Saya pikir itu hanya mengatakan mereka melihat kami sebagai kompetisi.",
  ui_story_5031_50310402_76_dialog_content = "Dan itulah mengapa mereka ingin melenyapkan kita sejak dini.",
  ui_story_5031_50310402_77_dialog_content = "Saya punya sedikit langkah pertama... tapi itu mungkin berhasil: Saya bisa menjadi umpan sebagai seseorang yang tidak memiliki akses ke Lumina.",
  ui_story_5031_50310402_78_dialog_content = "Saya akan melakukan yang terbaik untuk menarik banyak Eclipsites ke atas saat Anda menggunakan pengalihan untuk keluar dari bawah Jona dan ibu jari Azure.",
  ui_story_5031_50310402_79_dialog_content = "Itu terlalu berisiko, PlayerName! Kita hanya bisa mencoba menerobos lagi. Saya akan lebih berhati-hati dengan itu!",
  ui_story_5031_50310402_80_dialog_content = "Jona dan Azure terlalu baik. Mereka akan dapat menunjukkan Anda dari jarak jauh, Carleen.",
  ui_story_5031_50310402_81_dialog_content = "Saya tidak turun semudah itu. Percayalah pada kekuatanku.",
  ui_story_5031_50310402_82_dialog_content = "Saya percaya, dan sekarang saatnya untuk menaruh kepercayaan Anda pada kekuatan saya juga.",
  ui_story_5031_50310402_83_dialog_content = "Carleen, Saya pikir saran PlayerName patut dicoba.",
  ui_story_5031_50310402_84_dialog_content = "Saya pikir itu mungkin opsi taktis terbaik yang kami miliki.",
  ui_story_5031_50310402_85_dialog_content = "Baik-baik saja maka. Tapi hati-hati, ya?",
  ui_story_5031_50310402_86_dialog_content = "Yakinlah. Fia, kamu pergi dengan Carleen dan Vice.",
  ui_story_5031_50310402_87_dialog_content = "H-Hah? Oke.",
  ui_story_5031_50310402_88_dialog_content = "gerhana! Makan masuk!",
  ui_story_5031_50310402_89_dialog_content = "500 Lumamber adalah semua yang diperlukan untuk mendapatkan perjamuan terbesar yang pernah Anda lihat ini! Sekarang atau tidak sama sekali! Ahhhh!",
  ui_story_5031_50310402_90_dialog_content = "Graah!",
  ui_story_5031_50310402_91_dialog_content = "Graaaah...!",
  ui_story_5031_50310402_92_dialog_content = "Hah? Apakah itu PlayerName? Apa yang dia lakukan?",
  ui_story_5031_50310402_93_dialog_content = "Caelestit Cerdas. Dia memancing Eclipsites untuk menghalangi pandangan kita, kurasa.",
  ui_story_5031_50310402_94_dialog_content = "Lalu dia orang bodoh yang akan mendapatkan imbalan orang bodoh tepat di tushnya karena meremehkanku...",
  ui_story_5031_50310402_95_dialog_content = "Hai wanita.",
  ui_story_5031_50310402_96_dialog_content = "Apa?",
  ui_story_5031_50310402_97_dialog_content = "Saya khawatir saya menganggap band bergembira Carleen agak di bawah perlindungan saya ...",
  ui_story_5031_50310402_98_dialog_content = "Saya memiliki cukup kemarahan di tangan saya yang tercemar untuk pergi berkeliling ... Kalian berani menyerang bangsawan? Ambil benjolan Anda!!",
  ui_story_5031_50310402_99_dialog_content = "Dapatkan di belakangku, Vice, Fi!",
  ui_story_5031_50310402_100_dialog_content = "Aku akan mengalahkan kalian semua Eclipsites sendirian!",
  ui_story_5031_50310402_101_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_5031_50310402_102_dialog_content = "Grah...",
  ui_story_5031_50310402_103_dialog_content = "Astaga!!",
  ui_story_5031_50310402_104_dialog_content = "Graah!",
  ui_story_5031_50310402_105_dialog_content = "Graah!",
  ui_story_5031_50310402_106_dialog_content = "Mereka lemah, tapi terlalu banyak. Mereka telah kita dikelilingi.",
  ui_story_5031_50310402_107_dialog_content = "Ini bukan waktunya untuk memanjakan, Carleen. Kita harus kembali dengan PlayerName.",
  ui_story_5031_50310402_108_dialog_content = "Andai saja aturan mengizinkan Kepompong Bulan... Huh. Ambil itu, Anda Eclipsites!",
  ui_story_5031_50310402_108X1_dialog_content = "Kalau saja saya mendapat kekuatan baru sebagai Vice telah mendapatkan...!",
  ui_story_5031_50310402_108X2_dialog_content = "Tenanglah, Carleen.",
  ui_story_5031_50310402_108X3_dialog_content = "Lepaskan saja kesadaranmu seperti Vice dikatakan...",
  ui_story_5031_50310402_108X4_dialog_content = "Lepaskan... Napas.",
  ui_story_5031_50310402_108X5_dialog_content = "Carleen.",
  ui_story_5031_50310402_108X6_dialog_content = "Ayah...",
  ui_story_5031_50310402_108X7_dialog_content = "Anda dan saya sama-sama tahu bahwa Eclipsites tidak dapat dimusnahkan.",
  ui_story_5031_50310402_108X8_dialog_content = "Tindakan sembrono hanya menyebabkan kematian tentara yang percaya pada Anda.",
  ui_story_5031_50310402_108X9_dialog_content = "Tanpa kekuatan besar, Anda tidak dapat membela orang yang dicintai.",
  ui_story_5031_50310402_108X10_dialog_content = "Kamu tidak cukup kuat... Harus menemukan cara... untuk menjadi lebih kuat.",
  ui_story_5031_50310402_108X11_dialog_content = "Aku sangat kecewa...",
  ui_story_5031_50310402_108X12_dialog_content = "Tidak... Itu tidak benar, Ayah!",
  ui_story_5031_50310402_108X13_dialog_content = "Carleen!",
  ui_story_5031_50310402_108X14_dialog_content = "Graah!",
  ui_story_5031_50310402_108X15_dialog_content = "Kalahkan!!",
  ui_story_5031_50310402_109_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5031_50310402_110_dialog_content = "K-Kamu tidak bisa menggunakan tinju! Kami tidak akan mendapatkan poin.",
  ui_story_5031_50310402_111_dialog_content = "Tenang, Carleen! Kita harus menemukan PlayerName terlebih dahulu!",
  ui_story_5031_50310402_112_dialog_content = "... Saya minta maaf. Kamu benar.",
  ui_story_5031_50310402_113_dialog_content = "<color=#e8d9bb>Cincin-cincin!</color>",
  ui_story_5031_50310402_114_dialog_content = "\"Pertandingan sekarang telah berakhir! Semua peserta yang tersisa, silakan pergi ke podium juri untuk mencetak gol.\"",
  ui_story_5031_50310402_115_dialog_content = "Kerja bagus, Carleen. Kita lolos ke babak berikutnya!",
  ui_story_5031_50310402_116_dialog_content = "Yah, sebagian besar berkat PlayerName karena telah mengeluarkan kami dari lingkaran Rediesel Wrench.",
  ui_story_5031_50310402_117_dialog_content = "Tanpa risiko kecil untuk diri sendiri. Saya tidak akan membiarkannya dalam pertempuran nyata.",
  ui_story_5031_50310402_118_dialog_content = "Aha, Caelestite benar-benar berpikir dia menyelamatkan semua orang!",
  ui_story_5031_50310402_119_dialog_content = "Hah? Azure? Maksud kamu apa?",
  ui_story_5031_50310402_120_dialog_content = "Seorang pria Lumo memilih berkelahi entah dari mana. Dia mengganggu kita dengan buruk.",
  ui_story_5031_50310402_121_dialog_content = "Anda dapat berterima kasih kepada bintang keberuntungan Anda karena dia melakukannya ... Tanpa dia, Anda akan bersulang.",
  ui_story_5031_50310402_122_dialog_content = "Tapi jauh lebih menyenangkan menjatuhkannya daripada memainkan permainan anak konyol ini dengan pistol air.",
  ui_story_5031_50310402_123_dialog_content = "Menyebut dirinya bangsawan, dia tidak seperti bangsawan mana pun yang pernah kulihat, dan dia membuat kami sibuk.",
  ui_story_5031_50310402_124_dialog_content = "Sayang sekali pria pendiam itu menyeretnya pergi. Kami bisa saja bertarung lama dan keras.",
  ui_story_5031_50310402_125_dialog_content = "B-Bos...",
  ui_story_5031_50310402_126_dialog_content = "Anda berani menunjukkan wajah Anda lagi?",
  ui_story_5031_50310402_127_dialog_content = "Kami tidak menentang wanita dan anak-anak. Kamu lupa?!",
  ui_story_5031_50310402_128_dialog_content = "Aku sangat menyesal. Aku tidak tahu apa yang merasukiku.",
  ui_story_5031_50310402_129_dialog_content = "Mulailah dengan push-up dari dek utama. Aku akan berurusan denganmu setelah minumku.",
  ui_story_5031_50310402_130_dialog_content = "Y-Ya, Bos!",
  ui_story_5031_50310402_131_dialog_content = "Selalu hujan di parade saya ...",
  ui_story_5031_50310402_132_dialog_content = "Saya tidak menyadari bahwa Rediesel Wrench memiliki sisi itu.",
  ui_story_5031_50310402_133_dialog_content = "Saya akan menganggap itu sebagai pujian. Baiklah, Putri, aku akan minum bersama Azure. Sampai jumpa.",
  ui_story_5031_50310402_134_dialog_content = "Sampai jumpa! Kami mendapatkan minuman keras gratis di sana. Hei Caelestite, silakan datang.",
  ui_story_5031_50310402_135_dialog_content = "Fiuh... Entah bagaimana kita berakhir dengan satu lawan yang lebih sedikit untuk dikhawatirkan.",
  ui_story_5031_50310402_136_dialog_content = "Menurut saya Gronru dan temannya juga berhasil. Mereka benar-benar mencetak gol yang cukup tinggi.",
  ui_story_5031_50310402_137_dialog_content = "Saya tidak berharap semua orang akan menganggapnya begitu serius. Melihat Jona dan Azure—dieliminasi di babak pertama!",
  ui_story_5031_50310402_138_dialog_content = "Saya yakin babak selanjutnya hanya akan... lebih intens, menyayat hati, dan antagonis...",
  ui_story_5031_50310402_139_dialog_content = "Dengung.",
  ui_story_5031_50310402_140_dialog_content = "Itu cukup terdengar!",
  ui_story_5031_50310402_141_dialog_content = "Hanya membangun suasana cemas Anda!",
  ui_story_5031_50310402_142_dialog_content = "Salam, Laird.",
  ui_story_5031_50310402_143_dialog_content = "Salam pembuka. Anda ...",
  ui_story_5031_50310402_144_dialog_content = "Betul sekali. Saya Subli.",
  ui_story_5031_50310402_145_dialog_content = "Jeno menyuruhku membawakanmu ini sebagai hadiah.",
  ui_story_5031_50310402_146_dialog_content = "Lalu, ini...?",
  ui_story_5031_50310402_147_dialog_content = "Selimut. Dia khawatir Anda mungkin masuk angin dalam angin laut ini.",
  ui_story_5031_50310402_148_dialog_content = "... Saya mengerti. Sampaikan terima kasihku.",
  ui_story_5031_50310402_149_dialog_content = "Dan terima kasih juga, Subli.",
  ui_story_5031_50310402_150_dialog_content = "Hei, jangan sebutkan itu.",
  ui_story_5031_50310402_151_dialog_content = "...",
  ui_story_5031_50310501_1_dialog_content = "Saya salut kepada Anda, para pejuang pemberani, yang telah berhasil melewati babak pertama!",
  ui_story_5031_50310501_2_dialog_content = "Tidak diragukan lagi, Anda semua telah membuktikan keberanian Anda dalam perjalanan menuju harta karun tertinggi ini.",
  ui_story_5031_50310501_3_dialog_content = "Aturan kami untuk babak berikutnya juga sangat sederhana.",
  ui_story_5031_50310501_4_dialog_content = "Saya yakin Anda semua pernah merasakan manfaat memainkan permainan yang sangat mirip dengan anak-anak.",
  ui_story_5031_50310501_5_dialog_content = "Keluarlah, oh binatang buas yang menggeliat di senja hari! Oh penjaga artefak dan sihir aneh!",
  ui_story_5031_50310501_6_dialog_content = "<color=#e8d9bb>Bum...!</color>",
  ui_story_5031_50310501_7_dialog_content = "Lihat, ini Penjaga Rahasia kita di babak ini.",
  ui_story_5031_50310501_8_dialog_content = "Ahem. Sekarang, saya akan membahas beberapa aturan.",
  ui_story_5031_50310501_9_dialog_content = "Saat Eclipsite unik ini berubah menjadi hijau...",
  ui_story_5031_50310501_10_dialog_content = "Anda harus melakukannya secepat mungkin, melewati semua Eclipsites lain yang menghalangi Anda.",
  ui_story_5031_50310501_11_dialog_content = "Lewati saja garis ini untuk lolos ke babak berikutnya.",
  ui_story_5031_50310501_12_dialog_content = "Harap berhati-hati saat berubah menjadi merah!",
  ui_story_5031_50310501_13_dialog_content = "Tidak ada Aurorian atau Eclipsites yang diizinkan untuk bergerak saat itu. Jika Anda melakukannya, Anda akan terlempar ke laut oleh Eclipsite terdekat, dan kemudian Anda akan keluar.",
  ui_story_5031_50310501_14_dialog_content = "Siapa pun yang tidak mencapai garis finis pada akhirnya juga akan keluar.",
  ui_story_5031_50310501_15_dialog_content = "Dan Anda dapat merasa bebas untuk menggunakan Luminatics yang sesuai. Tidak ada batasan sekarang.",
  ui_story_5031_50310501_16_dialog_content = "Tepat. Jadi ayolah! Tunjukkan pada kami apa yang Anda punya! Tantang makhluk saya untuk hadiah!",
  ui_story_5031_50310501_17_dialog_content = "PlayerName.",
  ui_story_5031_50310501_18_dialog_content = "Ya. Sekarang saya akhirnya bisa menggunakan kekuatan saya.",
  ui_story_5031_50310501_19_dialog_content = "Jangan khawatir. Saya akan membantu semua orang mencapai garis finish tepat waktu!",
  ui_story_5031_50310502_1_dialog_content = "Heh! Bahkan aku bisa mengeluarkan Eclipsite seperti itu!",
  ui_story_5031_50310502_2_dialog_content = "Perhatikan dan pelajari, Anda Eclipsites kotor!",
  ui_story_5031_50310502_3_dialog_content = "Hai! Yang besar akan berubah warna. Lebih baik berhenti!",
  ui_story_5031_50310502_4_dialog_content = "Beri aku waktu sebentar! Aku bisa memimpin!",
  ui_story_5031_50310502_5_dialog_content = "Idiot. Anda akan tersingkir, tahukah Anda?",
  ui_story_5031_50310502_6_dialog_content = "Omong-omong, saya harus berterima kasih kepada Anda karena mendapatkan poin di babak terakhir saat saya terlibat dengan dua bandit itu.",
  ui_story_5031_50310502_7_dialog_content = "Aku tidak pernah tahu mereka begitu tangguh... Itu pemanasan yang bagus.",
  ui_story_5031_50310502_8_dialog_content = "Jika Anda tidak menarik saya pergi ... Saya bisa membuat contoh dari mereka!",
  ui_story_5031_50310502_9_dialog_content = "...",
  ui_story_5031_50310502_10_dialog_content = "Tut. Saya mencoba untuk memuji Anda, kawan! Luminatics Anda menutup mulut Anda?",
  ui_story_5031_50310502_11_dialog_content = "<color=#e8d9bb>Cincin-cincin!</color>",
  ui_story_5031_50310502_12_dialog_content = "Itu berubah warna!",
  ui_story_5031_50310502_13_dialog_content = "Graah!",
  ui_story_5031_50310502_14_dialog_content = "J-Jangan datang!",
  ui_story_5031_50310502_15_dialog_content = "<color=#e8d9bb>Celepuk!</color>",
  ui_story_5031_50310502_16_dialog_content = "<color=#e8d9bb>Celepuk!!</color>",
  ui_story_5031_50310502_17_dialog_content = "Lebih dari mereka pergi! Rakyat jelata dengan nama, rakyat jelata secara alami ...",
  ui_story_5031_50310502_18_dialog_content = "Kita tidak boleh menjelajah terlalu jauh dari sang putri. Lindungi dia di tempat yang lebih dekat.",
  ui_story_5031_50310502_19_dialog_content = "Kita tidak bisa membiarkan dia berenang di laut seperti jiwa-jiwa yang malang dan bodoh itu.",
  ui_story_5031_50310502_20_dialog_content = "Terima kasih untuk selimutnya, Jeno.",
  ui_story_5031_50310502_21_dialog_content = "Sama-sama. Tetap hangat, tetap baik. Sepertinya angin sepoi-sepoi akan meniupmu.",
  ui_story_5031_50310502_22_dialog_content = "Hehe. Sebuah permainan yang aneh untuk orang dewasa seusia Anda, tentunya?",
  ui_story_5031_50310502_23_dialog_content = "Dengan cara apa? Apakah itu terlalu kekanak-kanakan?",
  ui_story_5031_50310502_24_dialog_content = "Sama sekali tidak. Aku hanya sedikit terkejut.",
  ui_story_5031_50310502_25_dialog_content = "Anda masih menikmati permainan ini bahkan setelah bertahun-tahun, bahkan membawanya kembali untuk putaran ini...",
  ui_story_5031_50310502_26_dialog_content = "Karena saya orang yang cukup nostalgia.",
  ui_story_5031_50310502_27_dialog_content = "Saya juga dikutuk dengan ingatan yang panjang. Misalnya, sesuatu yang tidak penting seperti janji yang terlewatkan bertahun-tahun yang lalu—yang saya tunggu sepanjang hari.",
  ui_story_5031_50310502_28_dialog_content = "... Saya benar-benar minta maaf karena tidak mengucapkan selamat tinggal bertahun-tahun yang lalu.",
  ui_story_5031_50310502_29_dialog_content = "Itu benar.",
  ui_story_5031_50310502_30_dialog_content = "…?",
  ui_story_5031_50310502_31_dialog_content = "Aku hanya ingin mendengarmu mengatakan itu.",
  ui_story_5031_50310502_32_dialog_content = "Saya hanya bisa membayangkan...",
  ui_story_5031_50310502_33_dialog_content = "Bayangkan semua kerja keras yang terlibat dalam pekerjaan seseorang mulai dari putra seorang pemilik restoran hingga laird Harbour City.",
  ui_story_5031_50310502_34_dialog_content = "Tapi saya masih mendapatkan kesan kuat bahwa Anda tidak berubah sama sekali dalam banyak hal penting lainnya. Saya harap itu tidak salah.",
  ui_story_5031_50310502_35_dialog_content = "Dalam hal-hal penting apa?",
  ui_story_5031_50310502_36_dialog_content = "Seperti latihan aerobik yang Anda lakukan di Harbour City. Sangat konyol tapi... sangat kamu.",
  ui_story_5031_50310502_37_dialog_content = "Ha ha ha! Konyol, tapi efektif untuk membantu semua orang tetap bugar.",
  ui_story_5031_50310502_38_dialog_content = "Bagaimana denganmu? Saya mencari Anda untuk waktu yang lama setelah kembali ke Lumopolis. Tidak ada yang tahu keberadaanmu.",
  ui_story_5031_50310502_39_dialog_content = "Aku?",
  ui_story_5031_50310502_40_dialog_content = "Saya mencari Anda untuk waktu yang lama setelah kembali ke Harbour City. Tidak ada yang tahu ke mana Anda pergi.",
  ui_story_5031_50310502_41_dialog_content = "Beberapa bahkan mengatakan kepada saya bahwa Anda dan keluarga Anda tidak lagi bersama kami ...",
  ui_story_5031_50310502_42_dialog_content = "Sebuah penjumlahan yang adil.",
  ui_story_5031_50310502_43_dialog_content = "Providence memberi kami pelarian ke Zamrud dan, seperti pengungsi yang melarikan diri dari Krisis Kegelapan, kami memegang rakit penyelamat kami untuk semua yang berharga.",
  ui_story_5031_50310502_44_dialog_content = "Seperti sudah ditakdirkan, saya akhirnya diselamatkan oleh Lady Victoria dari Ordo Sejati.",
  ui_story_5031_50310502_45_dialog_content = "Dia juga memberiku kemampuan untuk memanipulasi Origin.",
  ui_story_5031_50310502_46_dialog_content = "Baru setelah saya kembali ke Zamrud saya mengetahui bahwa orang tua saya telah meninggal.",
  ui_story_5031_50310502_47_dialog_content = "Dan, tentu saja, saya menyalahkan pemimpin sirkus sebelumnya atas kematian mereka. Saya menantangnya untuk berduel dalam kemarahan saya.",
  ui_story_5031_50310502_48_dialog_content = "Kebenarannya sudah lama datang, cukup lama bagi biang keladi untuk memaafkan kecerobohan ini.",
  ui_story_5031_50310502_49_dialog_content = "Dan kemudian hanya saya sendiri, Zamrud, dan sesama anggota sirkus dalam perjalanan kami melintasi laut lepas.",
  ui_story_5031_50310502_50_dialog_content = "Maaf... Mereka orang baik.",
  ui_story_5031_50310502_51_dialog_content = "Anda tidak perlu meminta maaf. Itu bukan salahmu.",
  ui_story_5031_50310502_52_dialog_content = "Aku mungkin memanfaatkan True Order untuk memajukan karirku sebagai seorang penyihir...",
  ui_story_5031_50310502_53_dialog_content = "Tetapi, sejujurnya, saya tidak begitu peduli dengan Ordo dan doktrin-doktrinnya.",
  ui_story_5031_50310502_54_dialog_content = "Bagaimanapun, Ordo memiliki begitu banyak sekte... Saya khawatir saya mungkin tipe yang paling \"teralih\".",
  ui_story_5031_50310502_55_dialog_content = "Namun saya harus menghormati janji yang saya buat untuk Lady Victoria untuk kebaikannya.",
  ui_story_5031_50310502_56_dialog_content = "Aku tidak pernah ingin mengingkari janji...",
  ui_story_5031_50310502_57_dialog_content = "Sebuah janji... *Batuk*",
  ui_story_5031_50310502_58_dialog_content = "Apakah itu—apakah Anda batuk darah?",
  ui_story_5031_50310502_59_dialog_content = "Aku baik-baik saja. Sedikit terlalu banyak bekerja dengan politik... dan juga kedinginan...",
  ui_story_5031_50310502_60_dialog_content = "Apakah Anda menganggap saya bodoh?",
  ui_story_5031_50310502_61_dialog_content = "Ha ha! Jauh dari itu. Saya sangat sehat, terima kasih.",
  ui_story_5031_50310502_62_dialog_content = "Atau apakah Anda ingin menggunakan kekuatan ramalan Anda untuk melihat masa depan saya? Saya yakin saya memiliki setidaknya 200 tahun lagi.",
  ui_story_5031_50310502_63_dialog_content = "Ramalan? Silahkan. Anda bisa mengatakan yang sebenarnya!",
  ui_story_5031_50310502_64_dialog_content = "*Terengah-engah* Nah, sebagai mantan penduduk Harbour City, Anda pasti akrab dengan yang disebut \"Pahlawan Legendaris\"?",
  ui_story_5031_50310502_65_dialog_content = "Tentu saja. Sebuah cerita pengantar tidur untuk anak-anak kecil.",
  ui_story_5031_50310502_66_dialog_content = "... Tapi cerita pengantar tidur itu nyata.",
  ui_story_5031_50310502_67_dialog_content = "...",
  ui_story_5031_50310502_68_dialog_content = "Sederhananya, mereka menyegel Eclipsites dengan semacam perjanjian darah.",
  ui_story_5031_50310502_69_dialog_content = "Eclipsites yang terkena dampak jatuh ke hibernasi yang dalam, sementara Harbour City secara efektif dilindungi dari mendekat.",
  ui_story_5031_50310502_70_dialog_content = "Tetapi ini harus dibayar—tidak hanya bagi mereka, tetapi juga bagi keturunan mereka.",
  ui_story_5031_50310502_71_dialog_content = "Dan inilah sumber sebenarnya dari kondisi yang dikenal sebagai Sindrom Modali.",
  ui_story_5031_50310502_72_dialog_content = "Apa? Apakah itu sebabnya Anda memiliki bekas luka di wajah Anda? Sindrom Modali?",
  ui_story_5031_50310502_73_dialog_content = "*Batuk* Memang. Tapi jangan khawatir. Aku... ugh... mengatasi dengan cukup baik.",
  ui_story_5031_50310502_74_dialog_content = "Jika itu disegel dengan sebuah perjanjian, lalu apakah ada cara untuk membatalkannya?",
  ui_story_5031_50310502_75_dialog_content = "Mungkin. Itulah yang saya cari selama bertahun-tahun ini... sebuah solusi.",
  ui_story_5031_50310502_76_dialog_content = "Dan apa yang telah Anda temukan?",
  ui_story_5031_50310502_77_dialog_content = "Maaf, belum ada yang cukup untuk saya bagikan. Dan ada rahasia dan kepentingan yang terlibat yang tidak bisa diceritakan dengan sederhana atau enteng.",
  ui_story_5031_50310502_78_dialog_content = "...",
  ui_story_5031_50310502_79_dialog_content = "Lihat! Gadis itu adalah pembangkit tenaga listrik! Dia berlomba di depan!",
  ui_story_5031_50310502_80_dialog_content = "Pasangannya bahkan tidak menggunakan Luminatics! Kenapa dia masih memimpin?",
  ui_story_5031_50310502_81_dialog_content = "Siapa yang tidak bisa menggunakan Luminatics? Apakah dia seorang Caelestit?",
  ui_story_5031_50310502_82_dialog_content = "Apa? Mari kita lihat Caelestit!",
  ui_story_5031_50310502_83_dialog_content = "Ringmaster, bisakah saya mengganggu Anda sebentar? Paket persediaan baru. Hanya perlu Anda untuk sign off.",
  ui_story_5031_50310502_84_dialog_content = "Tentu. Aku akan segera.",
  ui_story_5031_50310502_85_dialog_content = "Saya khawatir Anda mungkin harus menilai solo sampai saya kembali.",
  ui_story_5031_50310502_86_dialog_content = "Silakan, Jeno.",
  ui_story_5031_50310602_1_dialog_content = "\"Ronde 2 balapan—mulai!\"",
  ui_story_5031_50310602_2_dialog_content = "<color=#e8d9bb>Cincin-cincin!</color>",
  ui_story_5031_50310602_3_dialog_content = "PlayerName! Tetap dekat dengan kami!",
  ui_story_5031_50310602_4_dialog_content = "Tetap dekat di PlayerName, Vice dan Fia! Jangan biarkan Eclipsites mendapatkan dia.",
  ui_story_5031_50310602_5_dialog_content = "Siap!",
  ui_story_5031_50310602_6_dialog_content = "Saya tidak menyadari bahwa kami hanya punya sedikit waktu untuk bergerak. Maaf, saya tidak bisa membantu lebih banyak.",
  ui_story_5031_50310602_7_dialog_content = "Saya pikir beberapa Aurorian telah berlari dengan Luminatics mereka.",
  ui_story_5031_50310602_8_dialog_content = "Sudahlah. Kami hanya perlu fokus.",
  ui_story_5031_50310602_9_dialog_content = "PlayerName, saya ingin Anda memberi saya jalan ke depan.",
  ui_story_5031_50310602_10_dialog_content = "Siap!",
  ui_story_5031_50310602_11_dialog_content = "Ah...",
  ui_story_5031_50310602_12_dialog_content = "Ini mengganggu saya pada banyak tingkatan. Saya tahu aturan mengatakan untuk menjaga jarak dari Yang Mulia, tapi saya tidak bisa mengizinkannya.",
  ui_story_5031_50310602_13_dialog_content = "Hei, bukankah kau... Hakim itu? Aku ingat.",
  ui_story_5031_50310602_14_dialog_content = "Saya memang Hakim Matthieu, Yang Mulia, dan kaleng kacang di sebelah saya ini adalah rekan saya, Loewe.",
  ui_story_5031_50310602_15_dialog_content = "aku sadar miskin Pittman telah berada di bawah kasih karunia Anda, tetapi apa yang ingin saya katakan adalah—",
  ui_story_5031_50310602_16_dialog_content = "Yang Mulia... Anda pantas mendapatkan yang lebih baik.",
  ui_story_5031_50310602_17_dialog_content = "Seorang prajurit perkasa tidak boleh bergabung di pinggul dengan seseorang yang tidak mampu Luminatik yang belum sempurna.",
  ui_story_5031_50310602_18_dialog_content = "Anda pasti sudah memenuhi syarat sekarang tanpa halangan dari Caelestit ini — bahkan jika dia seharusnya membantu.",
  ui_story_5031_50310602_19_dialog_content = "Saya melihat di Caelestite ketergantungan malang yang sama dari semua rakyat jelata.",
  ui_story_5031_50310602_20_dialog_content = "A-Apa?!",
  ui_story_5031_50310602_21_dialog_content = "Jangan pedulikan dia.",
  ui_story_5031_50310602_22_dialog_content = "Apa?",
  ui_story_5031_50310602_23_dialog_content = "Dia sedikit bengkok di dalam.",
  ui_story_5031_50310602_24_dialog_content = "Hai! Apa yang kamu katakan?!",
  ui_story_5031_50310602_25_dialog_content = "Ceritakan lebih banyak! Saya ingin mendengar lebih banyak.",
  ui_story_5031_50310602_26_dialog_content = "Dia biasanya berpura-pura santai.",
  ui_story_5031_50310602_27_dialog_content = "Tapi dia, pada kenyataannya, membenci rakyat jelata.",
  ui_story_5031_50310602_28_dialog_content = "Tapi dia membangun neurosis besar-besaran terhadap rakyat jelata...",
  ui_story_5031_50310602_29_dialog_content = "Yang lucu mengingat latar belakangnya sendiri ...",
  ui_story_5031_50310602_30_dialog_content = "Hai! Bukan kata lain! Saya melarangnya! Kembali ke keheningan Anda!",
  ui_story_5031_50310602_31_dialog_content = "Anda akan mendengar dan mematuhi! Berhenti!",
  ui_story_5031_50310602_32_dialog_content = "... Diam!",
  ui_story_5031_50310602_33_dialog_content = "Tut.",
  ui_story_5031_50310602_34_dialog_content = "Saya pikir para bangsawan Lumopolis semua memandang rendah rakyat jelata ke tingkat yang berbeda.",
  ui_story_5031_50310602_35_dialog_content = "Ini tidak sama.",
  ui_story_5031_50310602_X35_dialog_content = "Dia mencuci tangannya setidaknya sepuluh kali jika seseorang menyentuh tangannya secara tidak sengaja.",
  ui_story_5031_50310602_X36_dialog_content = "Dia berteriak ketika debu jatuh ke atasnya.",
  ui_story_5031_50310602_36_dialog_content = "Ooh... May juga hidup dalam kasus dan menyingkirkan dunia luar.",
  ui_story_5031_50310602_37_dialog_content = "Ya, dia terobsesi dengan kebersihan sampai tingkat yang gila.",
  ui_story_5031_50310602_38_dialog_content = "Aku sangat menyesal mendengarnya...",
  ui_story_5031_50310602_39_dialog_content = "Aku tidak butuh belas kasihan dari gadis terpencil sepertimu!",
  ui_story_5031_50310602_40_dialog_content = "Dia malas bekerja.",
  ui_story_5031_50310602_41_dialog_content = "Malas di tempat kerja, katamu? Anda tidak melukis gambar yang mengesankan.",
  ui_story_5031_50310602_42_dialog_content = "Dan mengambil keuntungan dari sentimen teman sekelas lamanya.",
  ui_story_5031_50310602_X42_dialog_content = "Mendorong sesuatu ke Pittma...",
  ui_story_5031_50310602_43_dialog_content = "<color=#e8d9bb>Cincin-cincin!</color>",
  ui_story_5031_50310602_44_dialog_content = "Ini berubah warna! Pegang kudamu, semuanya!",
  ui_story_5031_50310602_45_dialog_content = "Oh, tidak!",
  ui_story_5031_50310602_46_dialog_content = "Saya tidak bisa berhenti berlari! Tolong aku!",
  ui_story_5031_50310602_47_dialog_content = "G-Menjauh dariku, rakyat jelata yang kotor!",
  ui_story_5031_50310602_48_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310602_49_dialog_content = "Saya sangat menyesal, Pak.",
  ui_story_5031_50310602_50_dialog_content = "Menjauhlah! Jauh!",
  ui_story_5031_50310602_51_dialog_content = "Bajuku! Aku harus ke ruang ganti!",
  ui_story_5031_50310602_52_dialog_content = "Aku akan kembali untuk mandi, Loewe!",
  ui_story_5031_50310602_53_dialog_content = "Dia pemakan yang rewel.",
  ui_story_5031_50310602_54_dialog_content = "Dia mengatakan lidahnya sensitif terhadap panas.",
  ui_story_5031_50310602_55_dialog_content = "Meneriakkan hal-hal seperti: \"Ah! Panas sekali!\"",
  ui_story_5031_50310602_56_dialog_content = "Dan membuatku melihatnya!",
  ui_story_5031_50310602_57_dialog_content = "Aku tidak ingin melihatnya sama sekali.",
  ui_story_5031_50310602_58_dialog_content = "Tiga telah dieliminasi!",
  ui_story_5031_50310602_59_dialog_content = "Sampai jumpa lagi!",
  ui_story_5031_50310602_60_dialog_content = "Saya mendapat perasaan yang berbeda dari kesan penampilan. Cara berbicara yang singkat dan padat ini sangat mengesankan.",
  ui_story_5031_50310602_X60_dialog_content = "Ya, ini sepertinya orang yang menarik.",
  ui_story_5031_50310602_61_dialog_content = "Saya minta maaf, Carleen.",
  ui_story_5031_50310602_62_dialog_content = "Untuk apa? Jangan dengarkan apa pun yang Matthieu katakan.",
  ui_story_5031_50310602_63_dialog_content = "Kamu berusaha sangat keras, tapi aku tidak pandai berkelahi. Terkadang aku berpikir aku mengecewakanmu.",
  ui_story_5031_50310602_64_dialog_content = "Anda pikir saya berusaha terlalu keras? Apakah itu sebabnya Anda mengatakan itu?",
  ui_story_5031_50310602_65_dialog_content = "Ya. Saya pikir Anda telah menjadi pesaing utama dalam karnaval ini ... membawa tim kami di pundak Anda.",
  ui_story_5031_50310602_66_dialog_content = "Kau pikir begitu...?",
  ui_story_5031_50310602_67_dialog_content = "Aku tidak pernah menganggapmu sebagai beban. Faktanya, Anda adalah senjata rahasia kami dengan semua hal yang dapat Anda lakukan!",
  ui_story_5031_50310602_68_dialog_content = "Tentu saja, PlayerName. Anda selalu menjadi rekan tim yang sangat penting.",
  ui_story_5031_50310602_69_dialog_content = "Aduh, masya Allah. PlayerName, Anda tidak bisa membiarkan diri Anda dipengaruhi oleh apa yang dikatakan beberapa orang aneh secara acak.",
  ui_story_5031_50310602_70_dialog_content = "Kalian semua…",
  ui_story_5031_50310602_71_dialog_content = "<color=#e8d9bb>Cincin-cincin!</color>",
  ui_story_5031_50310602_72_dialog_content = "Sekarang hijau. Siap-siap!",
  ui_story_5031_50310602_73_dialog_content = "Oke. Semuanya, langsung saja!",
  ui_story_5031_50310701_1_dialog_content = "Kita sudah hampir sampai, PlayerName.",
  ui_story_5031_50310701_2_dialog_content = "Tinggal beberapa langkah lagi ke babak selanjutnya...",
  ui_story_5031_50310701_3_dialog_content = "<color=#e8d9bb>Cincin-cincin!</color>",
  ui_story_5031_50310701_4_dialog_content = "Kita harus pergi! Sekarang juga!",
  ui_story_5031_50310701_5_dialog_content = "Tunggu, berhenti!",
  ui_story_5031_50310701_6_dialog_content = "Sekarang sudah kembali ke warna aslinya!",
  ui_story_5031_50310701_7_dialog_content = "<color=#e8d9bb>Cincin-cincin!</color>",
  ui_story_5031_50310701_8_dialog_content = "Apa yang terjadi? Apakah semakin cepat?",
  ui_story_5031_50310701_9_dialog_content = "Aduh!",
  ui_story_5031_50310701_10_dialog_content = "Astaga. Ini berputar sangat cepat sekarang!",
  ui_story_5031_50310701_11_dialog_content = "Mereka sedang menguji waktu reaksi—jika tidak, mengapa membuatnya begitu tak terduga?",
  ui_story_5031_50310701_12_dialog_content = "Kita harus melangkah dengan hati-hati sekarang.",
  ui_story_5031_50310701_13_dialog_content = "Empat kontestan lainnya tersingkir!",
  ui_story_5031_50310701_14_dialog_content = "Anda melihat gadis itu di sana, Carleen? Saya pikir ada yang salah dengan dia.",
  ui_story_5031_50310701_15_dialog_content = "Dia tidak terlihat terlalu bahagia. Aku bisa merasakan kekuatan Lumina-nya semakin lemah dalam hitungan detik.",
  ui_story_5031_50310701_16_dialog_content = "Huu-huu...",
  ui_story_5031_50310701_17_dialog_content = "Oh tidak. Dia pingsan!",
  ui_story_5031_50310701_18_dialog_content = "Bukankah itu berarti dia akan dibuang ke dalam air?",
  ui_story_5031_50310701_19_dialog_content = "Sepertinya dia kesakitan dengan mata tertutup.",
  ui_story_5031_50310701_20_dialog_content = "Mereka tidak bisa membuangnya ke laut jika dia memiliki kondisi medis!",
  ui_story_5031_50310701_21_dialog_content = "PlayerName, PlayerName, kita harus memikirkan sesuatu.",
  ui_story_5031_50310701_22_dialog_content = "Grah...",
  ui_story_5031_50310701_23_dialog_content = "Kami tidak bisa menunggu lebih lama lagi!",
  ui_story_5031_50310701_24_dialog_content = "Carleen!",
  ui_story_5031_50310702_1_dialog_content = "Waktu habis!!",
  ui_story_5031_50310702_2_dialog_content = "Ada apa, Yang Mulia?",
  ui_story_5031_50310702_3_dialog_content = "Wanita ini sedang tidak sehat.",
  ui_story_5031_50310702_4_dialog_content = "Aku akan melihat-lihat. Aku tahu beberapa obat.",
  ui_story_5031_50310702_5_dialog_content = "Apakah Anda baik-baik saja, nona muda? Bisakah kamu mendengarku?",
  ui_story_5031_50310702_6_dialog_content = "Huu-huu...",
  ui_story_5031_50310702_7_dialog_content = "Aku tahu kondisinya... Sindrom Modali.",
  ui_story_5031_50310702_8_dialog_content = "Cepat, minum pil ini.",
  ui_story_5031_50310702_9_dialog_content = "Bisakah saya menyusahkan Anda untuk membawa selimut itu, Jeno?",
  ui_story_5031_50310702_10_dialog_content = "Tentu.",
  ui_story_5031_50310702_11_dialog_content = "Heh, heh...",
  ui_story_5031_50310702_12_dialog_content = "Laird Elvis... Terima kasih. Saya merasa jauh lebih baik.",
  ui_story_5031_50310702_13_dialog_content = "Jangan terlalu memaksakan diri. Suhu tubuhmu rendah. Anda akan lebih nyaman dalam selimut.",
  ui_story_5031_50310702_14_dialog_content = "Ya... Terima kasih, Pak—Anda mengajari kami latihan aerobik, dan saya selalu minum air hangat.",
  ui_story_5031_50310702_15_dialog_content = "Ya, sangat bagus, Ranka. Saya bangga padamu.",
  ui_story_5031_50310702_16_dialog_content = "Selimutnya, Elvis.",
  ui_story_5031_50310702_17_dialog_content = "Ah. Terima kasih.",
  ui_story_5031_50310702_18_dialog_content = "Patou!",
  ui_story_5031_50310702_19_dialog_content = "Ini saya, Pak.",
  ui_story_5031_50310702_20_dialog_content = "Mintalah para penjaga membawanya kembali ke keluarganya dan memberi kesan kepada mereka betapa mendesaknya kunjungan ke rumah sakit.",
  ui_story_5031_50310702_21_dialog_content = "Serahkan pada saya, Pak!",
  ui_story_5031_50310702_22_dialog_content = "Apakah Anda melihat betapa mudanya dia, Jeno?",
  ui_story_5031_50310702_23_dialog_content = "...",
  ui_story_5031_50310702_24_dialog_content = "Laird Elvis, Anda adalah laird yang setia dan baik hati di Harbour City.",
  ui_story_5031_50310702_25_dialog_content = "Saya telah melihat lebih banyak bangsawan dari Anda hari ini daripada dari banyak yang disebut bangsawan seumur hidup.",
  ui_story_5031_50310702_26_dialog_content = "Harbour City benar-benar beruntung memiliki laird seperti Anda.",
  ui_story_5031_50310702_27_dialog_content = "Sheesh. Dia hanya orang biasa. Saya pikir Anda telah kehilangan perspektif, Yang Mulia.",
  ui_story_5031_50310702_28_dialog_content = "Sangat tidak menyenangkan untuk... setengah diserang oleh orang biasa yang tersingkir itu.",
  ui_story_5031_50310702_29_dialog_content = "Saya hampir terlempar ke laut. Tapi saya berhasil bangkit kembali.",
  ui_story_5031_50310702_30_dialog_content = "Kapan kita bisa kembali untuk mandi dan berganti pakaian?",
  ui_story_5031_50310702_31_dialog_content = "Diam.",
  ui_story_5031_50310702_32_dialog_content = "Terima kasih atas kata-kata baik Anda, Yang Mulia.",
  ui_story_5031_50310702_33_dialog_content = "Tapi aku tidak bisa membantu lebih dari itu.",
  ui_story_5031_50310702_34_dialog_content = "Maaf, tapi panggilan tugas mendesak. Sampai nanti.",
  ui_story_5031_50310702_35_dialog_content = "Tentu.",
  ui_story_5031_50310702_36_dialog_content = "...",
  ui_story_5031_50310702_37_dialog_content = "Anda mengirim untuk saya, Pak?",
  ui_story_5031_50310702_38_dialog_content = "Kita kehabisan waktu, Patou.",
  ui_story_5031_50310702_39_dialog_content = "Itu <color=#FFB400>Batu angin</color> tumbuh lebih lemah. Saya dapat merasakannya.",
  ui_story_5031_50310702_40_dialog_content = "Itu sebabnya saya, dan kemudian gadis itu, jatuh di bawah penyakit ini.",
  ui_story_5031_50310702_41_dialog_content = "Saya khawatir segel mungkin tidak bertahan lebih lama.",
  ui_story_5031_50310702_42_dialog_content = "Mengapa tidak mencari bantuan dari Lumopolis, Pak? Bagaimana dengan wanita yang baik hati itu, Putri Carleen?",
  ui_story_5031_50310702_43_dialog_content = "Dia mungkin menghubungkan kita dengan Tuhan Schwartz.",
  ui_story_5031_50310702_44_dialog_content = "Saya percaya itu Tuhan Schwartz memiliki wawasan untuk membantu kami dalam hal ini.",
  ui_story_5031_50310702_45_dialog_content = "Tetapi alasan saya memberitahu saya untuk tidak menaruh kepercayaan pada Dewan Penatua.",
  ui_story_5031_50310702_46_dialog_content = "Apa yang lebih mungkin? Bahwa mereka akan mengirim pasukan untuk mempertahankan Harbour City? Atau meminta kami untuk mengosongkan tanah yang telah kami warisi secara turun-temurun?",
  ui_story_5031_50310702_47_dialog_content = "Pikirkan biaya yang harus dibayar oleh nenek moyang kita untuk melindungi rahasia Windstone... Itu disimpan dengan baik bahkan sampai hari ini.",
  ui_story_5031_50310702_48_dialog_content = "Jika keberadaannya didengungkan di luar negeri, kita mungkin juga harus bersaing dengan mereka yang ingin mengambilnya.",
  ui_story_5031_50310702_49_dialog_content = "Lalu, tanpa Windstone, Harbour City pasti hilang.",
  ui_story_5031_50310702_50_dialog_content = "Saya tidak akan memberikan kehancuran yang nenek moyang kita berikan hidup mereka dan generasi yang telah dibangun dengan keringat dan kerja keras.",
  ui_story_5031_50310702_51_dialog_content = "Semua yang saya lakukan adalah untuk keselamatan dan keamanan Harbour City. Kenyataannya adalah kita sendiri.",
  ui_story_5031_50310702_52_dialog_content = "Ya pak. Saya mengerti.",
  ui_story_5031_50310702_53_dialog_content = "Kami dengan senang hati menawarkan hidup kami untuk api dan pedang untuk membela Harbour City, dan House Modali.",
  ui_story_5031_50310702_54_dialog_content = "Dan tidak ada cara untuk kembali.",
  ui_story_5031_50310702_55_dialog_content = "Kekalahan akan berarti akhir dari Harbour City, dan penduduknya. Tidak ada yang datang untuk menyelamatkan kita.",
  ui_story_5031_50310702_56_dialog_content = "Kita harus belajar bagaimana menyelamatkan diri kita sendiri, Patou.",
  ui_story_5031_50310702_57_dialog_content = "Putri Carleen, apakah Anda yakin akan menyembunyikan identitas Anda?",
  ui_story_5031_50310702_58_dialog_content = "Ya. Saya tidak ingin apa pun datang antara saya dan liburan santai kami. Terima kasih atas pengertiannya, Laird Elvis.",
  ui_story_5031_50310702_59_dialog_content = "Baiklah.",
  ui_story_5031_50310702_60_dialog_content = "Dengarkan aku, semuanya.",
  ui_story_5031_50310702_61_dialog_content = "Wanita yang baru saja pingsan karena sakit akan terlempar ke laut oleh Eclipsites menurut aturan kami.",
  ui_story_5031_50310702_62_dialog_content = "Namun wanita pemberani ini dan teman-temannya mempertaruhkan diskualifikasi untuk menyelamatkannya dari situasi berbahaya!",
  ui_story_5031_50310702_63_dialog_content = "Dia bisa saja jatuh pingsan ke dalam air.",
  ui_story_5031_50310702_64_dialog_content = "Mereka mungkin telah melanggar aturan, tapi kami menghargai kebaikan hati di Harbour City ini!",
  ui_story_5031_50310702_65_dialog_content = "... Dan karena ini adalah kebiasaan kami, saya harap Anda akan bergabung dengan saya untuk menyambut tim mereka kembali ke kompetisi!",
  ui_story_5031_50310702_66_dialog_content = "Hore! Hore!",
  ui_story_5031_50310702_67_dialog_content = "Kamu luar biasa, Laird Elvis!",
  ui_story_5031_50310702_68_dialog_content = "Terima kasih semua! Saya merasa terhormat menjadi gubernur Anda.",
  ui_story_5031_50310702_69_dialog_content = "Terima kasih, Laird Elvis!",
  ui_story_5031_50310702_70_dialog_content = "Jangan menyebutkannya. Saya yakin Anda semua akan melakukan hal yang sama.",
  ui_story_5031_50310702_71_dialog_content = "Anda dan teman Anda dapat kembali ke pertandingan.",
  ui_story_5031_50310702_X71_dialog_content = "Kalau begitu mari kita lanjutkan!",
  ui_story_5031_50310702_X72_dialog_content = "Huff, huff...! Kalian berlari terlalu cepat. Kami bahkan telah mencapai garis finish entah bagaimana.",
  ui_story_5031_50310702_X73_dialog_content = "Cepat, PlayerName! Ini berubah warna lagi!",
  ui_story_5031_50310702_X74_dialog_content = "Dengan serius? Tidak, aku tidak bisa melakukannya lagi.",
  ui_story_5031_50310702_72_dialog_content = "Berlari di sini, PlayerName. Kami akan menangkapmu!",
  ui_story_5031_50310702_73_dialog_content = "Siap!",
  ui_story_5031_50310702_74_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310702_75_dialog_content = "Hampir saja.",
  ui_story_5031_50310702_76_dialog_content = "Anda sangat berat, PlayerName.",
  ui_story_5031_50310702_77_dialog_content = "Kita berhasil!",
  ui_story_5031_50310702_78_dialog_content = "Kami berada di babak berikutnya!",
  ui_story_5031_50310702_79_dialog_content = "Tetapi banyak pesaing kuat lainnya juga berhasil.",
  ui_story_5031_50310702_80_dialog_content = "Orang itu membuat keributan... adalah Petugas itu Gronru?",
  ui_story_5031_50310702_81_dialog_content = "Hai! Cepatlah, Ciel!",
  ui_story_5031_50310702_82_dialog_content = "Ayo, gunakan ultimatemu!",
  ui_story_5031_50310702_83_dialog_content = "Atau kita akan tersingkir!",
  ui_story_5031_50310702_84_dialog_content = "C-Ce, tapi <color=#FFB400>Styx</color> masih...",
  ui_story_5031_50310702_85_dialog_content = "Uh... Oke. \"Pembaruan status mekanisme kaki—Tanda II.\"",
  ui_story_5031_50310702_86_dialog_content = "\"Tingkatkan pelepasan daya sebesar 50%.\"",
  ui_story_5031_50310702_87_dialog_content = "Ayo kita pergi!",
  ui_story_5031_50310702_88_dialog_content = "Wow! Ciel langsung pergi!",
  ui_story_5031_50310702_89_dialog_content = "Ahhh! Menyingkirlah, semuanya! Saya kehilangan kendali atas Styx!",
  ui_story_5031_50310702_90_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5031_50310702_91_dialog_content = "V-Sangat mengesankan. Bahkan meninggalkan lubang di gedung.",
  ui_story_5031_50310702_92_dialog_content = "Dan tanda yang agak panjang di geladak.",
  ui_story_5031_50310702_93_dialog_content = "Wow, itu luar biasa. Ke mana dia pergi?",
  ui_story_5031_50310702_94_dialog_content = "Apakah kamu baik-baik saja, Ciel?",
  ui_story_5031_50310702_95_dialog_content = "Ikeh ikeh! Saya tidak berpikir saya terluka.",
  ui_story_5031_50310702_96_dialog_content = "Anda mungkin tidak terluka, tapi saya tidak bisa mengatakan hal yang sama untuk Zamrud kita tercinta.",
  ui_story_5031_50310702_97_dialog_content = "Oh. Aku sangat menyesal!",
  ui_story_5031_50310702_98_dialog_content = "Aku tidak bermaksud! Saya belum selesai men-debug Styx—tidak, ini salah saya karena lemah...",
  ui_story_5031_50310702_99_dialog_content = "Tidak apa-apa. Saya tidak tertarik untuk disalahkan. Mari kita pikirkan apa yang harus dilakukan selanjutnya.",
  ui_story_5031_50310702_100_dialog_content = "Idealnya, kami hanya menyewa seseorang untuk memperbaikinya.",
  ui_story_5031_50310702_101_dialog_content = "Tapi saya tidak berpikir Ciel adalah anak uang.",
  ui_story_5031_50310702_102_dialog_content = "Kamu benar. Saya minta maaf atas hal tersebut...",
  ui_story_5031_50310702_103_dialog_content = "Berhenti meminta maaf. Ayo. Tidak apa-apa!",
  ui_story_5031_50310702_104_dialog_content = "Itu mengingatkanku! Anda dapat menantang ronde kami berikutnya—kontes selancar!",
  ui_story_5031_50310702_105_dialog_content = "Laird Elvis mensponsori putaran berikutnya dengan hadiah tambahan untuk pemenang.",
  ui_story_5031_50310702_106_dialog_content = "B-Benarkah!?",
  ui_story_5031_50310702_107_dialog_content = "Memang! Dan aku cukup yakin... itu lima juta Nightium!",
  ui_story_5031_50310702_108_dialog_content = "Itu cukup untuk menutupi biaya perbaikan.",
  ui_story_5031_50310702_109_dialog_content = "Luar biasa! aku masuk!",
  ui_story_5031_50310702_110_dialog_content = "Hei, mari kita tidak maju dari diri kita sendiri.",
  ui_story_5031_50310702_111_dialog_content = "Saya dan saudara perempuan Merylt juga bergabung.",
  ui_story_5031_50310702_112_dialog_content = "Dan aku berniat untuk menang, Ciel!",
  ui_story_5031_50310702_113_dialog_content = "Kalau kalah... oh, apa namanya lagi? Stix, kan?",
  ui_story_5031_50310702_114_dialog_content = "Ini akan menjadi milikku.",
  ui_story_5031_50310702_115_dialog_content = "... Aku tidak bisa.",
  ui_story_5031_50310702_116_dialog_content = "Hai. Saya hanya ingin meminjamnya untuk mempelajarinya. Aku tidak akan mencurinya darimu atau semacamnya.",
  ui_story_5031_50310702_117_dialog_content = "Aku akan mengembalikannya setelah.",
  ui_story_5031_50310702_118_dialog_content = "Maaf.",
  ui_story_5031_50310702_119_dialog_content = "Masalahnya... aku tidak bisa melakukan itu...",
  ui_story_5031_50310801_1_dialog_content = "Hai semuanya! Saya harap angin musim panas yang sejuk dan buah-buahan gratis membuat Anda semua bersemangat?",
  ui_story_5031_50310801_2_dialog_content = "Anda terlihat cukup istirahat dan siap untuk masuk ke babak kompetisi berikutnya!",
  ui_story_5031_50310801_3_dialog_content = "Ya!",
  ui_story_5031_50310801_4_dialog_content = "Oh, kamu terlihat sangat bersemangat! Dan sepertinya Anda tidak bisa menunggu lebih lama lagi.",
  ui_story_5031_50310801_5_dialog_content = "Jadi kali ini kita bisa menyeka sebagian keringat yang telah kita kumpulkan.",
  ui_story_5031_50310801_6_dialog_content = "Saatnya berendam air dingin di pemandian besar laut di bawah terik matahari!",
  ui_story_5031_50310801_7_dialog_content = "Ini adalah saat yang kalian semua tunggu-tunggu—a <size=45>kontes selancar</size>!",
  ui_story_5031_50310801_8_dialog_content = "Wow!!",
  ui_story_5031_50310801_9_dialog_content = "Dan karena sudah menjadi tradisi mengadakan kontes selancar di Harbour City, tim pemenang...",
  ui_story_5031_50310801_10_dialog_content = "... Mereka juga akan menerima hadiah khusus dari Laird Elvis dari <color=#FFB400>lima juta Nightium</color>!",
  ui_story_5031_50310801_11_dialog_content = "F-Lima juta?",
  ui_story_5031_50310801_12_dialog_content = "Lima juta!?",
  ui_story_5031_50310801_13_dialog_content = "PlayerName, Vice! Jangan serakah!",
  ui_story_5031_50310801_14_dialog_content = "Jangan lupa mengapa kita ada di sini!",
  ui_story_5031_50310801_15_dialog_content = "Ya... Tapi mungkin kita bisa memenangkan uang sambil membantu Fia mendapatkan binatang yang menakjubkan itu.",
  ui_story_5031_50310801_16_dialog_content = "Harbour City cukup kaya, kan?",
  ui_story_5031_50310801_17_dialog_content = "Memang itu. Mereka sedang booming dalam beberapa tahun terakhir.",
  ui_story_5031_50310801_18_dialog_content = "Tidak setiap hari Anda melihat seorang laird memberikan hadiah besar untuk rakyatnya.",
  ui_story_5031_50310801_19_dialog_content = "Tidak heran Harbour City berjalan dengan baik jika itu yang Laird Elvis rencanakan.",
  ui_story_5031_50310801_20_dialog_content = "Carleen benar-benar telah melakukan yang terbaik, bukan?",
  ui_story_5031_50310801_21_dialog_content = "Saya kira Anda sudah memikirkan semua masalah ekonomi selama liburan ini?",
  ui_story_5031_50310801_22_dialog_content = "Oh, aku minta maaf jika aku membunuh mood untuk kalian ...",
  ui_story_5031_50310801_23_dialog_content = "Tidak tidak. Bukan itu yang saya maksud.",
  ui_story_5031_50310801_24_dialog_content = "Aku hanya sedikit khawatir kau mulai lelah.",
  ui_story_5031_50310801_25_dialog_content = "Ya, Carleen! Itu tidak sebanding dengan stresnya. Mari kita santai!",
  ui_story_5031_50310801_26_dialog_content = "Lihat betapa menyenangkannya Fia dengan nanas itu.",
  ui_story_5031_50310801_27_dialog_content = "Aku yakin dia baik-baik saja dan benar-benar teralihkan dari rencana besarnya.",
  ui_story_5031_50310801_28_dialog_content = "Nyam! Ini benar-benar manis!",
  ui_story_5031_50310801_29_dialog_content = "Itu bagus, Anda tahu, mereka memiliki buah-buahan gratis!",
  ui_story_5031_50310801_30_dialog_content = "Ya. Hal ini memang.",
  ui_story_5031_50310801_31_dialog_content = "Saya harus banyak belajar dari Fia.",
  ui_story_5031_50310801_32_dialog_content = "<size=33>Dan bukan hanya dia, tapi juga Vice dan PlayerName juga...</size>",
  ui_story_5031_50310801_33_dialog_content = "Anda dan saya sama-sama tahu bahwa Eclipsites tidak dapat dimusnahkan.",
  ui_story_5031_50310801_34_dialog_content = "Seorang penguasa harus lebih menahan diri—tidak terburu-buru melakukan tindakan untuk menghentikan mereka sendiri.",
  ui_story_5031_50310801_35_dialog_content = "Anda bukan satu-satunya yang akan menderita dalam pertukaran itu—bagaimana dengan mereka yang mengikuti Anda?",
  ui_story_5031_50310801_36_dialog_content = "...",
  ui_story_5031_50310801_37_dialog_content = "Saya ingin Anda benar-benar mempertimbangkan mengapa saya mengizinkan Anda untuk ikut dengan PlayerName dan yang lainnya.",
  ui_story_5031_50310801_38_dialog_content = "Aku…",
  ui_story_5031_50310801_39_dialog_content = "Anda membutuhkan lebih banyak waktu untuk tumbuh menjadi peran Anda yang mulia dan istimewa dalam hidup.",
  ui_story_5031_50310801_40_dialog_content = "... Ya, Ayah.",
  ui_story_5031_50310801_41_dialog_content = "Carleen? Carleen!",
  ui_story_5031_50310801_42_dialog_content = "Hah? Maaf, apa yang kamu katakan?",
  ui_story_5031_50310801_43_dialog_content = "Saya hanya mengatakan mungkin kita harus pergi berubah? Kami pasti akan menghabiskan banyak waktu di dalam air.",
  ui_story_5031_50310801_44_dialog_content = "Tidak bisa menodai pakaian baru Anda!",
  ui_story_5031_50310801_45_dialog_content = "Ah. Sangat baik.",
  ui_story_5031_50310801_46_dialog_content = "Tunggu—saya harus berubah menjadi apa?",
  ui_story_5031_50310801_47_dialog_content = "Heh! Itu secara alami akan—",
  ui_story_5031_50310801_48_dialog_content = "baju renang!",
  ui_story_5031_50310801_49_dialog_content = "Wow! Kau terlihat hebat, Carleen dan Vice!",
  ui_story_5031_50310801_50_dialog_content = "Terima kasih, Fia.",
  ui_story_5031_50310801_51_dialog_content = "K-Kenapa kau membawa baju renangku juga?",
  ui_story_5031_50310801_52_dialog_content = "Siapa yang tidak membawa baju renang ke pantai?",
  ui_story_5031_50310801_53_dialog_content = "Ini adalah olahraga air pertama kami, jadi saya tidak berpikir untuk mengeluarkannya sampai sekarang.",
  ui_story_5031_50310801_54_dialog_content = "Saya berharap saya punya baju renang juga!",
  ui_story_5031_50310801_55_dialog_content = "Kami akan langsung menuju outlet mode Harbour City setelah memesan satu untuk Anda!",
  ui_story_5031_50310801_56_dialog_content = "Benarkah? Terima kasih, Vice!",
  ui_story_5031_50310801_57_dialog_content = "Wow. Pertama kali saya memesan pakaian renang untuk saya. Luar biasa!",
  ui_story_5031_50310801_58_dialog_content = "Saya juga memperhatikan beberapa peralatan yang sangat bagus sebelumnya. Mungkin kita bisa membelinya juga!",
  ui_story_5031_50310801_59_dialog_content = "Bagus!",
  ui_story_5031_50310801_60_dialog_content = "Lalu…",
  ui_story_5031_50310801_61_dialog_content = "Ehem, aku...",
  ui_story_5031_50310801_62_dialog_content = "Hah? Apa itu, PlayerName?",
  ui_story_5031_50310801_63_dialog_content = "Saya minta maaf karena mengganggu Anda di tengah obrolan yang hebat ...",
  ui_story_5031_50310801_64_dialog_content = "Tapi... Aku tidak bisa berselancar.",
  ui_story_5031_50310801_65_dialog_content = "<size=45>Apa?!</size>",
  ui_story_5031_50310801_66_dialog_content = "Jadi itu berarti saya tidak akan mendapatkan baju renang saya?",
  ui_story_5031_50310801_67_dialog_content = "Itu yang kamu khawatirkan? Apakah Anda lupa tujuan kita yang sebenarnya di sini—binatang ajaib Anda?",
  ui_story_5031_50310801_68_dialog_content = "Baju renangku dan juga Cloudwhale... Boo-hoo...",
  ui_story_5031_50310801_69_dialog_content = "... Mereka semua di luar jangkauan! Waaaah!",
  ui_story_5031_50310801_70_dialog_content = "Maafkan aku, Fia. Jangan menangis!",
  ui_story_5031_50310801_71_dialog_content = "Aku akan memikirkan cara—bahkan jika kita tidak mendapatkan tempat pertama...",
  ui_story_5031_50310801_72_dialog_content = "Saya yakin kita bisa menemukan cukup uang untuk membeli beberapa pakaian renang!",
  ui_story_5031_50310801_73_dialog_content = "... Sungguh?",
  ui_story_5031_50310801_74_dialog_content = "Ya! Carleen dan Vice bisa menjamin saya, bukan?",
  ui_story_5031_50310801_75_dialog_content = "T-Itu bagus sekali!",
  ui_story_5031_50310801_76_dialog_content = "Maaf, saya seharusnya tidak mulai berfantasi tentang memenangkan hadiah sebelum bertanya tentang situasinya dengan jelas.",
  ui_story_5031_50310801_77_dialog_content = "Itu bukan salahmu, Vice. Aku hanya sangat tidak terkoordinasi. Aku bahkan tidak bisa berselancar!",
  ui_story_5031_50310801_78_dialog_content = "Oh, tidak, Anda salah paham, PlayerName.",
  ui_story_5031_50310801_79_dialog_content = "Tidak semua orang cocok untuk berselancar.",
  ui_story_5031_50310801_80_dialog_content = "Kebetulan saya pernah mempelajarinya.",
  ui_story_5031_50310801_X80_dialog_content = "Saya juga begitu. Ketika saya mengunjungi Harbour City di masa kecil saya, saya hanya menonton kompetisi selancar tahun itu.",
  ui_story_5031_50310801_X81_dialog_content = "Itu sebabnya saya menjadi tertarik di dalamnya dan menemukan diri saya seorang guru.",
  ui_story_5031_50310801_81_dialog_content = "Oh? Jadi belajar surfing dari mana, Fia?",
  ui_story_5031_50310801_82_dialog_content = "Hah? Saya tidak pernah belajar berselancar.",
  ui_story_5031_50310801_83_dialog_content = "Apa?!",
  ui_story_5031_50310801_84_dialog_content = "Lalu kenapa kamu menangis? Jika Anda belum pernah melakukannya sebelumnya dan tidak tahu caranya!",
  ui_story_5031_50310801_85_dialog_content = "Bagaimana kamu bisa meneriakiku seperti itu, Caelestite! Anda tidak akan menemukan pacar dengan sikap seperti itu.",
  ui_story_5031_50310801_86_dialog_content = "Pacar g?",
  ui_story_5031_50310801_87_dialog_content = "Apa yang kau bicarakan? Hei, kembali!",
  ui_story_5031_50310801_88_dialog_content = "Wow! Semua orang menuju air! Kita harus pergi—sekarang!",
  ui_story_5031_50310801_89_dialog_content = "... Kamu cepat!",
  ui_story_5031_50310801_90_dialog_content = "...",
  ui_story_5031_50310801_91_dialog_content = "...",
  ui_story_5031_50310801_92_dialog_content = "(Bagaimana itu menjadi begitu canggung tiba-tiba?)",
  ui_story_5031_50310801_93_dialog_content = "Ahem, jadi, kita akan ke sana sekarang juga, kan?",
  ui_story_5031_50310801_94_dialog_content = "Ya. Saya kira demikian.",
  ui_story_5031_50310801_95_dialog_content = "Oke. Ayo pergi.",
  ui_story_5031_50310801_96_dialog_content = "(Apa yang ada di dalamnya?)",
  ui_story_5031_50310801_97_dialog_content = "Benar. Letakkan kedua tangan sejajar di sekitar dada bagian bawah dan rapatkan kedua kaki Anda.",
  ui_story_5031_50310801_98_dialog_content = "Kemudian gunakan kekuatan di lengan Anda untuk menopang tubuh Anda.",
  ui_story_5031_50310801_99_dialog_content = "L-Seperti ini?",
  ui_story_5031_50310801_100_dialog_content = "Betul sekali. Menatap lurus ke depan. Anda baik-baik saja.",
  ui_story_5031_50310801_101_dialog_content = "Saat ombak datang, itu isyarat Anda untuk berdiri. Jaga agar kaki Anda selebar bahu dan luruskan punggung Anda.",
  ui_story_5031_50310801_102_dialog_content = "Berikut gelombang!",
  ui_story_5031_50310801_103_dialog_content = "Rasakan kecepatan papan selancar Anda di bawah ombak? Sedang terjadi!",
  ui_story_5031_50310801_104_dialog_content = "B-baiklah!",
  ui_story_5031_50310801_105_dialog_content = "Berdiri... Wow!",
  ui_story_5031_50310801_106_dialog_content = "<color=#e8d9bb>Celepuk!</color>",
  ui_story_5031_50310801_107_dialog_content = "PlayerName!",
  ui_story_5031_50310801_108_dialog_content = "*Uhuk-uhuk*",
  ui_story_5031_50310801_109_dialog_content = "Aku baik-baik saja. Aku masih hidup...",
  ui_story_5031_50310801_110_dialog_content = "Ayo, PlayerName. Jangan terlalu lemah.",
  ui_story_5031_50310801_111_dialog_content = "Bahkan aku tahu bagaimana cara berdiri di atas papan selancar.",
  ui_story_5031_50310801_112_dialog_content = "Anda tidak berdiri sama sekali! Anda jelas berjongkok!",
  ui_story_5031_50310801_113_dialog_content = "Aku masih lebih baik darimu!",
  ui_story_5031_50310801_114_dialog_content = "Dan dengan ide Carleen, yang perlu saya pelajari hanyalah berjongkok!",
  ui_story_5031_50310801_115_dialog_content = "Jangan lupa saya satu-satunya yang bisa meminta ikan datang untuk membantu mendorong papan selancar saya!",
  ui_story_5031_50310801_116_dialog_content = "Anda harus menjadi...",
  ui_story_5031_50310801_117_dialog_content = "Waktunya telah tiba!",
  ui_story_5031_50310801_118_dialog_content = "Wow! Senang melihat begitu banyak orang di luar sana berlatih di atas ombak. Kerja yang baik!",
  ui_story_5031_50310801_119_dialog_content = "Sepertinya janji 5 juta Nightium sangat menarik!",
  ui_story_5031_50310801_120_dialog_content = "Haha!",
  ui_story_5031_50310801_121_dialog_content = "Heh! Hanya bercanda!",
  ui_story_5031_50310801_122_dialog_content = "Jadi mari kita mulai dengan aturan!",
  ui_story_5031_50310801_123_dialog_content = "Seperti sebelumnya, empat orang menjadi satu tim. Anda akan bergiliran menghadapi ombak.",
  ui_story_5031_50310801_124_dialog_content = "Jika Anda tidak memiliki empat orang di tim Anda, Anda dapat masuk dengan lebih sedikit.",
  ui_story_5031_50310801_125_dialog_content = "Anda dapat masuk hanya dengan dua orang, karena hanya dua pemain terbaik di tim Anda yang akan dinilai!",
  ui_story_5031_50310801_126_dialog_content = "Seperti sebelumnya, Anda mendapatkan poin untuk menghilangkan ilusi Eclipsite. Tapi Anda tidak akan tersingkir dengan jatuh ke dalam air.",
  ui_story_5031_50310801_127_dialog_content = "Terlepas dari Eclipsites, setengah dari poin Anda akan berasal dari teknik berselancar Anda.",
  ui_story_5031_50310801_128_dialog_content = "Jadi saya sarankan mengatur urutan di mana Anda akan pergi. Ini akan sangat penting!",
  ui_story_5031_50310801_129_dialog_content = "Oh tidak! Saya baru saja mengungkapkan rahasia penting untuk menang. Saya kira itu akan membuat kontes jauh lebih intens!",
  ui_story_5031_50310801_130_dialog_content = "Hahahahaha!",
  ui_story_5031_50310801_131_dialog_content = "Pokoknya—bersenang-senanglah, semuanya!",
  ui_story_5031_50310801_132_dialog_content = "Kami baru saja akan memulai putaran pertama—sebentar lagi.",
  ui_story_5031_50310801_133_dialog_content = "Bisakah semua tim berbaris? Dan bisakah kita memiliki pemain pertama dari setiap tim berdasarkan lokasi awal?",
  ui_story_5031_50310801_134_dialog_content = "Saya ingin memberi tahu Anda semua rahasia kecil ...",
  ui_story_5031_50310801_135_dialog_content = "Peselancar pertama kita hari ini akan menjadi... aku!",
  ui_story_5031_50310801_136_dialog_content = "Ya!",
  ui_story_5031_50310801_137_dialog_content = "Kamu pasti bisa berselancar, Rainbow!",
  ui_story_5031_50310801_138_dialog_content = "Rainbow benar-benar memenangkan orang banyak.",
  ui_story_5031_50310801_139_dialog_content = "Dia pasti hebat dalam hal ini. Dia punya banyak kepercayaan diri.",
  ui_story_5031_50310801_140_dialog_content = "Baiklah. Bagaimanapun, aturan mengatakan hanya dua pencetak gol terbaik yang akan dihitung, jadi itu bisa bagus untuk kita.",
  ui_story_5031_50310801_141_dialog_content = "Itulah mengapa urutan Anda masuk sangat penting.",
  ui_story_5031_50310801_142_dialog_content = "Jadi jika mereka memiliki Rainbow untuk tim mereka, maka kita harus...",
  ui_story_5031_50310801_143_dialog_content = "Hmph! Bukankah sudah jelas aku harus pergi dulu? Aku yang terbaik!",
  ui_story_5031_50310801_144_dialog_content = "... Anda? Terbaik?",
  ui_story_5031_50310801_145_dialog_content = "Apa yang Anda maksudkan?",
  ui_story_5031_50310801_146_dialog_content = "Jangan lupa aku satu-satunya yang berhasil mengikuti instruksi Carleen saat itu!",
  ui_story_5031_50310801_147_dialog_content = "Ini adalah hal yang pasti! Aku akan menang dengan mudah.",
  ui_story_5031_50310801_148_dialog_content = "Anda bisa berdiri di sini dan menunggu kemenangan saya kembali, PlayerName!",
  ui_story_5031_50310801_149_dialog_content = "... Apakah akan semudah itu?",
  ui_story_5031_50310801_150_dialog_content = "Sesuatu tentang kesombongannya membuatku semakin khawatir.",
  ui_story_5031_50310801_151_dialog_content = "Ahem, saya harus menjadi MC yang satu ini karena Rainbow telah melibatkan dirinya sendiri.",
  ui_story_5031_50310801_152_dialog_content = "Uh... Harus kuakui kalian semua tampak kecil dari sudut pandang ini, terombang-ambing di atas ombak...",
  ui_story_5031_50310801_153_dialog_content = "Meskipun Anda kecil, Anda telah menguasai hukum gerak alami, yang memungkinkan Anda untuk berselancar.",
  ui_story_5031_50310801_154_dialog_content = "Ini tidak kurang dari sebuah bentuk seni kecerdasan tertinggi dan rasa estetika ...",
  ui_story_5031_50310801_155_dialog_content = "Selamat tinggal, semuanya! Naiki ritme ombak ini, dan taklukkan...",
  ui_story_5031_50310801_156_dialog_content = "... Cukup! Ayo mulai! Awal!",
  ui_story_5031_50310801_157_dialog_content = "Kami menunggu!",
  ui_story_5031_50310801_158_dialog_content = "Ck. Aku hanya tidak bisa mengerti orang bodoh yang biasa-biasa saja.",
  ui_story_5031_50310801_159_dialog_content = "Karena kalian semua sangat tidak sabar, maka mari kita mulai. Pergi!",
  ui_story_5031_50310801_160_dialog_content = "...",
  ui_story_5031_50310801_161_dialog_content = "Hah? Itu dia?",
  ui_story_5031_50310801_162_dialog_content = "Kami ingin pembawa acara lain!",
  ui_story_5031_50310801_163_dialog_content = "Ha ha! Jeno yang malang.",
  ui_story_5031_50310801_164_dialog_content = "Kalau begitu, lebih baik aku pergi!",
  ui_story_5031_50310801_165_dialog_content = "Ayo, Ciel! Ini dimulai! Cepat!",
  ui_story_5031_50310801_166_dialog_content = "Ini sudah dimulai? Bukankah ada semacam sinyal?",
  ui_story_5031_50310801_167_dialog_content = "O-Oh, sayang. \"Pembaruan status mekanisme kaki—Mode Semprot\"!",
  ui_story_5031_50310801_168_dialog_content = "Apakah mereka berselancar dengan mekanisme?",
  ui_story_5031_50310801_169_dialog_content = "Ombak baru saja menyapu para kontestan itu ke laut!",
  ui_story_5031_50310801_170_dialog_content = "Apa yang harus kita lakukan tentang itu?",
  ui_story_5031_50310801_171_dialog_content = "Tidak apa-apa. Fia cukup jauh sekarang ... dan tampaknya akan stabil.",
  ui_story_5031_50310801_172_dialog_content = "Oooh! Pergilah, Rainbow!!",
  ui_story_5031_50310801_173_dialog_content = "Wow! Dia berubah seperti seorang profesional!",
  ui_story_5031_50310801_174_dialog_content = "Gadis di mekanisme itu juga tidak terlalu buruk. Dia cepat!",
  ui_story_5031_50310801_175_dialog_content = "Tapi tidak terlihat sebagus Rainbow di papan.",
  ui_story_5031_50310801_176_dialog_content = "Hmph. Kontes ini jauh dari sesederhana yang Anda bayangkan.",
  ui_story_5031_50310801_177_dialog_content = "Mengaum! Makhluk terkutuk dari dalam!",
  ui_story_5031_50310801_178_dialog_content = "Graaaah!",
  ui_story_5031_50310801_179_dialog_content = "Mereka di sini!",
  ui_story_5031_50310801_180_dialog_content = "Heh! Rainbow akan berubah lagi!",
  ui_story_5031_50310801_181_dialog_content = "Ooh. Hati-hati, Rainbow!",
  ui_story_5031_50310801_182_dialog_content = "Hah? Ada Eclipsites yang keluar dari ombak!",
  ui_story_5031_50310801_183_dialog_content = "Itu akan sedikit sulit...",
  ui_story_5031_50310801_184_dialog_content = "R-Rainbow?",
  ui_story_5031_50310801_185_dialog_content = "Yaaaaaa!",
  ui_story_5031_50310801_186_dialog_content = "Aku sudah cukup lama bertahan denganmu, Eclipsites yang malang!",
  ui_story_5031_50310801_187_dialog_content = "<size=45>Mati!</size>",
  ui_story_5031_50310801_188_dialog_content = "Anda tidak terlihat terlalu bahagia. Apa kau memikirkan gadis Ranka itu?",
  ui_story_5031_50310802_X1_dialog_content = "Anda tidak terlihat terlalu bahagia. Apa kau memikirkan gadis Ranka itu?",
  ui_story_5031_50310802_1_dialog_content = "Oh, eh, ya...",
  ui_story_5031_50310802_2_dialog_content = "Biarkan saya memberi Anda beberapa buah. Anda harus tetap terhidrasi.",
  ui_story_5031_50310802_3_dialog_content = "Terima kasih, Jeno.",
  ui_story_5031_50310802_4_dialog_content = "Apakah obat yang baru saja Anda berikan padanya \"solusi\" yang Anda bicarakan?",
  ui_story_5031_50310802_5_dialog_content = "Sama sekali tidak. Itu adalah sesuatu yang saya temukan setelah mempelajari teks-teks lama. Itu hanya untuk menghilangkan rasa sakit sementara.",
  ui_story_5031_50310802_6_dialog_content = "Namun Anda menemukan itu?",
  ui_story_5031_50310802_7_dialog_content = "Sekali waktu, Anda ingin menjadi seorang koki. Tapi Anda menjadi apoteker?",
  ui_story_5031_50310802_8_dialog_content = "Heh! Harbour City tidak membutuhkan lebih banyak koki, tetapi kami membutuhkan seseorang yang memahami Sindrom Modali dengan sangat baik.",
  ui_story_5031_50310802_9_dialog_content = "Jadi, dengan kata lain, Anda mengorbankan impian Anda untuk melakukan sesuatu yang hebat dalam hidup Anda?",
  ui_story_5031_50310802_10_dialog_content = "Saya tidak pernah ingin menjadi hebat. Aku hanya tidak ingin berdiri di saat orang lain kesakitan.",
  ui_story_5031_50310802_11_dialog_content = "Dan saya bukan seorang apoteker. Saya hanya menyalin apa yang saya baca di gulungan kuno. Itu mudah.",
  ui_story_5031_50310802_12_dialog_content = "Saya akan merasa bebas untuk mengejar impian saya setelah saya mengetahui Sindrom Modali.",
  ui_story_5031_50310802_13_dialog_content = "Dan apa yang akan Anda lakukan?",
  ui_story_5031_50310802_14_dialog_content = "Saya mungkin mencoba membuka rantai ruang seni kelas atas dengan restoran yang terpasang.",
  ui_story_5031_50310802_15_dialog_content = "Anda masih ingat janji itu dari bertahun-tahun yang lalu?",
  ui_story_5031_50310802_16_dialog_content = "Sudah begitu lama... Saya pikir Anda sudah lupa.",
  ui_story_5031_50310802_17_dialog_content = "Saya memiliki ingatan yang sangat baik. Saya bahkan ingat hal-hal kecil—seperti potret yang seharusnya Anda lukis untuk saya.",
  ui_story_5031_50310802_18_dialog_content = "Saya telah mengosongkan ruang di galeri seni Harbour City.",
  ui_story_5031_50310802_19_dialog_content = "...",
  ui_story_5031_50310802_20_dialog_content = "Jadi ada yang bisa saya bantu?",
  ui_story_5031_50310802_21_dialog_content = "Apa maksudmu?",
  ui_story_5031_50310802_22_dialog_content = "Apakah ada yang bisa saya lakukan untuk membantu Anda dengan \"Sindrom Modali\" ini?",
  ui_story_5031_50310802_23_dialog_content = "...",
  ui_story_5031_50310802_24_dialog_content = "Sebenarnya...",
  ui_story_5031_50310802_25_dialog_content = "Wow! Rainbow luar biasa!",
  ui_story_5031_50310802_26_dialog_content = "Perpaduan sempurna antara kekuatan dan keindahan!",
  ui_story_5031_50310802_27_dialog_content = "... Apa yang Anda katakan?",
  ui_story_5031_50310802_28_dialog_content = "Tidak apa-apa. Mari kita nikmati acaranya dulu.",
  ui_story_5031_50310802_29_dialog_content = "Saya harus berusaha menjadi hakim yang baik. Tidak ingin mengecewakan para kontestan.",
  ui_story_5031_50310802_30_dialog_content = "Rainbow sangat kuat—dan juga menakutkan...",
  ui_story_5031_50310802_31_dialog_content = "Kau benar.",
  ui_story_5031_50310802_32_dialog_content = "Jangan katakan itu tentang Rainbow, buncis!",
  ui_story_5031_50310802_33_dialog_content = "Ya. Bahkan jika Merylt peduli padamu!",
  ui_story_5031_50310802_34_dialog_content = "Maaf. Saya bersungguh-sungguh dengan cara yang baik!",
  ui_story_5031_50310802_35_dialog_content = "Saya sangat terpesona oleh tampilan semangatnya yang tak kenal takut ...",
  ui_story_5031_50310802_36_dialog_content = "Jangan membuat masalah, Subli.",
  ui_story_5031_50310802_37_dialog_content = "Rainbow sangat, sangat membenci Eclipsites. Itu sebabnya dia melakukan itu.",
  ui_story_5031_50310802_38_dialog_content = "Dia membenci Eclipsites?",
  ui_story_5031_50310802_39_dialog_content = "Ya...",
  ui_story_5031_50310802_40_dialog_content = "Desa Rainbow dihancurkan oleh Eclipsites.",
  ui_story_5031_50310802_41_dialog_content = "Begitulah cara dia kehilangan teman dan keluarganya.",
  ui_story_5031_50310802_42_dialog_content = "Itulah sebabnya Rainbow marah setiap kali dia melihat Eclipsites—bahkan ilusi.",
  ui_story_5031_50310802_43_dialog_content = "Dia benar-benar orang yang manis dan lembut. Hanya dengan Eclipsites.",
  ui_story_5031_50310802_44_dialog_content = "Ya. Saya suka Rainbow!",
  ui_story_5031_50310802_45_dialog_content = "Saya juga. Aku lebih menyukainya daripada pemimpin kami—dia selalu terlihat galak.",
  ui_story_5031_50310802_46_dialog_content = "Saya pikir... pemimpin sirkus kami baik...",
  ui_story_5031_50310802_47_dialog_content = "Hanya Anda yang akan mengatakan sesuatu seperti itu!",
  ui_story_5031_50310802_48_dialog_content = "Jadi itu sebabnya ...",
  ui_story_5031_50310802_49_dialog_content = "Melihat sikap ceria Rainbow, sulit dipercaya dia memiliki masa lalu yang tragis.",
  ui_story_5031_50310802_50_dialog_content = "Terkadang gadis yang paling bahagia dan paling manis adalah yang memiliki masa lalu yang paling menyakitkan dan tragis.",
  ui_story_5031_50310802_51_dialog_content = "Saya menghormatinya.",
  ui_story_5031_50310802_52_dialog_content = "Benar. Mau tak mau aku merasa beruntung bukan menjadi orang pertama yang pergi ke sana...",
  ui_story_5031_50310802_53_dialog_content = "Hei... Ada apa dengan Fia?",
  ui_story_5031_50310802_54_dialog_content = "Berhenti datang ke papan selancar saya dari mana-mana sekaligus!",
  ui_story_5031_50310802_55_dialog_content = "Pilih arah!",
  ui_story_5031_50310802_56_dialog_content = "Astaga. Cara yang salah! Tidak ada! Wow!",
  ui_story_5031_50310802_57_dialog_content = "<color=#e8d9bb>Celepuk!</color>",
  ui_story_5031_50310802_58_dialog_content = "Ha ha! Bagaimana gadis itu bisa berbelok 360 derajat?",
  ui_story_5031_50310802_59_dialog_content = "Sekarang dia sedang berenang. Dia tidak akan memenangkan banyak poin untuk gaya.",
  ui_story_5031_50310802_60_dialog_content = "*Uhuk-uhuk*",
  ui_story_5031_50310802_61_dialog_content = "Ikan bodoh!",
  ui_story_5031_50310802_62_dialog_content = "PlayerName pasti akan menertawakanku, boo-hoo...",
  ui_story_5031_50310802_63_dialog_content = "Fia pasti khawatir aku menertawakannya sekarang.",
  ui_story_5031_50310802_64_dialog_content = "Tapi... hahaha!",
  ui_story_5031_50310802_65_dialog_content = "Saya harus mengatakan itu sangat lucu, hahaha!",
  ui_story_5031_50310802_66_dialog_content = "Jangan tertawa terlalu keras, PlayerName.",
  ui_story_5031_50310802_67_dialog_content = "Ini adalah kesalahanku. Saya tidak menyangka Fia memiliki masalah koordinasi dengan ikan.",
  ui_story_5031_50310802_68_dialog_content = "Agak tidak realistis berharap dia bisa menang dengan komunikasi ikan.",
  ui_story_5031_50310802_69_dialog_content = "Tidak tidak. Fia mengatakan itu akan menjadi sepotong kue!",
  ui_story_5031_50310802_70_dialog_content = "Anda tidak bisa terus menyalahkan diri sendiri untuk semuanya, Carleen. Lagipula itu hanya permainan. Siapa peduli?",
  ui_story_5031_50310802_71_dialog_content = "… Iya.",
  ui_story_5031_50310802_72_dialog_content = "Izinkan saya memberi Anda beberapa komentar—saya yakin Anda dapat mengetahui apa yang terjadi jika Anda masih memiliki mata yang berharga.",
  ui_story_5031_50310802_73_dialog_content = "Peselancar paling menonjol dalam kontes saat ini adalah Rainbow of the Circus milik kami sendiri—serta Ciel of Illumina.",
  ui_story_5031_50310802_74_dialog_content = "Keduanya bahkan untuk Eclipsites hancur dan jauh di depan dalam hal gaya.",
  ui_story_5031_50310802_75_dialog_content = "Namun mengingat respon penonton kami, Rainbow tampaknya memiliki teknik yang sedikit lebih unggul.",
  ui_story_5031_50310802_76_dialog_content = "Jadi saya berharap Anda semua, delapan belas kontestan, benar-benar biasa-biasa saja seperti Anda, semoga sukses.",
  ui_story_5031_50310802_77_dialog_content = "... Dan perjuangan yang gagah berani melawan gelombang dan perubahan kehidupan.",
  ui_story_5031_50310802_78_dialog_content = "...",
  ui_story_5031_50310802_79_dialog_content = "Tunggu saja, Jeno!",
  ui_story_5031_50310802_80_dialog_content = "Turun ke laut bersamamu!",
  ui_story_5031_50310802_81_dialog_content = "Graaaah!",
  ui_story_5031_50310802_82_dialog_content = "Fiuh, bahkan jika kamu adalah ilusi, aku tidak bisa menahannya!",
  ui_story_5031_50310802_83_dialog_content = "Aku merasa jauh lebih baik setelah menghancurkan kalian semua!",
  ui_story_5031_50310802_84_dialog_content = "Kau begitu... kuat...",
  ui_story_5031_50310802_85_dialog_content = "Hah? Segera kembali padamu, gadis!",
  ui_story_5031_50310802_86_dialog_content = "Anda cukup cocok untuk saya yang dibesarkan di tepi laut!",
  ui_story_5031_50310802_87_dialog_content = "Sebenarnya, saya baru saja mendapatkan nilai dengan membunuh Eclipsites.",
  ui_story_5031_50310802_88_dialog_content = "Saya tidak mendapat banyak skor dalam hal keterampilan berselancar saya.",
  ui_story_5031_50310802_89_dialog_content = "Saya hanya memanfaatkan celah dalam aturan...",
  ui_story_5031_50310802_90_dialog_content = "Kamu aneh, Ciel.",
  ui_story_5031_50310802_91_dialog_content = "W-Aneh?",
  ui_story_5031_50310802_92_dialog_content = "Ya. Saya memberi Anda pujian, tetapi Anda tidak hanya tidak akan menerimanya, Anda juga terlihat kesal.",
  ui_story_5031_50310802_93_dialog_content = "Apa yang salah dengan mencetak gol dengan membunuh Eclipsites? Bagaimana itu menyalahgunakan aturan?",
  ui_story_5031_50310802_94_dialog_content = "...",
  ui_story_5031_50310802_95_dialog_content = "Ciel, kamu baik. Anda harus lebih percaya diri.",
  ui_story_5031_50310802_96_dialog_content = "Terus meragukan diri sendiri adalah salah satu cara pasti untuk mengacaukan segalanya.",
  ui_story_5031_50310802_97_dialog_content = "Aku…",
  ui_story_5031_50310802_98_dialog_content = "Graagh!",
  ui_story_5031_50310802_99_dialog_content = "Lebih Banyak Eclipsites!? Anda tidak akan lolos!",
  ui_story_5031_50310802_100_dialog_content = "Saya baik?",
  ui_story_5031_50310802_101_dialog_content = "Hehe.. Hehehehe.",
  ui_story_5031_50310802_102_dialog_content = "Kalau begitu, tidak mungkin aku mengecewakan Rainbow!",
  ui_story_5031_50310802_103_dialog_content = "\"Pembaruan status mekanisme lengan—Tipe II\"!",
  ui_story_5031_50310802_104_dialog_content = "\"Tingkatkan pelepasan daya sebesar 60%\"!",
  ui_story_5031_50310802_105_dialog_content = "<color=#e8d9bb>Bergemuruh—</color>",
  ui_story_5031_50310802_106_dialog_content = "C-Ciel!?",
  ui_story_5031_50310802_107_dialog_content = "Apakah dia meningkatkan output energi lagi?",
  ui_story_5031_50310802_108_dialog_content = "Tapi Stix adalah...",
  ui_story_5031_50310802_109_dialog_content = "Hai! Gadis mecha itu melepaskan energi yang begitu kuat di laut!",
  ui_story_5031_50310802_110_dialog_content = "Kapal bergoyang maju mundur! Kita akan tenggelam...",
  ui_story_5031_50310802_111_dialog_content = "Dia terbang ke langit! Dia mencoba untuk mendapatkan lebih banyak poin dengan jumping flip?",
  ui_story_5031_50310802_112_dialog_content = "Tidak, tunggu... Itu...",
  ui_story_5031_50310802_113_dialog_content = "gerhana! Dia menjatuhkan Eclipsites dari laut!",
  ui_story_5031_50310802_114_dialog_content = "Ah, itu...",
  ui_story_5031_50310802_115_dialog_content = "Kekuatan yang luar biasa!",
  ui_story_5031_50310802_116_dialog_content = "Karena saya tidak begitu terampil, saya harus mengandalkan sisa 50% poin.",
  ui_story_5031_50310802_117_dialog_content = "Styx, serangan sapuan!",
  ui_story_5031_50310802_118_dialog_content = "Tetapi mecha memiliki output yang bagus dan dapat meluncurkan serangan area yang efektif.",
  ui_story_5031_50310802_119_dialog_content = "Benar, mechanya lebih berat, jadi tidak bisa melakukan tindakan gesit.",
  ui_story_5031_50310802_120_dialog_content = "Ciel mengambil keuntungan dari ini untuk langsung membunuh sejumlah besar Eclipsites, membalikkan keadaan dengan mendapatkan banyak poin!",
  ui_story_5031_50310802_121_dialog_content = "Mencoba keluar dari situasi putus asa meskipun kekurangannya. Ini menginspirasi.",
  ui_story_5031_50310802_122_dialog_content = "Lalu, apakah laird akan memberinya skor?",
  ui_story_5031_50310802_123_dialog_content = "Tentu saja, pemimpin sirkus.",
  ui_story_5031_50310802_124_dialog_content = "I-Apakah itu...",
  ui_story_5031_50310802_125_dialog_content = "<color=#e8d9bb>Klik... Klak...</color>",
  ui_story_5031_50310802_126_dialog_content = "Hah?",
  ui_story_5031_50310802_127_dialog_content = "Oh tidak! Styx tidak dapat mempertahankan output energi yang begitu tinggi...",
  ui_story_5031_50310802_128_dialog_content = "Ahhhh! Aku jatuh!",
  ui_story_5031_50310802_129_dialog_content = "Ciel!",
  ui_story_5031_50310802_130_dialog_content = "Hah!",
  ui_story_5031_50310802_131_dialog_content = "Hah? Rainbow?",
  ui_story_5031_50310802_132_dialog_content = "Hmm...",
  ui_story_5031_50310802_133_dialog_content = "Anda dapat membuka mata Anda sekarang. Aku punya kamu.",
  ui_story_5031_50310802_134_dialog_content = "Apa?",
  ui_story_5031_50310802_135_dialog_content = "R-Rainbow?",
  ui_story_5031_50310802_136_dialog_content = "Itu ceroboh. Beralih ke output energi tinggi saat mecha Anda tidak dikalibrasi untuk itu.",
  ui_story_5031_50310802_137_dialog_content = "Aku minta maaf.",
  ui_story_5031_50310802_138_dialog_content = "Styx mengalami ledakan, dan kerusakannya tidak sepenuhnya diperbaiki.",
  ui_story_5031_50310802_139_dialog_content = "Maaf membebanimu...",
  ui_story_5031_50310802_140_dialog_content = "Apakah begitu? Sayang sekali!",
  ui_story_5031_50310802_141_dialog_content = "Saya sangat menantikan kemampuannya setelah sepenuhnya diperbaiki!",
  ui_story_5031_50310802_142_dialog_content = "...",
  ui_story_5031_50310802_143_dialog_content = "Hmm... Rainbow?",
  ui_story_5031_50310802_144_dialog_content = "Hmm? Ada apa?",
  ui_story_5031_50310802_145_dialog_content = "Mengapa Anda menyelamatkan saya? Jika saya jatuh ke laut, saya akan kehilangan banyak poin.",
  ui_story_5031_50310802_146_dialog_content = "Hah? Sehat...",
  ui_story_5031_50310802_147_dialog_content = "Mungkin karena itu, dibandingkan dengan 5 juta Nightium...",
  ui_story_5031_50310802_148_dialog_content = "Aku lebih tertarik padamu.",
  ui_story_5031_50310901_1_dialog_content = "Babak pertama selesai! Sekarang, apakah kontestan untuk putaran kedua akan mencapai titik awal yang ditentukan?",
  ui_story_5031_50310901_2_dialog_content = "Sementara itu, skor akhir untuk putaran pertama akan dihitung.",
  ui_story_5031_50310901_3_dialog_content = "Tidak apa-apa, Fia. Kami masih memiliki kesempatan.",
  ui_story_5031_50310901_4_dialog_content = "Ya. Jangan merasa buruk. Kami tidak pernah berharap Anda mendapatkan skor tinggi.",
  ui_story_5031_50310901_5_dialog_content = "Aaaah!",
  ui_story_5031_50310901_6_dialog_content = "PlayerName Bodoh!",
  ui_story_5031_50310901_7_dialog_content = "Hah? Memangnya apa yang sudah kulakukan?",
  ui_story_5031_50310901_8_dialog_content = "Aku mencoba menghiburmu.",
  ui_story_5031_50310901_9_dialog_content = "Hentikan dulu, PlayerName.",
  ui_story_5031_50310901_10_dialog_content = "... Saya percaya ada kesalahpahaman.",
  ui_story_5031_50310901_11_dialog_content = "Bersiaplah untuk putaran kedua, semuanya.",
  ui_story_5031_50310901_12_dialog_content = "Saya mendengar Rainbow mengatakan mereka akan mengirim Merylt berikutnya.",
  ui_story_5031_50310901_13_dialog_content = "Hm? Kamu baik-baik saja, Fia?",
  ui_story_5031_50310901_14_dialog_content = "*Menangis* Carleen! PlayerName, dia...",
  ui_story_5031_50310901_15_dialog_content = "Tunggu sebentar! Saya tidak melakukan apa-apa!",
  ui_story_5031_50310901_16_dialog_content = "Fia, lupakan dia. Mari kita fokus pada putaran berikutnya.",
  ui_story_5031_50310901_17_dialog_content = "Anda ingin hadiah mon⁠—maksud saya baju renang... Dan kita punya Cloudwhale untuk diselamatkan, bukan?",
  ui_story_5031_50310901_18_dialog_content = "Hoho, iya...",
  ui_story_5031_50310901_19_dialog_content = "Lalu keringkan air matamu. Mari kita bahas pengaturan kita untuk babak selanjutnya.",
  ui_story_5031_50310901_20_dialog_content = "Lalu... Saya mengusulkan agar PlayerName pergi berikutnya!",
  ui_story_5031_50310901_21_dialog_content = "Hah?!",
  ui_story_5031_50310901_22_dialog_content = "Hmph! Anda tertawa ketika saya jatuh ke dalam air, bukan?",
  ui_story_5031_50310901_23_dialog_content = "Sekarang giliranku untuk menertawakanmu!",
  ui_story_5031_50310901_24_dialog_content = "Bagaimana Anda tahu saya sedang tertawa⁠—Tidak, tunggu. Itu tidak masuk akal!",
  ui_story_5031_50310901_25_dialog_content = "Saya pikir memenangkan pertandingan lebih penting!",
  ui_story_5031_50310901_26_dialog_content = "Kami hanya membutuhkan dua skor kemenangan, jadi saya bahkan tidak perlu melanjutkan, kan?",
  ui_story_5031_50310901_27_dialog_content = "Apakah Anda lupa, PlayerName? Kamu dan Fia dihitung sebagai satu.",
  ui_story_5031_50310901_28_dialog_content = "Skor Anda dan Fia dijumlahkan.",
  ui_story_5031_50310901_29_dialog_content = "Benar... Itu terjadi...",
  ui_story_5031_50310901_30_dialog_content = "Kami tidak tahu siapa Vice dan aku akan menghadapinya saat giliran kita.",
  ui_story_5031_50310901_31_dialog_content = "Jadi, untuk amannya, sebaiknya Anda berpartisipasi.",
  ui_story_5031_50310901_32_dialog_content = "Maka sebenarnya masuk akal untuk mengirim PlayerName berikutnya.",
  ui_story_5031_50310901_33_dialog_content = "BENAR. Merylt harus menjadi yang paling ringan dari kembar tiga.",
  ui_story_5031_50310901_34_dialog_content = "Dan saya tidak merasa Petugas Gronru apakah ada yang pandai berselancar",
  ui_story_5031_50310901_35_dialog_content = "Jadi, jika itu masalahnya ...",
  ui_story_5031_50310901_36_dialog_content = "Kalau begitu...",
  ui_story_5031_50310901_37_dialog_content = "Aku tahu, aku tahu... Aku akan pergi. Berhentilah menatapku.",
  ui_story_5031_50310901_38_dialog_content = "Hehe! Semoga berhasil, PlayerName.",
  ui_story_5031_50310901_39_dialog_content = "Tidak ada tekanan, oke? Ingat saja apa yang telah kami ajarkan kepada Anda.",
  ui_story_5031_50310901_40_dialog_content = "Tidak apa-apa bahkan jika Anda tidak bisa melakukannya.",
  ui_story_5031_50310901_41_dialog_content = "Aku mengerti, aku mengerti.",
  ui_story_5031_50310901_42_dialog_content = "Hmph! Anda sebaiknya tidak menjadi tautan terlemah, PlayerName!",
  ui_story_5031_50310901_43_dialog_content = "Anda sendiri tidak mendapatkan nilai yang bagus!",
  ui_story_5031_50310901_44_dialog_content = "Sementara kami mengumumkan skor, apakah semua kontestan akan mendapatkan posisi Anda?",
  ui_story_5031_50310901_45_dialog_content = "Pemenang babak terakhir adalah... Rainbow!",
  ui_story_5031_50310901_46_dialog_content = "Itu tidak mengherankan. Dia adalah jagoan kami.",
  ui_story_5031_50310901_47_dialog_content = "Rainbow-!",
  ui_story_5031_50310901_48_dialog_content = "Namun, ada sesuatu yang akan menjatuhkan kaus kaki Anda!",
  ui_story_5031_50310901_49_dialog_content = "Kami memiliki kontestan lain dengan skor yang sama berbagi peringkat yang sama, dan itu adalah... Ciel!",
  ui_story_5031_50310901_50_dialog_content = "Itu gadis mecha!",
  ui_story_5031_50310901_51_dialog_content = "Menakjubkan! Dia mengejar skor Rainbow!?",
  ui_story_5031_50310901_52_dialog_content = "Luar biasa, Ciel!",
  ui_story_5031_50310901_53_dialog_content = "Terima kasih, Officer Gronru!",
  ui_story_5031_50310901_54_dialog_content = "Petugas Gronru? Mengapa kamu di sini!?",
  ui_story_5031_50310901_55_dialog_content = "Anda harus berada di posisi Anda!",
  ui_story_5031_50310901_56_dialog_content = "Nah, itu karena...",
  ui_story_5031_50310901_57_dialog_content = "Saya tahu Anda ingin mengadu Merylt, PlayerName, dan saya satu sama lain...",
  ui_story_5031_50310901_58_dialog_content = "Berharap untuk mengambil keuntungan dari situasi, bukan?",
  ui_story_5031_50310901_59_dialog_content = "...",
  ui_story_5031_50310901_60_dialog_content = "Hmm...",
  ui_story_5031_50310901_61_dialog_content = "Nah, coba tebak? Aku tidak akan membuat segalanya begitu mudah bagimu!",
  ui_story_5031_50310901_62_dialog_content = "Hmm... Jangan gugup.",
  ui_story_5031_50310901_63_dialog_content = "Ada lebih sedikit orang di babak ini. Yang perlu saya lakukan adalah menahan diri saya sendiri.",
  ui_story_5031_50310901_64_dialog_content = "PlayerName, Uh...",
  ui_story_5031_50310901_65_dialog_content = "Apa yang terjadi, Merylt?",
  ui_story_5031_50310901_66_dialog_content = "Uhm, papanmu... Itu tidak ditambatkan padamu.",
  ui_story_5031_50310901_67_dialog_content = "Ini sangat berbahaya...",
  ui_story_5031_50310901_68_dialog_content = "Oh! Aku benar-benar melupakannya!",
  ui_story_5031_50310901_69_dialog_content = "Terima kasih banyak, Merylt!",
  ui_story_5031_50310901_70_dialog_content = "Hmm...!",
  ui_story_5031_50310901_71_dialog_content = "Oh, dia baru saja terjun ke air!",
  ui_story_5031_50310901_72_dialog_content = "Apakah saya mengatakan sesuatu yang salah lagi?",
  ui_story_5031_50310901_73_dialog_content = "Nah, sudah waktunya.",
  ui_story_5031_50310901_74_dialog_content = "Mari kita mulai putaran kedua.",
  ui_story_5031_50310901_75_dialog_content = "Hahahaha... Hanya seperti itu, lagi?",
  ui_story_5031_50310901_76_dialog_content = "Apakah itu gaya pemimpin sirkus?",
  ui_story_5031_50310901_77_dialog_content = "Oh, tidak ada mecha di babak ini. Betapa mengecewakan.",
  ui_story_5031_50310901_78_dialog_content = "Hah? Lihat! Itu gadis kembar tiga sirkus...",
  ui_story_5031_50310901_79_dialog_content = "Gerakannya bahkan lebih anggun dari Rainbow!",
  ui_story_5031_50310901_80_dialog_content = "Tentu saja! Merylt salah satu anggota sirkus dengan keseimbangan dan kontrol terbaik!",
  ui_story_5031_50310901_81_dialog_content = "Dia telah menguasai trapeze terbang tinggi dan cincin gym. Berselancar seharusnya menjadi hal yang mudah baginya!",
  ui_story_5031_50310901_82_dialog_content = "Anda benar-benar tahu semua yang perlu diketahui tentang anggota sirkus.",
  ui_story_5031_50310901_83_dialog_content = "Yah, mereka bukan hanya karyawan saya.",
  ui_story_5031_50310901_84_dialog_content = "Mereka adalah keluargaku.",
  ui_story_5031_50310901_85_dialog_content = "...",
  ui_story_5031_50310901_86_dialog_content = "Itu benar-benar mengingatkan saya pada Anda yang dulu.",
  ui_story_5031_50310901_87_dialog_content = "Apakah begitu? Bocah tak berguna yang selalu bergantung pada keluarganya dan kau?",
  ui_story_5031_50310901_88_dialog_content = "Tidak. Anak laki-laki polos yang menangis karena burung yang jatuh dari sarangnya.",
  ui_story_5031_50310901_89_dialog_content = "Anda bahkan mematahkan lengan Anda ketika mencoba memasangnya kembali dan mengenakan gips selama enam bulan.",
  ui_story_5031_50310901_90_dialog_content = "Dan Anda masih berusaha untuk menjaga semua orang di sekitar Anda.",
  ui_story_5031_50310901_91_dialog_content = "Oh, cukup dengan semua hal memalukan tentangku.",
  ui_story_5031_50310901_92_dialog_content = "Nikmati saja permainannya.",
  ui_story_5031_50310901_93_dialog_content = "Ha... Baiklah, baiklah.",
  ui_story_5031_50310902_1_dialog_content = "Seperti yang diharapkan, kontestan dengan skor tertinggi masih menjadi anggota sirkus kami...",
  ui_story_5031_50310902_2_dialog_content = "Merylt!",
  ui_story_5031_50310902_3_dialog_content = "Ohhhhhh!",
  ui_story_5031_50310902_4_dialog_content = "Hasil cemerlang ini adalah buah dari kerja keras dan keringatnya yang tiada henti di bawah bintang-bintang.",
  ui_story_5031_50310902_5_dialog_content = "Saya harap kesuksesannya akan menginspirasi dan membangkitkan sesuatu di semua tulang malas Anda!",
  ui_story_5031_50310902_X5_dialog_content = "...",
  ui_story_5031_50310902_X6_dialog_content = "Hmph, jadi malu sampai kehilangan kata-kata? Baik, tidak semua orang ingin melakukan sesuatu dengan hidup mereka.",
  ui_story_5031_50310902_X7_dialog_content = "Kontestan untuk putaran ketiga, bersiaplah!",
  ui_story_5031_50310902_X8_dialog_content = "Kontestan putaran ketiga, harap bersiap-siap.",
  ui_story_5031_50310902_6_dialog_content = "Kontestan untuk putaran ketiga, bersiaplah!",
  ui_story_5031_50310902_7_dialog_content = "Hah? PlayerName, Anda mendapatkan nol poin? Tidak mungkin.",
  ui_story_5031_50310902_8_dialog_content = "Dalam cara berbicara, itu di luar apa yang bisa dilakukan orang normal.",
  ui_story_5031_50310902_9_dialog_content = "Tanpa Carleen dan Vice, kami benar-benar tidak tahu apa yang harus dilakukan tentang Cloudwhale.",
  ui_story_5031_50310902_10_dialog_content = "*Hiks* Cukup...",
  ui_story_5031_50310902_11_dialog_content = "Sebagai seorang Caelestit, aku minta maaf.",
  ui_story_5031_50310902_12_dialog_content = "Oh, berhenti menyalahkan PlayerName, Fia.",
  ui_story_5031_50310902_13_dialog_content = "Tidak realistis untuk berpikir bahwa seorang pemula bisa belajar berselancar dalam satu hari.",
  ui_story_5031_50310902_14_dialog_content = "Kami akan mengejar. Jangan khawatir.",
  ui_story_5031_50310902_15_dialog_content = "Anda benar-benar dapat diandalkan, Carleen, Vice!",
  ui_story_5031_50310902_16_dialog_content = "Huh, berusaha lebih keras dan lakukan yang terbaik, PlayerName.",
  ui_story_5031_50310902_17_dialog_content = "Jangan marah. Aku akan berhenti menggodamu. Saat saya menguasai cara berselancar, Carleen dan saya akan melakukan yang terbaik untuk mengajari Anda!",
  ui_story_5031_50310902_18_dialog_content = "Hah. Kurasa aku harus bersyukur.",
  ui_story_5031_50310902_19_dialog_content = "Anda lebih baik!",
  ui_story_5031_50310902_20_dialog_content = "U-Um, PlayerName...",
  ui_story_5031_50310902_21_dialog_content = "Hah? Merylt? Apa yang bisa saya lakukan untuk Anda?",
  ui_story_5031_50310902_22_dialog_content = "Hmm...",
  ui_story_5031_50310902_23_dialog_content = "Oh, biarkan aku mengatakannya!",
  ui_story_5031_50310902_24_dialog_content = "PlayerName, Merylt ingin meminta maaf karena hampir menyakitimu!",
  ui_story_5031_50310902_25_dialog_content = "Oh itu! Jangan khawatir, Merylt. Anda tidak menyakiti saya.",
  ui_story_5031_50310902_26_dialog_content = "Saya hanya menghirup air karena saya sendiri ketakutan.",
  ui_story_5031_50310902_27_dialog_content = "Emm... Hmm...",
  ui_story_5031_50310902_28_dialog_content = "Anda sangat lembut, PlayerName! Berbeda dengan bos!",
  ui_story_5031_50310902_29_dialog_content = "Kelembutan seperti itu, tidak heran Merylt jatuh cinta padamu—Uhmm!?",
  ui_story_5031_50310902_30_dialog_content = "F-Frimet!",
  ui_story_5031_50310902_31_dialog_content = "Anda harus bersiap-siap, t-sekarang!",
  ui_story_5031_50310902_32_dialog_content = "Mm! Mmm!",
  ui_story_5031_50310902_33_dialog_content = "Ah, tunggu aku!",
  ui_story_5031_50310902_34_dialog_content = "Oh?",
  ui_story_5031_50310902_35_dialog_content = "Anda cukup populer, PlayerName.",
  ui_story_5031_50310902_36_dialog_content = "...",
  ui_story_5031_50310902_37_dialog_content = "Hah? Apa yang kau bicarakan?",
  ui_story_5031_50310902_38_dialog_content = "Bukan apa-apa!",
  ui_story_5031_50310902_39_dialog_content = "Lebih baik aku pergi bersiap-siap. Ini akan dimulai kapan saja sekarang.",
  ui_story_5031_50310902_40_dialog_content = "Benar, ayo.",
  ui_story_5031_50310902_41_dialog_content = "Bertingkah misterius...",
  ui_story_5031_50310902_42_dialog_content = "Ayo pergi ke pantai kalau begitu, Fia—",
  ui_story_5031_50310902_43_dialog_content = "Hah? Fi?",
  ui_story_5031_50310902_44_dialog_content = "Betulkah? Apa yang terjadi pada mereka semua?",
  ui_story_5031_50310902_45_dialog_content = "Sekarang kita berada di babak ketiga, semua orang harus sudah tahu aturannya. Mari kita mulai, kalau begitu.",
  ui_story_5031_50310902_46_dialog_content = "Rapid Torrent!",
  ui_story_5031_50310902_47_dialog_content = "Itu pelanggaran yang kuat.",
  ui_story_5031_50310902_48_dialog_content = "Sepertinya aku harus menganggapnya serius sekarang. Waktu untuk memamerkan pelatihan khusus saya!",
  ui_story_5031_50310902_49_dialog_content = "*Batuk-batuk*",
  ui_story_5031_50310902_50_dialog_content = "Elvis! Mana obatmu?",
  ui_story_5031_50310902_51_dialog_content = "Di dalam... kantong dalam mantelku.",
  ui_story_5031_50310902_52_dialog_content = "Jangan lupa matikan speakernya... batuk...",
  ui_story_5031_50310902_53_dialog_content = "Jangan khawatir. Aku mematikannya.",
  ui_story_5031_50310902_54_dialog_content = "Anda yakin itu ada di saku Anda? Saya tidak dapat menemukannya.",
  ui_story_5031_50310902_55_dialog_content = "Batuk, batuk... Ugh...",
  ui_story_5031_50310902_56_dialog_content = "Maaf... Apakah kamu punya saputangan?",
  ui_story_5031_50310902_57_dialog_content = "Tentu. Satu detik.",
  ui_story_5031_50310902_58_dialog_content = "<color=#e8d9bb>Gemerincing-</color>",
  ui_story_5031_50310902_59_dialog_content = "Ck, terlalu banyak hal.",
  ui_story_5031_50310902_60_dialog_content = "Bisakah kamu bersikap baik di saat seperti ini?",
  ui_story_5031_50310902_61_dialog_content = "...",
  ui_story_5031_50310902_62_dialog_content = "Ini.",
  ui_story_5031_50310902_63_dialog_content = "Terima kasih... Batuk, batuk...",
  ui_story_5031_50310902_64_dialog_content = "Ini adalah babak yang menarik! Benar-benar perkelahian!",
  ui_story_5031_50310902_65_dialog_content = "Ya! Eclipsite lain turun!",
  ui_story_5031_50310902_66_dialog_content = "Gadis dengan busur itu luar biasa!",
  ui_story_5031_50310902_67_dialog_content = "...",
  ui_story_5031_50310902_68_dialog_content = "Maaf, bisakah Anda membawa saya ke suatu tempat dengan lebih sedikit orang sehingga saya bisa beristirahat sebentar?",
  ui_story_5031_50310902_69_dialog_content = "Tentu saja.",
  ui_story_5031_50310902_70_dialog_content = "Hei, kamu, di sana!",
  ui_story_5031_50310902_71_dialog_content = "Iya, kau.",
  ui_story_5031_50310902_72_dialog_content = "Iya Bos?",
  ui_story_5031_50310902_73_dialog_content = "Pertahankan skor dan ambil alih untukku sebentar. Kami memiliki bisnis untuk didiskusikan.",
  ui_story_5031_50310902_74_dialog_content = "Baiklah!",
  ui_story_5031_50310902_75_dialog_content = "Jangan menatapku seperti itu. Aku baik-baik saja sekarang.",
  ui_story_5031_50310902_76_dialog_content = "Baik? Batuk darah di sekujur tubuhku tidak BAIK.",
  ui_story_5031_50310902_77_dialog_content = "Maaf tentang pakaianmu.",
  ui_story_5031_50310902_78_dialog_content = "Anda tahu bukan itu yang saya maksud.",
  ui_story_5031_50310902_79_dialog_content = "Jangan khawatir. Itu hanya berarti bahwa saya memiliki lebih banyak darah daripada yang saya butuhkan... Itu pertanda baik, bukan?",
  ui_story_5031_50310902_80_dialog_content = "Hentikan omong kosong.",
  ui_story_5031_50310902_81_dialog_content = "Anda benar-benar tidak bisa memberi tahu saya apa rencana Anda?",
  ui_story_5031_50310902_82_dialog_content = "Saya akan memastikan saya menyelesaikannya untuk Anda jika Anda mempercayai saya.",
  ui_story_5031_50310902_83_dialog_content = "...",
  ui_story_5031_50310902_84_dialog_content = "Kenapa tampangmu seperti itu?",
  ui_story_5031_50310902_85_dialog_content = "Oh, hanya saja kau mengingatkanku pada masa lalu kita lagi.",
  ui_story_5031_50310902_86_dialog_content = "Hal memalukan lain yang telah saya lakukan?",
  ui_story_5031_50310902_87_dialog_content = "Yah, kamu selalu lebih kecil dan lebih kurus dariku, tapi tetap saja, kamu mencoba yang terbaik untuk membantu orang lain, bantu aku.",
  ui_story_5031_50310902_88_dialog_content = "Dan itulah yang terlihat di matamu sekarang.",
  ui_story_5031_50310902_89_dialog_content = "Waktu mungkin telah menandai kita, tetapi itu tidak mengubah siapa kita.",
  ui_story_5031_50310902_90_dialog_content = "Ya... Beberapa hal berubah, tetapi beberapa tetap sama.",
  ui_story_5031_50310902_91_dialog_content = "Sama seperti bagaimana Anda masih lebih pendek dari saya.",
  ui_story_5031_50310902_92_dialog_content = "Ck. Tapi sekarang, saya bisa mengambil sepuluh dari Anda.",
  ui_story_5031_50310902_93_dialog_content = "Yeah... Kamu bukan lagi Jeno yang membutuhkan perlindunganku.",
  ui_story_5031_50310902_94_dialog_content = "Bukannya aku dalam kondisi apapun untuk melindungimu sekarang.",
  ui_story_5031_50310902_95_dialog_content = "Kemudian giliran saya.",
  ui_story_5031_50310902_96_dialog_content = "Ha... Tidak semudah itu, dan kau tidak bisa membicarakannya begitu saja.",
  ui_story_5031_50310902_97_dialog_content = "Aku serius, Elvis.",
  ui_story_5031_50310902_98_dialog_content = "Katakan padaku apa rencanamu, dan aku akan menemukan cara untuk mewujudkannya.",
  ui_story_5031_50310902_99_dialog_content = "Bagaimana jika itu melibatkan organisasi di belakang Anda?",
  ui_story_5031_50310902_100_dialog_content = "…?",
  ui_story_5031_50310902_101_dialog_content = "Bagaimana jika, bagaimana jika. Ini membutuhkan kapal Anda dan sesuatu dari kedalamannya?",
  ui_story_5031_50310902_102_dialog_content = "Apakah Anda masih akan membantu?",
  ui_story_5031_50310902_103_dialog_content = "Bagaimana kamu tahu...?",
  ui_story_5031_50310902_104_dialog_content = "Itu tidak penting, Jeno.",
  ui_story_5031_50310902_105_dialog_content = "Yang penting, kita bukan anak-anak lagi, dan kita tidak bisa kembali ke masa sederhana itu lagi.",
  ui_story_5031_50310902_106_dialog_content = "Setiap keputusan kami, janji, setiap kata membawa lebih banyak beban dan beban.",
  ui_story_5031_50310902_107_dialog_content = "Jadi, izinkan saya bertanya lagi. Jika itu masalahnya, apakah Anda masih akan membantu saya?",
  ui_story_5031_50310902_108_dialog_content = "...",
  ui_story_5031_50310902_109_dialog_content = "Aku... Aku pernah membuat janji.",
  ui_story_5031_50310902_110_dialog_content = "Saya berjanji untuk melindungi kapal dan melindungi benda itu.",
  ui_story_5031_50310902_111_dialog_content = "Begitu... Maaf telah menempatkanmu di posisi ini.",
  ui_story_5031_50310902_112_dialog_content = "Yang terbaik bagi kami adalah kembali ke permainan. Sepertinya pekerjaan itu lebih dari apa yang bisa ditangani oleh pengganti sementara Anda.",
  ui_story_5031_50310902_113_dialog_content = "Elvis, aku...",
  ui_story_5031_50310902_114_dialog_content = "Jeno.",
  ui_story_5031_50310902_115_dialog_content = "...",
  ui_story_5031_50310902_116_dialog_content = "Tidak apa-apa. Saya mengerti.",
  ui_story_5031_50310902_117_dialog_content = "Apapun itu, aku hanya ingin kau tahu...",
  ui_story_5031_50310902_118_dialog_content = "Aku merindukanmu selama belasan tahun terakhir.",
  ui_story_5031_50310902_119_dialog_content = "…!",
  ui_story_5031_50311001_1_dialog_content = "Yang mulia.",
  ui_story_5031_50311001_2_dialog_content = "Matiu? Apa itu?",
  ui_story_5031_50311001_3_dialog_content = "Apakah Anda akan mengikuti lelucon ini?",
  ui_story_5031_50311001_4_dialog_content = "Berada di air yang sama dengan rakyat jelata... Menjijikkan.",
  ui_story_5031_50311001_5_dialog_content = "Ya, aku sudah tidur.",
  ui_story_5031_50311001_6_dialog_content = "Jika Anda merasa tak tertahankan, Anda sebaiknya tetap tinggal di pantai atau kapal. Lebih baik lagi, Anda harus kembali ke Lumopolis.",
  ui_story_5031_50311001_7_dialog_content = "Tsk, sikap yang sangat marah ...",
  ui_story_5031_50311001_8_dialog_content = "Matiu.",
  ui_story_5031_50311001_9_dialog_content = "Hmph... Apa tugas. Mengapa saya harus melindungi diva seperti seorang putri?",
  ui_story_5031_50311001_10_dialog_content = "...",
  ui_story_5031_50311001_11_dialog_content = "Matthieu, aku bukan diva, dan putri ini tidak membutuhkan perlindunganmu.",
  ui_story_5031_50311001_12_dialog_content = "Dan jika Anda hanya kesal dengan kenyataan bahwa Anda tidak bisa berenang, jangan khawatir, saya akan baik-baik saja.",
  ui_story_5031_50311001_13_dialog_content = "Pfft...",
  ui_story_5031_50311001_14_dialog_content = "A-apa maksudmu?!",
  ui_story_5031_50311001_15_dialog_content = "Aku tidak bisa berenang!? Tidak mungkin aku tidak bisa melakukan sesuatu yang bisa dilakukan orang biasa!",
  ui_story_5031_50311001_16_dialog_content = "A-Dan, Loewe, aku mendengarmu menertawakanku! Beraninya kamu!",
  ui_story_5031_50311001_17_dialog_content = "Nah, Anda benar-benar tidak bisa berenang.",
  ui_story_5031_50311001_18_dialog_content = "Ahhhh! Anda...!",
  ui_story_5031_50311001_19_dialog_content = "Aku sudah cukup! Anda putri pemarah, tandai kata-kata saya, Anda akan menyesal bergaul dengan rakyat jelata!",
  ui_story_5031_50311001_20_dialog_content = "Aku akan pergi berubah!",
  ui_story_5031_50311001_21_dialog_content = "...",
  ui_story_5031_50311001_22_dialog_content = "Kenapa mereka ada di sini...?",
  ui_story_5031_50311001_23_dialog_content = "Dia mungkin ingin menghentikan saya memasuki permainan karena dia tidak bisa berenang sendiri.",
  ui_story_5031_50311001_24_dialog_content = "Aku benar-benar tidak mengerti kenapa Irridon bahkan mengirimnya.",
  ui_story_5031_50311001_25_dialog_content = "Vice! Kamu kembali!",
  ui_story_5031_50311001_26_dialog_content = "Selamat datang kembali, Vice.",
  ui_story_5031_50311001_27_dialog_content = "Anda sangat luar biasa, Vice! Anda pasti akan mendapatkan skor tinggi!",
  ui_story_5031_50311001_28_dialog_content = "Cloudwhale sama bagusnya dengan milik kita! Dan saya tidak perlu mendengarkan tuan saya berbicara dengan telinga saya!",
  ui_story_5031_50311001_29_dialog_content = "Anda memberi saya terlalu banyak pujian, Fia.",
  ui_story_5031_50311001_30_dialog_content = "Para kontestan lain adalah lawan yang layak.",
  ui_story_5031_50311001_31_dialog_content = "Saya tidak berpikir Petugas Gronru akan sangat pandai berselancar... Aku meremehkannya.",
  ui_story_5031_50311001_32_dialog_content = "Tidak masalah. Kami masih memiliki satu putaran lagi, tetapi skor mereka sudah ditentukan sekarang.",
  ui_story_5031_50311001_33_dialog_content = "Sekarang, giliran Carleen!",
  ui_story_5031_50311001_34_dialog_content = "Matthieu dan Loewe ada di sini? Apakah mereka juga di sini untuk berpartisipasi dalam permainan?",
  ui_story_5031_50311001_35_dialog_content = "Jangan pedulikan mereka.",
  ui_story_5031_50311001_36_dialog_content = "Kalau dipikir-pikir, kita sudah lama tidak mendengar suara tuan rumah kita.",
  ui_story_5031_50311001_37_dialog_content = "Kamu benar. Aku ingin tahu apa yang dia dan Elvis lakukan.",
  ui_story_5031_50311001_38_dialog_content = "Bagaimanapun, Anda lebih baik bersiap-siap, Carleen.",
  ui_story_5031_50311001_39_dialog_content = "Semoga beruntung, Carleen!",
  ui_story_5031_50311001_40_dialog_content = "Pergi, Carleen!",
  ui_story_5031_50311001_41_dialog_content = "Serahkan padaku.",
  ui_story_5031_50311001_42_dialog_content = "...",
  ui_story_5031_50311001_43_dialog_content = "Jeno, Pak?",
  ui_story_5031_50311001_44_dialog_content = "Apa?",
  ui_story_5031_50311001_45_dialog_content = "<size=33>Ah! Ada apa dengan perubahan sikap bos yang tiba-tiba...?</size>",
  ui_story_5031_50311001_46_dialog_content = "Uhm... Skor untuk babak terakhir ada di sini. Apakah Anda tidak akan mengumumkannya?",
  ui_story_5031_50311001_47_dialog_content = "...",
  ui_story_5031_50311001_48_dialog_content = "Uhm... Atau, setidaknya ucapkan kata untuk memulai ronde berikutnya...",
  ui_story_5031_50311001_49_dialog_content = "Semua kontestan sudah siap dan menunggu...",
  ui_story_5031_50311001_50_dialog_content = "Mulai.",
  ui_story_5031_50311001_51_dialog_content = "...",
  ui_story_5031_50311001_52_dialog_content = "Baiklah... Aku mulai terbiasa dengannya.",
  ui_story_5031_50311001_53_dialog_content = "Ice Blossom!",
  ui_story_5031_50311001_54_dialog_content = "Oh! Reaksi cepat!",
  ui_story_5031_50311001_55_dialog_content = "Dia menggunakan Lumina untuk membekukan ombak!",
  ui_story_5031_50311001_56_dialog_content = "Dan melaju kencang saat mengeksekusi gerakan dengan sempurna!",
  ui_story_5031_50311001_57_dialog_content = "Ini luar biasa! Aku sangat gembira!",
  ui_story_5031_50311001_58_dialog_content = "Pergilah!",
  ui_story_5031_50311001_59_dialog_content = "Graagh!!",
  ui_story_5031_50311001_60_dialog_content = "Hah? Membekukan begitu banyak Eclipsites secara bersamaan!?",
  ui_story_5031_50311001_61_dialog_content = "Wow!",
  ui_story_5031_50311001_62_dialog_content = "Gadis itu juga menyelamatkan Ranka, bukan?",
  ui_story_5031_50311001_63_dialog_content = "Dia luar biasa. Dia tidak hanya elegan, dia juga mematikan melawan semua Eclipsites itu!",
  ui_story_5031_50311001_64_dialog_content = "Bukan hanya itu, dia bahkan membekukan permukaan laut, menjadikannya jalannya! presisi seperti itu!",
  ui_story_5031_50311001_65_dialog_content = "Tunggu, apakah namanya Carleen?",
  ui_story_5031_50311001_66_dialog_content = "Sekarang saya ingat! Dia putri, bukan?",
  ui_story_5031_50311001_67_dialog_content = "Luar biasa, hanya luar biasa!",
  ui_story_5031_50311001_68_dialog_content = "Dia benar-benar membuat jantungku berdebar kencang! Aku harus mengikuti!",
  ui_story_5031_50311001_69_dialog_content = "Fiuh…",
  ui_story_5031_50311001_70_dialog_content = "Itu 62.",
  ui_story_5031_50311001_71_dialog_content = "Gronru memukul 70 dan Ciel dipaku ... 93.",
  ui_story_5031_50311001_72_dialog_content = "Ck. Memiliki mecha pasti menguntungkan dalam hal ini.",
  ui_story_5031_50311001_73_dialog_content = "Jika Vice mendapat 69... Hmm...",
  ui_story_5031_50311001_74_dialog_content = "Saya perlu mencatat setidaknya 32 lagi, dan mencetak lebih banyak dari gerakan juga.",
  ui_story_5031_50311001_75_dialog_content = "Adapun sirkus...",
  ui_story_5031_50311001_76_dialog_content = "Hai, Putri Carleen. Apakah Anda sedang istirahat di sini?",
  ui_story_5031_50311001_77_dialog_content = "Subli?",
  ui_story_5031_50311001_78_dialog_content = "Anda ingat nama saya! Aku sangat bahagia!",
  ui_story_5031_50311001_79_dialog_content = "Panggil saja aku Carleen.",
  ui_story_5031_50311001_80_dialog_content = "Baik, Carleen.",
  ui_story_5031_50311001_81_dialog_content = "Aku sangat menyukaimu, tapi aku punya kabar buruk untukmu.",
  ui_story_5031_50311001_82_dialog_content = "Ada apa?",
  ui_story_5031_50311001_83_dialog_content = "Strategi kami adalah mengirim Rainbow dan Merylt terlebih dahulu untuk mencetak poin sebanyak mungkin.",
  ui_story_5031_50311001_84_dialog_content = "Adapun Frimet dan aku...",
  ui_story_5031_50311001_85_dialog_content = "Kami di sini untuk mengganggu kontestan lain!",
  ui_story_5031_50311001_86_dialog_content = "Ugh!",
  ui_story_5031_50311001_87_dialog_content = "Tidak heran Frimet terus mengotak-atik Vice!",
  ui_story_5031_50311001_88_dialog_content = "Ya... Jadi jangan membenciku, kumohon. Ini bukan masalah pribadi.",
  ui_story_5031_50311001_89_dialog_content = "Ck! Beraninya orang biasa menyerang Putri Carleen!",
  ui_story_5031_50311001_90_dialog_content = "Loewe, aku ingin dia diturunkan, sekarang juga!",
  ui_story_5031_50311001_91_dialog_content = "...",
  ui_story_5031_50311001_92_dialog_content = "Betapa gesitnya... Dia benar-benar tumbuh di sirkus.",
  ui_story_5031_50311001_93_dialog_content = "Saya berada di posisi yang kurang menguntungkan di sini di papan yang begitu sempit ...",
  ui_story_5031_50311001_94_dialog_content = "Oh! Carleen, Anda menakjubkan!",
  ui_story_5031_50311001_95_dialog_content = "Anda dapat menjaga keseimbangan sambil mempertahankan serangan saya!",
  ui_story_5031_50311001_96_dialog_content = "Kamu sangat anggun, aku sangat mengagumimu!",
  ui_story_5031_50311001_97_dialog_content = "Uhm... Aku tidak bisa benar-benar menyakitinya.",
  ui_story_5031_50311001_98_dialog_content = "Aku hanya harus mencoba membuat jarak di antara kita.",
  ui_story_5031_50311001_99_dialog_content = "Hah? Kemana kamu pergi, Carleen?",
  ui_story_5031_50311001_100_dialog_content = "Maukah kamu bermain denganku lagi? Saya belum cukup bersenang-senang!",
  ui_story_5031_50311001_101_dialog_content = "Sekarang saatnya!",
  ui_story_5031_50311001_102_dialog_content = "Ice Blossom!",
  ui_story_5031_50311001_103_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5031_50311001_104_dialog_content = "Ah!",
  ui_story_5031_50311001_105_dialog_content = "Saya minta maaf. Anda lebih baik tinggal di sini.",
  ui_story_5031_50311001_106_dialog_content = "Aduh… Hah?",
  ui_story_5031_50311001_107_dialog_content = "Saya pikir saya sudah mati!",
  ui_story_5031_50311001_108_dialog_content = "Jadi dia hanya membekukanku di tempat ini!",
  ui_story_5031_50311001_109_dialog_content = "Saya tidak bisa bergerak, tetapi saya tidak terluka sama sekali, dan kepala saya tidak berada di dalam es ...",
  ui_story_5031_50311001_110_dialog_content = "Oh, kontrol dan presisi seperti itu! Sekarang saya suka Carleen bahkan lebih!",
  ui_story_5031_50311001_111_dialog_content = "Anak itu... Dia sangat aneh.",
  ui_story_5031_50311001_112_dialog_content = "Setidaknya dia tidak lagi menjadi ancaman. Yang perlu saya lakukan sekarang adalah fokus untuk mendapatkan poin.",
  ui_story_5031_50311001_113_dialog_content = "Aku membuang terlalu banyak waktu saat itu. Aku harus menebusnya demi semua orang.",
  ui_story_5031_50311002_1_dialog_content = "Berkumpul, semuanya!",
  ui_story_5031_50311002_2_dialog_content = "Bagaimana Anda menyukai kontes selancar?",
  ui_story_5031_50311002_3_dialog_content = "Kami menyukainya!",
  ui_story_5031_50311002_4_dialog_content = "Heheh, saya juga bersenang-senang!",
  ui_story_5031_50311002_5_dialog_content = "Anda semua memiliki waktu yang tak terlupakan di sini. Ini selamanya untuk Anda simpan!",
  ui_story_5031_50311002_6_dialog_content = "Sekarang, saatnya mengumumkan skor!",
  ui_story_5031_50311002_7_dialog_content = "Meneguk-",
  ui_story_5031_50311002_8_dialog_content = "Fia, suara menelanmu sangat keras.",
  ui_story_5031_50311002_9_dialog_content = "Aku tidak cemas sama sekali!",
  ui_story_5031_50311002_10_dialog_content = "Jangan khawatir. Carleen melakukan pekerjaan yang hebat. Kita akan baik-baik saja.",
  ui_story_5031_50311002_11_dialog_content = "Aku hanya mengejar skor Gronru dalam membunuh Eclipsites...",
  ui_story_5031_50311002_12_dialog_content = "Adapun skor gerakanku... Kita harus lihat.",
  ui_story_5031_50311002_13_dialog_content = "Rainbow dan timnya... mungkin masih di depan kita.",
  ui_story_5031_50311002_14_dialog_content = "Baik! Aku tidak akan membuatmu menunggu!",
  ui_story_5031_50311002_15_dialog_content = "Pemenang lomba selancar adalah...",
  ui_story_5031_50311002_16_dialog_content = "Hormat kami! Zamrud!",
  ui_story_5031_50311002_17_dialog_content = "Perhitungan rinci dan penilaian akan diposting di papan buletin. Silakan periksa jika Anda ragu!",
  ui_story_5031_50311002_18_dialog_content = "Saya berjanji itu adalah skor yang sah dari semua penonton di sini! Tidak ada bantuan!",
  ui_story_5031_50311002_19_dialog_content = "Wow!",
  ui_story_5031_50311002_20_dialog_content = "Rainbow, kamu pantas mendapatkannya!",
  ui_story_5031_50311002_21_dialog_content = "Terima kasih atas dukungan Anda terhadap Zamrud!",
  ui_story_5031_50311002_22_dialog_content = "Dan kami berterima kasih kepada laird untuk 5 juta Nightium!",
  ui_story_5031_50311002_23_dialog_content = "Hahahahah!",
  ui_story_5031_50311002_24_dialog_content = "Sangat sedih!",
  ui_story_5031_50311002_25_dialog_content = "Nightium... 5 juta Nightium...",
  ui_story_5031_50311002_26_dialog_content = "Boo-hoo, baju renangku...!",
  ui_story_5031_50311002_27_dialog_content = "Tidak masalah. Emerald bukanlah tim karnaval, jadi kami masih memiliki kesempatan di Cloudwhale.",
  ui_story_5031_50311002_28_dialog_content = "Adapun baju renangnya... Kita masih bisa membelinya tanpa hadiah uang.",
  ui_story_5031_50311002_29_dialog_content = "Betulkah? Anda benar-benar akan membelikan saya baju renang, PlayerName?",
  ui_story_5031_50311002_30_dialog_content = "Tentu, jika Anda berhenti membuat orang marah dan bergosip dan menjadi gadis yang baik.",
  ui_story_5031_50311002_31_dialog_content = "Apa!? Saya seorang wanita! Dari mana kesan Anda itu berasal?",
  ui_story_5031_50311002_32_dialog_content = "Jadi maksudmu kamu tidak bisa melakukannya? Oh, tidak apa-apa kalau begitu.",
  ui_story_5031_50311002_33_dialog_content = "Ahhh! Tapi kamu berjanji! Anda tidak bisa mengingkari janji!",
  ui_story_5031_50311002_34_dialog_content = "...",
  ui_story_5031_50311002_35_dialog_content = "Selanjutnya, tim runner-up kami!",
  ui_story_5031_50311002_36_dialog_content = "Diam! Mereka mengumumkan runner-up sekarang!",
  ui_story_5031_50311002_37_dialog_content = "runner up adalah...",
  ui_story_5031_50311002_38_dialog_content = "Gronru dan Ciel, dari Illumina!",
  ui_story_5031_50311002_39_dialog_content = "Wow!",
  ui_story_5031_50311002_40_dialog_content = "Apa?!",
  ui_story_5031_50311002_41_dialog_content = "<size=45>Apa?!</size>",
  ui_story_5031_50311002_42_dialog_content = "<size=55>Hah?</size>",
  ui_story_5031_50311002_43_dialog_content = "Nya... Gronru dan Ciel?",
  ui_story_5031_50311002_44_dialog_content = "I-Lalu... Bukankah itu berarti...",
  ui_story_5031_50311002_45_dialog_content = "Bukan kami yang membawa pulang hadiahnya...?",
  ui_story_5031_50311002_46_dialog_content = "T-The Cloudwhale akan menjadi milik orang lain!?",
  ui_story_5031_50311002_47_dialog_content = "Ahhhh! Guru akan memarahi saya sampai mati!",
  ui_story_5031_50311002_48_dialog_content = "...",
  ui_story_5031_50311002_49_dialog_content = "Carleen? Kemana kamu pergi?",
  ui_story_5031_50311002_50_dialog_content = "Carleen!",
  ui_story_5031_50311002_51_dialog_content = "Tunggu, Carleen. Kemana kamu pergi?",
  ui_story_5031_50311002_52_dialog_content = "Mobil⁠—",
  ui_story_5031_50311002_53_dialog_content = "Maaf, PlayerName dan Vice, tapi aku ingin menyendiri untuk sementara waktu.",
  ui_story_5031_50311002_54_dialog_content = "K-Kita bisa pergi.",
  ui_story_5031_50311002_55_dialog_content = "Tapi kami mengkhawatirkanmu. Bisakah Anda setidaknya ...",
  ui_story_5031_50311002_56_dialog_content = "Setidaknya beritahu kami... Apa yang terjadi?",
  ui_story_5031_50311002_56X1_dialog_content = "Ya. Apakah kita melakukan sesuatu yang salah?",
  ui_story_5031_50311002_56X2_dialog_content = "Tidak, tidak... Ini tidak ada hubungannya denganmu.",
  ui_story_5031_50311002_57_dialog_content = "Aku hanya... merasa seperti pecundang.",
  ui_story_5031_50311002_58_dialog_content = "Saya melakukan segalanya, tetapi saya masih tidak berhasil memenangkannya untuk teman-teman saya ... dan saya tidak bisa mendapatkan apa yang dia inginkan.",
  ui_story_5031_50311002_59_dialog_content = "Tapi itu bukan salahmu.",
  ui_story_5031_50311002_60_dialog_content = "Sejujurnya, saya harus menjadi orang yang bertanggung jawab ...",
  ui_story_5031_50311002_61_dialog_content = "Semua orang melakukan yang terbaik, tetapi saya mengacaukan semuanya karena saya tidak belajar berselancar.",
  ui_story_5031_50311002_62_dialog_content = "Itu berbeda...",
  ui_story_5031_50311002_63_dialog_content = "Bagaimana perbedaannya? Rasanya sama.",
  ui_story_5031_50311002_64_dialog_content = "Terima kasih telah mengatakan itu, tapi ini salahku, bukan milikmu, dan itu fakta.",
  ui_story_5031_50311002_65_dialog_content = "Ini adalah olahraga tim. Tidak ada yang harus mengambil semua kesalahan.",
  ui_story_5031_50311002_66_dialog_content = "Akulah yang perlu meminta maaf dan terima kasih.",
  ui_story_5031_50311002_67_dialog_content = "Tanpa kalian, kami tidak akan bisa sejauh ini.",
  ui_story_5031_50311002_68_dialog_content = "...",
  ui_story_5031_50311002_69_dialog_content = "Demikian juga, apakah Anda pikir kita bisa sejauh ini tanpa Vice?",
  ui_story_5031_50311002_70_dialog_content = "Tidak...",
  ui_story_5031_50311002_71_dialog_content = "Lihat, jadi Anda mengerti. Begitulah perasaan kami tentang Anda.",
  ui_story_5031_50311002_72_dialog_content = "Untuk hadiahnya, pausnya, atau apalah, kita tinggal mencari cara lain.",
  ui_story_5031_50311002_73_dialog_content = "Ini bukan seperti akhir dunia jika kita tidak menang.",
  ui_story_5031_50311002_74_dialog_content = "Ya, Carleen. Paling tidak, kita bisa melihat Jeno, Petugas Gronru, atau Rainbow.",
  ui_story_5031_50311002_75_dialog_content = "Kami dapat memberi tahu mereka tentang Cloudwhale. Saya yakin mereka akan bersedia membantu.",
  ui_story_5031_50311002_75X1_dialog_content = "Vice benar. Tak satu pun dari ini adalah masalah yang tidak dapat diselesaikan.",
  ui_story_5031_50311002_76_dialog_content = "Jadi, berhentilah kesal, Carleen.",
  ui_story_5031_50311002_77_dialog_content = "Mari kita mencari tahu sesuatu bersama-sama.",
  ui_story_5031_50311002_78_dialog_content = "...",
  ui_story_5031_50311002_79_dialog_content = "Oke.",
  ui_story_5031_50311002_80_dialog_content = "Kamu benar. Terima kasih.",
  ui_story_5031_50311002_81_dialog_content = "Saya harus belajar dari Anda. Mungkin ini yang ayahku inginkan...",
  ui_story_5031_50311002_82_dialog_content = "Yang mulia Schwartz? Maksud kamu apa?",
  ui_story_5031_50311002_83_dialog_content = "Sebenarnya, sebelum perjalanan ini, kami memiliki... percakapan.",
  ui_story_5031_50311002_83X1_dialog_content = "Percakapan?",
  ui_story_5031_50311002_83X2_dialog_content = "Ya. Ayah ingin saya merenungkan tujuan bepergian dengan Anda.",
  ui_story_5031_50311002_83X3_dialog_content = "Saya pikir saya mengerti apa yang dia maksud. Banyak hal yang bisa aku pelajari darimu.",
  ui_story_5031_50311002_83X4_dialog_content = "Tidak heran Anda tersesat di dunia Anda sendiri sepanjang hari, Carleen.",
  ui_story_5031_50311002_83X5_dialog_content = "Tetapi bahkan setelah memeras otak saya, banyak hal yang masih berada di luar jangkauan saya.",
  ui_story_5031_50311002_83X6_dialog_content = "Seperti terobosan yang Anda bicarakan, Vice. Saya benar-benar mencobanya hari ini.",
  ui_story_5031_50311002_83X7_dialog_content = "Eh? Anda mencoba?",
  ui_story_5031_50311002_83X8_dialog_content = "Ya, dan saya mengikuti apa yang Anda sarankan, pelepasan kesadaran.",
  ui_story_5031_50311002_83X9_dialog_content = "Tapi saya terus mengingat percakapan dengan ayah saya ... dan dengan demikian tidak bisa berkonsentrasi.",
  ui_story_5031_50311002_83X10_dialog_content = "Jadi saya gagal.",
  ui_story_5031_50311002_83X11_dialog_content = "Saya mengerti. Itu sebenarnya cukup umum.",
  ui_story_5031_50311002_83X12_dialog_content = "Sangat sulit untuk membebaskan diri Anda dari emosi apa pun sehingga Anda dapat benar-benar fokus.",
  ui_story_5031_50311002_83X13_dialog_content = "Bagi saya, saya menyingkirkan semua pikiran lain karena saya berpegang pada kilau itu.",
  ui_story_5031_50311002_83X14_dialog_content = "Bersinar? Saya ingat Anda menyebutkannya. Apa itu?",
  ui_story_5031_50311002_83X15_dialog_content = "Um... Saya memikirkan hal-hal menyenangkan yang saya lakukan dengan Anda dan PlayerName.",
  ui_story_5031_50311002_83X16_dialog_content = "Dan sebelum aku menyadarinya, ada keheningan di dalam diriku.",
  ui_story_5031_50311002_83X17_dialog_content = "Tapi itu agak mendalam dan sulit untuk saya gambarkan.",
  ui_story_5031_50311002_83X18_dialog_content = "Saya mengerti. Lalu aku akan...",
  ui_story_5031_50311002_84_dialog_content = "PlayerName! Carleen! Vice!",
  ui_story_5031_50311002_85_dialog_content = "Mengapa Anda meninggalkan saya di belakang? Kami telah mencari Anda!",
  ui_story_5031_50311002_85X1_dialog_content = "Ups, aku tidak percaya kami melupakanmu! Kami sangat terburu-buru.",
  ui_story_5031_50311002_86_dialog_content = "Ada apa, Fia? Mengapa Anda begitu bingung?",
  ui_story_5031_50311002_87_dialog_content = "Mencarimu, tentu saja!",
  ui_story_5031_50311002_88_dialog_content = "Dengar, dengar! Jeno baru saja datang untuk memberitahu kami bahwa...",
  ui_story_5031_50311002_89_dialog_content = "Peringkat kontes selancar hanya berfungsi untuk menentukan urutan kontes berikutnya! Kami masih memiliki kontes lain!",
  ui_story_5031_50311002_90_dialog_content = "Kami tampil dengan sirkus sebagai anggota!",
  ui_story_5031_50311002_91_dialog_content = "Artinya, kita masih punya kesempatan!",
  ui_story_5031_50311101_1_dialog_content = "Tunggu, jadi apa sebenarnya⁠—",
  ui_story_5031_50311101_2_dialog_content = "Huu huu-<size=45>Waaaagh!!</size>",
  ui_story_5031_50311101_3_dialog_content = "<size=45>Kami ... tujuan besar ...</size>",
  ui_story_5031_50311101_4_dialog_content = "Cloudwhale... Kalau begini terus, kita akan kehilangan Cloudwhale! <size=45>Waaaagh!</size>",
  ui_story_5031_50311101_5_dialog_content = "(Ya ampun ... Pertempuran terakhir yang paling penting akan datang ...)",
  ui_story_5031_50311101_6_dialog_content = "(Tapi binatang ajaib itu mengamuk dan tidak mau mendengarkan Fia.)",
  ui_story_5031_50311101_7_dialog_content = "(Kita akan tersingkir seperti ini. Lebih baik aku membujuk Fia untuk berusaha lebih keras!)",
  ui_story_5031_50311101_8_option_content = "Fi, jangan marah!",
  ui_story_5031_50311101_9_dialog_content = "D-Apakah itu berarti Anda punya ide, PlayerName?",
  ui_story_5031_50311101_10_dialog_content = "Sejujurnya, tidak. Tapi kami hanya punya waktu kurang dari satu jam untuk berlatih.",
  ui_story_5031_50311101_11_dialog_content = "Penonton akan datang untuk melihat pertunjukan setelah itu.",
  ui_story_5031_50311101_12_dialog_content = "Kami sangat mati! Waaaagh!",
  ui_story_5031_50311101_13_dialog_content = "Berhenti berhenti! Berhenti menangis!",
  ui_story_5031_50311101_14_dialog_content = "Ingat? Kami melintasi seluruh Astra untuk melindungi binatang buas yang menakjubkan dari segala rintangan.",
  ui_story_5031_50311101_15_dialog_content = "Kami berhasil melakukannya! Tidak mungkin hal seperti ini bisa menjatuhkan kita, kan?",
  ui_story_5031_50311101_16_dialog_content = "Jika Anda mau berusaha lebih keras untuk lolos ke Bica, kami bisa memberi mereka penampilan yang luar biasa!",
  ui_story_5031_50311101_17_dialog_content = "Hai?",
  ui_story_5031_50311101_18_dialog_content = "Aku... aku dipukuli.",
  ui_story_5031_50311101_19_dialog_content = "Maksud saya, kami memasuki kontes tanpa mengetahui apakah hadiah terakhirnya benar-benar Cloudwhale.",
  ui_story_5031_50311101_20_dialog_content = "(Dan kamu baru menyadarinya sekarang!?)",
  ui_story_5031_50311101_21_dialog_content = "Hai! Itu terlihat di wajahmu! Anda memikirkan sesuatu yang buruk tentang saya, bukan!?",
  ui_story_5031_50311101_22_dialog_content = "TIDAK! Tentu saja tidak! Saya tidak akan berani!",
  ui_story_5031_50311101_23_dialog_content = "Bagaimana dengan ini? Mari kita berpura-pura pergi ke kamar kecil dan melihat apakah hadiahnya adalah Cloudwhale?",
  ui_story_5031_50311101_24_dialog_content = "Jika ya, maka Anda akan termotivasi untuk berlatih dengan Bica, bukan?",
  ui_story_5031_50311101_25_dialog_content = "B-Bisakah kita benar-benar melakukan itu?",
  ui_story_5031_50311101_26_dialog_content = "Jeno itu sepertinya pria yang menakutkan. Akan buruk jika kita membuatnya kesal.",
  ui_story_5031_50311101_27_dialog_content = "Oh, itu hanya akan mengintip sebentar. Itu akan baik-baik saja!",
  ui_story_5031_50311101_28_dialog_content = "Saya juga akan mencoba menggunakan kemampuan psikis saya sehingga tidak ada yang akan mengetahuinya!",
  ui_story_5031_50311101_29_dialog_content = "Hm... Benar! Itu akan berhasil!",
  ui_story_5031_50311101_30_dialog_content = "Saya percaya Anda, PlayerName. Binatang ajaib \"super eksotis\" saya, Caelestite!",
  ui_story_5031_50311101_31_dialog_content = "Ayo, berhenti memanggilku binatang yang menakjubkan!",
  ui_story_5031_50311101_32_dialog_content = "Oh ya sudah. Kami tidak punya banyak waktu. Ayo bergerak!",
  ui_story_5031_50311101_33_dialog_content = "<color=#e8d9bb>Di suatu tempat jauh di dalam kapal</color>",
  ui_story_5031_50311101_34_dialog_content = "Ini adalah tempat yang tidak diizinkan oleh pemilik yang galak itu.",
  ui_story_5031_50311101_35_dialog_content = "Ini adalah labirin! Setiap koridor terlihat sama dan begitu banyak jalan bercabang...",
  ui_story_5031_50311101_36_dialog_content = "Di mana mereka menyembunyikan Cloudwhale?",
  ui_story_5031_50311101_37_dialog_content = "Berhenti, Fia.",
  ui_story_5031_50311101_38_dialog_content = "Mari kita bersembunyi di sini sebentar. Aku merasakan seseorang datang lewat sini.",
  ui_story_5031_50311101_39_dialog_content = "*Menguap* Ini sudah putaran ketiga patroli.",
  ui_story_5031_50311101_40_dialog_content = "Saya tidak tahu apa yang dipikirkan bos, mengirim kami untuk berpatroli di tempat yang kedap udara seperti ini.",
  ui_story_5031_50311101_41_dialog_content = "Mengapa ada patroli di sirkus? Mungkinkah pemilik sirkus menyembunyikan sesuatu?",
  ui_story_5031_50311101_42_dialog_content = "Tanpamu, aku pasti sudah tertangkap dan dibuang, PlayerName.",
  ui_story_5031_50311101_43_dialog_content = "Ini semua berkatmu, PlayerName. Saat kita menemukan Cloudwhale, aku pasti akan memberimu hadiah!",
  ui_story_5031_50311101_44_dialog_content = "Bagaimana dengan sebungkus kue hewan? Kylo menyukainya. Apakah Anda pikir Anda akan menyukainya, PlayerName?",
  ui_story_5031_50311101_45_dialog_content = "Mari kita pikirkan itu setelah kita menemukan hadiahnya.",
  ui_story_5031_50311101_46_dialog_content = "Hmm...",
  ui_story_5031_50311101_47_dialog_content = "Tahan. Aku merasakan dua orang di depan... Tapi mereka tidak bergerak.",
  ui_story_5031_50311101_48_dialog_content = "Mari kita coba menyelinap melewati mereka, kalau begitu.",
  ui_story_5031_50311101_49_dialog_content = "Tunggu!",
  ui_story_5031_50311101_50_dialog_content = "Apa lagi?",
  ui_story_5031_50311101_51_dialog_content = "Kedua orang ini merasa... akrab, entah bagaimana.",
  ui_story_5031_50311101_52_dialog_content = "Elvis dan Patou?",
  ui_story_5031_50311101_53_dialog_content = "Laird dan penjaga? Kenapa mereka di sini?",
  ui_story_5031_50311101_54_dialog_content = "Bagaimana saya tahu? Mari kita lupakan mereka dulu dan fokus pada target kita.",
  ui_story_5031_50311101_55_dialog_content = "Mari kita diam dan tidak mengingatkan mereka akan kehadiran kita.",
  ui_story_5031_50311101_56_dialog_content = "Saya minta maaf Pak. Kami telah mencari di kediaman Jeno dan di mana-mana terkait tetapi tidak menemukan apa pun yang menyerupai kunci.",
  ui_story_5031_50311101_57_dialog_content = "Tidak masalah. Aku tahu di mana itu.",
  ui_story_5031_50311101_58_dialog_content = "Dia menyimpan kuncinya setiap saat.",
  ui_story_5031_50311101_59_dialog_content = "Sekarang, itu akan sulit...",
  ui_story_5031_50311101_60_dialog_content = "Tidak apa-apa. Rencananya masih jalan. Kita harus membuatnya bekerja malam ini.",
  ui_story_5031_50311101_61_dialog_content = "Rencana? PlayerName, mereka membicarakan beberapa rencana⁠—",
  ui_story_5031_50311101_62_option_content = "Hush!",
  ui_story_5031_50311101_63_dialog_content = "Apakah Anda mendengar itu?",
  ui_story_5031_50311101_64_dialog_content = "Siapa disana? Keluar, sekarang!",
  ui_story_5031_50311101_65_dialog_content = "(Oh tidak! Lari!)",
  ui_story_5031_50311101_66_dialog_content = "Huff, huft. Kami berhasil sampai di dek.",
  ui_story_5031_50311101_67_dialog_content = "Huff!!! Anda sangat kasar, PlayerName! Anda hampir mencekik saya!",
  ui_story_5031_50311101_68_dialog_content = "Saya minta maaf! Aku terlalu fokus untuk menjauh.",
  ui_story_5031_50311101_69_dialog_content = "Mereka menuju ke sana!",
  ui_story_5031_50311101_70_dialog_content = "*Batuk* Ayo... temukan mereka.",
  ui_story_5031_50311101_71_dialog_content = "Oh! Mereka masih di belakang kita. Lebih baik kita mencari tempat untuk bersembunyi!",
  ui_story_5031_50311101_72_dialog_content = "Hei, PlayerName dan Fia Kecil!",
  ui_story_5031_50311101_73_dialog_content = "Aku tidak kecil!",
  ui_story_5031_50311101_74_dialog_content = "Apakah kamu sudah selesai latihan?",
  ui_story_5031_50311101_75_dialog_content = "Hah? T-Tidak, belum. Tapi kami perlu melakukan sesuatu, jadi tolong, permisi...",
  ui_story_5031_50311101_76_dialog_content = "Hehe! Aku punya kartu as di lengan bajuku!",
  ui_story_5031_50311101_77_dialog_content = "Dengan bantuan Tahta, saya pasti akan menjadi pemenang kali ini!",
  ui_story_5031_50311101_78_dialog_content = "Mengapa saya tidak memberi Anda pratinjau singkat, saingan saya yang kalah!?",
  ui_story_5031_50311101_79_dialog_content = "(Oh, tidak, kami terjerat dengan Gronru. Apakah ada tempat untuk bersembunyi di dekat sini?)",
  ui_story_5031_50311101_80_dialog_content = "PlayerName, mereka hampir mendekati kita!",
  ui_story_5031_50311101_81_dialog_content = "Gunakan kemampuan psikis Anda untuk melakukan sesuatu!",
  ui_story_5031_50311101_82_dialog_content = "Ini tidak bekerja seperti itu!",
  ui_story_5031_50311101_83_dialog_content = "Tak terkalahkan—",
  ui_story_5031_50311101_84_dialog_content = "Laut biru-",
  ui_story_5031_50311101_85_dialog_content = "<size=45>Takhta!!</size>",
  ui_story_5031_50311101_86_dialog_content = "Cahayanya, sangat menyilaukan!",
  ui_story_5031_50311101_87_dialog_content = "Ugh... Ada apa dengan cahaya itu!?",
  ui_story_5031_50311101_88_dialog_content = "Luar biasa, bukan?",
  ui_story_5031_50311101_89_dialog_content = "Ini memberikan pencahayaan ke Tahta saya!",
  ui_story_5031_50311101_90_dialog_content = "Dengan cara ini, saya bahkan bisa berselancar di malam yang paling gelap!",
  ui_story_5031_50311101_91_dialog_content = "Oke. T-Itu keren?",
  ui_story_5031_50311101_92_dialog_content = "Itu luar biasa!",
  ui_story_5031_50311101_93_dialog_content = "Itu menarik perhatian banyak orang!?",
  ui_story_5031_50311101_94_dialog_content = "Itu tadi Menajubkan! Bisakah Anda melakukannya lagi?",
  ui_story_5031_50311101_95_dialog_content = "Lagi? Tentu saja!",
  ui_story_5031_50311101_96_dialog_content = "Ck. Ada terlalu banyak orang di sini. Mereka pasti sudah kabur sekarang.",
  ui_story_5031_50311101_97_dialog_content = "Tidak masalah. Mereka mungkin telah menguping, tapi itu tidak mempengaruhi rencana kita.",
  ui_story_5031_50311101_98_dialog_content = "Mari kita kembali. Semuanya berjalan sesuai rencana.",
  ui_story_5031_50311101_99_dialog_content = "Siap, laksanakan.",
  ui_story_5031_50311101_100_dialog_content = "Mereka pergi. Apa yang lega.",
  ui_story_5031_50311101_101_dialog_content = "Terima kasih banyak, Gronru!",
  ui_story_5031_50311101_102_dialog_content = "Heh? Terima kasih untuk apa? Apa yang kau bicarakan?",
  ui_story_5031_50311101_103_dialog_content = "Kami akan berterima kasih setelah semua ini selesai.",
  ui_story_5031_50311101_104_dialog_content = "Tapi kami punya hal yang harus dilakukan. Nanti!",
  ui_story_5031_50311101_105_dialog_content = "Hei, kenapa kamu terburu-buru, sainganku yang kalah!?",
  ui_story_5031_50311101_106_dialog_content = "Yah, setidaknya mereka terlihat lebih santai sekarang.",
  ui_story_5031_50311101_107_dialog_content = "Mereka pasti menikmati penampilanku yang luar biasa!",
  ui_story_5031_50311101_108_dialog_content = "Setelah melalui semua kesulitan, kami tidak hanya membuang waktu, kami masih tidak tahu apa hadiah utamanya.",
  ui_story_5031_50311101_109_dialog_content = "Tidak ada yang bisa kami lakukan. Itu besar dan penuh dengan penjaga di dalam kapal.",
  ui_story_5031_50311101_110_dialog_content = "Tidak mungkin kita bisa mencari di seluruh kapal hanya dengan kita berdua.",
  ui_story_5031_50311101_111_dialog_content = "Sepertinya kita harus melakukannya dengan susah payah dan menjadi pemenangnya!",
  ui_story_5031_50311101_112_dialog_content = "Tapi... Kita kehabisan waktu...",
  ui_story_5031_50311101_113_dialog_content = "Cloudwhale saya... Cloudwhale saya yang malang pasti sudah...",
  ui_story_5031_50311101_114_dialog_content = "Kenapa kamu menangis lagi!?",
  ui_story_5031_50311101_115_dialog_content = "PlayerName, Fia. Apakah Anda masih berlatih?",
  ui_story_5031_50311101_116_dialog_content = "Apakah Anda mengatakan sesuatu yang kasar kepada Fia untuk membuatnya menangis?",
  ui_story_5031_50311101_117_option_content = "Tidak mungkin!",
  ui_story_5031_50311101_118_option_content = "Itu bukan aku!",
  ui_story_5031_50311101_119_dialog_content = "Bica tidak mau berkolaborasi, jadi Fia panik.",
  ui_story_5031_50311101_120_dialog_content = "Hai!",
  ui_story_5031_50311101_121_dialog_content = "Mereka... Mereka tidak memujimu!",
  ui_story_5031_50311101_122_dialog_content = "Hai?",
  ui_story_5031_50311101_123_dialog_content = "Aneh. Saya pikir mereka memiliki hubungan yang baik.",
  ui_story_5031_50311101_124_dialog_content = "Kenapa Bica tiba-tiba tidak mau berkolaborasi?",
  ui_story_5031_50311101_125_dialog_content = "Apakah Anda tidak berbicara dengan Bica tentang hal itu?",
  ui_story_5031_50311101_126_dialog_content = "Aku berbicara, tapi Bica tidak mau mendengarkan!",
  ui_story_5031_50311101_127_dialog_content = "Apa yang kamu katakan pada Bica?",
  ui_story_5031_50311101_128_dialog_content = "Saya mengatakan kepada Bica untuk bekerja dengan saya untuk memenangkan hadiah penting itu.",
  ui_story_5031_50311101_129_dialog_content = "Lalu, apa yang Bica katakan?",
  ui_story_5031_50311101_130_dialog_content = "Bica tidak mengatakan apa-apa ...",
  ui_story_5031_50311101_131_dialog_content = "Jadi Bica tidak setuju?!",
  ui_story_5031_50311101_132_dialog_content = "Tapi Bica sudah berjanji untuk menjadi partner sementaraku... Bagaimana tidak setuju?!",
  ui_story_5031_50311101_133_dialog_content = "Waaaah!!!",
  ui_story_5031_50311101_134_dialog_content = "Oh, jangan menangis, Fia... Kaulah satu-satunya yang bisa membantu dirimu sendiri kali ini.",
  ui_story_5031_50311101_135_dialog_content = "Membantu diriku sendiri?",
  ui_story_5031_50311101_136_dialog_content = "Bica mungkin telah setuju untuk menjadi pasangan Anda, tetapi itu tidak berarti Anda dapat memerintah begitu saja.",
  ui_story_5031_50311101_137_dialog_content = "Anda berada dalam situasi ini sekarang hanya karena Anda tidak benar-benar mendengarkan Bica.",
  ui_story_5031_50311101_138_dialog_content = "Lalu apa yang harus saya lakukan?",
  ui_story_5031_50311101_139_dialog_content = "Pertama, minta maaf kepada Bica.",
  ui_story_5031_50311101_140_dialog_content = "Bukan hanya permintaan maaf. Anda harus meminta bantuan Bica dalam hal ini, dan minta persetujuan Bica!",
  ui_story_5031_50311101_141_dialog_content = "Akankah Bica membantuku kali ini?",
  ui_story_5031_50311101_142_dialog_content = "Itu terlihat jauh lebih ganas daripada Bica liar ...",
  ui_story_5031_50311101_143_dialog_content = "Itu tergantung pada sikap Anda.",
  ui_story_5031_50311101_144_dialog_content = "Kamu pasti bisa, Fia.",
  ui_story_5031_50311101_145_dialog_content = "Ya. Jangan menyerah. Lakukan yang terbaik.",
  ui_story_5031_50311101_146_dialog_content = "Al-Baiklah. Saya akan mencoba.",
  ui_story_5031_50311101_147_dialog_content = "Bica, aku...",
  ui_story_5031_50311101_148_dialog_content = "Maaf.",
  ui_story_5031_50311101_149_dialog_content = "Hai hai?",
  ui_story_5031_50311101_150_dialog_content = "(Bica meletakkan cakarnya di samping telinganya. Apakah dia meminta Fia untuk berbicara lebih keras?)",
  ui_story_5031_50311101_151_dialog_content = "Aku…",
  ui_story_5031_50311101_152_dialog_content = "<size=45>Saya minta maaf!</size>",
  ui_story_5031_50311101_153_dialog_content = "Itu salahku. Aku seharusnya tidak memaksamu untuk membantu penampilanku, mengabaikan keinginanmu...",
  ui_story_5031_50311101_154_dialog_content = "Saya minta maaf. Itu tidak akan terjadi lain kali... T-Tidak akan ada waktu berikutnya!",
  ui_story_5031_50311101_155_dialog_content = "Aku akan selalu menanyakan perasaanmu di masa depan... Boo-hoo...",
  ui_story_5031_50311101_156_dialog_content = "Hai?",
  ui_story_5031_50311101_157_dialog_content = "Dan setelahnya? Eh, setelah itu... bagaimana kalau aku membelikanmu makanan enak?",
  ui_story_5031_50311101_158_dialog_content = "Hai—Hai hai?",
  ui_story_5031_50311101_159_dialog_content = "Hah? Anda ingin memiliki anggur legendaris Mr Peng?",
  ui_story_5031_50311101_160_dialog_content = "Anda mengatakan bahwa Bica lain mengatakan itu kepada Anda?",
  ui_story_5031_50311101_161_dialog_content = "Tapi itu sangat mahal...",
  ui_story_5031_50311101_162_dialog_content = "Hai hai?",
  ui_story_5031_50311101_163_dialog_content = "Tidak tidak! Saya tidak mengeluh!",
  ui_story_5031_50311101_164_dialog_content = "Aku akan membelikan apapun untukmu, selama kamu memaafkanku. Huu huu...",
  ui_story_5031_50311101_165_dialog_content = "(Oh, lihat saja ekspresi Fia sekarang.)",
  ui_story_5031_50311101_166_dialog_content = "(Dia harus benar-benar mengambil kesempatan ini untuk belajar bagaimana bekerja dengan orang lain.)",
  ui_story_5031_50311101_167_dialog_content = "Hai!",
  ui_story_5031_50311101_168_dialog_content = "(Bica tampak senang. Apakah Bica menerima permintaan maaf Fia?)",
  ui_story_5031_50311101_169_dialog_content = "Kau memaafkanku? Indah sekali!",
  ui_story_5031_50311101_170_dialog_content = "Lalu tentang performa...",
  ui_story_5031_50311101_171_dialog_content = "Hai!",
  ui_story_5031_50311101_172_dialog_content = "Hah?",
  ui_story_5031_50311101_173_dialog_content = "Fia, apa yang Bica katakan?",
  ui_story_5031_50311101_174_dialog_content = "Dikatakan ... \"Itu tergantung pada Anda.\"",
  ui_story_5031_50311101_175_dialog_content = "Apakah itu tidak jelas?!",
  ui_story_5031_50311101_176_dialog_content = "Apakah akan baik-baik saja? Tidakkah sebaiknya Anda bertanya kepada Bica sekali lagi, hanya untuk memastikan?",
  ui_story_5031_50311101_177_dialog_content = "Maksudku, hasil dari pertempuran terakhir tergantung pada ini...",
  ui_story_5031_50311101_178_dialog_content = "Tapi, aku…",
  ui_story_5031_50311101_179_dialog_content = "Pertempuran terakhir ada di depan kita! Kontestan, saatnya!",
  ui_story_5031_50311101_180_dialog_content = "Hah? Sudah?!",
  ui_story_5031_50311101_181_dialog_content = "Sudah satu jam? Tidak ada pilihan lain...",
  ui_story_5031_50311101_182_dialog_content = "Kita harus melakukannya!",
  ui_story_5031_50311101_183_dialog_content = "Serahkan padaku!",
  ui_story_5031_50311101_184_dialog_content = "Saya akan mencoba untuk mendapatkan poin sebanyak yang saya bisa.",
  ui_story_5031_50311101_185_dialog_content = "Bica dan saya akan melakukan yang terbaik juga!",
  ui_story_5031_50311101_186_dialog_content = "Hai!",
  ui_story_5031_50311201_1_dialog_content = "Saat malam tiba, babak ketiga kompetisi akan segera dimulai!",
  ui_story_5031_50311201_2_dialog_content = "Wow!!!",
  ui_story_5031_50311201_3_dialog_content = "Berdasarkan hasil dari babak sebelumnya, dua tim akan saling berhadapan di atas panggung!",
  ui_story_5031_50311201_4_dialog_content = "Mereka adalah... tim terkemuka dari Illumina!",
  ui_story_5031_50311201_5_dialog_content = "Dan tim yang sedang naik daun dipimpin oleh ahli ekstrozoologi pemula Fia!",
  ui_story_5031_50311201_6_dialog_content = "Ohhhhhh!",
  ui_story_5031_50311201_7_dialog_content = "Itu sambutan hangat dari penonton. Besar!",
  ui_story_5031_50311201_8_dialog_content = "Sekarang, sebelum game resmi dimulai, mari kita nikmati penampilan pembuka oleh Ringmaster—Jeno dan ketiga bersaudara!",
  ui_story_5031_50311201_9_dialog_content = "Pertama, Pemimpin Ring Jeno!",
  ui_story_5031_50311201_10_dialog_content = "The Foresight Ritual, kemampuan yang dicari oleh banyak Aurorian sepanjang zaman.",
  ui_story_5031_50311201_11_dialog_content = "Untuk berkomunikasi dengan keberadaan yang lebih besar, untuk menguraikan fragmen dari masa lalu atau masa depan ...",
  ui_story_5031_50311201_12_dialog_content = "Dan untuk dapat melihat sejarah yang sebenarnya atau mengintip ke masa depan.",
  ui_story_5031_50311201_13_dialog_content = "Malam ini, saya akan menunjukkan kekuatan kuno ini dan menjawab semua pertanyaan Anda.",
  ui_story_5031_50311201_14_dialog_content = "Dek Kartu Asal ini akan menjadi bantuan saya.",
  ui_story_5031_50311201_15_dialog_content = "Oh! Ini dia! Ritual Pandangan ke Depan yang legendaris!",
  ui_story_5031_50311201_16_dialog_content = "Mampu memanggil Eclipsites dan meramalkan masa depan. Rahasia apa yang dimiliki kekuatan Origin?",
  ui_story_5031_50311201_17_dialog_content = "Selanjutnya, saya harus meminta bantuan dari audiens yang beruntung.",
  ui_story_5031_50311201_18_dialog_content = "Siapa tamu yang ditakdirkan yang akan berpapasan denganku?",
  ui_story_5031_50311201_19_dialog_content = "Saya!!!",
  ui_story_5031_50311201_20_dialog_content = "Saya! Jemput aku!",
  ui_story_5031_50311201_21_dialog_content = "Aku merasakannya. aku merasakannya sekarang...",
  ui_story_5031_50311201_22_dialog_content = "Kartu Asal menunjukkan nasibku pada... KAMU!",
  ui_story_5031_50311201_23_dialog_content = "Wanita di sebelah kanan barisan depan.",
  ui_story_5031_50311201_24_dialog_content = "Aku-Aku?",
  ui_story_5031_50311201_25_dialog_content = "Iya kamu. Silakan datang ke sini.",
  ui_story_5031_50311201_26_dialog_content = "Anda dapat mengajukan pertanyaan apa pun kepada saya, dan saya akan menjawab Anda menggunakan Kartu Asal.",
  ui_story_5031_50311201_27_dialog_content = "Butuh sesuatu?",
  ui_story_5031_50311201_28_dialog_content = "Apa pun boleh.",
  ui_story_5031_50311201_29_dialog_content = "Lalu... Apakah Anda tahu dari mana saya berasal?",
  ui_story_5031_50311201_30_dialog_content = "Oh, Kartu Asal, jadilah mataku dan beri aku pemandangan kebenaran! Katakan dari mana wanita ini berasal!",
  ui_story_5031_50311201_31_dialog_content = "(Kartu-kartu itu menari-nari di antara jari-jari Jeno, lalu dia mengeluarkan satu!)",
  ui_story_5031_50311201_32_dialog_content = "Kartu Asal telah memberi saya jawabannya. Anda dari Petyaburg.",
  ui_story_5031_50311201_33_dialog_content = "Bagaimana kamu tahu?!",
  ui_story_5031_50311201_34_dialog_content = "Kartu Asal memberi saya jawabannya. Tidak hanya itu, itu juga memberitahuku sesuatu yang lain—",
  ui_story_5031_50311201_35_dialog_content = "Anda adalah keluarga viscount, dan keluarga bahagia yang Anda miliki.",
  ui_story_5031_50311201_36_dialog_content = "Namun, untuk beberapa alasan, Anda tidak duduk dengan pasangan Anda, tetapi Anda masih memiliki ikatan yang kuat dengannya.",
  ui_story_5031_50311201_37_dialog_content = "Itu menakjubkan...",
  ui_story_5031_50311201_38_dialog_content = "Tiketnya laris manis, dan kami hanya bisa mendapatkan kursi terpisah.",
  ui_story_5031_50311201_39_dialog_content = "Dan, pasangan Anda bersikeras memberikan kursi barisan depan kepada Anda.",
  ui_story_5031_50311201_40_dialog_content = "Y-Ya...",
  ui_story_5031_50311201_41_dialog_content = "Kartu Asal berharap Anda hidup bahagia bersama! Anda dapat kembali ke tempat duduk Anda sekarang.",
  ui_story_5031_50311201_42_dialog_content = "Astaga! Itu luar biasa!!!",
  ui_story_5031_50311201_43_dialog_content = "Pilih satu lagi! Jemput aku!",
  ui_story_5031_50311201_44_dialog_content = "Waktu berlalu. Bahkan Kartu Asal harus mematuhi hukum waktu.",
  ui_story_5031_50311201_45_dialog_content = "Dan silahkan nikmati pertunjukan berikut ini. Saya menantikan persimpangan takdir berikutnya.",
  ui_story_5031_50311201_46_dialog_content = "Pertunjukan yang luar biasa dari Ringmaster Jeno!",
  ui_story_5031_50311201_47_dialog_content = "Sekarang, silakan nikmati trapeze terbang tinggi yang mendebarkan dari Merylt, Subli, dan Frimet!",
  ui_story_5031_50311201_48_dialog_content = "Benar... Ini dia!",
  ui_story_5031_50311201_49_dialog_content = "Mari kita membuat rahang mereka jatuh!",
  ui_story_5031_50311201_50_dialog_content = "Oke!",
  ui_story_5031_50311201_51_dialog_content = "Ayo kita lakukan!",
  ui_story_5031_50311201_52_dialog_content = "(Merylt memanjat tangga dan mengulurkan tangannya ke arah dua lainnya.)",
  ui_story_5031_50311201_53_dialog_content = "Hee!",
  ui_story_5031_50311201_54_dialog_content = "Frimet, jangan jatuhkan aku!",
  ui_story_5031_50311201_55_dialog_content = "Subli... Kau begitu berat...",
  ui_story_5031_50311201_56_dialog_content = "(Itu hampir! Untungnya, Frimet menangkap Subli!)",
  ui_story_5031_50311201_57_dialog_content = "Aku akan pergi berikutnya!",
  ui_story_5031_50311201_58_dialog_content = "(Hah? Apakah mereka akan...?)",
  ui_story_5031_50311201_59_dialog_content = "Yo!",
  ui_story_5031_50311201_60_dialog_content = "Disana!",
  ui_story_5031_50311201_61_dialog_content = "Ini ... bahkan lebih berat sekarang!",
  ui_story_5031_50311201_62_dialog_content = "Voila!",
  ui_story_5031_50311201_63_option_content = "Luar biasa!",
  ui_story_5031_50311201_64_dialog_content = "Ohhhhhh! Itu luar biasa!",
  ui_story_5031_50311201_65_dialog_content = "T-Terima kasih semuanya!",
  ui_story_5031_50311201_66_dialog_content = "Apakah kamu terkesan?",
  ui_story_5031_50311201_67_dialog_content = "Sangat terkesan!",
  ui_story_5031_50311201_68_dialog_content = "Itu hanyalah pertunjukan sederhana ...",
  ui_story_5031_50311201_69_dialog_content = "Tapi kami dengan senang hati menerima tepuk tangan Anda!",
  ui_story_5031_50311201_70_dialog_content = "Silakan nantikan kompetisinya!",
  ui_story_5031_50311201_71_dialog_content = "Kami berterima kasih atas penampilan luar biasa Anda!",
  ui_story_5031_50311201_72_dialog_content = "Sekarang waktunya untuk mengumumkan... Putaran terakhir dimulai—SEKARANG!",
  ui_story_5031_50311201_73_dialog_content = "Yang pertama adalah Tim Illumina. Gronru dan Ciel akan mendemonstrasikan jurus spesial mereka!",
  ui_story_5031_50311201_74_dialog_content = "Saya memodifikasi mecha saya berdasarkan umpan balik Gronru, hanya untuk saat ini...",
  ui_story_5031_50311201_75_dialog_content = "Ini harus bekerja, tolong!",
  ui_story_5031_50311201_76_dialog_content = "Oh! Sepertinya Ciel menyiapkan sesuatu yang luar biasa!",
  ui_story_5031_50311201_77_dialog_content = "...",
  ui_story_5031_50311201_78_dialog_content = "Hah? Fi? Apa kamu baik baik saja? Kenapa kamu menggigil?",
  ui_story_5031_50311201_79_dialog_content = "Aku sangat gugup...",
  ui_story_5031_50311201_80_dialog_content = "Kamu gugup?",
  ui_story_5031_50311201_81_dialog_content = "T-Tidak mungkin!",
  ui_story_5031_50311201_82_dialog_content = "Saya seorang ahli ekstrozoologi!, tidak mungkin saya—Aduh!",
  ui_story_5031_50311201_83_dialog_content = "Anda sangat gugup sehingga Anda menggigit lidah Anda?",
  ui_story_5031_50311201_84_dialog_content = "Aku tidak gugup!",
  ui_story_5031_50311201_85_dialog_content = "Fia, jernihkan pikiranmu dan tarik napas dalam-dalam.",
  ui_story_5031_50311201_86_dialog_content = "*Menghirup*",
  ui_story_5031_50311201_87_dialog_content = "*Menghembuskan*",
  ui_story_5031_50311201_88_dialog_content = "Merasa lebih baik sekarang?",
  ui_story_5031_50311201_89_dialog_content = "Oh tidak... tidak lebih baik. Hatiku berdebar!",
  ui_story_5031_50311201_90_dialog_content = "Ciel dan Gronru terlihat luar biasa tetapi saya bahkan tidak tahu apakah Bica akan membantu ...",
  ui_story_5031_50311201_91_dialog_content = "Tidak mungkin kita menang!",
  ui_story_5031_50311201_92_dialog_content = "Jangan panik. Tidak ada gunanya memikirkan itu sekarang.",
  ui_story_5031_50311201_93_dialog_content = "Fokus saja pada apa yang perlu Anda lakukan. Fokus saja pada kinerja itu sendiri.",
  ui_story_5031_50311201_94_dialog_content = "Tapi bagaimana jika Bica tetap tidak mau berkolaborasi?",
  ui_story_5031_50311201_95_dialog_content = "Hmm…",
  ui_story_5031_50311201_96_option_content = "Pernahkah Anda mendengar sebuah pepatah?",
  ui_story_5031_50311201_97_dialog_content = "Pepatah apa?",
  ui_story_5031_50311201_98_dialog_content = "Pujian bisa menghasilkan keajaiban!",
  ui_story_5031_50311201_99_dialog_content = "Apa?!",
  ui_story_5031_50311201_100_dialog_content = "Kurang lebih apa yang saya maksud. Bagaimanapun, cobalah untuk membuat Bica bahagia sehingga itu akan membantu.",
  ui_story_5031_50311201_101_dialog_content = "Yang penting adalah mendapatkan hadiah utama, apakah itu Cloudwhale atau bukan. Semua kekhawatiran lain adalah sekunder!",
  ui_story_5031_50311201_102_dialog_content = "Aku akan mencobanya!",
  ui_story_5031_50311201_103_dialog_content = "Semoga beruntung. Vice, Carleen, dan saya akan melakukan yang terbaik untuk mendapatkan poin.",
  ui_story_5031_50311201_104_dialog_content = "Skor akhir kami akan menjadi rata-rata kami.",
  ui_story_5031_50311201_105_dialog_content = "Jadi, cara terbaik untuk memenangkan ini adalah kita semua melakukan yang terbaik!",
  ui_story_5031_50311201_106_dialog_content = "O-oh, baiklah...",
  ui_story_5031_50311201_107_dialog_content = "Lihat! Itu adalah penampilan yang luar biasa oleh Gronru dan Ciel!",
  ui_story_5031_50311201_108_dialog_content = "Mecha Ciel dan tahta Gronru menari dalam cahaya yang menyilaukan!",
  ui_story_5031_50311201_109_dialog_content = "Mecha Ciel seolah-olah tanpa beban, melakukan tarian seperti pertempuran dengan keterampilan ekstrim!",
  ui_story_5031_50311201_110_dialog_content = "Dia memberikan keseimbangan sempurna antara berat badan dan kecantikan!",
  ui_story_5031_50311201_111_dialog_content = "Sekarang giliran Tim Fia yang naik ke atas panggung!",
  ui_story_5031_50311201_112_dialog_content = "Performa luar biasa apa yang dia siapkan untuk kita?",
  ui_story_5031_50311201_113_dialog_content = "Fiuh... Sudah waktunya. Ayo pergi, Bica!",
  ui_story_5031_50311201_114_dialog_content = "Hai!",
  ui_story_5031_50311201_115_dialog_content = "(Semoga berhasil, Fia, Bica!)",
  ui_story_5031_50311201_116_dialog_content = "(Tolong, jangan biarkan ada yang salah kali ini ...)",
  ui_story_5031_50311201_117_dialog_content = "Baik! Mari kita lakukan! Bica, datang ke sini!",
  ui_story_5031_50311201_118_dialog_content = "Hai!",
  ui_story_5031_50311201_119_dialog_content = "Seperti yang saya katakan, Bica. Lompat dan lakukan jungkir balik, oke?",
  ui_story_5031_50311201_120_dialog_content = "Hai hai?",
  ui_story_5031_50311201_121_dialog_content = "(Bica menatap Fia dengan senyum nakal?!)",
  ui_story_5031_50311201_122_dialog_content = "Tolong ... silakan berkolaborasi!",
  ui_story_5031_50311201_123_dialog_content = "Hai?",
  ui_story_5031_50311201_124_dialog_content = "(Bica bermain bodoh?!)",
  ui_story_5031_50311201_125_dialog_content = "Ada apa?",
  ui_story_5031_50311201_126_dialog_content = "Kami tidak menghabiskan uang untuk melihat Anda membuang waktu kami!",
  ui_story_5031_50311201_127_dialog_content = "*Tersedu*",
  ui_story_5031_50311201_128_dialog_content = "T-Tolong!",
  ui_story_5031_50311201_129_dialog_content = "Hai!",
  ui_story_5031_50311201_129X1_dialog_content = "Bica adalah yang terbaik! Pasti mudah bagimu untuk mengurus kasus sekecil itu!",
  ui_story_5031_50311201_130_dialog_content = "Aku akan membelikanmu anggur Tuan Peng setelah ini!",
  ui_story_5031_50311201_131_dialog_content = "Hai!",
  ui_story_5031_50311201_132_dialog_content = "Itu berhasil?!",
  ui_story_5031_50311201_133_dialog_content = "Hai!",
  ui_story_5031_50311201_134_dialog_content = "Yo-ho! Lakukan yang lain!",
  ui_story_5031_50311201_135_dialog_content = "Sekarang, saya akan melempar bola ini. Tolong tangkap!",
  ui_story_5031_50311201_136_dialog_content = "Hai!",
  ui_story_5031_50311201_137_dialog_content = "Hai!",
  ui_story_5031_50311201_138_dialog_content = "Dilakukan dengan baik!",
  ui_story_5031_50311201_139_dialog_content = "(Bagus, Bica bersedia membantu saya dengan imbalan anggur!)",
  ui_story_5031_50311201_140_dialog_content = "Hai?",
  ui_story_5031_50311201_141_dialog_content = "Hei tunggu! Itu bukan makanan!",
  ui_story_5031_50311201_142_dialog_content = "Hahahahaha!",
  ui_story_5031_50311201_143_dialog_content = "(Itu hampir. Setidaknya penonton mengira itu adalah bagian dari pertunjukan.)",
  ui_story_5031_50311201_144_dialog_content = "Sekarang, ayo tunjukkan pada penonton trik rahasiamu, Bica!",
  ui_story_5031_50311201_145_dialog_content = "Trik rahasia? Trik rahasia apa?",
  ui_story_5031_50311201_146_dialog_content = "Apakah Anda akan membuat Bica menelan batu seperti terakhir kali dengan pemburu?",
  ui_story_5031_50311201_147_dialog_content = "Itu berbahaya!",
  ui_story_5031_50311201_148_dialog_content = "Aku tidak akan melakukan hal seperti itu!",
  ui_story_5031_50311201_149_dialog_content = "Saya sudah menyiapkan ini!",
  ui_story_5031_50311201_150_dialog_content = "Lihat!",
  ui_story_5031_50311201_151_dialog_content = "Gelembung?",
  ui_story_5031_50311201_152_dialog_content = "Oh! Begitu banyak gelembung yang indah!",
  ui_story_5031_50311201_153_dialog_content = "Tapi apa hubungannya dengan penjinakan binatang buas?",
  ui_story_5031_50311201_154_dialog_content = "Terserah Bica sekarang!",
  ui_story_5031_50311201_155_dialog_content = "Hai!",
  ui_story_5031_50311201_156_dialog_content = "Hai—!",
  ui_story_5031_50311201_157_dialog_content = "(Benar! Gelembung-gelembung itu semuanya berbentuk bola. Yang disukai Bica!)",
  ui_story_5031_50311201_158_dialog_content = "Oooh! Pria kecil itu bahkan memiliki bakat itu?!",
  ui_story_5031_50311201_159_dialog_content = "Hai!",
  ui_story_5031_50311201_160_dialog_content = "H-Hai!",
  ui_story_5031_50311201_161_dialog_content = "*Hoik*",
  ui_story_5031_50311201_162_dialog_content = "(Bica menelan terlalu banyak udara, dan tubuhnya menjadi kembung!)",
  ui_story_5031_50311201_163_dialog_content = "Hahahahaha! Itu sangat menggemaskan!",
  ui_story_5031_50311201_164_dialog_content = "Itu saja untuk kinerja kami!",
  ui_story_5031_50311201_165_dialog_content = "Silakan nantikan apa yang rekan tim saya persiapkan untuk Anda selanjutnya!",
  ui_story_5031_50311201_166_dialog_content = "Wow!!!",
  ui_story_5031_50311201_167_dialog_content = "Setelah penampilan Fia selesai, saya, Vice, dan Carleen juga mengambil panggung dalam urutan itu.",
  ui_story_5031_50311201_168_dialog_content = "Saya menggunakan kemampuan psikis saya untuk membaca pikiran.",
  ui_story_5031_50311201_169_dialog_content = "Vice menunjukkan keahlian menembaknya yang mengesankan ...",
  ui_story_5031_50311201_170_dialog_content = "Dan aku hanya bisa berharap dia tidak akan meletakkan apel target di atas kepalaku, lain kali...",
  ui_story_5031_50311201_171_dialog_content = "Carleen adalah angsa hitam. Dia mengejutkan semua orang dengan baletnya.",
  ui_story_5031_50311201_172_dialog_content = "Terlebih lagi... Dia bahkan meminta Jeno untuk menampilkan Eclipsites di atas panggung sebagai bagian dari pertunjukannya!",
  ui_story_5031_50311202_1_dialog_content = "Ice Blossom!",
  ui_story_5031_50311202_2_dialog_content = "saya bertaruh Carleen adalah satu-satunya yang pernah menggabungkan balet dan pertempuran!",
  ui_story_5031_50311202_3_dialog_content = "Yang LUAR BIASA!",
  ui_story_5031_50311202_4_dialog_content = "Tepuk tangan meriah untuk balet Carleen! Itu mendebarkan sekaligus spektakuler!",
  ui_story_5031_50311202_5_dialog_content = "Sekarang, saat yang ditunggu semua orang...",
  ui_story_5031_50311202_6_dialog_content = "Saatnya untuk hasil!",
  ui_story_5031_50311202_7_dialog_content = "Hai!",
  ui_story_5031_50311202_8_dialog_content = "Aku sangat gugup... Aku tidak bisa... bernapas...",
  ui_story_5031_50311202_9_dialog_content = "Tunggu, Fia!",
  ui_story_5031_50311202_10_dialog_content = "Pikirkan tentang Cloudwhale Anda!",
  ui_story_5031_50311202_11_dialog_content = "Cloudwhale, ya, Cloudwhale-ku... Hadiah utamaku!",
  ui_story_5031_50311202_12_dialog_content = "Pemenang lomba ini adalah...",
  ui_story_5031_50311202_13_dialog_content = "Tim Fia!",
  ui_story_5031_50311202_14_dialog_content = "aku menang...?",
  ui_story_5031_50311202_15_dialog_content = "Oh ya! Saya menang!",
  ui_story_5031_50311202_16_dialog_content = "Hai!",
  ui_story_5031_50311202_17_dialog_content = "Terlepas dari performa Fia yang kurang sempurna, kerja tim di antara mereka benar-benar mengesankan.",
  ui_story_5031_50311202_18_dialog_content = "Dan balet Miss Carleen sangat luar biasa.",
  ui_story_5031_50311202_19_dialog_content = "Jadi, skor rata-rata Tim Fia cukup tinggi untuk memberi mereka tempat pertama!",
  ui_story_5031_50311202_20_dialog_content = "Selamat, Fia!",
  ui_story_5031_50311202_21_dialog_content = "Aku tidak pernah tahu gadis kecil sepertimu bisa begitu luar biasa, Fia!",
  ui_story_5031_50311202_22_dialog_content = "Anda telah mengalahkan saya, tetapi saya tidak akan kalah dari Anda lain kali!",
  ui_story_5031_50311202_23_dialog_content = "Selamat, Fia! Anda menyelesaikan pertunjukan dan mendapatkan kemenangan!",
  ui_story_5031_50311202_24_dialog_content = "Tapi aku benar-benar penasaran. Apa sebenarnya hadiah utama itu?",
  ui_story_5031_50311202_25_dialog_content = "Mungkinkah Cloudwhale yang dicari Fia?",
  ui_story_5031_50311202_26_dialog_content = "Benar! Hadiah utama saya, satu-satunya harta karun dari kedalaman laut!",
  ui_story_5031_50311202_27_dialog_content = "Tentu saja. Saya memiliki hadiah dengan saya.",
  ui_story_5031_50311202_28_dialog_content = "Ini dia.",
  ui_story_5031_50311202_29_dialog_content = "Lihat! Lo, lo, lo!",
  ui_story_5031_50311202_30_dialog_content = "Apa?! A-Bukankah ini... KYLLO?!",
  ui_story_5031_50311202_31_dialog_content = "Bukankah aku mengirimmu ke laut untuk melacak Cloudwhale?",
  ui_story_5031_50311202_32_dialog_content = "Tidak heran saya tidak pernah mendengar kabar dari Anda! Anda telah mengendur selama ini!",
  ui_story_5031_50311202_33_dialog_content = "Saya menangkap hewan ini dari laut belum lama ini.",
  ui_story_5031_50311202_34_dialog_content = "Kelihatannya enak, jadi saya berencana untuk membuatnya menjadi sup krim seafood untuk pemenangnya.",
  ui_story_5031_50311202_35_dialog_content = "Lo, lo? Lihat!",
  ui_story_5031_50311202_36_dialog_content = "Anda tidak bisa memasak Kyllo!",
  ui_story_5031_50311202_37_dialog_content = "Ini temanku!",
  ui_story_5031_50311202_38_dialog_content = "Seorang teman? Dan saya pikir itu adalah bahan makanan yang langka dan lezat.",
  ui_story_5031_50311202_39_dialog_content = "Nah, Anda adalah pemenangnya, dan itu adalah hadiah Anda. Aku akan menyerahkannya padamu.",
  ui_story_5031_50311202_40_dialog_content = "Lo, lo...",
  ui_story_5031_50311202_41_dialog_content = "Fiuh, Anda hal kecil ceroboh! Anda tahu Anda hampir mati?",
  ui_story_5031_50311202_42_dialog_content = "Lo... Lo, lo!",
  ui_story_5031_50311202_43_dialog_content = "Hah? Anda bilang Anda tertangkap jaring saat mencari Cloudwhale di bawah laut?",
  ui_story_5031_50311202_44_dialog_content = "Dan Anda dikurung di kapal selama berhari-hari?",
  ui_story_5031_50311202_45_dialog_content = "Lalu... Apa kau melihat Cloudwhale di kapal?",
  ui_story_5031_50311202_46_dialog_content = "lihat? Lo, lo!",
  ui_story_5031_50311202_47_dialog_content = "Tidak? Sedihnya...",
  ui_story_5031_50311202_48_dialog_content = "Sekarang setelah pemenang diumumkan, bisakah semua orang naik ke geladak?",
  ui_story_5031_50311202_49_dialog_content = "Perjamuan dan kembang api akan segera dimulai.",
  ui_story_5031_50311202_50_dialog_content = "Apakah Anda mengatakan kembang api? Ayo cepat dan dapatkan tempat yang bagus!",
  ui_story_5031_50311202_51_dialog_content = "Tidak Cloudwhale... Kenapa hadiah utamanya bukan Cloudwhale?!",
  ui_story_5031_50311202_52_dialog_content = "Semua itu tidak berguna!",
  ui_story_5031_50311202_53_dialog_content = "Bagaimana itu bisa menjadi paus?",
  ui_story_5031_50311202_54_dialog_content = "Zamrud tidak akan bisa mengatasinya, bahkan jika kita hanya berbicara tentang anak paus.",
  ui_story_5031_50311202_55_dialog_content = "Apakah saya benar untuk berasumsi bahwa Anda belum pernah melihat ikan paus, nona muda?",
  ui_story_5031_50311202_56_dialog_content = "J-Jadi bagaimana jika aku belum pernah melihatnya?!",
  ui_story_5031_50311202_57_dialog_content = "Ini eksotis. Itu normal bahwa saya belum pernah melihatnya sebelumnya ...",
  ui_story_5031_50311202_58_dialog_content = "Pfft...",
  ui_story_5031_50311202_59_dialog_content = "Itu tidak lucu! Berhenti tertawa!",
  ui_story_5031_50311202_60_dialog_content = "Baiklah baiklah. Itu semua tidak sia-sia, Anda tahu.",
  ui_story_5031_50311202_61_option_content = "Kami memang memenangkan kontes",
  ui_story_5031_50311202_62_dialog_content = "Fia dan Bica sekarang berteman juga, kan?",
  ui_story_5031_50311202_63_dialog_content = "Hai!",
  ui_story_5031_50311202_64_dialog_content = "A-Baiklah! Aku akan membelikanmu anggur!",
  ui_story_5031_50311202_65_option_content = "Setidaknya kau menyelamatkan Kyllo.",
  ui_story_5031_50311202_66_dialog_content = "Lo, lo!",
  ui_story_5031_50311202_67_dialog_content = "Sayangnya... Aku hanya tidak menyangka hadiah utamanya adalah Kyllo.",
  ui_story_5031_50311202_68_dialog_content = "Karena Anda tertangkap secara tidak sengaja, maka Anda sebaiknya kembali mencari Cloudwhale.",
  ui_story_5031_50311202_69_dialog_content = "lihat?",
  ui_story_5031_50311202_70_dialog_content = "Saya tidak butuh bantuan Anda di sini. Baiklah, baiklah, lakukanlah!",
  ui_story_5031_50311202_71_dialog_content = "Biarkan saya membantu Anda dan meluncurkan Anda ke laut, kalau begitu!",
  ui_story_5031_50311202_72_dialog_content = "Lo—!",
  ui_story_5031_50311202_73_dialog_content = "(Kyllo menjadi bintang jatuh yang melesat melintasi langit... Fia sangat menakutkan!)",
  ui_story_5031_50311202_74_dialog_content = "Hmm... Apakah Anda benar-benar seorang extrozoologist?",
  ui_story_5031_50311202_75_dialog_content = "Jelas, dong!",
  ui_story_5031_50311202_76_dialog_content = "Tapi bagaimana ramalanmu, Jeno?",
  ui_story_5031_50311202_77_dialog_content = "Apakah kamu juga seorang Caelestite yang memiliki kemampuan psikis?",
  ui_story_5031_50311202_78_dialog_content = "Itu sama sekali bukan ramalan, tidak juga. Itu semua keterampilan observasi saya.",
  ui_story_5031_50311202_79_dialog_content = "Ingat wanita itu? Gaunnya mungkin tampak tidak biasa, tetapi kainnya khusus untuk Petyaburg.",
  ui_story_5031_50311202_80_dialog_content = "Adapun kehidupan cintanya... cincin di jarinya memberitahuku bahwa dia sudah menikah.",
  ui_story_5031_50311202_81_dialog_content = "Dan, cara dia terus melihat ke belakang berarti dia mungkin tidak duduk dengan pasangannya.",
  ui_story_5031_50311202_82_dialog_content = "Aku hanya menyatukan semuanya dan—",
  ui_story_5031_50311202_83_dialog_content = "Maaf mengganggu, Jeno, tapi ada sesuatu yang perlu saya bicarakan dengan Anda, secara pribadi, di atas panggung.",
  ui_story_5031_50311202_84_dialog_content = "Tentu.",
  ui_story_5031_50311202_85_dialog_content = "Maaf, semuanya. Aku akan segera kembali.",
  ui_story_5031_50311202_86_dialog_content = "Hai! Setidaknya selesaikan kalimatmu!",
  ui_story_5031_50311202_87_dialog_content = "Astaga, baru saja keluar dari percakapan seperti itu.",
  ui_story_5031_50311202_88_dialog_content = "Kembang api sudah dimulai!",
  ui_story_5031_50311202_89_dialog_content = "Itu benar-benar indah.",
  ui_story_5031_50311202_90_dialog_content = "Jadi di sana Anda!",
  ui_story_5031_50311202_91_dialog_content = "E-Semua orang di sini...",
  ui_story_5031_50311202_92_dialog_content = "Rainbow, ada apa dengan semangkuk makanan di pangkuanmu itu? Anda akan mengambilnya kembali untuk dimakan?",
  ui_story_5031_50311202_93_dialog_content = "Anda tidak akan bergabung dengan kami?",
  ui_story_5031_50311202_94_dialog_content = "Saya punya rencana lain!",
  ui_story_5031_50311202_95_dialog_content = "Tentu, kembang apinya indah, tapi Ciel dan aku baru saja menemukan ide bagus tentang cara memodifikasi mecha kami!",
  ui_story_5031_50311202_96_dialog_content = "Kami tidak sabar untuk segera mengerjakannya!",
  ui_story_5031_50311202_97_dialog_content = "Ya...",
  ui_story_5031_50311202_98_dialog_content = "Maaf kami tidak bisa menghabiskan waktu bersamamu malam ini.",
  ui_story_5031_50311202_99_dialog_content = "Oh, jangan khawatir tentang itu. Kita punya banyak waktu di masa depan!",
  ui_story_5031_50311202_100_dialog_content = "Kami akan pergi kalau begitu!",
  ui_story_5031_50311202_101_dialog_content = "Mereka terlihat sangat dekat. Aku sedikit iri pada mereka.",
  ui_story_5031_50311202_102_dialog_content = "Apakah Anda melewatkan sesuatu, Carleen?",
  ui_story_5031_50311202_103_dialog_content = "Anda memiliki saya dan PlayerName!",
  ui_story_5031_50311202_104_dialog_content = "Ya, kami telah bepergian dan bertahan bersama melalui semuanya selama ini!",
  ui_story_5031_50311202_105_dialog_content = "Tepat. Sama seperti kali ini!",
  ui_story_5031_50311202_106_dialog_content = "Kami akan kalah jika bukan karena balet luar biasa Anda yang memberi kami begitu banyak poin!",
  ui_story_5031_50311202_107_dialog_content = "Betul sekali! Ini semua berkatmu!",
  ui_story_5031_50311202_108_dialog_content = "Jadi jangan mulai bertingkah seperti orang asing, kamu!",
  ui_story_5031_50311202_109_dialog_content = "Apakah begitu...? Baiklah baiklah.",
  ui_story_5031_50311202_110_dialog_content = "Terima kasih.",
  ui_story_5031_50311202_111_dialog_content = "Iya!",
  ui_story_5031_50311301_1_dialog_content = "Saya tidak menyadarinya sebelumnya di siang hari, tetapi jika Anda melihat lebih dekat, Harbour City benar-benar terlihat mempesona di malam hari di bawah kembang api.",
  ui_story_5031_50311301_2_dialog_content = "Ya. Bangunan putihnya dicat oleh kembang api yang bersinar. Ini bahkan lebih menawan daripada siang hari!",
  ui_story_5031_50311301_3_dialog_content = "PlayerName, Vice, dan Fia. Saya ingin pergi berbicara dengan Elvis.",
  ui_story_5031_50311301_4_dialog_content = "Maukah kamu menungguku sebentar?",
  ui_story_5031_50311301_5_dialog_content = "Tentu saja! Kami akan berada di sini.",
  ui_story_5031_50311301_6_dialog_content = "Baiklah. Terima kasih.",
  ui_story_5031_50311301_7_dialog_content = "Sepertinya itu akhirnya berakhir ...",
  ui_story_5031_50311301_8_dialog_content = "Tapi saya masih belum menemukan Cloudwhale saya...",
  ui_story_5031_50311301_9_dialog_content = "Sekarang, di mana Cloudwhale yang legendaris itu berada...?",
  ui_story_5031_50311301_10_dialog_content = "Jangan terburu-buru. Beberapa hal yang tidak bisa Anda dapatkan dengan tergesa-gesa.",
  ui_story_5031_50311301_11_dialog_content = "Betul sekali. Seperti kadang-kadang semakin saya terburu-buru untuk menemukan jepit rambut saya setelah saya bangun, semakin sulit bagi saya untuk menemukannya.",
  ui_story_5031_50311301_12_dialog_content = "Tetapi ketika saya akhirnya menyerah, saya menyadari bahwa itu telah ada di samping saya selama ini!",
  ui_story_5031_50311301_13_dialog_content = "Sungguh?",
  ui_story_5031_50311301_14_dialog_content = "Tentu saja.",
  ui_story_5031_50311301_15_dialog_content = "Baiklah, aku akan mempercayaimu kali ini.",
  ui_story_5031_50311301_16_dialog_content = "Halo semuanya.",
  ui_story_5031_50311301_17_dialog_content = "Carleen? Apakah Anda memiliki bicara cepat?",
  ui_story_5031_50311301_18_dialog_content = "Tidak, tidak sama sekali. Saya tidak dapat menemukan Elvis di mana pun.",
  ui_story_5031_50311301_19_dialog_content = "Bukankah dia menyeret Jeno untuk mengobrol di atas panggung?",
  ui_story_5031_50311301_20_dialog_content = "Saya mampir ke sana tetapi tidak melihat mereka.",
  ui_story_5031_50311301_21_dialog_content = "Elvis dan Jeno...",
  ui_story_5031_50311301_22_dialog_content = "Mungkinkah mereka menuju kabin?",
  ui_story_5031_50311301_23_dialog_content = "Kabin? Jeno tidak pernah membiarkan siapa pun mendekatinya, bukan?",
  ui_story_5031_50311301_24_dialog_content = "Tetapi jika mereka tidak berada di tempat lain, mungkin di sanalah mereka berada.",
  ui_story_5031_50311301_25_dialog_content = "Mari kita pergi memeriksa. Seharusnya ada orang yang tahu ke mana mereka pergi.",
  ui_story_5031_50311301_26_dialog_content = "Bagaimana Anda tahu jalan menuju kabin dengan baik, PlayerName?",
  ui_story_5031_50311301_27_dialog_content = "Karena Fia dan aku pernah dikejar oleh Elvis dan Patou di sini untuk waktu yang lama.",
  ui_story_5031_50311301_28_dialog_content = "Elvis dan Patou? Bagaimana itu bisa terjadi?",
  ui_story_5031_50311301_29_dialog_content = "Singkat cerita, kami...",
  ui_story_5031_50311301_30_dialog_content = "Lihat, PlayerName, ada seseorang di tanah di sana!",
  ui_story_5031_50311301_31_dialog_content = "Apakah itu... Jeno?!",
  ui_story_5031_50311301_32_dialog_content = "Betulkah? Anda akan menggambar saya gambar?",
  ui_story_5031_50311301_33_dialog_content = "Ya, tapi saya menggambar dengan lambat dan juga tidak terlalu bagus.",
  ui_story_5031_50311301_34_dialog_content = "Tidak masalah. Gambar Anda adalah yang terbaik untuk saya!",
  ui_story_5031_50311301_35_dialog_content = "Yah... Kurasa sampai jumpa besok pagi di pelabuhan?",
  ui_story_5031_50311301_36_dialog_content = "Gambarkan untukku setelah pekerjaanmu di tepi laut, dan aku akan membuatkan sup seafood untukmu!",
  ui_story_5031_50311301_37_dialog_content = "Wow, sup seafood dari Elvis!",
  ui_story_5031_50311301_38_dialog_content = "Luar biasa! Ini kesepakatan, kalau begitu!",
  ui_story_5031_50311301_39_dialog_content = "Sampai besok!",
  ui_story_5031_50311301_40_dialog_content = "S-sampai jumpa besok!",
  ui_story_5031_50311301_41_dialog_content = "...",
  ui_story_5031_50311301_42_dialog_content = "...",
  ui_story_5031_50311301_43_dialog_content = "Kami punya janji.",
  ui_story_5031_50311301_44_dialog_content = "Kami punya janji...",
  ui_story_5031_50311301_45_dialog_content = "<size=33>Je...</size>",
  ui_story_5031_50311301_46_dialog_content = "<size=33>Jeno...</size>",
  ui_story_5031_50311301_47_dialog_content = "Siapa di sana?",
  ui_story_5031_50311301_48_dialog_content = "Jeno!",
  ui_story_5031_50311301_49_dialog_content = "Elvis? Apa itu kamu? Apakah kamu sudah kembali?",
  ui_story_5031_50311301_50_dialog_content = "<size=45>Bangun, Jeno!</size>",
  ui_story_5031_50311301_51_dialog_content = "Elvis!",
  ui_story_5031_50311301_52_dialog_content = "Ahhhh!",
  ui_story_5031_50311301_53_dialog_content = "Ahhhh!",
  ui_story_5031_50311301_54_dialog_content = "Mengapa Anda berteriak, PlayerName? Anda membuat saya takut!",
  ui_story_5031_50311301_55_dialog_content = "M-Maaf, aku juga takut.",
  ui_story_5031_50311301_56_dialog_content = "Bagaimana perasaanmu, Jeno? Apakah kamu terluka?",
  ui_story_5031_50311301_57_dialog_content = "Apa... Apa yang aku lakukan di sini?",
  ui_story_5031_50311301_58_dialog_content = "Bukankah seharusnya kami menanyakan itu padamu?",
  ui_story_5031_50311301_59_dialog_content = "Kenapa kamu tidur di sini? Kami telah mencarimu.",
  ui_story_5031_50311301_60_dialog_content = "Uh, Fia, itu jelas bukan \"tidur\"...",
  ui_story_5031_50311301_61_dialog_content = "Inilah masalahnya. Kembang api dan perayaan berakhir, jadi kami ingin mengucapkan selamat tinggal pada Laird Elvis.",
  ui_story_5031_50311301_62_dialog_content = "Tapi kami tidak bisa menemukannya di mana pun, jadi kami pikir kalian berdua mungkin ada di kabin.",
  ui_story_5031_50311301_63_dialog_content = "Kami mengambil kesempatan hanya untuk melihat Anda berbaring di sini, tidak sadarkan diri.",
  ui_story_5031_50311301_64_dialog_content = "Yah, aku... Aduh.",
  ui_story_5031_50311301_65_dialog_content = "Tidak ada yang akan mengganggu kita di sini. Apa yang ingin kamu katakan, Elvis?",
  ui_story_5031_50311301_66_dialog_content = "Aku hanya... Aku hanya ingin mengucapkan terima kasih, Jeno.",
  ui_story_5031_50311301_67_dialog_content = "... Hah? Itu datang entah dari mana.",
  ui_story_5031_50311301_68_dialog_content = "Untuk apa?",
  ui_story_5031_50311301_69_dialog_content = "Terima kasih telah menerima undangan saya dan memberi orang-orang di Harbour City kenangan yang begitu indah.",
  ui_story_5031_50311301_70_dialog_content = "Bagiku, kehadiranmu... sangat berarti.",
  ui_story_5031_50311301_71_dialog_content = "Itu bukan masalah besar. Kami berkeliaran di mana-mana, jadi tidak ada bedanya di mana kami bekerja.",
  ui_story_5031_50311301_72_dialog_content = "Selain itu, Anda membayar kami lebih dari cukup. Dalam hal ini, kita harus mengucapkan terima kasih.",
  ui_story_5031_50311301_73_dialog_content = "Tidak, Jeno.",
  ui_story_5031_50311301_74_dialog_content = "Saya tidak pernah bisa membayar Anda apa yang saya berutang.",
  ui_story_5031_50311301_75_dialog_content = "Terima kasih kepada saya? Apa yang kamu bicarakan-",
  ui_story_5031_50311301_76_dialog_content = "Aduh!",
  ui_story_5031_50311301_77_dialog_content = "Maaf.",
  ui_story_5031_50311301_78_dialog_content = "Batuk, batuk... A-Apa-apaan ini...",
  ui_story_5031_50311301_79_dialog_content = "Apa ini…?",
  ui_story_5031_50311301_80_dialog_content = "Jeno... Maafkan aku.",
  ui_story_5031_50311301_81_dialog_content = "Maksudmu Laird Elvis membiusmu?",
  ui_story_5031_50311301_82_dialog_content = "Ya.",
  ui_story_5031_50311301_83_dialog_content = "Tunggu, Elvis adalah orang jahat?",
  ui_story_5031_50311301_84_dialog_content = "Jangan langsung menyimpulkan, Fia. Kami belum tahu kebenarannya.",
  ui_story_5031_50311301_85_dialog_content = "<size=33>Kutukan, itu hilang ...</size>",
  ui_story_5031_50311301_86_dialog_content = "Ada apa, Jeno? Apa yang sedang Anda cari...",
  ui_story_5031_50311301_87_dialog_content = "Wow! Apa yang terjadi?",
  ui_story_5031_50311301_88_dialog_content = "Kapal... sedang goyang?",
  ui_story_5031_50311301_89_dialog_content = "... Tidak pernah menyangka dia akan melakukan ini.",
  ui_story_5031_50311301_90_dialog_content = "Tunggu, Jeno!",
  ui_story_5031_50311301_91_dialog_content = "Je-Jeno... Huff, puff...",
  ui_story_5031_50311301_92_dialog_content = "Pikiran menjelaskan apa yang terjadi?",
  ui_story_5031_50311301_93_dialog_content = "...",
  ui_story_5031_50311301_94_dialog_content = "Aku kehabisan akal.",
  ui_story_5031_50311301_95_dialog_content = "Jika dia berhasil mengaktifkan HAL itu, saya membutuhkan bantuan Anda semua.",
  ui_story_5031_50311301_96_dialog_content = "Itu?",
  ui_story_5031_50311301_97_dialog_content = "Saya baru saja menemukan kunci ruang inti kapal yang saya bawa hilang.",
  ui_story_5031_50311301_98_dialog_content = "Apakah ada sesuatu yang penting di ruangan itu?",
  ui_story_5031_50311301_99_dialog_content = "Itu <color=#FFB400>Inti Energi</color>.",
  ui_story_5031_50311301_100_dialog_content = "Inti energi?",
  ui_story_5031_50311301_101_dialog_content = "Kenapa kalian semua terlihat seperti tahu persis apa itu?",
  ui_story_5031_50311301_102_dialog_content = "Inti energi adalah ciptaan peradaban kuno. Anggap saja sebagai sumber daya yang berharga.",
  ui_story_5031_50311301_103_dialog_content = "Tidak pernah membayangkan akan ada satu di kapal ...",
  ui_story_5031_50311301_104_dialog_content = "Karena kapal ini awalnya berasal dari reruntuhan kuno.",
  ui_story_5031_50311301_105_dialog_content = "Dan HAL yang kumaksud adalah senjata kuno yang menjaga inti energi...",
  ui_story_5031_50311301_106_dialog_content = "<color=#FFB400>Penjaga Inti</color>.",
  ui_story_5031_50311301_107_dialog_content = "Ketika Core Guardian diaktifkan, ia akan menyerang semua bentuk kehidupan yang mendekati inti energi tanpa pandang bulu.",
  ui_story_5031_50311301_108_dialog_content = "Itu berarti seluruh kapal dalam bahaya.",
  ui_story_5031_50311301_109_dialog_content = "Jadi maksudmu Laird Elvis mengambil kuncinya saat kau pingsan.",
  ui_story_5031_50311301_110_dialog_content = "Dan sekarang dia memasuki ruang inti, mencoba merebut inti energi?",
  ui_story_5031_50311301_111_dialog_content = "Kemungkinan besar, tapi...",
  ui_story_5031_50311301_112_dialog_content = "Jeno!",
  ui_story_5031_50311301_113_dialog_content = "Ini Rainbow dan Ciel!",
  ui_story_5031_50311301_114_dialog_content = "Jeno, kami baru saja mendapat peringatan bahwa ruang inti telah dibuka!",
  ui_story_5031_50311301_115_dialog_content = "Saya tahu. Kami sedang menuju ke sana sekarang.",
  ui_story_5031_50311301_116_dialog_content = "Dalam perjalanan, kami melihat penjaga tentara bayaran juga pingsan...",
  ui_story_5031_50311301_117_dialog_content = "Hati-hati, Rainbow!",
  ui_story_5031_50311301_118_dialog_content = "Ah! Hampir saja. Terima kasih, Ciel.",
  ui_story_5031_50311301_119_dialog_content = "Hah? Ini adalah... Penjaga Kota Pelabuhan?",
  ui_story_5031_50311301_120_dialog_content = "Mereka ditugaskan untuk menunda kita?",
  ui_story_5031_50311301_121_dialog_content = "...",
  ui_story_5031_50311301_122_dialog_content = "Menyingkirlah, kau pelayan bodoh!",
  ui_story_5031_50311302_1_dialog_content = "Kapan Elvis...",
  ui_story_5031_50311302_2_dialog_content = "Sejak kapan orang-orang ini memasuki kabin?",
  ui_story_5031_50311302_3_dialog_content = "Aku bisa merasakan aliran Lumina lain mendekat!",
  ui_story_5031_50311302_4_dialog_content = "Ini jauh lebih banyak daripada yang kita dapatkan di sini sekarang...",
  ui_story_5031_50311302_5_dialog_content = "<color=#e8d9bb>DUAR!</color>",
  ui_story_5031_50311302_6_dialog_content = "Argh! kapal saya!",
  ui_story_5031_50311302_7_dialog_content = "Apa yang Elvis lakukan pada kapalku?!",
  ui_story_5031_50311302_8_dialog_content = "Kami tidak bisa melakukan apa-apa selain terjebak di sini jika ini terus berlanjut.",
  ui_story_5031_50311302_9_dialog_content = "Semua orang dalam acar...",
  ui_story_5031_50311302_10_dialog_content = "Aku harus melakukan ini!",
  ui_story_5031_50311302_11_dialog_content = "Pembaruan status mekanisme lengan—Tipe III.",
  ui_story_5031_50311302_12_dialog_content = "Pembaruan status mekanisme kaki—Tipe III.",
  ui_story_5031_50311302_13_dialog_content = "Meningkatkan output energi sebesar 70%.",
  ui_story_5031_50311302_14_dialog_content = "Apa?",
  ui_story_5031_50311302_15_dialog_content = "Apa yang kamu lakukan, Ciel? Mecha Anda belum sepenuhnya diuji!",
  ui_story_5031_50311302_16_dialog_content = "Aku akan membuat mereka sibuk sementara kalian pergi ke ruang inti.",
  ui_story_5031_50311302_17_dialog_content = "Namun…",
  ui_story_5031_50311302_18_dialog_content = "Jangan khawatir!",
  ui_story_5031_50311302_19_dialog_content = "Kami melakukan kalibrasi bersama, Anda ingat? Styx akan baik-baik saja!",
  ui_story_5031_50311302_20_dialog_content = "Ciel benar, Rainbow.",
  ui_story_5031_50311302_21_dialog_content = "Kita tidak bisa menghabiskan terlalu banyak waktu di sini.",
  ui_story_5031_50311302_22_dialog_content = "Kita harus mempercayai rekan kita... Serahkan ini pada Ciel.",
  ui_story_5031_50311302_23_dialog_content = "Carleen…",
  ui_story_5031_50311302_24_dialog_content = "(Carleen memang telah berubah.)",
  ui_story_5031_50311302_25_dialog_content = "...",
  ui_story_5031_50311302_26_dialog_content = "Jangan terlalu menikmati diri sendiri dan hancurkan mechanya, Ciel!",
  ui_story_5031_50311302_27_dialog_content = "Jika tidak, Anda tidak akan pernah bisa membayar saya kembali!",
  ui_story_5031_50311302_28_dialog_content = "H-hah?!",
  ui_story_5031_50311302_29_dialog_content = "Oke, jangan khawatir.",
  ui_story_5031_50311302_30_dialog_content = "Anda punya ini, Ciel.",
  ui_story_5031_50311302_31_dialog_content = "Hati-hati, Ciel!",
  ui_story_5031_50311302_32_dialog_content = "Kami tidak ingin memilih seorang gadis. Anda sebaiknya lari sekarang.",
  ui_story_5031_50311302_33_dialog_content = "Aku lebih dari cukup untuk menerima kalian semua.",
  ui_story_5031_50311302_34_dialog_content = "Nah, jika itu yang Anda inginkan.",
  ui_story_5031_50311302_35_dialog_content = "Hmm, mereka lebih tangguh dan memiliki lebih banyak orang.",
  ui_story_5031_50311302_36_dialog_content = "Kalau begitu, aku harus...",
  ui_story_5031_50311302_37_dialog_content = "Meningkatkan output energi sebesar 80%.",
  ui_story_5031_50311302_38_dialog_content = "Astaga... Daya tembaknya meningkat lagi?",
  ui_story_5031_50311302_39_dialog_content = "Mecha ini seperti monster.",
  ui_story_5031_50311302_40_dialog_content = "Tapi untuk laird, kita tidak akan jatuh.",
  ui_story_5031_50311302_41_dialog_content = "Pasukan 1! Tahan formasi Anda dan tekan dengan perisai Lumina Anda!",
  ui_story_5031_50311302_42_dialog_content = "Dia sudah selesai jika dia keluar dari mecha itu!",
  ui_story_5031_50311302_43_dialog_content = "Siap, Pak!",
  ui_story_5031_50311302_44_dialog_content = "Perisai mereka menjadi lebih tahan lama saat ditumpuk menjadi satu?",
  ui_story_5031_50311302_45_dialog_content = "Bersiaplah untuk senjata Lumina, Pasukan 2!",
  ui_story_5031_50311302_46_dialog_content = "Oh, tidak, jika aku tidak bisa menghancurkan perisai ini dan membiarkan mereka mendekat...",
  ui_story_5031_50311302_47_dialog_content = "Oke, harus tenang, bernapas ...",
  ui_story_5031_50311302_48_dialog_content = "Mungkin lebih sulit, tetapi Lumina adalah kuncinya jika menggunakan energi.",
  ui_story_5031_50311302_49_dialog_content = "Jadi saya hanya perlu melepaskan lebih banyak Lumina daripada itu.",
  ui_story_5031_50311302_50_dialog_content = "Tapi Styx sudah down sekali hari ini...",
  ui_story_5031_50311302_51_dialog_content = "Jika saya meningkatkan output, Styx mungkin...",
  ui_story_5031_50311302_52_dialog_content = "Saya memutuskan. Saya akan banyak membantu orang setelah saya membangun mekanisme dinamis!",
  ui_story_5031_50311302_53_dialog_content = "Oh? Jadi apa yang paling ingin kamu lakukan dengannya, Ciel?",
  ui_story_5031_50311302_54_dialog_content = "Yah, saya pikir ...",
  ui_story_5031_50311302_55_dialog_content = "Kupikir...",
  ui_story_5031_50311302_56_dialog_content = "Saya akan membantu dan melindungi teman-teman saya dan dapat diandalkan!",
  ui_story_5031_50311302_57_dialog_content = "Maaf, Rainbow. Maaf, Stix!",
  ui_story_5031_50311302_58_dialog_content = "<size=45>Tingkatkan keluaran energi hingga 100%!</size>",
  ui_story_5031_50311302_59_dialog_content = "A-Apa? Perisai rusak! Tapi bagaimana caranya...",
  ui_story_5031_50311302_60_dialog_content = "Dia pasti monster!",
  ui_story_5031_50311302_61_dialog_content = "Huff.. sip..",
  ui_story_5031_50311302_62_dialog_content = "Sepertinya itu cukup merepotkan...",
  ui_story_5031_50311302_63_dialog_content = "Tidak hanya sirkuit kaki yang mendesis, tetapi Lumina juga ...",
  ui_story_5031_50311302_64_dialog_content = "Jangan mundur!",
  ui_story_5031_50311302_65_dialog_content = "Tidak masalah jika perisai itu hilang. Dia hanya memiliki begitu banyak energi!",
  ui_story_5031_50311302_66_dialog_content = "Bisakah kita membiarkan satu gadis menahan kita semua?!",
  ui_story_5031_50311302_67_dialog_content = "... Ya pak!",
  ui_story_5031_50311302_68_dialog_content = "Huff... Aku tidak akan membiarkanmu lewat...",
  ui_story_5031_50311302_69_dialog_content = "Pelanggarannya berkurang. Sekarang saatnya!",
  ui_story_5031_50311302_70_dialog_content = "Masih tidak bisa menang meskipun keunggulan angka Anda. Anda yakin Anda yang terbaik di Harbour City?",
  ui_story_5031_50311302_71_dialog_content = "Itu terdengar seperti...",
  ui_story_5031_50311302_72_dialog_content = "Ah!",
  ui_story_5031_50311302_73_dialog_content = "I-Ini dia!",
  ui_story_5031_50311302_74_dialog_content = "Fiuh, bukankah aku sudah memberitahumu untuk tidak terlalu menikmati dirimu sendiri?",
  ui_story_5031_50311302_75_dialog_content = "Styx terlihat lebih buruk untuk dipakai! Astaga, aku baru saja menghabiskan sepanjang sore untuk memperbaikinya!",
  ui_story_5031_50311302_76_dialog_content = "Itu kamu ya Rainbow! Kenapa kamu kembali?",
  ui_story_5031_50311302_77_dialog_content = "Karena aku mengkhawatirkanmu.",
  ui_story_5031_50311302_78_dialog_content = "Tapi bagaimana dengan ruang inti?",
  ui_story_5031_50311302_79_dialog_content = "Jeno dan teman-temannya ada di sana.",
  ui_story_5031_50311302_80_dialog_content = "Tut, beraninya kau menyelinap menyerangku?",
  ui_story_5031_50311302_81_dialog_content = "Ugh!",
  ui_story_5031_50311302_82_dialog_content = "...",
  ui_story_5031_50311302_83_dialog_content = "Hmm? Ada apa, Ciel? Mengapa Anda terlihat seperti itu?",
  ui_story_5031_50311302_84_dialog_content = "... Itu masuk akal.",
  ui_story_5031_50311302_85_dialog_content = "Seseorang yang mempermalukan dirinya sendiri seperti saya tidak berhak berbicara tentang kepercayaan dan ketergantungan.",
  ui_story_5031_50311302_86_dialog_content = "Jika kau tidak kembali padaku, mungkin aku...",
  ui_story_5031_50311302_87_dialog_content = "...",
  ui_story_5031_50311302_88_dialog_content = "Terkadang kamu agak konyol, Ciel.",
  ui_story_5031_50311302_89_dialog_content = "Apa?",
  ui_story_5031_50311302_90_dialog_content = "Tapi aku suka kamu yang bodoh!",
  ui_story_5031_50311302_91_dialog_content = "Saya percaya Anda, dan itulah mengapa saya tahu Anda akan berusaha 100% untuk melindungi kami.",
  ui_story_5031_50311302_92_dialog_content = "Tapi tidak ada yang tahu bagaimana kondisi Styx lebih baik dari kita. Saya sadar bagaimana itu akan berakhir, dan inilah saya.",
  ui_story_5031_50311302_93_dialog_content = "...",
  ui_story_5031_50311302_94_dialog_content = "Saya percaya Jeno juga, dan saya percaya mereka akan membela Zamrud.",
  ui_story_5031_50311302_95_dialog_content = "Jadi yakinlah.",
  ui_story_5031_50311302_96_dialog_content = "Ketika semuanya selesai, saya akan merapikan Styx dengan Anda.",
  ui_story_5031_50311302_97_dialog_content = "Kami akan membuatnya cerdas, kuat, dan tidak rusak bahkan pada output 300%!",
  ui_story_5031_50311302_98_dialog_content = "… Oke.",
  ui_story_5031_50311302_99_dialog_content = "Tapi kita harus menyingkirkan gangguan ini terlebih dahulu.",
  ui_story_5031_50311302_100_dialog_content = "Ayo. Anda meluncurkan serangan diam-diam bahkan ketika Anda jauh melebihi jumlah kami.",
  ui_story_5031_50311302_101_dialog_content = "Apakah kamu tidak tahu malu?",
  ui_story_5031_50311302_102_dialog_content = "...",
  ui_story_5031_50311401_1_dialog_content = "*Batuk-batuk*",
  ui_story_5031_50311401_2_dialog_content = "Nah, siap untuk pergi sekarang.",
  ui_story_5031_50311401_3_dialog_content = "Tinggal menunggu potongan terakhir jatuh ke tempatnya.",
  ui_story_5031_50311401_4_dialog_content = "Langkah kaki mendekat, Pak.",
  ui_story_5031_50311401_5_dialog_content = "Baiklah, biarkan mereka datang. Anda harus meninggalkan kapal sesuai rencana dan mencegah orang lain mendekat.",
  ui_story_5031_50311401_6_dialog_content = "...",
  ui_story_5031_50311401_7_dialog_content = "Ada apa?",
  ui_story_5031_50311401_8_dialog_content = "Apakah Anda yakin, Pak?",
  ui_story_5031_50311401_9_dialog_content = "Seharusnya aku tidak meninggalkanmu sendiri...",
  ui_story_5031_50311401_10_dialog_content = "Anda melakukan pekerjaan Anda. Aku harus menghadapi apa yang akan terjadi selanjutnya sendirian.",
  ui_story_5031_50311401_11_dialog_content = "...",
  ui_story_5031_50311401_12_dialog_content = "Atau apakah kamu tidak percaya padaku, Patou?",
  ui_story_5031_50311401_13_dialog_content = "Aku pasti percaya padamu! Anda tahu bukan itu yang saya maksud.",
  ui_story_5031_50311401_14_dialog_content = "Jika Anda melakukannya, pergi sekarang. Anda hanya akan merusak rencana dengan tetap di sini.",
  ui_story_5031_50311401_15_dialog_content = "Jangan khawatir. Semuanya di bawah kendali saya sejauh ini.",
  ui_story_5031_50311401_16_dialog_content = "Ingat apa yang saya katakan ... Jangan masuk tidak peduli apa yang Anda dengar.",
  ui_story_5031_50311401_17_dialog_content = "... Iya.",
  ui_story_5031_50311401_18_dialog_content = "Jaga diri kamu.",
  ui_story_5031_50311401_19_dialog_content = "Elvis!",
  ui_story_5031_50311401_20_dialog_content = "Oh? Bukan Rainbow dan Ciel tapi Yang Mulia dan kalian?",
  ui_story_5031_50311401_21_dialog_content = "Tapi tidak apa-apa. Anda hanya sedikit lebih lambat dari yang saya kira.",
  ui_story_5031_50311401_22_dialog_content = "Semuanya sudah siap tetapi Anda masih tidak muncul, jadi saya khawatir jika orang-orang itu benar-benar menghentikan Anda.",
  ui_story_5031_50311401_23_dialog_content = "Apakah dia mengharapkan kita dari cara dia berbicara...?",
  ui_story_5031_50311401_24_dialog_content = "Saya tidak melihat Patou. Aku ingin tahu apa yang ada di lengan bajunya.",
  ui_story_5031_50311401_25_dialog_content = "Apapun itu, mari kita berhati-hati.",
  ui_story_5031_50311401_26_dialog_content = "Ya.",
  ui_story_5031_50311401_27_dialog_content = "Apakah itu... inti energi di sebelahnya?",
  ui_story_5031_50311401_28_dialog_content = "Harus. Saya bisa merasakan energi yang kuat dan tidak biasa darinya.",
  ui_story_5031_50311401_29_dialog_content = "Tapi bagaimana dia akan membawa sesuatu yang besar bersamanya?",
  ui_story_5031_50311401_30_dialog_content = "Dengarkan aku, Elvis.",
  ui_story_5031_50311401_31_dialog_content = "Saya tidak tahu apa yang Anda rencanakan untuk dilakukan dengan inti energi.",
  ui_story_5031_50311401_32_dialog_content = "Tapi saya tahu tujuan utama Anda adalah untuk melindungi orang-orang Harbour City dari Sindrom Modali.",
  ui_story_5031_50311401_33_dialog_content = "Apa yang Anda lakukan sekarang, bagaimanapun, hanya akan membahayakan kota.",
  ui_story_5031_50311401_34_dialog_content = "Ketika inti energi keluar dari mode normalnya, ia akan bangun...",
  ui_story_5031_50311401_35_dialog_content = "Walinya.",
  ui_story_5031_50311401_36_dialog_content = "...",
  ui_story_5031_50311401_37_dialog_content = "Anda tahu tentang itu?",
  ui_story_5031_50311401_38_dialog_content = "Anda akan menemukan informasi yang Anda butuhkan juga, setelah Anda membaca setiap buku di dunia ini.",
  ui_story_5031_50311401_39_dialog_content = "Senjata robot: Penjaga Inti.",
  ui_story_5031_50311401_40_dialog_content = "Sebuah produk peradaban kuno, dengan kekuatan yang cukup untuk menghancurkan sebuah kota kecil.",
  ui_story_5031_50311401_41_dialog_content = "Saat inti energi mengalami gangguan, Penjaga Inti diaktifkan.",
  ui_story_5031_50311401_42_dialog_content = "Jika operasi ini berlanjut, itu tidak hanya akan menyebabkan Guardian menyerang tetapi dapat mengakibatkan penghancuran diri inti.",
  ui_story_5031_50311401_43_dialog_content = "Itu sebabnya kalian orang Orde Sejati tidak akan pernah bisa mendapatkan inti energi ini, kan?",
  ui_story_5031_50311401_44_dialog_content = "...",
  ui_story_5031_50311401_45_dialog_content = "Pesanan Benar...?",
  ui_story_5031_50311401_46_dialog_content = "Kamu bersama True Order, Jeno?",
  ui_story_5031_50311401_47_dialog_content = "... Ceritanya panjang. Pemahaman saya tentang inti memang datang dari The True Order, tapi itu tidak penting.",
  ui_story_5031_50311401_48_dialog_content = "Mari kita kesampingkan masalah Jeno dan True Order untuk saat ini.",
  ui_story_5031_50311401_49_dialog_content = "Jika Anda tahu banyak tentang itu, Elvis, mengapa Anda masih melakukan sesuatu yang dapat membahayakan orang-orang di Harbour City?",
  ui_story_5031_50311401_50_dialog_content = "Membahayakan orang-orang di Harbour City?",
  ui_story_5031_50311401_51_dialog_content = "Tidak, tidak, Yang Mulia, saya tidak seperti bangsawan tua yang dimanjakan di Lumopolis.",
  ui_story_5031_50311401_52_dialog_content = "Saya tidak akan pernah bermain-main dengan kehidupan orang-orang saya.",
  ui_story_5031_50311401_53_dialog_content = "Aku punya alasan untuk melakukan ini.",
  ui_story_5031_50311401_54_dialog_content = "Tapi saya tidak berpikir Anda akan pernah bisa mengetahuinya.",
  ui_story_5031_50311401_55_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_5031_50311401_56_dialog_content = "Suara apakah itu? Begitu keras dan menjengkelkan!",
  ui_story_5031_50311401_57_dialog_content = "Astaga... Apa yang kau lakukan, Elvis?",
  ui_story_5031_50311401_58_dialog_content = "Karena semua tamu hadir, saya bisa mendapatkan pertunjukan di jalan.",
  ui_story_5031_50311401_59_dialog_content = "Saya mengagumi karakter Anda, Yang Mulia, tetapi saya lebih cenderung melakukan apa saja untuk masa depan Harbour City.",
  ui_story_5031_50311401_60_dialog_content = "Jika Anda ingin menyimpan dendam, biarkan itu untuk saya saja.",
  ui_story_5031_50311401_61_dialog_content = "Segelnya tidak stabil lagi, jadi saya harus menyelamatkan kota dengan cara apa pun yang saya bisa.",
  ui_story_5031_50311401_62_dialog_content = "Lihat, permata di tongkatnya bersinar!",
  ui_story_5031_50311401_63_dialog_content = "Permata itu...",
  ui_story_5031_50311401_64_dialog_content = "Ini menyerap energi dari inti!",
  ui_story_5031_50311401_65_dialog_content = "Ah, kau bahkan bisa merasakannya, Caelestite?",
  ui_story_5031_50311401_66_dialog_content = "Yah, kurasa itu berarti aku tidak bisa membiarkan kalian hidup-hidup.",
  ui_story_5031_50311401_67_dialog_content = "Tapi aku berencana untuk melakukannya.",
  ui_story_5031_50311401_68_dialog_content = "\"Aktivitas yang tidak biasa terdeteksi.\"",
  ui_story_5031_50311401_69_dialog_content = "\"Pertahanan otomatis diaktifkan. Sedang menjalani analisis sistem.\"",
  ui_story_5031_50311401_70_dialog_content = "Hei, robot besar yang tergantung di bawah balok besar itu bergerak!",
  ui_story_5031_50311401_71_dialog_content = "Ah, yang terburuk telah terjadi.",
  ui_story_5031_50311401_72_dialog_content = "Core Guardian akan segera dibangunkan...",
  ui_story_5031_50311401_73_dialog_content = "Hati-hati, kalian.",
  ui_story_5031_50311401_74_dialog_content = "\"Identifikasi Energi: Lumina.\"",
  ui_story_5031_50311401_75_dialog_content = "\"Analisis: Target bermusuhan.\"",
  ui_story_5031_50311401_76_dialog_content = "\"Kesimpulan: Mulai mode serangan.\"",
  ui_story_5031_50311401_77_dialog_content = "Energinya semakin kuat!",
  ui_story_5031_50311401_78_dialog_content = "Dapatkan di belakangku, Fia!",
  ui_story_5031_50311401_79_dialog_content = "Oh baiklah!",
  ui_story_5031_50311402_1_dialog_content = "Vice, Jeno, aku akan menyerang dari kiri belakang.",
  ui_story_5031_50311402_2_dialog_content = "Aku ingin kamu menahan serangan Penjaga Inti!",
  ui_story_5031_50311402_3_dialog_content = "Siap!",
  ui_story_5031_50311402_4_dialog_content = "Hati-hati dengan kumpulan energi di lengan kanannya, Vice!",
  ui_story_5031_50311402_5_dialog_content = "Ini akan menyerang!",
  ui_story_5031_50311402_6_dialog_content = "OK saya mengerti!",
  ui_story_5031_50311402_7_dialog_content = "Ice Blossom!",
  ui_story_5031_50311402_8_dialog_content = "\"Lambung dipukul.\"",
  ui_story_5031_50311402_9_dialog_content = "\"Mulailah menilai kerusakannya.\"",
  ui_story_5031_50311402_10_dialog_content = "Wow, robot besar itu tidak bergerak!",
  ui_story_5031_50311402_11_dialog_content = "Kamu luar biasa, Carleen!",
  ui_story_5031_50311402_12_dialog_content = "Tidak terlalu. Energinya masih berjalan normal di dalamnya.",
  ui_story_5031_50311402_13_dialog_content = "Anda sangat kompeten, bahkan melebihi antisipasi saya.",
  ui_story_5031_50311402_14_dialog_content = "Meskipun saya telah mendengar banyak tentang apa yang dapat dilakukan PlayerName tetapi melihat adalah percaya.",
  ui_story_5031_50311402_15_dialog_content = "Ini memalukan, namun...",
  ui_story_5031_50311402_16_dialog_content = "Bahwa usahamu akan sia-sia.",
  ui_story_5031_50311402_17_dialog_content = "\"Penilaian selesai, tidak ada kerusakan serius.\"",
  ui_story_5031_50311402_18_dialog_content = "\"Perbarui data musuh, sesuaikan output kerusakan.\"",
  ui_story_5031_50311402_19_dialog_content = "Apa ini...?",
  ui_story_5031_50311402_20_dialog_content = "Carleen, itu mengumpulkan energi besar di dada. Bebek!",
  ui_story_5031_50311402_21_dialog_content = "Ugh!",
  ui_story_5031_50311402_22_dialog_content = "Hampir saja.",
  ui_story_5031_50311402_23_dialog_content = "Kau baik-baik saja, Carleen?",
  ui_story_5031_50311402_24_dialog_content = "Saya baik-baik saja. Berkat peringatan PlayerName, itu hanya goresan.",
  ui_story_5031_50311402_25_dialog_content = "Bagus, karena kekuatan yang baru saja dilepaskannya mengerikan...",
  ui_story_5031_50311402_26_dialog_content = "Setengah dari dinding di ruangan itu meleleh.",
  ui_story_5031_50311402_27_dialog_content = "Kekuatan senjata peradaban kuno memang menakutkan.",
  ui_story_5031_50311402_28_dialog_content = "Mari mengelilinginya dan temukan titik lemahnya.",
  ui_story_5031_50311402_29_dialog_content = "Ya. Anda juga berhati-hati.",
  ui_story_5031_50311402_30_dialog_content = "Anda tahu, apakah Anda memperhatikan sesuatu yang aneh?",
  ui_story_5031_50311402_31_dialog_content = "Ada apa?",
  ui_story_5031_50311402_32_dialog_content = "Mengapa Guardian hanya menyerang kita?",
  ui_story_5031_50311402_33_dialog_content = "Elvis jelas berdiri tepat di sebelah inti dan menyedot energinya.",
  ui_story_5031_50311402_34_dialog_content = "Itu benar.",
  ui_story_5031_50311402_35_dialog_content = "Karena Wali...",
  ui_story_5031_50311402_36_dialog_content = "...",
  ui_story_5031_50311402_37_dialog_content = "Kamu tahu kenapa, Jeno?",
  ui_story_5031_50311402_38_dialog_content = "Tidak, tidak ada.",
  ui_story_5031_50311402_39_dialog_content = "Mengapa Anda tidak menyelesaikan apa yang Anda katakan?",
  ui_story_5031_50311402_40_dialog_content = "Kamu masih peduli dengan perasaanku sampai sekarang?",
  ui_story_5031_50311402_41_dialog_content = "Masih sama kamu, Jeno.",
  ui_story_5031_50311402_42_dialog_content = "Tidak masalah. Saya sudah terbiasa, Anda bisa memuntahkannya.",
  ui_story_5031_50311402_43_dialog_content = "Elvis...",
  ui_story_5031_50311402_44_dialog_content = "Beri tahu mereka itu karena Guardian mengenali musuh melalui Lumina.",
  ui_story_5031_50311402_45_dialog_content = "Tapi bagi saya, dengan semua Lumina saya diserap ...",
  ui_story_5031_50311402_46_dialog_content = "Aku tidak lebih dari mayat.",
  ui_story_5031_50311402_47_dialog_content = "L-Lumina diserap?",
  ui_story_5031_50311402_48_dialog_content = "Itu menjelaskan mengapa saya tidak bisa merasakan Lumina di Elvis.",
  ui_story_5031_50311402_49_dialog_content = "Saya pikir itu karena penyakitnya.",
  ui_story_5031_50311402_50_dialog_content = "Ini adalah sebaliknya. Kehilangan Lumina menyebabkan penyakit.",
  ui_story_5031_50311402_51_dialog_content = "Modali Syndrome sebenarnya adalah penyakit akibat hilangnya Lumina dalam jangka waktu yang lama.",
  ui_story_5031_50311402_52_dialog_content = "Para korban hidup dengan rasa sakit Lumina yang terus-menerus meninggalkan tubuh mereka. Kasus yang parah bahkan...",
  ui_story_5031_50311402_53_dialog_content = "Jadi, solusinya adalah mendapatkan energi inti?",
  ui_story_5031_50311402_54_dialog_content = "Saya tidak yakin secara spesifik, tapi itulah inti dari rencananya.",
  ui_story_5031_50311402_55_dialog_content = "Dengarkan aku, Elvis.",
  ui_story_5031_50311402_56_dialog_content = "Bahkan jika Anda mendapatkan inti energi, Anda tidak dapat mengontrol Guardian.",
  ui_story_5031_50311402_57_dialog_content = "Setelah kita turun, perhatiannya akan tertuju padamu dan Harbour City.",
  ui_story_5031_50311402_58_dialog_content = "Harus ada cara lain. Kita dapat...",
  ui_story_5031_50311402_59_dialog_content = "Tidak ada cara lain, Jeno.",
  ui_story_5031_50311402_60_dialog_content = "Saya telah mencari solusi sejak pertama kali saya menyaksikan orang-orang saya meninggal karena penyakit ini.",
  ui_story_5031_50311402_61_dialog_content = "Saya mencoba setiap opsi yang mungkin selama bertahun-tahun, bahkan ketika peluang sukses sangat tipis.",
  ui_story_5031_50311402_62_dialog_content = "Tapi yang tersisa hanyalah kekecewaan dan tubuh yang menurun.",
  ui_story_5031_50311402_63_dialog_content = "Saya harus menyelesaikannya meskipun waktu saya habis.",
  ui_story_5031_50311402_64_dialog_content = "Namun…",
  ui_story_5031_50311402_65_dialog_content = "Berhenti bicara, Jeno. The Guardian datang dengan cara Anda!",
  ui_story_5031_50311402_66_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5031_50311402_67_dialog_content = "Jeno!",
  ui_story_5031_50311402_68_dialog_content = "Uhuk, uhuk.",
  ui_story_5031_50311402_69_dialog_content = "Aku baik-baik saja...",
  ui_story_5031_50311402_70_dialog_content = "Syukurlah, itu membuatku takut ...",
  ui_story_5031_50311402_71_dialog_content = "Itu rendah, Elvis!",
  ui_story_5031_50311402_72_dialog_content = "Anda mengalihkan perhatian Jeno dengan dalih pembicaraan!",
  ui_story_5031_50311402_73_dialog_content = "Tidak, Anda salah paham, Nona Fia.",
  ui_story_5031_50311402_74_dialog_content = "Itu bukan niat saya. Sebaliknya, aku membutuhkan kalian semua...",
  ui_story_5031_50311402_75_dialog_content = "Anda membutuhkan kami untuk menjaga Penjaga tetap sibuk saat Anda menyerap energi, kan?",
  ui_story_5031_50311402_76_dialog_content = "Anda sangat cerdik, Yang Mulia.",
  ui_story_5031_50311402_77_dialog_content = "Adapun Penjaga Inti, saya dapat mengungkapkan beberapa informasi mengingat Anda sangat khawatir tentang orang-orang di Harbour City.",
  ui_story_5031_50311402_78_dialog_content = "Perbedaan antara True Order dan saya adalah saya memiliki sesuatu yang tidak mereka miliki.",
  ui_story_5031_50311402_79_dialog_content = "Saya dapat mengikat inti energi ke darah saya dan mengendalikannya.",
  ui_story_5031_50311402_80_dialog_content = "Setelah saya selesai menyerap inti energi, Guardian akan mematuhi saya juga.",
  ui_story_5031_50311402_81_dialog_content = "Dengan demikian, Anda dapat beristirahat dengan tenang dengan kapal ini di dasar laut, mengetahui orang-orang saya aman.",
  ui_story_5031_50311402_82_dialog_content = "Anda telah memutuskan untuk membunuh kami saat itu, Laird Elvis.",
  ui_story_5031_50311402_83_dialog_content = "Maaf, tapi saya tidak bisa mengambil risiko Dewan Penatua mengetahui hal ini.",
  ui_story_5031_50311402_84_dialog_content = "Yah, kurasa tidak ada lagi yang perlu kita diskusikan.",
  ui_story_5031_50311402_85_dialog_content = "Tapi apakah Anda bermaksud baik, saya tidak akan membiarkan Anda menyakiti teman-teman saya.",
  ui_story_5031_50311402_86_dialog_content = "Jeno, ilusi yang kamu buat membawa Lumina kamu, kan?",
  ui_story_5031_50311402_87_dialog_content = "Ya.",
  ui_story_5031_50311402_88_dialog_content = "Berapa banyak gambar tentara yang dapat Anda proyeksikan?",
  ui_story_5031_50311402_89_dialog_content = "Saya mungkin bisa mengendalikan lebih dari sepuluh pada saat yang sama.",
  ui_story_5031_50311402_90_dialog_content = "Anda punya rencana, Carleen?",
  ui_story_5031_50311402_91_dialog_content = "aku ingin kamu, Vice, dan Jeno, untuk membuat Guardian sibuk untukku.",
  ui_story_5031_50311402_92_dialog_content = "Mengembalikan inti energi menjadi normal adalah prasyarat untuk menonaktifkan Guardian.",
  ui_story_5031_50311402_93_dialog_content = "Itu harus memperjelas tujuan kita.",
  ui_story_5031_50311402_94_dialog_content = "Aku akan menghentikan Elvis menyerap inti energi.",
  ui_story_5031_50311501_1_dialog_content = "Rapid Torrent!",
  ui_story_5031_50311501_2_dialog_content = "Oke, kita mendapat perhatian Guardian.",
  ui_story_5031_50311501_3_dialog_content = "Sekarang, Carleen!",
  ui_story_5031_50311501_4_dialog_content = "Cepat. Aku tidak bisa menyimpan semua ilusi ini lama-lama.",
  ui_story_5031_50311501_5_dialog_content = "Baiklah, terima kasih!",
  ui_story_5031_50311501_6_dialog_content = "Uhuk, uhuk...",
  ui_story_5031_50311501_7_dialog_content = "Saya tidak akan mengharapkan sesuatu yang kurang dari Anda, Nyonya Carleen.",
  ui_story_5031_50311501_8_dialog_content = "Bahkan tidak mengenal Jeno sehari dan masih menemukan cara menggunakan kekuatannya untuk mengalihkan perhatian Guardian.",
  ui_story_5031_50311501_9_dialog_content = "Pikiran yang sangat taktis, ditambah dengan kemampuan PlayerName...",
  ui_story_5031_50311501_10_dialog_content = "Aku senang aku tidak pernah meremehkanmu sejak awal.",
  ui_story_5031_50311501_11_dialog_content = "Ugh!",
  ui_story_5031_50311501_12_dialog_content = "Apa yang salah, Carleen?!",
  ui_story_5031_50311501_13_dialog_content = "Aku... tidak bisa... bergerak...",
  ui_story_5031_50311501_14_dialog_content = "Tenagaku terkuras...",
  ui_story_5031_50311501_15_dialog_content = "Tetap di sini dan jangan kemana-mana, Fia!",
  ui_story_5031_50311501_16_dialog_content = "Tapi robot itu akan membunuhmu, PlayerName!",
  ui_story_5031_50311501_17_dialog_content = "Hei, kenapa robot itu tidak bereaksi sama sekali?",
  ui_story_5031_50311501_18_dialog_content = "Carleen!",
  ui_story_5031_50311501_19_dialog_content = "PlayerName…",
  ui_story_5031_50311501_20_dialog_content = "(Lumina di Carleen mengalir dengan cepat!)",
  ui_story_5031_50311501_21_dialog_content = "Sial...",
  ui_story_5031_50311501_22_dialog_content = "<size=45>Apa yang telah kamu lakukan, Elvis?!</size>",
  ui_story_5031_50311501_23_dialog_content = "Tidak enak rasanya jika Lumina dikeluarkan darimu, bukan?",
  ui_story_5031_50311501_24_dialog_content = "Sebagai kontingensi, saya menempatkan a <color=#FFB400>tindakan pencegahan keselamatan</color> pada Yang Mulia.",
  ui_story_5031_50311501_25_dialog_content = "Tindakan pencegahan keamanan? Kapan?",
  ui_story_5031_50311501_26_dialog_content = "Apakah itu pakaian yang dia kenakan?",
  ui_story_5031_50311501_27_dialog_content = "Benar.",
  ui_story_5031_50311501_28_dialog_content = "Ketika Anda bertanya kepada saya bagaimana cara masuk ke kabin, saya tahu ini mungkin terjadi.",
  ui_story_5031_50311501_29_dialog_content = "Pakaian pada dirinya dirancang khusus.",
  ui_story_5031_50311501_30_dialog_content = "Saat <color=#FFB400>Lumothread</color> diaktifkan, ia akan menempel pada pemakainya dan menyerap Lumina dengan cepat.",
  ui_story_5031_50311501_31_dialog_content = "Oleh karena itu, dia lebih baik tidak menggunakan Lumina sama sekali.",
  ui_story_5031_50311501_32_dialog_content = "Apa-apaan kau…!",
  ui_story_5031_50311501_33_dialog_content = "maafkan aku... aku meremehkannya...",
  ui_story_5031_50311501_34_dialog_content = "Itu bukan salahmu. Anda harus...",
  ui_story_5031_50311501_35_dialog_content = "Hati-hati, Jeno!",
  ui_story_5031_50311501_36_dialog_content = "Hah!?",
  ui_story_5031_50311501_37_dialog_content = "Apakah kamu baik-baik saja, Jeno?",
  ui_story_5031_50311501_38_dialog_content = "Aduh! Lenganku...",
  ui_story_5031_50311501_39_dialog_content = "Aku tidak bisa memindahkannya.",
  ui_story_5031_50311501_40_dialog_content = "Jangan bergerak. Anda berdarah!",
  ui_story_5031_50311501_41_dialog_content = "\"Musuh terluka. Mode pengejaran diaktifkan.\"",
  ui_story_5031_50311501_42_dialog_content = "The Guardian menyerang ke arah Anda, Vice!",
  ui_story_5031_50311501_43_dialog_content = "Oh tidak, ini terlalu cepat!",
  ui_story_5031_50311501_44_dialog_content = "Sudah terlambat bagi saya untuk menembak!",
  ui_story_5031_50311501_45_dialog_content = "Berhenti... Aduh!",
  ui_story_5031_50311501_46_dialog_content = "J-Jeno?",
  ui_story_5031_50311501_47_dialog_content = "...",
  ui_story_5031_50311501_48_dialog_content = "Dia pingsan.",
  ui_story_5031_50311501_49_dialog_content = "Oh tidak, apa yang akan kita lakukan sekarang?",
  ui_story_5031_50311501_50_dialog_content = "Oh ya, aku masih punya ini!",
  ui_story_5031_50311501_51_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_5031_50311501_52_dialog_content = "\"?\"",
  ui_story_5031_50311501_53_dialog_content = "Kena kau! Untungnya saya masih mendapatkan master senjata yang diberikan kepada saya!",
  ui_story_5031_50311501_54_dialog_content = "Bagaimana Anda menyukainya, robot?",
  ui_story_5031_50311501_55_dialog_content = "\"Di bawah serangan yang tidak diketahui, kerusakan yang diderita: 0.\"",
  ui_story_5031_50311501_56_dialog_content = "\"Target tidak menghabiskan Lumina. Analisis: Penghapusan prioritas.\"",
  ui_story_5031_50311501_57_dialog_content = "Waaah! Mengapa itu menagih saya sekarang ?!",
  ui_story_5031_50311501_58_dialog_content = "Aaaah!",
  ui_story_5031_50311501_59_dialog_content = "Fi!",
  ui_story_5031_50311501_60_dialog_content = "...",
  ui_story_5031_50311501_61_dialog_content = "Kami sudah selesai jika ini terus berlanjut.",
  ui_story_5031_50311501_62_dialog_content = "Saya satu-satunya yang tersisa sekarang, jadi jangan panik.",
  ui_story_5031_50311501_63_dialog_content = "Aku harus menghentikan Elvis dulu untuk menghentikan Guardian.",
  ui_story_5031_50311501_64_dialog_content = "...",
  ui_story_5031_50311501_65_dialog_content = "Berbaring sebentar, Carleen, dan jangan gunakan Lumina lagi.",
  ui_story_5031_50311501_66_dialog_content = "Apa yang kamu lakukan, PlayerName?",
  ui_story_5031_50311501_67_dialog_content = "Aku akan menghentikan Elvis.",
  ui_story_5031_50311501_68_dialog_content = "Saya kira sudah waktunya saya menempatkan pelatihan dari Sinsa dan lain-lain untuk digunakan dengan baik.",
  ui_story_5031_50311501_69_dialog_content = "Namun…",
  ui_story_5031_50311501_70_dialog_content = "Santai saja, Carleen.",
  ui_story_5031_50311501_71_dialog_content = "Aku mungkin tidak memiliki Lumina, tapi melawan orang sakit-sakitan seperti Elvis...",
  ui_story_5031_50311501_72_dialog_content = "Aku tidak akan kalah.",
  ui_story_5031_50311501_73_dialog_content = "Berhati-hatilah.",
  ui_story_5031_50311501_74_dialog_content = "Pidato yang sangat menggugah. Menakjubkan.",
  ui_story_5031_50311501_75_dialog_content = "Tetapi menyebut seseorang sebagai pria yang sakit-sakitan sangat tidak sopan.",
  ui_story_5031_50311501_76_dialog_content = "Potong omong kosong.",
  ui_story_5031_50311501_77_dialog_content = "Diam dan-",
  ui_story_5031_50311501_78_dialog_content = "Turun!",
  ui_story_5031_50311501_79_dialog_content = "Heheh.",
  ui_story_5031_50311501_80_dialog_content = "<size=45>PlayerName! Hati-Hati!</size>",
  ui_story_5031_50311501_81_dialog_content = "\"Mengganti prioritas perintah, menimpa perintah default. Beralih target.\"",
  ui_story_5031_50311501_82_dialog_content = "Ugh!!",
  ui_story_5031_50311501_83_dialog_content = "PlayerName!",
  ui_story_5031_50311501_84_dialog_content = "Mana mungkin...",
  ui_story_5031_50311501_85_dialog_content = "Ini tidak mungkin...",
  ui_story_5031_50311501_86_dialog_content = "Anda datang begitu dekat, PlayerName.",
  ui_story_5031_50311501_87_dialog_content = "Sayang sekali saya telah menyerap semua energi dari inti.",
  ui_story_5031_50311501_88_dialog_content = "Sekarang, saya mengendalikan Core Guardian.",
  ui_story_5031_50311501_89_dialog_content = "Jika tidak, seseorang tanpa Lumina sepertimu akan sangat mengganggu.",
  ui_story_5031_50311501_90_dialog_content = "\"Perintah prioritas tertinggi diperbarui, beralih ke mode kontrol manual.\"",
  ui_story_5031_50311501_91_dialog_content = "\"Sistem pertahanan otomatis dimatikan.\"",
  ui_story_5031_50311501_92_dialog_content = "(Itu menyakitkan!)",
  ui_story_5031_50311501_93_dialog_content = "(Saya tidak bisa merasakan kaki saya.)",
  ui_story_5031_50311501_94_dialog_content = "Biar kulihat, satu-satunya yang tersisa yang masih bisa bergerak adalah...",
  ui_story_5031_50311501_95_dialog_content = "Merindukan Vice, Kukira.",
  ui_story_5031_50311501_96_dialog_content = "Habisi dia, lalu kita akan menuju lokasi berikutnya.",
  ui_story_5031_50311501_97_dialog_content = "\"Perintah baru diterima. Beralih target.\"",
  ui_story_5031_50311501_98_dialog_content = "(Tidak, Vice!)",
  ui_story_5031_50311501_99_dialog_content = "<size=33>Lari, Vice...</size>",
  ui_story_5031_50311501_100_dialog_content = "Oh? Masih bisa berdiri, ya?",
  ui_story_5031_50311501_101_dialog_content = "<size=33>Hah?</size>",
  ui_story_5031_50311501_102_dialog_content = "Saya menghormati Anda, karena masih mampu dengan kekuatan seperti itu dalam situasi seperti ini.",
  ui_story_5031_50311501_103_dialog_content = "Namun—dan maafkan aku atas keterusteranganku—ini hanya akan mempercepat kematianmu.",
  ui_story_5031_50311501_104_dialog_content = "<size=33>Carleen...?</size>",
  ui_story_5031_50311501_105_dialog_content = "Ini semua karena aku...",
  ui_story_5031_50311501_106_dialog_content = "Yang mulia?",
  ui_story_5031_50311501_107_dialog_content = "Ini semua... karena aku...",
  ui_story_5031_50311501_108_dialog_content = "Ah, dia mengigau karena kehilangan Lumina...",
  ui_story_5031_50311501_109_dialog_content = "Sangat terpuji bagaimana Anda masih berusaha melindungi teman-teman Anda ketika Anda dalam keadaan yang menyedihkan.",
  ui_story_5031_50311501_110_dialog_content = "\"Target baru terdeteksi. Mulai serangan?\"",
  ui_story_5031_50311501_111_dialog_content = "Tidak dibutuhkan. Dia bukan ancaman.",
  ui_story_5031_50311501_112_dialog_content = "<size=45>Hentikan, Carleen!</size>",
  ui_story_5031_50311501_113_dialog_content = "(Sial, aku bahkan tidak bisa mengeluarkan suara.)",
  ui_story_5031_50311501_114_dialog_content = "(Aku harus melakukan sesuatu...)",
  ui_story_5031_50311501_115_option_content = "Forced Control!",
  ui_story_5031_50311501_116_dialog_content = "Apa yang Anda persiapkan jika suatu hari, kota Anda diserang Eclipsite?",
  ui_story_5031_50311501_117_dialog_content = "(Apakah itu... Schwartz?)",
  ui_story_5031_50311501_118_dialog_content = "(Apakah ini mimpi? Apakah karena Carleen akan kehilangan kesadaran?)",
  ui_story_5031_50311501_119_dialog_content = "Saya akan segera mengumpulkan pasukan untuk mempertahankannya.",
  ui_story_5031_50311501_120_dialog_content = "Dan jika kekuatan Eclipsite berhasil melewati pertahanan Anda?",
  ui_story_5031_50311501_121_dialog_content = "Aku akan bergegas dengan pasukan cadangan.",
  ui_story_5031_50311501_122_dialog_content = "Dan kemudian Eclipsites yang telah menggali terowongan bawah tanah muncul di pusat kota.",
  ui_story_5031_50311501_123_dialog_content = "Aku akan memerintahkan para prajurit untuk bertahan, dan kemudian aku—",
  ui_story_5031_50311501_124_dialog_content = "Sekarang benteng mulai runtuh.",
  ui_story_5031_50311501_125_dialog_content = "...",
  ui_story_5031_50311501_126_dialog_content = "Aku akan mengalahkan semua Eclipsites.",
  ui_story_5031_50311501_127_dialog_content = "Anda dan saya sama-sama tahu bahwa mereka tidak dapat dimusnahkan.",
  ui_story_5031_50311501_128_dialog_content = "...",
  ui_story_5031_50311501_129_dialog_content = "Bagi saya, Anda masih jauh dari menjadi penguasa yang hebat...",
  ui_story_5031_50311501_130_dialog_content = "Lumopolis belum bisa bergantung padamu.",
  ui_story_5031_50311501_131_dialog_content = "B-Ayah?",
  ui_story_5031_50311501_132_dialog_content = "Saya mengirim Anda ke Northland untuk belajar di bawah Bethlehem, tapi saya tidak melihat bukti kemajuan.",
  ui_story_5031_50311501_133_dialog_content = "Kekuatan Anda tidak mencukupi dan Anda kekurangan kekuatan pikiran.",
  ui_story_5031_50311501_134_dialog_content = "Itu sebabnya Anda kehilangan teman-teman Anda.",
  ui_story_5031_50311501_135_dialog_content = "Mereka terluka, bahkan mati, semua karena Anda, Yang Mulia.",
  ui_story_5031_50311501_136_dialog_content = "Aku, aku...",
  ui_story_5031_50311501_137_dialog_content = "Saya mempercayai Anda, dan saya mengikuti rencana pertempuran Anda, Carleen.",
  ui_story_5031_50311501_138_dialog_content = "Tapi apa yang membuatku?",
  ui_story_5031_50311501_139_dialog_content = "PlayerName dan aku akan mati karenamu.",
  ui_story_5031_50311501_140_dialog_content = "Saya minta maaf, Vice...",
  ui_story_5031_50311501_141_dialog_content = "Fokus, Carleen, itu bukan Vice!",
  ui_story_5031_50311501_142_dialog_content = "Apakah itu...",
  ui_story_5031_50311501_143_dialog_content = "PlayerName?",
  ui_story_5031_50311501_144_dialog_content = "Ya, ini aku!",
  ui_story_5031_50311501_145_dialog_content = "Saya minta maaf karena tidak pernah memperhatikan seberapa banyak konflik internal yang Anda alami, Carleen.",
  ui_story_5031_50311501_146_dialog_content = "Tetapi Vice tidak akan pernah mengatakan itu. Apa yang Anda lihat tidak nyata tetapi ilusi!",
  ui_story_5031_50311501_147_dialog_content = "Apakah Anda mencoba lari dari tanggung jawab Anda?",
  ui_story_5031_50311501_148_dialog_content = "Sayang sekali. Teruslah mengutarakan bagaimana Anda akan melindungi orang lain ketika Anda sebenarnya lemah.",
  ui_story_5031_50311501_149_dialog_content = "Anda tidak cocok untuk memerintah.",
  ui_story_5031_50311501_150_dialog_content = "Aku…",
  ui_story_5031_50311501_151_dialog_content = "Dengarkan aku, Carleen.",
  ui_story_5031_50311501_152_dialog_content = "Anda tidak harus menanggung beban menjadi penguasa sepanjang waktu!",
  ui_story_5031_50311501_153_dialog_content = "Untuk saya dan Vice, kamu adalah Carleen dan hanya Carleen!",
  ui_story_5031_50311501_154_dialog_content = "Mm?",
  ui_story_5031_50311501_154X1_dialog_content = "Apakah Anda ingat hal itu? Vice dikatakan, Carleen?",
  ui_story_5031_50311501_154X2_dialog_content = "Anda tidak boleh menyerah pada obsesi Anda!",
  ui_story_5031_50311501_154X3_dialog_content = "obsesiku...",
  ui_story_5031_50311501_154X4_dialog_content = "Saya sangat mengantuk selama proses tersebut. Saya pikir saya tidak akan pernah bangun.",
  ui_story_5031_50311501_154X5_dialog_content = "Aku terus berpikir kembali ke diriku yang dulu, takut aku akan kehilangan diriku sendiri jika aku santai bahkan untuk sesaat.",
  ui_story_5031_50311501_154X6_dialog_content = "Saya juga melihat banyak hal luar biasa, seperti saya ada di sana.",
  ui_story_5031_50311501_154X7_dialog_content = "Ilusi itu terasa begitu nyata, seperti ujian bagiku.",
  ui_story_5031_50311501_154X8_dialog_content = "Untungnya, saya berpegang teguh pada kilau dalam kesadaran dan dipertahankan sampai akhir.",
  ui_story_5031_50311501_154X9_dialog_content = "Bersinar? Saya ingat Anda menyebutkannya. Apa itu?",
  ui_story_5031_50311501_154X10_dialog_content = "Um... Saya memikirkan hal-hal menyenangkan yang saya lakukan dengan Anda dan PlayerName.",
  ui_story_5031_50311501_154X11_dialog_content = "Dan sebelum aku menyadarinya, ada keheningan di dalam diriku.",
  ui_story_5031_50311501_154X12_dialog_content = "Ya, Carleen, jangan menyerah dan jangan kalah!",
  ui_story_5031_50311501_155_dialog_content = "Kami berjuang bersama dan mundur bersama.",
  ui_story_5031_50311501_156_dialog_content = "Kami akan selalu saling mendukung.",
  ui_story_5031_50311501_157_dialog_content = "Kami tidak meminta Anda bertanggung jawab saat kami dalam masalah.",
  ui_story_5031_50311501_158_dialog_content = "Anda tidak harus melindungi kami semua sendirian.",
  ui_story_5031_50311501_159_dialog_content = "Kita harus bekerja sebagai sebuah tim dan menghadapi masalah sebagai sebuah tim!",
  ui_story_5031_50311501_160_dialog_content = "PlayerName…",
  ui_story_5031_50311501_161_dialog_content = "Apapun yang terjadi, Vice dan aku tidak akan pernah menyalahkanmu!",
  ui_story_5031_50311501_162_dialog_content = "Jadi tarik dirimu bersama-sama, Carleen! Jangan disesatkan oleh ilusi!",
  ui_story_5031_50311501_163_dialog_content = "Yang asli Vice tidak menyerah dan masih berjuang untuk kita.",
  ui_story_5031_50311501_164_dialog_content = "Dia membutuhkanmu!",
  ui_story_5031_50311501_165_dialog_content = "...",
  ui_story_5031_50311501_166_dialog_content = "Anda benar, PlayerName.",
  ui_story_5031_50311501_167_dialog_content = "Teman-teman saya masih berjuang, bagaimana saya bisa membuang waktu untuk merendahkan diri sendiri?",
  ui_story_5031_50311501_168_dialog_content = "Jadi, Anda hanya akan mengabaikan kesalahan yang Anda buat?",
  ui_story_5031_50311501_169_dialog_content = "Jelas bahwa Anda meremehkan dan tidak kompeten ...",
  ui_story_5031_50311501_170_dialog_content = "Dibawa ke kesulitan saat ini.",
  ui_story_5031_50311501_171_dialog_content = "Ya, tapi saya tidak akan menjadi tawanan atas keputusan saya sendiri, benar atau salah.",
  ui_story_5031_50311501_172_dialog_content = "...",
  ui_story_5031_50311501_173_dialog_content = "Karena itu tidak ada artinya. Jika saya membuat kesalahan ...",
  ui_story_5031_50311501_174_dialog_content = "Saya akan berusaha untuk memperbaikinya.",
  ui_story_5031_50311501_175_dialog_content = "Jika itu cara Anda mendefinisikan \"jalan penguasa\"...",
  ui_story_5031_50311501_176_dialog_content = "Saya harap Anda akan tetap teguh pada keyakinan itu.",
  ui_story_5031_50311501_176X1_dialog_content = "Baiklah.",
  ui_story_5031_50311501_176X2_dialog_content = "Karena saya...",
  ui_story_5031_50311501_176X3_dialog_content = "Saya telah menemukan sesuatu yang dapat saya pegang.",
  ui_story_5031_50311501_177_dialog_content = "Ah, gambar itu—",
  ui_story_5031_50311501_178_dialog_content = "Maaf membuat anda menunggu, Vice.",
  ui_story_5031_50311501_179_dialog_content = "Carleen!",
  ui_story_5031_50311501_180_dialog_content = "\"Peringatan: Lumina masif terdeteksi, tingkat ancaman tinggi.\"",
  ui_story_5031_50311501_181_dialog_content = "\"Hilangkan target segera.\"",
  ui_story_5031_50311501_182_dialog_content = "Cahaya Indah!",
  ui_story_5031_50311501_183_dialog_content = "Kok bisa?",
  ui_story_5031_50311501_184_dialog_content = "Tetapi <color=#FFB400>Lumothread</color> masih menyerap Lumina-nya?!",
  ui_story_5031_50311501_185_dialog_content = "Carleen sedang mandi di Lumina!",
  ui_story_5031_50311501_186_dialog_content = "Apa yang terjadi di sini?",
  ui_story_5031_50311501_187_dialog_content = "Keraguan diri dan kecemasan yang tidak perlu hanya akan mengurangi.",
  ui_story_5031_50311501_188_dialog_content = "Sebuah pertempuran selalu berubah. Seseorang harus fokus pada apa yang sedang berlangsung, bukan ketakutan internal.",
  ui_story_5031_50311501_189_dialog_content = "Sekarang aku akan bertarung denganmu, Vice.",
  ui_story_5031_50311501_190_dialog_content = "Apakah Anda baik-baik saja secara fisik, Carleen?",
  ui_story_5031_50311501_191_dialog_content = "Saya tidak tahu mengapa, tetapi saya merasakan energi tanpa henti.",
  ui_story_5031_50311501_192_dialog_content = "Apapun, saya hanya punya satu tujuan sekarang ...",
  ui_story_5031_50311501_193_dialog_content = "Dan itu untuk mengalahkan musuh bersamamu.",
  ui_story_5031_50311501_194_dialog_content = "Ya!",
  ui_story_5031_50311501_195_dialog_content = "\"Peringatan: Lumina masif terdeteksi, tingkat ancaman sangat tinggi.\"",
  ui_story_5031_50311501_196_dialog_content = "\"Mengaktifkan Mode Showdown.\"",
  ui_story_5031_50311502_1_dialog_content = "\"Peringatan... Kerusakan lambung kapal lebih dari 70%.\"",
  ui_story_5031_50311502_2_dialog_content = "\"Lengan kanan terputus dan tidak dapat diperbaiki secara otomatis.\"",
  ui_story_5031_50311502_3_dialog_content = "Apakah Anda bertahan baik-baik saja, Vice?",
  ui_story_5031_50311502_4_dialog_content = "Ya. Penindasan jarak jauh tidak akan menghabiskan terlalu banyak energi untukku!",
  ui_story_5031_50311502_5_dialog_content = "Oke, mari kita konsentrasikan api di sebelah kanannya.",
  ui_story_5031_50311502_6_dialog_content = "Lengan kanan ke bawah, sehingga akan mempengaruhi serangan dan pertahanannya.",
  ui_story_5031_50311502_7_dialog_content = "Siap!",
  ui_story_5031_50311502_8_dialog_content = "Saya harus mengatakan, Anda melebihi harapan saya, Carleen.",
  ui_story_5031_50311502_9_dialog_content = "Saya mengagumi itu, bahkan jika kita berada di sisi yang berlawanan.",
  ui_story_5031_50311502_10_dialog_content = "Namun, saya punya alasan untuk tidak gagal.",
  ui_story_5031_50311502_11_dialog_content = "Oleh karena itu, mohon maafkan saya karena tidak tinggal untuk melihat akhir dari pertunjukan ini.",
  ui_story_5031_50311502_12_dialog_content = "Kamu tidak akan kemana-mana, Elvis!",
  ui_story_5031_50311502_13_dialog_content = "Hentikan mereka.",
  ui_story_5031_50311502_14_dialog_content = "Mencari, Vice, jangan membelakangi Guardian!",
  ui_story_5031_50311502_15_dialog_content = "Aghhh!",
  ui_story_5031_50311502_16_dialog_content = "...",
  ui_story_5031_50311502_17_dialog_content = "Tikus, dia lolos.",
  ui_story_5031_50311502_18_dialog_content = "Tidak masalah. Kami akan mencari tahu setelah selesai di sini.",
  ui_story_5031_50311502_19_dialog_content = "Kau benar.",
  ui_story_5031_50311502_20_dialog_content = "Sekarang, masalah Wali.",
  ui_story_5031_50311502_21_dialog_content = "Jadi, kita harus... Hmm?",
  ui_story_5031_50311502_22_dialog_content = "Apa itu, Carleen?",
  ui_story_5031_50311502_23_dialog_content = "(Lumina Carleen semakin kuat?)",
  ui_story_5031_50311502_24_dialog_content = "Pakaian ini tidak menyedot Lumina saya lagi.",
  ui_story_5031_50311502_25_dialog_content = "Apakah karena Elvis pergi?",
  ui_story_5031_50311502_26_dialog_content = "Itu akan menjelaskan mengapa Anda baik-baik saja dalam hal itu sebelumnya.",
  ui_story_5031_50311502_27_dialog_content = "Saya kira Elvis harus memeliharanya sendiri agar bisa berfungsi.",
  ui_story_5031_50311502_28_dialog_content = "Dalam hal ini, saya tidak perlu menahan diri.",
  ui_story_5031_50311502_29_dialog_content = "Mari kita berikan pukulan terakhir pada mesin bodoh dan tidak pandang bulu ini sebelum menghancurkan kapal.",
  ui_story_5031_50311502_30_dialog_content = "Ya! Jeno lebih baik bersyukur begitu dia bangun.",
  ui_story_5031_50311502_31_dialog_content = "Apakah Anda menentang saya?",
  ui_story_5031_50311502_32_dialog_content = "Laird bertemu dengan pemilik sirkus, dan tidak ada yang boleh naik ke kapal.",
  ui_story_5031_50311502_33_dialog_content = "Kami hanya menjalankan perintah, jadi harap dipahami.",
  ui_story_5031_50311502_34_dialog_content = "Anda semua tidak terlihat seperti Anda hanya menonton tempat.",
  ui_story_5031_50311502_35_dialog_content = "Belum lagi suara ledakan yang datang dari kapal.",
  ui_story_5031_50311502_36_dialog_content = "Pertemuan? Lebih seperti dendam padaku.",
  ui_story_5031_50311502_37_dialog_content = "Apakah kamu tidak khawatir tentang tuanmu? Dia terlalu kurus untuk melawan Jeno.",
  ui_story_5031_50311502_38_dialog_content = "Silakan pergi.",
  ui_story_5031_50311502_39_dialog_content = "Oh? Apakah Anda akan membuat saya?",
  ui_story_5031_50311502_40_dialog_content = "Maka Anda sebaiknya bersiap untuk konsekuensinya, karena saya akan melaporkannya ke...",
  ui_story_5031_50311502_41_dialog_content = "Jangan kurang ajar, Patou.",
  ui_story_5031_50311502_42_dialog_content = "Tuan tanah!",
  ui_story_5031_50311502_43_dialog_content = "Oh, bukan Laird Elvis? Apakah rapat sudah selesai?",
  ui_story_5031_50311502_44_dialog_content = "Maaf membuatmu menunggu, Matthieu, tapi aku punya urusan penting dengan seorang teman lama.",
  ui_story_5031_50311502_45_dialog_content = "Patou dan anak buahnya hanya mengikuti perintah. Tolong maafkan mereka.",
  ui_story_5031_50311502_46_dialog_content = "Saya mengerti. May kita naik kapal sekarang?",
  ui_story_5031_50311502_47_dialog_content = "Silakan, merasa bebas.",
  ui_story_5031_50311502_48_dialog_content = "<size=33>Apakah kita akan membiarkan dia masuk begitu saja, Pak?</size>",
  ui_story_5031_50311502_49_dialog_content = "<size=33>Tidak masalah. Kapal akan segera meledak.</size>",
  ui_story_5031_50311502_50_dialog_content = "<size=33>Saya lebih suka menuju...</size>",
  ui_story_5031_50311502_51_dialog_content = "Sebentar, Laird Elvis.",
  ui_story_5031_50311502_52_dialog_content = "Ada apa?",
  ui_story_5031_50311502_53_dialog_content = "Apakah Anda melihat Yang Mulia Carleen kapal?",
  ui_story_5031_50311502_54_dialog_content = "Tidak. Apakah dia dan teman-temannya ada di pesawat?",
  ui_story_5031_50311502_55_dialog_content = "Itu aneh. Saya sudah menunggu sejak perayaan selesai tetapi tidak pernah melihat Yang Mulia.",
  ui_story_5031_50311502_56_dialog_content = "Dia tidak turun atau melihat Anda, jadi mengapa dia tinggal di kapal?",
  ui_story_5031_50311502_57_dialog_content = "Mungkin dia mengucapkan selamat tinggal pada teman-teman baru yang dia buat.",
  ui_story_5031_50311502_58_dialog_content = "Karena mereka mungkin berkenalan dengan cukup baik sepanjang hari.",
  ui_story_5031_50311502_59_dialog_content = "Saya ditugaskan ke Yang Mulia sebagai pengawal. Jadi pada dasarnya saya mengasuhnya sepanjang hari, takut dia akan terluka.",
  ui_story_5031_50311502_60_dialog_content = "Saya percaya dia tidak banyak berhubungan dengan orang-orang sirkus, dari pengamatan saya.",
  ui_story_5031_50311502_61_dialog_content = "Tapi Nona Vice dan Nona Ciel adalah teman lama.",
  ui_story_5031_50311502_62_dialog_content = "Dan PlayerName sangat akrab dengan Miss Rainbow...",
  ui_story_5031_50311502_63_dialog_content = "Izinkan saya untuk menyela, Laird Elvis.",
  ui_story_5031_50311502_64_dialog_content = "Ya?",
  ui_story_5031_50311502_65_dialog_content = "Saya percaya saya tidak menyebutkan orang lain.",
  ui_story_5031_50311502_66_dialog_content = "Jika Anda tidak melihatnya, bagaimana Anda bisa begitu yakin dia bersama mereka?",
  ui_story_5031_50311502_67_dialog_content = "...",
  ui_story_5031_50311502_68_dialog_content = "Itu karena mereka berempat dekat dan selalu hang out bareng.",
  ui_story_5031_50311502_69_dialog_content = "Anda tampaknya tahu banyak untuk mengetahui mereka hanya untuk satu hari.",
  ui_story_5031_50311502_70_dialog_content = "Saya dekat dengan pasangan saya yang terbungkus erat itu, namun dia tidak ada di sini.",
  ui_story_5031_50311502_71_dialog_content = "...",
  ui_story_5031_50311502_72_dialog_content = "Patou.",
  ui_story_5031_50311502_73_dialog_content = "Ya, laird.",
  ui_story_5031_50311502_74_dialog_content = "Saya melihat kita melanjutkan ke fase \"tidak ada saksi\".",
  ui_story_5031_50311502_75_dialog_content = "Bukan pose bertarung yang buruk di sana.",
  ui_story_5031_50311502_76_dialog_content = "Tapi Anda mungkin tidak tahu bahwa di balik eksterior dingin Tuan Kota kita, dia sangat protektif terhadap putrinya.",
  ui_story_5031_50311502_77_dialog_content = "Jadi, apakah Anda pikir saya, sebagai pengawalnya, dapat dengan mudah ditangani?",
  ui_story_5031_50311502_78_dialog_content = "Saatnya masuk, Loewe!",
  ui_story_5031_50311502_79_dialog_content = "Apa?",
  ui_story_5031_50311502_80_dialog_content = "Kamu terlalu banyak bicara, Matthieu.",
  ui_story_5031_50311502_81_dialog_content = "Itu urusanmu bagaimana?",
  ui_story_5031_50311502_82_dialog_content = "Kalian berdua saja?",
  ui_story_5031_50311502_83_dialog_content = "Anda berharap untuk melawan anak buah saya hanya dengan kalian berdua?",
  ui_story_5031_50311502_84_dialog_content = "Salah, hanya satu.",
  ui_story_5031_50311502_85_dialog_content = "Anda punya ini, Loewe. Aku akan masuk untuk menyelamatkan.",
  ui_story_5031_50311502_86_dialog_content = "...",
  ui_story_5031_50311502_87_dialog_content = "Tidak usah.",
  ui_story_5031_50311502_88_dialog_content = "Hei, itu terdengar seperti...",
  ui_story_5031_50311502_89_dialog_content = "Apa?!",
  ui_story_5031_50311502_90_dialog_content = "Terima kasih telah membuat Elvis sibuk.",
  ui_story_5031_50311502_91_dialog_content = "Itu sangat membantu.",
  ui_story_5031_50311502_92_dialog_content = "Yang mulia! Senang melihat Anda masih hidup!",
  ui_story_5031_50311502_93_dialog_content = "Tak mungkin!",
  ui_story_5031_50311502_94_dialog_content = "Dimana Wali? Kenapa kapalnya tidak meledak?",
  ui_story_5031_50311502_95_dialog_content = "Carleen memukulnya dengan kekuatan penuh, dan itu adalah tumpukan besi tua sekarang.",
  ui_story_5031_50311502_96_dialog_content = "Meskipun saya harus mengatakan bahwa robot itu dibuat dengan luar biasa!",
  ui_story_5031_50311502_97_dialog_content = "Sayang sekali itu berhenti bergerak ketika kami sampai di sana.",
  ui_story_5031_50311502_98_dialog_content = "Tidak masalah. Masih bagus untuk penelitian.",
  ui_story_5031_50311502_99_dialog_content = "Kau benar!",
  ui_story_5031_50311502_100_dialog_content = "Tapi bagaimana caranya? Bagaimana Anda masih bisa menggunakan kekuatan seperti itu di bawah kendali?",
  ui_story_5031_50311502_101_dialog_content = "Tunggu, apakah Lumothread berhenti menyerap?",
  ui_story_5031_50311502_102_dialog_content = "Apakah Anda tidak mengontrol itu, Elvis?",
  ui_story_5031_50311502_103_dialog_content = "Jangan bilang itu mencapai kapasitas maksimum?",
  ui_story_5031_50311502_104_dialog_content = "Itu tidak mungkin... Pakaian itu seharusnya bisa menyerap Lumina dari dua, bahkan tiga Aurorian!",
  ui_story_5031_50311502_105_dialog_content = "Itu tidak penting.",
  ui_story_5031_50311502_106_dialog_content = "Apa, apakah rencanamu gagal, Elvis.",
  ui_story_5031_50311502_107_dialog_content = "Menyerah. Anda tidak bisa pergi sekarang.",
  ui_story_5031_50311502_108_dialog_content = "Tidak, tidak... Aku tidak boleh gagal! Saya tidak boleh gagal!",
  ui_story_5031_50311502_109_dialog_content = "Itu <color=#FFB400>segel</color> segera...",
  ui_story_5031_50311502_110_dialog_content = "Patou!",
  ui_story_5031_50311502_111_dialog_content = "Siap, Pak!",
  ui_story_5031_50311502_112_dialog_content = "Perlawanan tidak ada gunanya.",
  ui_story_5031_50311502_113_dialog_content = "Argh…",
  ui_story_5031_50311502_114_dialog_content = "Sekarang, Laird!",
  ui_story_5031_50311502_115_dialog_content = "Aku akan menjadi bahan tertawaan jika kau pergi. Pikir saya akan membiarkan itu terjadi?",
  ui_story_5031_50311502_116_dialog_content = "Ugh!",
  ui_story_5031_50311502_117_dialog_content = "Ayo! Saya baru saja \"menyenggol\" dia, dan dia sudah selesai?",
  ui_story_5031_50311502_118_dialog_content = "Seberapa lemah pria itu?",
  ui_story_5031_50311502_119_dialog_content = "Tuan tanah!",
  ui_story_5031_50311502_120_dialog_content = "Aku yang kamu lawan.",
  ui_story_5031_50311502_121_dialog_content = "Sialan!",
  ui_story_5031_50311502_122_dialog_content = "Tak satu pun dari Anda pergi.",
  ui_story_5031_50311601_1_dialog_content = "Kamu punya Ciel, kan, Rainbow?",
  ui_story_5031_50311601_2_dialog_content = "Ya! Aku akan merawatnya dengan baik, petugas!",
  ui_story_5031_50311601_3_dialog_content = "Frimet akan membantu juga!",
  ui_story_5031_50311601_4_dialog_content = "Dan Subli!",
  ui_story_5031_50311601_5_dialog_content = "M-Merylt juga.",
  ui_story_5031_50311601_6_dialog_content = "Oh sangat bagus!",
  ui_story_5031_50311601_7_dialog_content = "Terima kasih, Petugas Gronru, untuk membiarkan saya tinggal.",
  ui_story_5031_50311601_8_dialog_content = "Semuanya baik. Tidak banyak yang terjadi akhir-akhir ini.",
  ui_story_5031_50311601_9_dialog_content = "Kamu bisa tenang di sini, Ciel.",
  ui_story_5031_50311601_10_dialog_content = "... Dengan serius? Biarkan inti energi itu begitu saja?",
  ui_story_5031_50311601_11_dialog_content = "Oh, itu hanya inti daya kecil. Itu tidak berharga bagi Illumina.",
  ui_story_5031_50311601_12_dialog_content = "Meskipun sangat mirip dengan inti energi, itu lebih buruk dalam banyak aspek, dan kemurnian energi yang dihasilkan tidak baik.",
  ui_story_5031_50311601_13_dialog_content = "Selain itu, setelah penanganan yang tidak masuk akal oleh laird itu, pada dasarnya itu adalah sepotong sampah.",
  ui_story_5031_50311601_14_dialog_content = "Berbicara tentang nilai penelitian... Mungkin itu akan memberi Anda inspirasi untuk meningkatkan \"Styx\" Anda.",
  ui_story_5031_50311601_15_dialog_content = "Sial, aku belum cukup mempelajari kapal ini. Mengapa saya harus diingat saat ini!",
  ui_story_5031_50311601_15X1_dialog_content = "Ciel, Anda harus memberi perhatian ekstra pada sistem transmisi saat Anda memperbaiki inti untuk mereka!",
  ui_story_5031_50311601_15X2_dialog_content = "Buat catatan yang bagus! Saya akan membacanya ketika Anda kembali!",
  ui_story_5031_50311601_15X3_dialog_content = "Aku, aku mengerti...",
  ui_story_5031_50311601_16_dialog_content = "Hei, apa yang kamu bisikkan?",
  ui_story_5031_50311601_17_dialog_content = "Aku juga ingin mendengarnya!",
  ui_story_5031_50311601_18_dialog_content = "Uh, jika itu untuk kita, mereka tidak perlu berbisik...",
  ui_story_5031_50311601_19_dialog_content = "Hmm, itu masuk akal.",
  ui_story_5031_50311601_20_dialog_content = "Lupakan saja.",
  ui_story_5031_50311601_21_dialog_content = "Ini dia.",
  ui_story_5031_50311601_22_dialog_content = "Apa katamu?",
  ui_story_5031_50311601_23_dialog_content = "Siapa yang membuat semua kebisingan itu?",
  ui_story_5031_50311601_24_dialog_content = "Apakah Anda yakin, Yang Mulia?",
  ui_story_5031_50311601_25_dialog_content = "Apakah Anda benar-benar tinggal di sini untuk menjalankan tempat itu?",
  ui_story_5031_50311601_26_dialog_content = "Ya.",
  ui_story_5031_50311601_27_dialog_content = "Tapi Elvis mengangkat senjata melawanmu. Itu pengkhianatan!",
  ui_story_5031_50311601_28_dialog_content = "Yang mulia Schwartz tidak akan tahan untuk itu!",
  ui_story_5031_50311601_29_dialog_content = "Itulah mengapa aku butuh bantuan dari kalian berdua.",
  ui_story_5031_50311601_30_dialog_content = "Mengapa saya mendapatkan firasat buruk tentang ini?",
  ui_story_5031_50311601_31_dialog_content = "Saya harap Anda dan Tuan Loewe akan merahasiakan bagian dari insiden ini.",
  ui_story_5031_50311601_32_dialog_content = "Juga, saya ingin Anda berdua tinggal bersama saya di Harbour City untuk sementara waktu.",
  ui_story_5031_50311601_33_dialog_content = "Sayangnya, tidak.",
  ui_story_5031_50311601_34_dialog_content = "Maaf, Yang Mulia, itu datang langsung dari Nyonya Irridon.",
  ui_story_5031_50311601_35_dialog_content = "Saya berkewajiban untuk menghormati itu.",
  ui_story_5031_50311601_36_dialog_content = "...",
  ui_story_5031_50311601_37_dialog_content = "Saya mengerti, Tuan Matthieu. Saya tidak mempertanyakan kesetiaan Anda sama sekali.",
  ui_story_5031_50311601_38_dialog_content = "Tapi aku lebih suka tidak membuat masalah untukmu dan Loewe.",
  ui_story_5031_50311601_39_dialog_content = "Bagaimanapun, saya mendapat 17 jahitan untuk luka saya, belum lagi ketidakmampuan untuk menggunakan Lumina karena kelelahan.",
  ui_story_5031_50311601_40_dialog_content = "Itu bisa menjadi masalah jika Lady Irridon atau Tuhan Schwartz mencari tahu tentang hal itu.",
  ui_story_5031_50311601_41_dialog_content = "Tentu saja, tapi...",
  ui_story_5031_50311601_42_dialog_content = "Tentu saja, itu berasal dari kelalaian saya sendiri, dan saya baik-baik saja sekarang.",
  ui_story_5031_50311601_43_dialog_content = "Dokter juga mengatakan kepada saya bahwa saya harus pulih sepenuhnya, jika diberikan waktu.",
  ui_story_5031_50311601_44_dialog_content = "Jadi, jika Anda ingin menghindari tudingan jari yang tidak perlu, saya akan dengan senang hati mematuhinya.",
  ui_story_5031_50311601_45_dialog_content = "...",
  ui_story_5031_50311601_46_dialog_content = "Kenapa?",
  ui_story_5031_50311601_47_dialog_content = "Kenapa Apa?",
  ui_story_5031_50311601_48_dialog_content = "Mengapa Anda bersikeras untuk tetap tinggal, Yang Mulia?",
  ui_story_5031_50311601_49_dialog_content = "Mengapa menutupi pelanggaran Elvis?",
  ui_story_5031_50311601_50_dialog_content = "Karena, pertama-tama, dia melakukannya untuk kebaikan orang-orang di Harbour City.",
  ui_story_5031_50311601_51_dialog_content = "Kedua, Harbour City selalu menjadi pengikut Lumopolis, dan Laird Elvis bahkan pernah belajar di Lumopolis sebelumnya.",
  ui_story_5031_50311601_52_dialog_content = "Namun, dia tidak meminta bantuan dari Lumopolis tetapi mencari solusi sendiri dan bahkan menyimpannya dari Lumopolis.",
  ui_story_5031_50311601_53_dialog_content = "Menurut Anda mengapa demikian?",
  ui_story_5031_50311601_54_dialog_content = "...",
  ui_story_5031_50311601_55_dialog_content = "Itu karena dia tidak percaya Lumopolis bisa atau akan membantunya.",
  ui_story_5031_50311601_56_dialog_content = "Seorang laird yang tidak mau mempercayai kami adalah akar masalahnya.",
  ui_story_5031_50311601_57_dialog_content = "Kami tidak bisa menjamin laird berikutnya tidak akan membuat pilihan yang sama seperti yang dibuat Elvis.",
  ui_story_5031_50311601_58_dialog_content = "Jika kita tidak sampai ke akar masalahnya dan mengabaikannya, itu akan tumbuh lebih dalam.",
  ui_story_5031_50311601_59_dialog_content = "Jadi, saya ingin mengetahui maksud sebenarnya dari Elvis.",
  ui_story_5031_50311601_60_dialog_content = "Dan mencabutnya sebelum digali terlalu dalam.",
  ui_story_5031_50311601_61_dialog_content = "...",
  ui_story_5031_50311601_62_dialog_content = "Heh, bagi saya, Anda selalu tidak lebih dari seorang putri yang naif dan terlindung.",
  ui_story_5031_50311601_63_dialog_content = "…?",
  ui_story_5031_50311601_64_dialog_content = "Namun…",
  ui_story_5031_50311601_65_dialog_content = "Harus saya akui, itu adalah pidato yang masuk akal.",
  ui_story_5031_50311601_66_dialog_content = "Bukan begitu, Loew?",
  ui_story_5031_50311601_67_dialog_content = "Ya.",
  ui_story_5031_50311601_68_dialog_content = "Jadi...",
  ui_story_5031_50311601_69_dialog_content = "Tapi!",
  ui_story_5031_50311601_70_dialog_content = "...",
  ui_story_5031_50311601_71_dialog_content = "Kami tidak akan pernah berbohong kepada Lady Irridon.",
  ui_story_5031_50311601_72_dialog_content = "Oleh karena itu, kami masih akan melaporkan semuanya melalui Serikat Kurir kepadanya malam ini.",
  ui_story_5031_50311601_73_dialog_content = "Di mana Serikat Kurir itu lagi?",
  ui_story_5031_50311601_74_dialog_content = "A-Apa itu? Loew?",
  ui_story_5031_50311601_75_dialog_content = "...",
  ui_story_5031_50311601_76_dialog_content = "White Pearl Street, di sebelah Lucky Garden Restaurant.",
  ui_story_5031_50311601_77_dialog_content = "Itu dia.",
  ui_story_5031_50311601_78_dialog_content = "Itu pada Anda, kemudian.",
  ui_story_5031_50311601_79_dialog_content = "...",
  ui_story_5031_50311601_80_dialog_content = "Mengapa Anda tidak melakukannya?",
  ui_story_5031_50311601_81_dialog_content = "Karena saya masih harus mengamankan sekitarnya.",
  ui_story_5031_50311601_82_dialog_content = "Situasi berbahaya seperti itu membutuhkan orang yang lebih kuat secara keseluruhan untuk memastikan keselamatan Yang Mulia.",
  ui_story_5031_50311601_83_dialog_content = "...",
  ui_story_5031_50311601_84_dialog_content = "Apa, kamu ingin melawanku?",
  ui_story_5031_50311601_85_dialog_content = "Ayo kita coba.",
  ui_story_5031_50311601_86_dialog_content = "Ayo, mari kita pasang di sana. Aku akan mengalahkanmu hari ini.",
  ui_story_5031_50311601_87_dialog_content = "Dalam mimpimu.",
  ui_story_5031_50311601_88_dialog_content = "...",
  ui_story_5031_50311601_89_dialog_content = "Sudahkah Anda mencapai kesepakatan, Carleen?",
  ui_story_5031_50311601_90_dialog_content = "Kenapa mereka mulai bertengkar?",
  ui_story_5031_50311601_91_dialog_content = "Begitulah mereka. Mereka bertengkar dan bertengkar tetapi tidak pernah berpisah.",
  ui_story_5031_50311601_92_dialog_content = "Adapun laporan insiden ...",
  ui_story_5031_50311601_93_dialog_content = "Saya percaya kita memiliki pemahaman yang netral.",
  ui_story_5031_50311601_94_dialog_content = "Baiklah!",
  ui_story_5031_50311601_95_dialog_content = "Mereka mungkin tampak aneh tetapi ternyata sangat menyenangkan.",
  ui_story_5031_50311601_96_dialog_content = "Apakah Anda yakin Anda berdua tidak terluka?",
  ui_story_5031_50311601_97_dialog_content = "Anda tidak perlu menemani saya di sini.",
  ui_story_5031_50311601_98_dialog_content = "Bagaimana kami bisa meninggalkan Anda sendirian dalam kondisi Anda saat ini?",
  ui_story_5031_50311601_98X1_dialog_content = "Lumina Anda memancar seperti di luar kendali, dan Anda pingsan tak lama setelah kami melarikan diri ...",
  ui_story_5031_50311601_98X2_dialog_content = "Itu benar-benar membuat kami ketakutan!",
  ui_story_5031_50311601_98X3_dialog_content = "Maaf telah membuatmu cemas.",
  ui_story_5031_50311601_98X4_dialog_content = "Bagaimana Anda mencapai terobosan tiba-tiba, Carleen? Itu tadi Menajubkan.",
  ui_story_5031_50311601_98X5_dialog_content = "Pada saat itu... Saya merasakan apa yang Anda gambarkan, Vice.",
  ui_story_5031_50311601_98X6_dialog_content = "Saya bertemu semua kecemasan yang telah mengganggu saya.",
  ui_story_5031_50311601_98X7_dialog_content = "Mereka begitu nyata, sombong, dan mencekik.",
  ui_story_5031_50311601_98X8_dialog_content = "Oh, Carleen...",
  ui_story_5031_50311601_98X9_dialog_content = "Untungnya, PlayerName berhubungan dengan pikiran saya dan menarik saya kembali dari jurang.",
  ui_story_5031_50311601_98X10_dialog_content = "Itu membuatku sadar bahwa kalian berdua adalah \"sesuatu\" yang aku butuhkan...",
  ui_story_5031_50311601_98X11_dialog_content = "Terima kasih, PlayerName. Dan Anda juga, Vice.",
  ui_story_5031_50311601_98X12_dialog_content = "Anda melakukannya sendiri, Carleen. Anda mengatasi beban emosional dan menguasai pikiran Anda sendiri.",
  ui_story_5031_50311601_98X13_dialog_content = "Itu benar, tetapi PlayerName selalu memiliki sup ayam verbal untuk jiwa yang siap!",
  ui_story_5031_50311601_98X14_dialog_content = "Yang agak luar biasa!",
  ui_story_5031_50311601_98X15_dialog_content = "I-Apakah itu nyata?",
  ui_story_5031_50311601_98X16_dialog_content = "Saya hanya berbicara apa yang saya rasakan.",
  ui_story_5031_50311601_98X17_dialog_content = "Itu sangat bagus dalam dirinya sendiri.",
  ui_story_5031_50311601_98X18_dialog_content = "Ya.",
  ui_story_5031_50311601_98X19_dialog_content = "Tapi Anda harus tenang untuk sementara waktu, Carleen. Jangan terburu-buru pemulihan Anda.",
  ui_story_5031_50311601_98X20_dialog_content = "Pingsan karena kebocoran Lumina bisa terjadi jika Anda belum terbiasa.",
  ui_story_5031_50311601_98X21_dialog_content = "Jadi jangan memaksakan diri dengan kekuatan baru sebelum Anda pulih!",
  ui_story_5031_50311601_98X22_dialog_content = "Itu terdengar seperti sesuatu Carleen akan melakukan.",
  ui_story_5031_50311601_98X23_dialog_content = "Baik, aku paham.",
  ui_story_5031_50311601_98X24_dialog_content = "Aku akan menjaga diriku sendiri. Yakinlah.",
  ui_story_5031_50311601_98X25_dialog_content = "Adapun terobosan, saya akan mencari cara terbaik dengan Vice setelah saya benar-benar sembuh.",
  ui_story_5031_50311601_98X26_dialog_content = "Bukan masalah!",
  ui_story_5031_50311601_99_dialog_content = "Anda tidak perlu khawatir tentang kami. PlayerName dan saya tangguh, bukan?",
  ui_story_5031_50311601_100_dialog_content = "Ya. Anda dapat bersandar pada kami sesekali, Carleen.",
  ui_story_5031_50311601_101_dialog_content = "Jadi biarkan kami mengawasimu kali ini!",
  ui_story_5031_50311601_102_dialog_content = "Kalau begitu, terima kasih banyak.",
  ui_story_5031_50311601_103_dialog_content = "Bukan masalah!",
  ui_story_5031_50311601_104_dialog_content = "Apa yang harus kita lakukan selanjutnya?",
  ui_story_5031_50311601_105_dialog_content = "Mengingat kekacauan besar, ada banyak hal yang harus ditangani di Harbour City.",
  ui_story_5031_50311601_106_dialog_content = "Carleen akan sangat sibuk sebagai laird sementara.",
  ui_story_5031_50311601_107_dialog_content = "Memang. Tapi sebelum itu resmi, aku punya seseorang yang ingin kutemui.",
  ui_story_5031_50311601_108_dialog_content = "Siapa itu?",
  ui_story_5031_50311601_109_dialog_content = "Elvis.",
  ui_story_5031_50311601_110_dialog_content = "<color=#e8d9bb>Bersambung...</color>"
}
return config
